#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#include "аст.h"
#include "владение.h"
#include "заголовки.h"
#include "интерфейс.h"

#define МАКС_ИМЯ 128
#define МАКС_СВЯЗЕЙ_МАССИВОВ 32
#define МАКС_ГЛУБИНА_ОГРАНИЧЕНИЙ 64
#define МАКС_СИМВОЛОВ 256
#define МАКС_ГЛОБАЛЬНЫХ_КОНСТ 64
#define МАКС_ФАКТОВ 64          // стек фактов «имя == C» / «имя != C» по вложенным if
#define МАКС_КОНЪЮНКТОВ 16      // атомов в одном условии (для само-противоречий)

typedef struct {
    char массив[МАКС_ИМЯ];
    char длина[МАКС_ИМЯ];
} СвязьМассива;

typedef struct {
    char переменная[МАКС_ИМЯ];
    long минимальная_длина;
    int известна;
} ОграничениеДлины;

// Полная информация о типе (как в C: базовый тип + косвенность + знаковость).
typedef struct {
    ТипТокена тип;      // ТОКЕН_ЦЕЛОЕ32 и т.д.; ТОКЕН_НЕИЗВЕСТНЫЙ = «не знаем»;
                        // ТОКЕН_СТРУКТУРА — пользовательская структура (см. индекс)
    int указатели;      // число уровней «*»
    int беззнаковый;    // префикс «неподписанный»
    int срез;           // тип «срез<T>»; тип = тип элемента T
    int индекс_структуры; // для ТОКЕН_СТРУКТУРА: индекс в таблице структур, иначе -1
    // ВНИМАНИЕ: новые поля добавлять сюда ТОЛЬКО с обновлением всех позиционных
    // инициализаторов «{ тип, указатели, беззнаковый, срез, индекс }» — их по
    // коду больше тридцати. «поток<T>»/«Ящик<T>» в ИнфоТипа не нужны: их флаг
    // живёт в переменной (Символ.поток/Символ.ящик), а «Ящик» в выражении ведёт
    // себя как обычный указатель T* (указатели=1) — доступ «б.поле» работает без
    // отдельного бита; владение/move/autofree опираются на Символ.
} ИнфоТипа;

// Специальный маркер для nullptr: совместим с любым указателем.
#define ТОКЕН_НУЛ_УКАЗАТЕЛЬ ТОКЕН_НУЛЬ

static ИнфоТипа ТИП_НЕИЗВЕСТЕН_V = { ТОКЕН_НЕИЗВЕСТНЫЙ, 0, 0, 0, -1 };
static ИнфоТипа ТИП_НИЧЕГО_V = { ТОКЕН_НИЧЕГО, 0, 0, 0, -1 };
static ИнфоТипа ТИП_ЦЕЛОЕ32_V    = { ТОКЕН_ЦЕЛОЕ32,     0, 0, 0, -1 };

// Запись таблицы символов.
typedef struct {
    char имя[МАКС_ИМЯ];
    ТипТокена тип;
    int указатели;
    int массив;
    int беззнаковый;
    int срез;               // переменная — срез<T>
    int владеет_срезом;     // срез владеет памятью (из «выделить» или move),
                            // а не заимствует (параметр функции)
    int перемещён;          // владение ушло (move): использование — ошибка
    Токен токен_move;       // место, где произошёл move (для диагностик
                            // use-after-move и для path-merge владения)
    int индекс_структуры;   // для типа-структуры: индекс в таблице структур, иначе -1
    int длина_известна;     // 1, если длина среза известна на этапе компиляции
    long длина;             // длина среза, если длина_известна
    long длина_2;           // для 2D-массивов «T a[N][M]»: M (0 при 1D-массиве);
                            // первая длина живёт в «длина»/«размер_массива»
    // «срез<T> с = выделить(н)»: длина среза РАВНА значению переменной «н».
    // Пока ни «с», ни «н» не переприсваивались, «и < н» доказывает попадание в
    // границы ровно так же, как «и < длина(с)» → проверку можно снять.
    int длина_из_переменной;
    Токен длина_токен;      // имя «н» (валидно при длина_из_переменной)
    int поток;              // переменная — поток<T> (дескриптор); «присоединить»
                            // потребляет его (перемещён=1 → двойной join ловится)
    int ящик;               // переменная — Ящик<T> (одиночный владеющий heap-
                            // объект): владеет памятью (autofree free), ненулевой,
                            // move как у среза; «б.поле» = «б->поле»
    int буфер;              // переменная — буфер<T> (растущий владеющий буфер).
                            // Также срез=1: читается/индексируется как срез. Длина
                            // ИЗМЕНЯЕМА («добавить»/«перевыделить») → длина_известна
                            // всегда 0; приведение к срез<T> — только аргумент вызова
    Токен аллокатор;        // кастомный аллокатор «в Имя» (длина 0 — дефолтный
                            // calloc/free). Часть идентичности: move разрешён
                            // только между тем же аллокатором (иначе free не тем)
    int атом;               // глобал — атом<T> (_Atomic): изменяемый, атомарный
    int глубина;
    int значение_известно;
    long значение;
    // Указатель может быть нулём на каком-то пути исполнения: объявлен «= нуль»,
    // без инициализатора, переприсвоен «нуль», либо после слияния ветвей, где
    // хотя бы на одном пути он остаётся нулевым. Индексирование/разыменование
    // такого указателя — ошибка компиляции (нулевое разыменование). Поле
    // путь-чувствительно: сливается по «нуль на любом пути → нуль».
    int может_быть_нуль;
    // Скалярная переменная инициализирована (присвоена) к моменту чтения.
    // 0 только для скаляра, объявленного без инициализатора и пока не
    // присвоенного; чтение такого — ошибка (использование до инициализации).
    int инициализирована;
    // Указатель инициализирован строковым литералом (или скопирован из такого).
    // Строковый литерал лежит в .rodata — запись через такой указатель
    // (`с[i] = …`) недопустима (порча/крах). Проверяется статически.
    int из_литерала;
    // Срез<символ> гарантированно NUL-терминирован (§37 п.4): байт по адресу
    // .данные[длина] равен 0, значит .данные годна как C-строка «символ*» без
    // копии. Верно для строкового литерала («"…"» → NUL в .rodata за длиной) и
    // для f-строки в контексте среза (snprintf всегда пишет NUL). Для
    // «выделить»/«клон» и пользовательского байтового содержимого — 0 (NUL за
    // границами буфера был бы OOB-чтением). Используется «вкси» для zero-cost
    // на литералах/f-строках; иначе — рантайм-копия в стек-буфер + NUL.
    int с_нулем;
    // Указатель безопасно вернуть из функции (borrow-провенанс): значение
    // указывает в память, которой владеет ВЫЗЫВАЮЩИЙ (параметр-указатель,
    // «аргументы»), в статику (строковый литерал) или «нуль» — то есть память
    // переживёт возврат и не требует освобождения вызывающим. По умолчанию 0
    // (небезопасно): значения неизвестного/локального происхождения и результаты
    // C-функций вернуть нельзя — так исключены висячие указатели и ручное
    // управление памятью. Проставляется только для доказанно-безопасных источников.
    int безопасен_для_возврата;
    // Параметр по ссылке: 0 — нет; 1 — «изменяемый» (ref); 2 — «вывод» (out).
    // Для out проверяется definite-assignment: присвоен до каждого возврата.
    int по_ссылке;
    // «конст»: переменная иммутабельна — переприсваивание и передача в
    // «изменяемый»/«вывод» запрещены (проверка статическая, нулевая рантайм-цена).
    int неизменяемый;
    // Указатель объявлен как «возможно<T*>» (nullable). Без этого флага указатель
    // ненулевой по умолчанию: «нуль» ему присвоить нельзя, разыменование не
    // требует охранника. Для «возможно» разыменование допустимо только под
    // проверкой на «нуль» (через путь-чувствительный может_быть_нуль).
    int возможно;
} Символ;

typedef struct {
    const char *начало;
    size_t длина;
} ИмяСсылка;

// Доказанно-безопасный диапазон индекса цикла «для (и=c0; …; и=и+ш)», c0≥0,
// ш>0. Верхняя граница задаётся одной из двух форм условия:
//   режим среза:   «и < длина(с)»  → безопасен доступ именно к «с» (его длине);
//   режим предела: «и < N» (конст) → безопасен доступ к любому массиву/срезу
//                                    с известной длиной ≥ N;
//   режим переменной: «и < н»      → безопасен доступ к срезу, созданному как
//                                    «выделить(н)», пока ни он, ни «н» не
//                                    переприсваивались (длина(с) == н).
typedef struct {
    ИмяСсылка индекс;  // переменная-индекс цикла
    ИмяСсылка срез;    // режим среза: имя индексируемой переменной
    int есть_срез;     // 1 — активен режим среза
    long предел;       // режим предела: верхняя граница N
    int есть_предел;   // 1 — активен режим предела
    ИмяСсылка перем;   // режим переменной: имя «н» из условия «и < н»
    int есть_перем;    // 1 — активен режим переменной
} БезопаснаяПара;

#define МАКС_БЕЗОПАСНЫХ 32

// Группа срезов ДОКАЗАННО равной длины (через «утверждать_равные(a, b, …)»).
// Пока группа активна, в каноническом цикле «и < длина(a)» доступ «b[и]»
// безопасен для ЛЮБОГО члена группы — единственная рантайм-проверка длин
// вынесена ИЗ горячего цикла в «утверждать_равные», тело остаётся без проверок
// (векторизуется). Инвариант №1 цел: статика доказывает границу, цена — одна
// проверка вне цикла, а не ветка на каждой итерации. Ключевой паттерн SoA
// (физика/3D): «поз[i] = поз[i] + скор[i]*dt» на срезах-параметрах.
#define МАКС_ЧЛЕНОВ_ГРУППЫ 8
#define МАКС_ГРУПП_ДЛИНЫ 16
typedef struct {
    ИмяСсылка члены[МАКС_ЧЛЕНОВ_ГРУППЫ];
    int число_членов;
    int глубина;    // область объявления утверждения (снимается при выходе)
    int активна;    // сбрасывается при реассайне любого члена (длина изменилась)
} ГруппаРавнойДлины;

// Доказательство «все элементы среза-индексов ∈ [0, длина(база))» (через
// «утверждать_в_границах(индексы, длина(база))»). Даёт косвенный доступ
// индекс-буфера «база[индексы[i]]» БЕЗ рантайм-проверки в горячем цикле (3D:
// «вершины[индексы[i]]»). Одна O(n)-валидация индексов вынесена из цикла.
#define МАКС_ГРАНИЦ_ИНДЕКСОВ 16
typedef struct {
    ИмяСсылка индекс_срез;   // срез индексов (проверен: все элементы < длина(база))
    ИмяСсылка база_срез;     // срез, в который индексируем
    int глубина;
    int активна;             // сбрасывается при реассайне любого из двух срезов
} ГраницаИндексов;
#define МАКС_ФУНКЦИЙ 128

#define МАКС_ПАРАМЕТРОВ 16
#define МАКС_СТРУКТУР 64
#define МАКС_АЛЛОКАТОРОВ 16
#define МАКС_ПОЛЕЙ 32

// Поле структуры: имя + тип (примитив/указатель/вложенная структура/срез).
typedef struct {
    char имя[МАКС_ИМЯ];
    ТипТокена тип;
    int беззнаковый;
    int указатели;
    int индекс_структуры;  // если поле — структура, иначе -1
    // Поле-срез: структура владеет памятью среза (как «выделить»/«клон» для
    // локальной переменной). Инициализируется только в литерале поля при
    // объявлении; переприсваивание поля и «увод» среза из поля в отдельную
    // переменную не поддерживаются — структура остаётся единственным
    // владельцем на весь свой срок жизни (без этого — риск двойного free).
    int срез;
    int буфер;              // поле-«буфер<T>» (растущий буфер): срез=1 тоже.
                            // Структура владеет; «добавить»/«перевыделить» растят
                            // «s.поле»; autofree структуры освобождает как срез-поле
    int массив;             // поле-массив фикс. размера «Тип имя[N]»
    long размер_массива;    // N (при массив=1)
} ПолеСтруктуры;

typedef struct {
    char имя[МАКС_ИМЯ];
    // Токен имени структуры, УКАЗЫВАЮЩИЙ В ИСХОДНИК (переживает анализатор —
    // источники/токены живут до конца кодогена, а сам анализатор освобождается
    // раньше). Нужен, чтобы по «индекс_структуры» получить имя типа для кодогена
    // (каст элемента среза «(Точка*)срез_доступ(…)»): поле «имя» лежит внутри
    // анализатора и к кодогену уже освобождено.
    Токен имя_токен;
    ПолеСтруктуры поля[МАКС_ПОЛЕЙ];
    size_t число_полей;
    char деструктор[МАКС_ИМЯ];  // функция-деструктор из «[удалить = …]»
    int есть_деструктор;
    int это_союз;               // объявлено как «союз» (поля разделяют память)
    int внешний;                // «внешний тип Имя»: непрозрачный C-тип —
                                // полей нет, обращение только через указатель
    int обобщённая;             // шаблон «структура Имя<T>»: по переменной такого
                                // типа НЕ выводим тип-аргумент (ИнфоТипа неотличима
                                // от конкретной специализации) — нужны явные «<>»
} ОписаниеСтруктуры;

#define МАКС_ПЕРЕЧИСЛЕНИЙ 64
#define МАКС_ВАРИАНТОВ 64

#define МАКС_ПОЛЕЙ_ВАРИАНТА 8

// Поле полезной нагрузки варианта sum-типа (примитив или указатель).
typedef struct {
    char имя[МАКС_ИМЯ];
    ТипТокена тип;
    int беззнаковый;
    int указатели;
    int индекс_структуры;   // для payload-структуры/перечисления, иначе -1
} ПолеВарианта;

// Вариант перечисления: имя + вычисленное целое значение (как в C) + (для
// sum-типа) полезная нагрузка.
typedef struct {
    char имя[МАКС_ИМЯ];
    long значение;
    ПолеВарианта поля[МАКС_ПОЛЕЙ_ВАРИАНТА];
    size_t число_полей;     // >0 — вариант несёт данные (sum-тип)
} ВариантПеречисления;

typedef struct {
    char имя[МАКС_ИМЯ];
    ВариантПеречисления варианты[МАКС_ВАРИАНТОВ];
    size_t число_вариантов;
    int это_sum;            // хотя бы один вариант несёт данные → размеченный
                           // союз (tag+union), а не C-enum
} ОписаниеПеречисления;

// Сигнатура функции (тип возврата) — для типизации вызовов, в т.ч. возврата
// среза, который вызывающий принимает: «срез<T> д = создать()». Хранит также,
// какие параметры объявлены «владеет» (потребляют переданный срез — передача
// в них = move аргумента), и тип каждого параметра — нужен для авто-конверсии
// массива в срез на месте вызова (`сумма(а)` при `срез<целое32>`-параметре).
typedef struct {
    ТипТокена тип;
    int беззнаковый;
    int указатели;
    int срез;
    int буфер;             // параметр — «буфер<T>» (обычно «изменяемый буфер<T>»:
                           // функция растит буфер вызывающего по ссылке)
    int индекс_структуры;  // для тип==ТОКЕН_ФУНКУКАЗАТЕЛЬ: индекс типфункции-псевдонима
    int по_ссылке;         // 0 — по значению; 1 — «изменяемый» (ref); 2 — «вывод» (out)
} ИнфоПараметра;

// Почему функция признана нечистой. Хранится в сигнатуре, чтобы диагностика
// на месте вызова могла назвать ПРИЧИНУ и позицию, а не просто «не чистая».
typedef enum {
    ЭФФЕКТ_НЕТ = 0,
    ЭФФЕКТ_ССЫЛОЧНЫЙ_ПАРАМЕТР,   // «изменяемый»/«вывод» — запись в кадр вызывающего
    ЭФФЕКТ_УКАЗАТЕЛЬ_ПАРАМЕТР,   // указатель — можно писать в чужую память
    ЭФФЕКТ_ВЛАДЕЕТ_ПАРАМЕТР,     // потребляет срез (в общем срезе → double-free)
    ЭФФЕКТ_ЗАПИСЬ_В_СРЕЗ,        // пишет в срез-параметр — общие данные
    ЭФФЕКТ_ПОТОК,                // запустить/присоединить/параллельно
    ЭФФЕКТ_ВЫДЕЛЕНИЕ,            // выделить/клон (v1 — консервативно)
    ЭФФЕКТ_НЕБЕЗОПАСНО,          // внутри «небезопасно» возможен сырой указатель
    ЭФФЕКТ_ВЫЗОВ_НЕЧИСТОЙ,       // зовёт нечистую
    ЭФФЕКТ_ВНЕШНЯЯ               // зовёт внешнюю/libc — об эффектах ничего не известно
} ВидЭффекта;

typedef struct {
    char имя[МАКС_ИМЯ];
    ТипТокена тип_возврата;
    int беззнаковый;
    int указатели_возврата;   // косвенность типа возврата «Тип*»
    int срез;
    // Возврат-заимствование (§37 п.6, выводится пред-проходом «вывести_владение_
    // возврата», хранится тут как чистота): 1 — функция возвращает ЗАИМСТВОВАННЫЙ
    // срез (все возвраты — литералы/borrow-параметры/вызовы borrow-функций), 0 —
    // ВЛАДЕЮЩИЙ (есть возврат из «выделить»/«клон»/владеющей локали). Смешанный
    // (и то, и другое) — «возврат_смешанный=1», ошибка на месте возврата. Значимо
    // только при срез==1. На call-site решает, регистрировать ли результат в
    // autofree — компайл-тайм, нулевая рантайм-цена.
    int возврат_заимствован;
    int возврат_смешанный;
    // Для тип_возврата == ТОКЕН_СТРУКТУРА/ТОКЕН_ПЕРЕЧИСЛЕНИЕ: индекс типа в
    // соответствующей таблице (структуры/перечисления) — нужен, чтобы вызов
    // такой функции типизировался как конкретный тип, а не общее «структура»/
    // «перечисление» (иначе совместимы_для_присваивания не отличит одну
    // структуру от другой).
    int индекс_структуры_возврата;
    int владеет_параметра[МАКС_ПАРАМЕТРОВ];
    ИнфоПараметра параметры[МАКС_ПАРАМЕТРОВ];
    size_t число_параметров;
    // Чистота — выводится (не объявляется): у языка нет глобалов, поэтому
    // эффект наружу возможен только через «изменяемый»/«вывод», запись в
    // срез-параметр, указатель, «небезопасно» или вызов нечистой/внешней.
    // Нужна, чтобы пускать вызовы в тело «параллельно для»: чистый вызов не
    // может создать гонку. Заполняет «вывести_чистоту» до анализа тел.
    int чистая;
    ВидЭффекта вид_эффекта;   // почему нечистая (для диагностики)
    Токен где_эффект;         // позиция эффекта
    char имя_эффекта[МАКС_ИМЯ];  // имя параметра/функции, из-за которой нечистая
    // Обобщённая функция-шаблон (ведущие УЗЕЛ_ТИПОПАРАМЕТР) — для вывода
    // тип-аргументов на проходе вывода (см. вывести_типоаргументы). Тип-параметры
    // в порядке объявления; для каждого параметра — имя тип-параметра, если его
    // тип — «голый» тип-параметр T (длина 0 — параметр не тип-параметр).
    int обобщённая;
    size_t число_типопарам;
    Токен типопарам[8];
    Токен имя_типопарам_параметра[МАКС_ПАРАМЕТРОВ];
    Токен имя_типопарам_возврата;  // имя T, если тип возврата — «голый» T (иначе длина 0)
    int возврат_возможно;  // тип возврата — «возможно<T*>» (nullable): результат
                           // вызова может быть нулём → дереф только под охранником
} СигнатураФункции;

// Именованный тип-указатель на функцию («типфункции RET Имя(…)»): подпись, с
// которой сверяется присваиваемая функция и вызов через указатель.
typedef struct {
    char имя[МАКС_ИМЯ];
    ТипТокена тип_возврата;
    int беззнаковый_возврата;
    int указатели_возврата;
    int индекс_структуры_возврата;
    ИнфоПараметра параметры[МАКС_ПАРАМЕТРОВ];
    size_t число_параметров;
} ОписаниеТипфункции;

#define МАКС_ТИПФУНКЦИЙ 64

#define МАКС_СЛУШАТЕЛЕЙ 64
// Тип типизированного слушателя: «внешний слушатель<T> Имя для C_тип { … }».
// userdata_* — тип T (каст void*→T прячется в трампулине); c_имя — имя
// C-структуры (кодоген печатает её в литерале). Узел объявления держит
// сигнатуры полей (для трампулинов); здесь — только валидационная сводка.
typedef struct {
    char имя[МАКС_ИМЯ];
    ТипТокена userdata_тип;
    int userdata_индекс;      // индекс структуры T (или -1)
    int userdata_указатели;   // косвенность T (обычно 0: T по значению)
    char c_имя[МАКС_ИМЯ];     // имя C-структуры слушателя
    const Узел *узел;         // узел объявления (для кодогена: сигнатуры полей)
} ОписаниеСлушателя;

// Экземпляр слушателя: «Имя экз = { … }». Связывает имя с типом слушателя.
typedef struct {
    char имя[МАКС_ИМЯ];
    int индекс_типа;          // индекс в слушатель_типы
} ЭкземплярСлушателя;

// Факт о значении переменной, установленный условием if в объемлющей then-ветви:
// «имя == значение» (равно=1) или «имя != значение» (равно=0). Стек по областям
// (как ограничения): выход из блока снимает факты этого блока. Мутация переменной
// (присваивание/++/изменяемый-вывод) деактивирует факт (активен=0) — консервативно
// навсегда в текущей области, чтобы никогда не выдать ложное «код недостижим».
// Служит статической проверкой недостижимого кода: если условие вложенного if
// противоречит накопленным фактам — оно никогда не истинно (ошибка, инвариант №5).
typedef struct {
    char переменная[МАКС_ИМЯ];
    long значение;
    int  равно;               // 1: известно «имя == значение»; 0: «имя != значение»
    int  активен;             // 0 после инвалидации мутацией
    Токен позиция;            // токен переменной в условии — для каретки диагностики
} Факт;

typedef struct Анализатор {
    Диагностика *диаг;
    СвязьМассива связи[МАКС_СВЯЗЕЙ_МАССИВОВ];
    size_t число_связей;
    ОграничениеДлины ограничения[МАКС_ГЛУБИНА_ОГРАНИЧЕНИЙ];
    size_t глубина_ограничений;
    // Стек фактов «имя == C» / «имя != C» из условий объемлющих if (then-ветви).
    // Проверка недостижимого кода: условие вложенного if, противоречащее фактам,
    // никогда не истинно. Область — как у ограничений (снимается на выходе блока).
    Факт факты[МАКС_ФАКТОВ];
    size_t число_фактов;
    Символ символы[МАКС_СИМВОЛОВ];
    size_t число_символов;
    // Глобальные «конст»-константы верхнего уровня. Отдельный массив: рабочая
    // таблица символов сбрасывается между функциями (батч-режим), а константы
    // видны всем. СТРОГО иммутабельны (инвариант №4: глобальных ПЕРЕМЕННЫХ в
    // языке нет — гонки остаются невыразимыми, констант это не касается).
    Символ глобальные[МАКС_ГЛОБАЛЬНЫХ_КОНСТ];
    size_t число_глобальных;
    int глубина;
    int глубина_небезопасно;  // 0 — безопасный код; >0 — внутри «небезопасно { }».
                              // Разрешает операции с сырыми указателями
                              // (арифметика/индексация без проверки границ).
    int глубина_цикла;       // 0 — вне цикла, >0 — внутри пока/для (учёт
                             // нужен для запрета move источника из внешней
                             // области в теле цикла: на втором витке источник
                             // уже перемещён → use-after-move; статический
                             // однопроходный анализ это безопасно не разрешит)
    ИмяСсылка изменяемые[МАКС_СИМВОЛОВ];
    size_t число_изменяемых;
    // Стек доказанно-безопасных доступов (по одной паре на вложенный цикл).
    БезопаснаяПара безопасные[МАКС_БЕЗОПАСНЫХ];
    size_t число_безопасных;
    // Группы срезов равной длины («утверждать_равные»); стек по областям.
    ГруппаРавнойДлины группы_длины[МАКС_ГРУПП_ДЛИНЫ];
    size_t число_групп_длины;
    // Доказательства границ индекс-срезов («утверждать_в_границах»); стек.
    ГраницаИндексов границы_индексов[МАКС_ГРАНИЦ_ИНДЕКСОВ];
    size_t число_границ_индексов;
    // Тип возврата текущей функции (для проверки «вернуть»).
    ТипТокена тип_возврата;
    int беззнаковый_возврата;
    int указатели_возврата;
    int срез_возврата;       // функция возвращает срез<T>
    int возврат_заимствован_текущей;  // §37 п.6: текущая функция заимствует-возврат
    int возврат_смешанный_текущей;    // §37 п.6: смешанный возврат (ошибка на месте)
    int индекс_структуры_возврата;  // для СТРУКТУРА/ПЕРЕЧИСЛЕНИЕ: индекс типа
    // Сигнатуры всех функций (собираются до анализа тел — для вызовов вперёд).
    СигнатураФункции функции[МАКС_ФУНКЦИЙ];
    size_t число_функций;
    // Объявленные пользовательские структуры.
    ОписаниеСтруктуры структуры[МАКС_СТРУКТУР];
    size_t число_структур;
    ОписаниеТипфункции типыфункций[МАКС_ТИПФУНКЦИЙ];
    size_t число_типовфункций;
    // Объявленные перечисления.
    ОписаниеПеречисления перечисления[МАКС_ПЕРЕЧИСЛЕНИЙ];
    size_t число_перечислений;
    // Кастомные аллокаторы «аллокатор Имя { выделить=f освободить=g }».
    const Узел *аллокаторы[МАКС_АЛЛОКАТОРОВ];
    size_t число_аллокаторов;
    // Типизированные слушатели и их экземпляры.
    ОписаниеСлушателя слушатель_типы[МАКС_СЛУШАТЕЛЕЙ];
    size_t число_слушателей;
    ЭкземплярСлушателя слушатель_экземпляры[МАКС_СЛУШАТЕЛЕЙ];
    size_t число_экземпляров;
    // Внешние (C) функции, увиденные через заголовки. nullptr — заголовки не
    // сканировались (старый режим): тогда неизвестные вызовы не диагностируются
    // на уровне Konda (совместимость + escape-hatch для interop).
    const ТаблицаВнешних *внешние;
    // Накопитель предупреждений (не фатальных): элементы — Диагностика. nullptr,
    // если предупреждения не собираются. Заполняется, например, при вызове
    // функции, не объявленной ни в Konda, ни в подключённых заголовках.
    ДинМассив *предупреждения;
    // Накопитель ошибок для батч-режима (IDE/CLI: показать все ошибки сразу).
    // nullptr — старое поведение: анализ останавливается на первой ошибке.
    // Иначе на границе оператора/функции ошибка сливается сюда, состояние
    // анализатора восстанавливается до снимка, и разбор продолжается.
    ДинМассив *ошибки;
    // Проход вывода тип-аргументов (гибрид): диагностики подавляются (дерево ещё
    // не мономорфизировано — реальные ошибки даст проход 2), а обобщённые вызовы
    // без явных «<>» аннотируются выведенными тип-аргументами. См.
    // вывести_типоаргументы.
    int режим_вывода;
} Анализатор;

// Предел собираемых ошибок — защита от лавины на патологическом вводе.
#define МАКС_СОБИРАЕМЫХ_ОШИБОК 200

// Сливает текущую (первую) ошибку в список батч-режима и сбрасывает флаг, чтобы
// анализ мог продолжиться. Ничего не делает, если батч-режим не включён или
// ошибки нет. Возвращает 1, если анализ можно продолжать (место в списке есть).
static int собрать_ошибку(struct Анализатор *а)
{
    if (!а->ошибки || !а->диаг->ошибка) return а->ошибки != nullptr;
    if (а->ошибки->длина < МАКС_СОБИРАЕМЫХ_ОШИБОК) {
        Диагностика д = {0};
        д.строка = а->диаг->строка;
        д.колонка = а->диаг->колонка;
        snprintf(д.сообщение, sizeof(д.сообщение), "%s", а->диаг->сообщение);
        дин_массив_добавить(а->ошибки, &д);
    }
    а->диаг->ошибка = 0;  // сброс — можно продолжать
    а->диаг->сообщение[0] = '\0';
    return а->ошибки->длина < МАКС_СОБИРАЕМЫХ_ОШИБОК;
}

// Добавляет предупреждение (не прерывает анализ). Работает, только если
// накопитель задан.
static void предупреждение_семантики(struct Анализатор *а, const Токен *t,
                                     const char *текст)
{
    if (а->режим_вывода) return;  // проход вывода тип-аргументов не диагностирует
    if (!а->предупреждения) return;
    Диагностика д = {0};
    д.строка = t ? t->строка : 0;
    д.колонка = t ? t->позиция_в_строке : 0;
    snprintf(д.сообщение, sizeof(д.сообщение), "%s", текст);
    дин_массив_добавить(а->предупреждения, &д);
}

// ─── вспомогательные ────────────────────────────────────────────────────────

static int байты_равны(const char *a, size_t la, const char *b, size_t lb)
{
    return la == lb && memcmp(a, b, la) == 0;
}

static int токен_текст_равен(const Токен *t, const char *текст)
{
    return байты_равны(t->начало, t->длина, текст, strlen(текст));
}

// Закрытый список функций libc с неограниченной записью в буфер/разбором
// формата: классические источники переполнения буфера. Их вызов из безопасного
// кода запрещён — только в «небезопасно { }». Проверка чисто статическая
// (нулевая рантайм-цена); список намеренно узкий (безусловно опасные функции),
// чтобы не мешать обычному interop (printf, strlen, malloc и т.п. — разрешены).
static int libc_небезопасна(const char *имя, size_t длина)
{
    static const char *const список[] = {
        "gets",              // читает stdin без границ буфера
        "strcpy",  "strcat", // копирование/конкатенация строк без границ
        "stpcpy",
        "sprintf", "vsprintf", // форматирование в буфер без границ
        "wcscpy",  "wcscat", // широкие аналоги
    };
    for (size_t i = 0; i < sizeof(список) / sizeof(список[0]); ++i) {
        if (байты_равны(имя, длина, список[i], strlen(список[i]))) return 1;
    }
    return 0;
}

// Индекс структуры по имени-токену; -1 если не найдена.
static int найти_индекс_структуры(const Анализатор *а, const Токен *имя)
{
    for (size_t i = 0; i < а->число_структур; ++i) {
        if (байты_равны(а->структуры[i].имя, strlen(а->структуры[i].имя),
                        имя->начало, имя->длина)) {
            return (int)i;
        }
    }
    return -1;
}

// Узел кастомного аллокатора по имени-токену; nullptr если не объявлен.
static const Узел *найти_аллокатор(const Анализатор *а, const Токен *имя)
{
    if (!имя || имя->длина == 0) return nullptr;
    for (size_t i = 0; i < а->число_аллокаторов; ++i) {
        const Токен *н = &а->аллокаторы[i]->токен;
        if (н->длина == имя->длина
            && memcmp(н->начало, имя->начало, имя->длина) == 0)
            return а->аллокаторы[i];
    }
    return nullptr;
}

// Индекс типа-указателя на функцию по имени-токену; -1 если не найден.
static int найти_индекс_типфункции(const Анализатор *а, const Токен *имя)
{
    for (size_t i = 0; i < а->число_типовфункций; ++i) {
        if (байты_равны(а->типыфункций[i].имя, strlen(а->типыфункций[i].имя),
                        имя->начало, имя->длина)) {
            return (int)i;
        }
    }
    return -1;
}

static СигнатураФункции *найти_сигнатуру_по_имени(Анализатор *а,
                                                  const char *начало, size_t длина)
{
    for (size_t i = 0; i < а->число_функций; ++i)
        if (байты_равны(а->функции[i].имя, strlen(а->функции[i].имя), начало, длина))
            return &а->функции[i];
    return nullptr;
}

// Сигнатура функции совпадает с типом-указателем (возврат + параметры)?
// Два типфункции-псевдонима совместимы (одинаковая сигнатура)? Нужно для
// диспетч-таблиц: «Фнптр fp = т[i].функ», где т[i].функ имеет ДРУГОЙ псевдоним
// с той же сигнатурой (напр. авто-имя поля «команда_функ» vs локальный «Фнптр1»).
static int типфункции_совместимы(const ОписаниеТипфункции *a,
                                  const ОписаниеТипфункции *b)
{
    if (a->тип_возврата != b->тип_возврата) return 0;
    if (a->указатели_возврата != b->указатели_возврата) return 0;
    if (a->беззнаковый_возврата != b->беззнаковый_возврата) return 0;
    if (a->число_параметров != b->число_параметров) return 0;
    for (size_t i = 0; i < a->число_параметров; ++i) {
        if (a->параметры[i].тип != b->параметры[i].тип) return 0;
        if (a->параметры[i].указатели != b->параметры[i].указатели) return 0;
        if (a->параметры[i].срез != b->параметры[i].срез) return 0;
        if (a->параметры[i].беззнаковый != b->параметры[i].беззнаковый) return 0;
    }
    return 1;
}

static int сигнатура_совпадает_с_типфункцией(const СигнатураФункции *с,
                                             const ОписаниеТипфункции *т)
{
    if (с->тип_возврата != т->тип_возврата) return 0;
    if (с->указатели_возврата != т->указатели_возврата) return 0;
    if (с->беззнаковый != т->беззнаковый_возврата) return 0;
    if (с->число_параметров != т->число_параметров) return 0;
    for (size_t i = 0; i < с->число_параметров; ++i) {
        if (с->параметры[i].тип != т->параметры[i].тип) return 0;
        if (с->параметры[i].указатели != т->параметры[i].указатели) return 0;
        if (с->параметры[i].срез != т->параметры[i].срез) return 0;
        if (с->параметры[i].беззнаковый != т->параметры[i].беззнаковый) return 0;
    }
    return 1;
}

static void ошибка_семантики(Анализатор *а, const Токен *t, const char *текст);

// Структуре по индексу нужна деструкция? Да, если у неё есть собственный
// деструктор ИЛИ хотя бы одно поле-структура (по значению) транзитивно требует
// деструкции. Поле-структура по значению может ссылаться только на уже
// объявленную структуру (найти_индекс_структуры ищет среди зарегистрированных
// ранее), поэтому цепочка полей — DAG по порядку объявления и не может
// зациклиться: настоящий предел глубины — число различных структур в
// программе. Раньше здесь стоял фиксированный «глубина > 16» — для более
// глубокой (но валидной) вложенности деструктор молча пропускался в кодогене
// без единой диагностики (тихая утечка ресурса). Бонус: раз цикл структурно
// невозможен, при превышении границы (не должно происходить) — не «нет
// деструкции», а явная ошибка компиляции, чтобы баг не маскировался утечкой.
static int структура_индекс_нужна_деструкция(Анализатор *а, int индекс,
                                              int глубина)
{
    if (индекс < 0 || (size_t)индекс >= а->число_структур) return 0;
    if ((size_t)глубина > а->число_структур) {
        // Структурно недостижимо: поле-структура по значению может ссылаться
        // только на уже объявленную структуру, значит цикла быть не может, а
        // цепочка не длиннее числа структур в программе. Если всё же сюда
        // попали — внутренняя ошибка анализатора; явная диагностика лучше
        // тихого «деструкции нет» (утечка ресурса без единого сообщения).
        char msg[256];
        snprintf(msg, sizeof(msg),
            "не удалось определить необходимость деструкции структуры «%s»: "
            "цепочка вложенных полей длиннее числа объявленных структур",
            а->структуры[индекс].имя);
        ошибка_семантики(а, nullptr, msg);
        return 0;
    }
    const ОписаниеСтруктуры *с = &а->структуры[индекс];
    if (с->есть_деструктор) return 1;
    for (size_t i = 0; i < с->число_полей; ++i) {
        const ПолеСтруктуры *п = &с->поля[i];
        // Поле-срез — сама структура владеет его памятью (free при выходе из
        // области), это тоже «нужна деструкция», как собственный деструктор.
        if (п->срез) return 1;
        if (п->тип == ТОКЕН_СТРУКТУРА && п->указатели == 0
            && структура_индекс_нужна_деструкция(а, п->индекс_структуры, глубина + 1))
            return 1;
    }
    return 0;
}

// Индекс перечисления по имени-токену; -1 если не найдено.
static int найти_индекс_перечисления(const Анализатор *а, const Токен *имя)
{
    for (size_t i = 0; i < а->число_перечислений; ++i) {
        if (байты_равны(а->перечисления[i].имя, strlen(а->перечисления[i].имя),
                        имя->начало, имя->длина)) {
            return (int)i;
        }
    }
    return -1;
}

// Идентификатор — вариант какого-либо перечисления? Возвращает индекс
// перечисления (или -1) и кладёт значение варианта в *значение.
static int найти_вариант(const Анализатор *а, const char *имя, size_t длина,
                          long *значение)
{
    for (size_t i = 0; i < а->число_перечислений; ++i) {
        const ОписаниеПеречисления *п = &а->перечисления[i];
        for (size_t j = 0; j < п->число_вариантов; ++j) {
            if (байты_равны(п->варианты[j].имя, strlen(п->варианты[j].имя),
                            имя, длина)) {
                if (значение) *значение = п->варианты[j].значение;
                return (int)i;
            }
        }
    }
    return -1;
}

// Находит вариант по имени и возвращает его вместе с описанием перечисления и
// индексами (перечисление/вариант). Возвращает индекс перечисления или -1.
static int найти_вариант_подробно(const Анализатор *а, const char *имя, size_t длина,
                                   const ОписаниеПеречисления **вых_п,
                                   const ВариантПеречисления **вых_в, int *вых_вар)
{
    for (size_t i = 0; i < а->число_перечислений; ++i) {
        const ОписаниеПеречисления *п = &а->перечисления[i];
        for (size_t j = 0; j < п->число_вариантов; ++j) {
            if (байты_равны(п->варианты[j].имя, strlen(п->варианты[j].имя),
                            имя, длина)) {
                if (вых_п) *вых_п = п;
                if (вых_в) *вых_в = &п->варианты[j];
                if (вых_вар) *вых_вар = (int)j;
                return (int)i;
            }
        }
    }
    return -1;
}

// Тип — структура-значение (не указатель), требующая деструкции? Такие нельзя
// копировать/присваивать/передавать по значению — был бы двойной вызов
// деструктора (в т.ч. вложенного, если деструктор у поля).
static int структура_с_деструктором(Анализатор *а, ИнфоТипа т)
{
    return т.тип == ТОКЕН_СТРУКТУРА && т.указатели == 0
        && структура_индекс_нужна_деструкция(а, т.индекс_структуры, 0);
}

static void ошибка_семантики(Анализатор *а, const Токен *t, const char *текст)
{
    if (а->режим_вывода) return;  // проход вывода тип-аргументов не диагностирует
    if (а->диаг->ошибка) return;
    а->диаг->ошибка = 1;
    а->диаг->строка = t ? t->строка : 0;
    а->диаг->колонка = t ? t->позиция_в_строке : 0;
    snprintf(а->диаг->сообщение, sizeof(а->диаг->сообщение), "%s", текст);
}

// Внутренняя таблица анализатора (функции/структуры/перечисления/…) переполнена.
// Раньше такие лимиты молча обрывали сбор (`break`/`return`) — «лишняя» сущность
// тихо пропадала, а дальше вылезала непонятная «не найдена»/битый C. Теперь это
// явная ошибка транспиляции с позицией: пользователь видит причину, а не
// молчаливую мискомпиляцию (безопасность/предсказуемость важнее «работает пока
// не упрёшься»). Возвращает 0 — вызывающему удобно писать `return`/`break`.
static int переполнение_таблицы(Анализатор *а, const Токен *где,
                                const char *что, size_t предел)
{
    char msg[256];
    snprintf(msg, sizeof(msg),
             "слишком много: %s (предел компилятора — %zu); "
             "разбейте программу на модули или сообщите об ограничении",
             что, предел);
    ошибка_семантики(а, где, msg);
    // Сбор сущностей идёт ДО главного цикла-дренажа: в батч-режиме ошибку нужно
    // затолкнуть в список сразу, иначе она не всплывёт (диаг сбрасывается).
    if (а->ошибки) собрать_ошибку(а);
    return 0;
}

// Имена хранятся в char[МАКС_ИМЯ]; при копировании оно молча усекалось до 127
// БАЙТ. Два идентификатора с общим 127-байтным префиксом слились бы в один →
// ложная резолюция без диагностики (кириллица в UTF-8 «толще»: ~63 символа).
// Fail-closed: слишком длинное имя — явная ошибка, а не тихое усечение.
// Возвращает 1, если имя не помещается (вызывающий пропускает сущность).
static int имя_слишком_длинное(Анализатор *а, const Токен *где, size_t длина)
{
    if (длина < (size_t)МАКС_ИМЯ) return 0;
    char msg[128];
    snprintf(msg, sizeof msg,
             "имя слишком длинное (%zu байт, предел — %d): укоротите идентификатор",
             длина, МАКС_ИМЯ - 1);
    ошибка_семантики(а, где, msg);
    if (а->ошибки) собрать_ошибку(а);
    return 1;
}

// Definite-assignment для «вывод»-параметров: каждый out обязан быть присвоен
// на пути, доходящем до этой точки (перед «вернуть» и в конце тела на fall-
// through). Использует путь-чувствительный флаг «инициализирована» (сливается
// по ветвям: присвоен только если на всех путях). Вызывается там, где путь
// покидает функцию.
static void проверить_вывод_присвоен(Анализатор *а, const Токен *где)
{
    for (size_t i = 0; i < а->число_символов; ++i) {
        Символ *с = &а->символы[i];
        if (с->по_ссылке == 2 && !с->инициализирована) {
            char msg[256];
            snprintf(msg, sizeof msg,
                "выходной параметр «%s» не присвоен до возврата "
                "(«вывод» обязан быть присвоен по всем путям)", с->имя);
            ошибка_семантики(а, где, msg);
        }
    }
}

// ─── работа с типами ────────────────────────────────────────────────────────

static int тип_арифметический(ИнфоТипа т)
{
    if (т.срез || т.указатели > 0) return 0;
    switch (т.тип) {
        case ТОКЕН_ЦЕЛОЕ8: case ТОКЕН_ЦЕЛОЕ16:
        case ТОКЕН_ЦЕЛОЕ32: case ТОКЕН_ЦЕЛОЕ64:
        case ТОКЕН_БАЙТ: case ТОКЕН_ВЕЩЕСТВЕННОЕ: case ТОКЕН_ВЕЩЕСТВЕННОЕ64:
        case ТОКЕН_ЛОГИЧЕСКИЙ:    // bool в C — целочисленный тип; арифметика/условия
        case ТОКЕН_ПЕРЕЧИСЛЕНИЕ:  // enum в C — целое; в выражениях ведёт себя как int
            return 1;
        default: return 0;
    }
}

static int тип_целочисленный(ИнфоТипа т)
{
    if (т.срез || т.указатели > 0) return 0;
    switch (т.тип) {
        case ТОКЕН_ЦЕЛОЕ8: case ТОКЕН_ЦЕЛОЕ16:
        case ТОКЕН_ЦЕЛОЕ32: case ТОКЕН_ЦЕЛОЕ64:
        case ТОКЕН_БАЙТ: case ТОКЕН_ПЕРЕЧИСЛЕНИЕ: return 1;
        default: return 0;
    }
}

static int тип_указатель(ИнфоТипа т)
{
    if (т.срез) return 0;
    return т.указатели > 0 || т.тип == ТОКЕН_НУЛ_УКАЗАТЕЛЬ;
}

static int тип_скалярный(ИнфоТипа т)
{
    return тип_арифметический(т) || тип_указатель(т);
}

// Человекочитаемое описание типа для сообщений об ошибках.
static void описание_типа(ИнфоТипа т, char *out, size_t cap)
{
    const char *база;
    switch (т.тип) {
        case ТОКЕН_ЦЕЛОЕ8:       база = т.беззнаковый ? "неподписанный целое8"  : "целое8";  break;
        case ТОКЕН_ЦЕЛОЕ16:      база = т.беззнаковый ? "неподписанный целое16" : "целое16"; break;
        case ТОКЕН_ЦЕЛОЕ32:      база = т.беззнаковый ? "неподписанный целое32" : "целое32"; break;
        case ТОКЕН_ЦЕЛОЕ64:      база = т.беззнаковый ? "неподписанный целое64" : "целое64"; break;
        case ТОКЕН_БАЙТ:         база = "байт";         break;
        case ТОКЕН_ВЕЩЕСТВЕННОЕ: база = "вещественное"; break;
        case ТОКЕН_ВЕЩЕСТВЕННОЕ64: база = "вещественное64"; break;
        case ТОКЕН_ТИП_СИМВОЛ:  база = "символ";        break;
        case ТОКЕН_ЛОГИЧЕСКИЙ:  база = "логический";    break;
        case ТОКЕН_НИЧЕГО:      база = "ничего";        break;
        case ТОКЕН_СТРУКТУРА:    база = "структура";    break;
        case ТОКЕН_ПЕРЕЧИСЛЕНИЕ: база = "перечисление"; break;
        case ТОКЕН_НУЛ_УКАЗАТЕЛЬ: snprintf(out, cap, "нуль"); return;
        case ТОКЕН_НЕИЗВЕСТНЫЙ:  snprintf(out, cap, "<неизвестный>"); return;
        default:                 база = "?"; break;
    }
    if (т.срез) {
        snprintf(out, cap, "срез<%s>", база);
    } else if (т.указатели == 0) {
        snprintf(out, cap, "%s", база);
    } else {
        char звёзды[16] = {0};
        int n = т.указатели < 8 ? т.указатели : 8;
        for (int i = 0; i < n; ++i) звёзды[i] = '*';
        snprintf(out, cap, "%s%s", база, звёзды);
    }
}

// Совместимость типов при присваивании: цель ← источник.
// Правила как в C (без явного приведения):
//   - оба арифметические → OK (неявные числовые преобразования)
//   - цель = указатель, источник = нуль → OK
//   - оба указатели одного базового типа и уровня → OK
//   - указатель ← арифметика → ОШИБКА
//   - арифметика ← указатель → ОШИБКА
//   - указатели разных типов → ОШИБКА
static int совместимы_для_присваивания(ИнфоТипа цель, ИнфоТипа источник)
{
    // Срезы: цель-срез принимает только срез. Источник с неизвестным типом
    // элемента (результат «выделить») совместим с любым срезом.
    if (цель.срез || источник.срез) {
        if (!цель.срез || !источник.срез)
            return 0;  // срез ↔ не-срез несовместимы
        if (источник.тип == ТОКЕН_НЕИЗВЕСТНЫЙ || цель.тип == ТОКЕН_НЕИЗВЕСТНЫЙ)
            return 1;  // выделить(...) либо неизвестный элемент
        // Тип элемента должен совпасть полностью: базовый тип, знаковость,
        // косвенность (срез<T> ≠ срез<T*>) и — для структур — конкретная
        // структура (срез<Точка> ≠ срез<Цвет>).
        return цель.тип == источник.тип
            && цель.беззнаковый == источник.беззнаковый
            && цель.указатели == источник.указатели
            && цель.индекс_структуры == источник.индекс_структуры;
    }

    // nullptr → любой указатель (в т.ч. на структуру/перечисление/«внешний тип»).
    // Должно стоять ДО веток структуры/перечисления, иначе «возможно<Структура*>
    // п = нуль» отвергалось бы как «структура ← не-структура». Сама допустимость
    // «= нуль» (только для nullable «возможно<T*>») проверяется отдельно.
    if (тип_указатель(цель) && источник.тип == ТОКЕН_НУЛ_УКАЗАТЕЛЬ)
        return 1;

    // Структуры: совместимы только одинаковые структуры той же косвенности.
    if (цель.тип == ТОКЕН_СТРУКТУРА || источник.тип == ТОКЕН_СТРУКТУРА) {
        return цель.тип == ТОКЕН_СТРУКТУРА && источник.тип == ТОКЕН_СТРУКТУРА
            && цель.индекс_структуры == источник.индекс_структуры
            && цель.указатели == источник.указатели;
    }

    // Перечисления: enum ← enum того же типа (или его вариант) — OK; enum → целое
    // (расширение, как в C) — OK; целое → enum запрещено (нужен явный вариант),
    // как и смешение разных перечислений.
    if (цель.тип == ТОКЕН_ПЕРЕЧИСЛЕНИЕ || источник.тип == ТОКЕН_ПЕРЕЧИСЛЕНИЕ) {
        if (цель.тип == ТОКЕН_ПЕРЕЧИСЛЕНИЕ && источник.тип == ТОКЕН_ПЕРЕЧИСЛЕНИЕ)
            return цель.индекс_структуры == источник.индекс_структуры;
        if (источник.тип == ТОКЕН_ПЕРЕЧИСЛЕНИЕ && тип_целочисленный(цель))
            return 1;  // enum → целое
        return 0;       // целое → enum и прочее — запрещено
    }

    if (цель.тип == ТОКЕН_НЕИЗВЕСТНЫЙ || источник.тип == ТОКЕН_НЕИЗВЕСТНЫЙ)
        return 1;  // неизвестный тип — не проверяем

    int ц_ук = тип_указатель(цель);
    int и_ук = тип_указатель(источник);

    // nullptr → любой указатель
    if (ц_ук && источник.тип == ТОКЕН_НУЛ_УКАЗАТЕЛЬ)
        return 1;

    // оба арифметические
    if (!ц_ук && !и_ук)
        return 1;

    // указатель ← арифметика  или  арифметика ← указатель
    if (ц_ук != и_ук)
        return 0;

    // оба указатели: проверяем базовый тип и уровень косвенности
    return цель.тип == источник.тип && цель.указатели == источник.указатели;
}

// Коэрция строкового литерала ИЛИ f-строки в «срез<символ>» (§37): проверяет
// форму цели (срез<символ>: срез=1, тип=символ, указатели=0) и что источник —
// строковый литерал (УЗЕЛ_СТРОКА, борроу над .rodata) или f-строка
// (УЗЕЛ_F_СТРОКА, борроу над стек-буфером той же функции). Метит узел-источник
// `->срез=1`, чтобы кодоген эмитил его как заимствованный срез (для литерала —
// над .rodata с длиной sizeof-1; для f-строки — над стек-буфером с длиной от
// snprintf). Обе формы БОРРОУ: autofree их не трогает; возврат из функции
// небезопасен (стек умирает) — блокируется на сайте возврата. Применяется в
// присваивании/вызове/возврате ДО совместимы_для_присваивания.
static int коэрция_литерал_в_срез_символ(ИнфоТипа цель, Узел *источник)
{
    if (!источник) return 0;
    if (источник->тип != УЗЕЛ_СТРОКА && источник->тип != УЗЕЛ_F_СТРОКА) return 0;
    if (!цель.срез || цель.тип != ТОКЕН_ТИП_СИМВОЛ || цель.указатели != 0) return 0;
    источник->срез = 1;
    return 1;
}

// Размер типа в байтах (для статической проверки переполнения «выделить»).
// Указатель — 8 байт (LP64). 0 — неизвестно/непроверяемо.
static long размер_типа(ИнфоТипа т)
{
    if (т.срез) return 0;
    if (т.указатели > 0) return 8;
    switch (т.тип) {
        case ТОКЕН_ЦЕЛОЕ8: case ТОКЕН_БАЙТ: case ТОКЕН_ТИП_СИМВОЛ:
        case ТОКЕН_ЛОГИЧЕСКИЙ: return 1;
        case ТОКЕН_ЦЕЛОЕ16: return 2;
        case ТОКЕН_ЦЕЛОЕ32: case ТОКЕН_ВЕЩЕСТВЕННОЕ:
        case ТОКЕН_ПЕРЕЧИСЛЕНИЕ: return 4;
        case ТОКЕН_ЦЕЛОЕ64: case ТОКЕН_ВЕЩЕСТВЕННОЕ64: return 8;
        default: return 0;
    }
}

// Разрядность целого типа в битах (для проверки сдвигов). 0 — неизвестно.
static int ширина_бит(ИнфоТипа т)
{
    if (т.срез || т.указатели > 0) return 0;
    switch (т.тип) {
        case ТОКЕН_ЦЕЛОЕ8: case ТОКЕН_БАЙТ: case ТОКЕН_ТИП_СИМВОЛ: return 8;
        case ТОКЕН_ЦЕЛОЕ16: return 16;
        case ТОКЕН_ЦЕЛОЕ32: case ТОКЕН_ПЕРЕЧИСЛЕНИЕ: return 32;
        case ТОКЕН_ЦЕЛОЕ64: return 64;
        default: return 0;
    }
}

static int вычислить_константу(Анализатор *а, Узел *узел, long *из);

// Неявное сужение целого: цель уже источника по разрядности, и источник не
// сворачивается в константу (для констант диапазон уже проверяется отдельно).
// Такое присваивание тихо теряет данные в C — требуем явного «как<тип>(…)».
// Перечисления исключены (свои правила enum↔целое).
static int сужение_запрещено(Анализатор *а, ИнфоТипа цель, Узел *инит, ИнфоТипа ист)
{
    if (!инит) return 0;
    if (цель.тип == ТОКЕН_ПЕРЕЧИСЛЕНИЕ || ист.тип == ТОКЕН_ПЕРЕЧИСЛЕНИЕ) return 0;
    if (!тип_целочисленный(цель) || !тип_целочисленный(ист)) return 0;
    int шц = ширина_бит(цель), ши = ширина_бит(ист);
    if (шц == 0 || ши == 0 || шц >= ши) return 0;  // расширение/равно — допустимо
    long _к;
    if (вычислить_константу(а, инит, &_к)) return 0;  // константа — проверена диапазоном
    return 1;
}

// Тип результата смешанной арифметики двух чисел — «старший» операнд, как в C
// (usual arithmetic conversions, упрощённо). Вещественное доминирует над целым;
// при равной разрядности беззнаковый доминирует над знаковым (правило C).
// Раньше возвращался левый операнд, из-за чего «целое32 в = целое8 + целое64»
// типизировался как целое8 → присваивание целое64-суммы в целое32 молча
// усекалось. Теперь результат шире → такое присваивание ловится как сужение.
static ИнфоТипа объединить_арифметику(ИнфоТипа л, ИнфоТипа п)
{
    // Вещественное доминирует над целым; двойная точность — над одинарной.
    if (л.тип == ТОКЕН_ВЕЩЕСТВЕННОЕ64 || п.тип == ТОКЕН_ВЕЩЕСТВЕННОЕ64) {
        ИнфоТипа р = { ТОКЕН_ВЕЩЕСТВЕННОЕ64, 0, 0, 0, -1 };
        return р;
    }
    if (л.тип == ТОКЕН_ВЕЩЕСТВЕННОЕ || п.тип == ТОКЕН_ВЕЩЕСТВЕННОЕ) {
        ИнфоТипа р = { ТОКЕН_ВЕЩЕСТВЕННОЕ, 0, 0, 0, -1 };
        return р;
    }
    int шл = ширина_бит(л), шп = ширина_бит(п);
    if (шл == 0) шл = 32;  // перечисление/неизвестное — ранг целого32
    if (шп == 0) шп = 32;
    if (шл > шп) return л;
    if (шп > шл) return п;
    return л.беззнаковый ? л : п;  // равная разрядность: беззнаковый доминирует
}

// Совместимость операндов бинарного оператора. Возвращает 1 и кладёт
// тип результата в *рез при успехе; 0 при несовместимости.
// ─── перегрузка операторов: манглинг C-имён ──────────────────────────────────
// Короткий код оператора для манглинга C-имени перегрузки (или nullptr, если
// оператор не перегружаем). Совпадает по набору с токен_перегружаемый_оператор.
static const char *операторкод(const Токен *оп)
{
    if (токен_текст_равен(оп, "+"))  return "плюс";
    if (токен_текст_равен(оп, "-"))  return "минус";
    if (токен_текст_равен(оп, "*"))  return "умн";
    if (токен_текст_равен(оп, "/"))  return "дел";
    if (токен_текст_равен(оп, "%"))  return "ост";
    if (токен_текст_равен(оп, "==")) return "равн";
    if (токен_текст_равен(оп, "!=")) return "нерав";
    if (токен_текст_равен(оп, "<"))  return "менш";
    if (токен_текст_равен(оп, ">"))  return "болш";
    if (токен_текст_равен(оп, "<=")) return "менрав";
    if (токен_текст_равен(оп, ">=")) return "болрав";
    return nullptr;
}

// Ключ типа операнда для манглинга: имя структуры («::» → «__») либо код
// примитива «т<код>з<знак>». Указатель/срез/перечисление операндом перегрузки
// быть не могут → возвращает 0. Пишет ключ в out. Имя структуры берётся из
// текста имя_типа (совпадает с а->структуры[индекс].имя на месте вызова).
static int ключ_типа_оператора(ТипТокена тип, int беззнаковый, int указатели,
                                int срез, const Токен *имя_типа,
                                char *out, size_t cap)
{
    if (указатели > 0 || срез || тип == ТОКЕН_ПЕРЕЧИСЛЕНИЕ) return 0;
    if (тип == ТОКЕН_СТРУКТУРА) {
        size_t n = имя_типа->длина < cap - 1 ? имя_типа->длина : cap - 1;
        for (size_t i = 0; i < n; ++i)
            out[i] = имя_типа->начало[i] == ':' ? '_' : имя_типа->начало[i];
        out[n] = '\0';
        return n > 0;
    }
    snprintf(out, cap, "т%dз%d", (int)тип, беззнаковый ? 1 : 0);
    return 1;
}

// Полное манглированное C-имя перегрузки: «_опер_<опкод>_<ключ1>_<ключ2>».
static int манглированное_имя_оператора(
        const Токен *оп,
        ТипТокена т1, int бз1, int ук1, int ср1, const Токен *имятип1,
        ТипТокена т2, int бз2, int ук2, int ср2, const Токен *имятип2,
        char *out, size_t cap)
{
    const char *опкод = операторкод(оп);
    char к1[МАКС_ИМЯ], к2[МАКС_ИМЯ];
    if (!опкод) return 0;
    if (!ключ_типа_оператора(т1, бз1, ук1, ср1, имятип1, к1, sizeof к1)) return 0;
    if (!ключ_типа_оператора(т2, бз2, ук2, ср2, имятип2, к2, sizeof к2)) return 0;
    snprintf(out, cap, "_опер_%s_%s_%s", опкод, к1, к2);
    return 1;
}

// Тип операнда — структура-ЗНАЧЕНИЕ (не указатель, не срез): только для таких
// включается резолв перегрузки (встроенные операторы структур не имеют).
static int тип_структура_значение(ИнфоТипа т)
{
    return т.тип == ТОКЕН_СТРУКТУРА && т.указатели == 0 && т.срез == 0;
}

// Манглированное имя перегрузки на МЕСТЕ ВЫЗОВА (из ИнфоТипа операндов). Имя
// структуры берётся из таблицы (а->структуры[индекс].имя) — оно совпадает с
// текстом имя_типа параметра, поэтому имена перегрузки на объявлении и на
// вызове идентичны. Возвращает 0, если операнд неперегружаем.
static int имя_перегрузки_из_инфо(Анализатор *а, const Токен *оп,
                                   ИнфоТипа л, ИнфоТипа п,
                                   char *out, size_t cap)
{
    Токен имя_л = {0}, имя_п = {0};
    if (л.тип == ТОКЕН_СТРУКТУРА) {
        if (л.индекс_структуры < 0) return 0;
        имя_л.начало = а->структуры[л.индекс_структуры].имя;
        имя_л.длина = strlen(а->структуры[л.индекс_структуры].имя);
    }
    if (п.тип == ТОКЕН_СТРУКТУРА) {
        if (п.индекс_структуры < 0) return 0;
        имя_п.начало = а->структуры[п.индекс_структуры].имя;
        имя_п.длина = strlen(а->структуры[п.индекс_структуры].имя);
    }
    return манглированное_имя_оператора(оп,
        л.тип, л.беззнаковый, л.указатели, л.срез, &имя_л,
        п.тип, п.беззнаковый, п.указатели, п.срез, &имя_п,
        out, cap);
}

static int тип_бинопа(ИнфоТипа л, ИнфоТипа п,
                       const Токен *оп, ИнфоТипа *рез)
{
    int л_ук = тип_указатель(л);
    int п_ук = тип_указатель(п);
    int л_ар = тип_арифметический(л);
    int п_ар = тип_арифметический(п);

    int сложение = токен_текст_равен(оп, "+");
    int вычит    = токен_текст_равен(оп, "-");
    int сравнение = токен_текст_равен(оп, ">")  || токен_текст_равен(оп, "<")
                 || токен_текст_равен(оп, ">=") || токен_текст_равен(оп, "==")
                 || токен_текст_равен(оп, "<=") || токен_текст_равен(оп, "!=");
    int логическое = токен_текст_равен(оп, "&&") || токен_текст_равен(оп, "||");
    int побитовое = токен_текст_равен(оп, "&") || токен_текст_равен(оп, "|")
                 || токен_текст_равен(оп, "^");
    int сдвиг     = токен_текст_равен(оп, "<<") || токен_текст_равен(оп, ">>");

    // Логическое «и»/«или» (&&/||): операнды — любые истинностные (арифметика
    // или указатель), результат — целое32 (0/1), как в C.
    if (логическое) {
        if (тип_скалярный(л) && тип_скалярный(п)) {
            *рез = ТИП_ЦЕЛОЕ32_V;
            return 1;
        }
        return 0;  // срез/структура в логическом операторе — ошибка
    }

    // Побитовые «& | ^» и сдвиги «<< >>»: только целочисленные операнды (не
    // float/указатель/срез — как в C). Нулевая рантайм-цена. Результат сдвига —
    // тип левого операнда; побитового — «старший» из двух (обычные преобразования).
    if (побитовое || сдвиг) {
        if (тип_целочисленный(л) && тип_целочисленный(п)) {
            *рез = сдвиг ? л : объединить_арифметику(л, п);
            return 1;
        }
        return 0;  // побитовые/сдвиг над нецелым — ошибка
    }

    // Сравнение: допускаем арифметику и указатели одного типа, результат int.
    if (сравнение) {
        if ((л_ук && п_ук) &&
            (л.тип != п.тип || л.указатели != п.указатели) &&
            п.тип != ТОКЕН_НУЛ_УКАЗАТЕЛЬ && л.тип != ТОКЕН_НУЛ_УКАЗАТЕЛЬ) {
            return 0;  // сравнение указателей разных типов
        }
        *рез = ТИП_ЦЕЛОЕ32_V;
        return 1;
    }

    // Оба арифметические — стандартные числовые преобразования (как в C):
    // результат — «старший» (более широкий) операнд.
    if (л_ар && п_ар) {
        *рез = объединить_арифметику(л, п);
        return 1;
    }

    // Арифметика указателей: ptr ± integer → ptr.
    if ((сложение || вычит) && л_ук && п_ар) {
        *рез = л;
        return 1;
    }
    if (сложение && л_ар && п_ук) {
        *рез = п;
        return 1;
    }

    // ptr - ptr → ptrdiff_t (целое32).
    if (вычит && л_ук && п_ук) {
        if (л.тип != п.тип || л.указатели != п.указатели)
            return 0;  // разные типы указателей
        *рез = ТИП_ЦЕЛОЕ32_V;
        return 1;
    }

    return 0;  // всё остальное: ptr OP ptr, ptr * int, и т.д.
}

// ─── элиминация проверок границ ──────────────────────────────────────────────

// Поиск символа без права на изменение: элиминация проверок только читает
// таблицу (полная «найти_символ» объявлена ниже и требует неконстантный
// Анализатор — здесь он не нужен и не должен быть доступен).
static const Символ *найти_символ_конст(const Анализатор *а, const char *имя,
                                         size_t длина_имени)
{
    for (size_t i = а->число_символов; i > 0; --i) {
        const Символ *с = &а->символы[i - 1];
        if (байты_равны(с->имя, strlen(с->имя), имя, длина_имени))
            return с;
    }
    return nullptr;
}

// Активна ли группа равной длины, содержащая ОБА имени? (доказано len(и1)==len(и2))
static int срезы_равной_длины(const Анализатор *а,
                               const char *и1, size_t д1,
                               const char *и2, size_t д2)
{
    if (байты_равны(и1, д1, и2, д2)) return 1;  // одно и то же имя — тривиально
    for (size_t g = 0; g < а->число_групп_длины; ++g) {
        const ГруппаРавнойДлины *гр = &а->группы_длины[g];
        if (!гр->активна) continue;
        int есть1 = 0, есть2 = 0;
        for (int m = 0; m < гр->число_членов; ++m) {
            if (байты_равны(гр->члены[m].начало, гр->члены[m].длина, и1, д1)) есть1 = 1;
            if (байты_равны(гр->члены[m].начало, гр->члены[m].длина, и2, д2)) есть2 = 1;
        }
        if (есть1 && есть2) return 1;
    }
    return 0;
}

// Сбросить группы равной длины, содержащие имя (реассайн среза → длина могла
// измениться, доказательство больше не действительно).
static void сбросить_группы_с(Анализатор *а, const char *имя, size_t длина)
{
    for (size_t g = 0; g < а->число_групп_длины; ++g) {
        ГруппаРавнойДлины *гр = &а->группы_длины[g];
        if (!гр->активна) continue;
        for (int m = 0; m < гр->число_членов; ++m)
            if (байты_равны(гр->члены[m].начало, гр->члены[m].длина, имя, длина)) {
                гр->активна = 0;
                break;
            }
    }
    // И границы индексов, где имя — индекс-срез или база (реассайн ломает оба).
    for (size_t i = 0; i < а->число_границ_индексов; ++i) {
        ГраницаИндексов *г = &а->границы_индексов[i];
        if (!г->активна) continue;
        if (байты_равны(г->индекс_срез.начало, г->индекс_срез.длина, имя, длина)
            || байты_равны(г->база_срез.начало, г->база_срез.длина, имя, длина))
            г->активна = 0;
    }
}

// Доказано ли «база[индекс_срез[·]]» безопасным через «утверждать_в_границах»?
static int индекс_срез_в_границах(const Анализатор *а,
                                   const char *инд_имя, size_t инд_длина,
                                   const char *база_имя, size_t база_длина)
{
    for (size_t i = 0; i < а->число_границ_индексов; ++i) {
        const ГраницаИндексов *г = &а->границы_индексов[i];
        if (!г->активна) continue;
        if (байты_равны(г->индекс_срез.начало, г->индекс_срез.длина, инд_имя, инд_длина)
            && байты_равны(г->база_срез.начало, г->база_срез.длина, база_имя, база_длина))
            return 1;
    }
    return 0;
}

// Доступ «база[индекс]» доказанно-безопасен в текущем контексте? Истинно, если
// индекс — переменная активного канонического цикла, и его верхняя граница не
// превосходит длину базы (по имени среза, по известной длине ≥ предела, ЛИБО
// база доказанно равнодлинна срезу-условию через «утверждать_равные»).
static int индекс_безопасен_(const Анализатор *а, Узел *индекс,
                              const Токен *база_имя,
                              int длина_известна, long длина)
{
    if (!индекс || индекс->тип != УЗЕЛ_ИДЕНТИФИКАТОР) {
        return 0;
    }
    for (size_t i = 0; i < а->число_безопасных; ++i) {
        const БезопаснаяПара *п = &а->безопасные[i];
        if (!байты_равны(п->индекс.начало, п->индекс.длина,
                         индекс->токен.начало, индекс->токен.длина)) {
            continue;
        }
        // Режим среза: тот же срез/массив, что в условии «и < длина(с)», ИЛИ
        // база доказанно равнодлинна ему через «утверждать_равные» (SoA).
        if (п->есть_срез && база_имя
            && срезы_равной_длины(а, п->срез.начало, п->срез.длина,
                                  база_имя->начало, база_имя->длина)) {
            return 1;
        }
        // Режим предела: «и < N», доступ безопасен если длина базы ≥ N.
        if (п->есть_предел && длина_известна && п->предел <= длина) {
            return 1;
        }
        // Режим переменной: «и < н» безопасен ровно для среза, созданного как
        // «выделить(н)» той же переменной, — тогда длина(с) == н, и условие
        // цикла доказывает границу не хуже, чем «и < длина(с)».
        if (п->есть_перем && база_имя) {
            const Символ *база = найти_символ_конст(а, база_имя->начало,
                                                     база_имя->длина);
            if (база && база->длина_из_переменной
                && байты_равны(база->длина_токен.начало, база->длина_токен.длина,
                               п->перем.начало, п->перем.длина)) {
                return 1;
            }
        }
    }
    return 0;
}

// Обратно-совместимая обёртка: индекс — child(0), имя базы — узел->токен.
static int индекс_в_безопасном_контексте(const Анализатор *а, Узел *узел,
                                          int длина_известна, long длина)
{
    return индекс_безопасен_(а, узел_ребёнок(узел, 0), &узел->токен,
                             длина_известна, длина);
}

// ─── таблица символов ───────────────────────────────────────────────────────

static void войти_в_область(Анализатор *а) { а->глубина++; }

static void выйти_из_области(Анализатор *а)
{
    while (а->число_символов > 0
           && а->символы[а->число_символов - 1].глубина >= а->глубина) {
        а->число_символов--;
    }
    // Группы равной длины, объявленные в этой области, снимаем (стек-дисциплина).
    while (а->число_групп_длины > 0
           && а->группы_длины[а->число_групп_длины - 1].глубина >= а->глубина) {
        а->число_групп_длины--;
    }
    while (а->число_границ_индексов > 0
           && а->границы_индексов[а->число_границ_индексов - 1].глубина >= а->глубина) {
        а->число_границ_индексов--;
    }
    if (а->глубина > 0) а->глубина--;
}

static Символ *найти_символ(Анализатор *а, const char *имя, size_t длина_имени)
{
    for (size_t i = а->число_символов; i > 0; --i) {
        Символ *с = &а->символы[i - 1];
        if (байты_равны(с->имя, strlen(с->имя), имя, длина_имени))
            return с;
    }
    // Локальные имена затеняют глобальные константы (поиск выше — с конца).
    for (size_t i = 0; i < а->число_глобальных; ++i) {
        Символ *с = &а->глобальные[i];
        if (байты_равны(с->имя, strlen(с->имя), имя, длина_имени))
            return с;
    }
    return nullptr;
}

// Указатель-идентификатор ссылается на строковый литерал (провенанс .rodata)?
static int указатель_из_литерала(Анализатор *а, const Узел *узел)
{
    if (!узел || узел->тип != УЗЕЛ_ИДЕНТИФИКАТОР) return 0;
    Символ *с = найти_символ(а, узел->токен.начало, узел->токен.длина);
    return с && с->из_литерала;
}

// Указатель-идентификатор имеет borrow-провенанс, безопасный для возврата?
static int указатель_безопасен_для_возврата(Анализатор *а, const Узел *узел)
{
    if (!узел || узел->тип != УЗЕЛ_ИДЕНТИФИКАТОР) return 0;
    Символ *с = найти_символ(а, узел->токен.начало, узел->токен.длина);
    return с && с->безопасен_для_возврата;
}

// Можно ли безопасно вернуть это выражение как указатель (borrow)? Разрешены
// только источники, чья память переживёт возврат и принадлежит вызывающему/
// статике: «нуль», строковый литерал, borrow-безопасный указатель-переменная
// (параметр/argv/литерал или их копия), индексация такого указателя/среза
// (напр. «аргументы[i]»). Всё прочее — локальные данные, результаты C-функций,
// арифметика — отклоняется (возможен висячий указатель / ручное управление).
static int выражение_безопасно_для_возврата(Анализатор *а, const Узел *выр)
{
    if (!выр) return 0;
    switch (выр->тип) {
        case УЗЕЛ_НУЛЬ:
        case УЗЕЛ_СТРОКА:
        case УЗЕЛ_СИМВОЛ:
            return 1;
        case УЗЕЛ_ИДЕНТИФИКАТОР: {
            Символ *с = найти_символ(а, выр->токен.начало, выр->токен.длина);
            return с && !с->массив && с->безопасен_для_возврата;
        }
        case УЗЕЛ_ИНДЕКС: {
            // Индексация borrow-безопасного указателя/среза (память вызывающего).
            Символ *с = найти_символ(а, выр->токен.начало, выр->токен.длина);
            return с && с->безопасен_для_возврата && (с->указатели > 0 || с->срез);
        }
        default:
            return 0;
    }
}

static void объявить_символ(Анализатор *а,
                             const char *имя, size_t длина_имени,
                             ТипТокена тип, int указатели, int массив,
                             int беззнаковый, int срез,
                             int длина_известна, long длина,
                             const Токен *место,
                             int значение_известно, long значение)
{
    for (size_t i = а->число_символов; i > 0; --i) {
        Символ *с = &а->символы[i - 1];
        if (с->глубина != а->глубина) break;
        if (байты_равны(с->имя, strlen(с->имя), имя, длина_имени)) {
            char msg[256];
            snprintf(msg, sizeof(msg),
                     "переменная «%.*s» уже объявлена в этой области",
                     (int)длина_имени, имя);
            ошибка_семантики(а, место, msg);
            return;
        }
    }
    if (имя_слишком_длинное(а, место, длина_имени)) return;
    if (а->число_символов >= МАКС_СИМВОЛОВ) {
        переполнение_таблицы(а, место, "переменных в одной области видимости",
                             МАКС_СИМВОЛОВ);
        return;
    }
    Символ *с = &а->символы[а->число_символов++];
    size_t n = длина_имени < МАКС_ИМЯ - 1 ? длина_имени : МАКС_ИМЯ - 1;
    memcpy(с->имя, имя, n);
    с->имя[n] = '\0';
    с->тип = тип;
    с->указатели = указатели;
    с->массив = массив;
    с->беззнаковый = беззнаковый;
    с->срез = срез;
    с->владеет_срезом = 0;  // уточняется вызывающим после объявления
    с->перемещён = 0;
    с->токен_move = (Токен){0};
    с->индекс_структуры = -1;  // уточняется вызывающим для типа-структуры
    с->длина_известна = длина_известна;
    с->длина = длина;
    с->длина_2 = 0;  // 2D-массивы проставляют это поле вызывающим после объявления
    с->глубина = а->глубина;
    с->значение_известно = значение_известно;
    с->значение = значение;
    с->может_быть_нуль = 0;
    с->инициализирована = 1;  // по умолчанию; скаляр без init выставит 0
    с->из_литерала = 0;
}

static int переменная_изменяемая(const Анализатор *а,
                                  const char *имя, size_t длина_имени)
{
    for (size_t i = 0; i < а->число_изменяемых; ++i) {
        if (байты_равны(а->изменяемые[i].начало, а->изменяемые[i].длина,
                        имя, длина_имени))
            return 1;
    }
    return 0;
}

// Связь «длина(с) == н» перестала быть верной: «н» (или сам срез) изменилась.
// Вызывается по ходу анализа, поэтому позиция учитывается сама собой:
// «н = 5; с = выделить(н)» связь сохраняет, «с = выделить(н); н = 100» — рвёт.
static void сбросить_связь_длины(Анализатор *а, const Токен *имя)
{
    for (size_t i = 0; i < а->число_символов; ++i) {
        Символ *с = &а->символы[i];
        if (!с->длина_из_переменной) continue;
        // Изменилась переменная длины — или сам срез переприсвоен.
        if (байты_равны(с->длина_токен.начало, с->длина_токен.длина,
                        имя->начало, имя->длина)
            || байты_равны(с->имя, strlen(с->имя), имя->начало, имя->длина)) {
            с->длина_из_переменной = 0;
        }
    }
}

// ─── аксессоры таблицы символов для модуля «владение» ───────────────────────
//
// Модуль владения (владение.c) работает с состоянием владения каждого
// символа через узкий API, чтобы не разглашать структуру Анализатор/Символ.
// Реализация — здесь. Сама структура остаётся приватной для семантики.

size_t кво_символов(const Анализатор *а)
{
    return а->число_символов;
}

ВладениеЭлемент владение_символа(const Анализатор *а, size_t индекс)
{
    return (ВладениеЭлемент){
        .владеет_срезом = а->символы[индекс].владеет_срезом,
        .перемещён      = а->символы[индекс].перемещён,
        .токен_move     = а->символы[индекс].токен_move,
    };
}

void задать_владение_символа(Анализатор *а, size_t индекс, ВладениеЭлемент новое)
{
    а->символы[индекс].владеет_срезом = новое.владеет_срезом;
    а->символы[индекс].перемещён      = новое.перемещён;
    а->символы[индекс].токен_move     = новое.токен_move;
}

const char *имя_символа(const Анализатор *а, size_t индекс)
{
    return а->символы[индекс].имя;
}

void диагностика_владения(Анализатор *а, const Токен *где, const char *сообщение)
{
    ошибка_семантики(а, где, сообщение);
}

// ─── свёртка констант ───────────────────────────────────────────────────────

static int вычислить_константу(Анализатор *а, Узел *узел, long *из)
{
    if (!узел) return 0;
    switch (узел->тип) {
        case УЗЕЛ_ЧИСЛО:
            if (узел->токен.тип == ТОКЕН_ИСТИНА) { *из = 1; return 1; }
            if (узел->токен.тип == ТОКЕН_ЛОЖЬ)   { *из = 0; return 1; }
            *из = значение_целого_литерала(узел->токен.начало, узел->токен.длина);
            return 1;
        case УЗЕЛ_ИДЕНТИФИКАТОР: {
            Символ *с = найти_символ(а, узел->токен.начало, узел->токен.длина);
            if (с && с->значение_известно) { *из = с->значение; return 1; }
            // Вариант перечисления — целочисленная константа.
            if (!с) {
                long зн;
                if (найти_вариант(а, узел->токен.начало, узел->токен.длина, &зн) >= 0) {
                    *из = зн; return 1;
                }
            }
            return 0;
        }
        case УЗЕЛ_УНОП: {
            long в;
            if (токен_текст_равен(&узел->токен, "-")
                && вычислить_константу(а, узел_ребёнок(узел, 0), &в)) {
                *из = -в; return 1;
            }
            if (токен_текст_равен(&узел->токен, "~")
                && вычислить_константу(а, узел_ребёнок(узел, 0), &в)) {
                *из = ~в; return 1;
            }
            return 0;
        }
        case УЗЕЛ_БИНОП: {
            long л, п;
            if (!вычислить_константу(а, узел_ребёнок(узел, 0), &л)
                || !вычислить_константу(а, узел_ребёнок(узел, 1), &п))
                return 0;
            const Токен *о = &узел->токен;
            // Свёртка с защитой от UB в самом транспиляторе: при переполнении
            // long или недопустимом делении/сдвиге считаем «не константа» —
            // типизация выдаст понятную ошибку отдельно.
            long r;
            if (токен_текст_равен(о, "+")) {
                if (__builtin_add_overflow(л, п, &r)) return 0;
                *из = r;
                return 1;
            }
            if (токен_текст_равен(о, "-")) {
                if (__builtin_sub_overflow(л, п, &r)) return 0;
                *из = r;
                return 1;
            }
            if (токен_текст_равен(о, "*")) {
                if (__builtin_mul_overflow(л, п, &r)) return 0;
                *из = r;
                return 1;
            }
            if (токен_текст_равен(о, "/")) {
                if (п == 0 || (п == -1 && л == LONG_MIN)) return 0;
                *из = л / п;
                return 1;
            }
            if (токен_текст_равен(о, "%")) {
                if (п == 0 || (п == -1 && л == LONG_MIN)) return 0;
                *из = л % п;
                return 1;
            }
            if (токен_текст_равен(о, "<<")) {
                if (п < 0 || п >= 64) return 0;
                *из = (long)((unsigned long)л << п);
                return 1;
            }
            if (токен_текст_равен(о, ">>")) {
                if (п < 0 || п >= 64) return 0;
                *из = л >> п;
                return 1;
            }
            if (токен_текст_равен(о, "&")) { *из = л & п; return 1; }
            if (токен_текст_равен(о, "|")) { *из = л | п; return 1; }
            if (токен_текст_равен(о, "^")) { *из = л ^ п; return 1; }
            return 0;
        }
        default: return 0;
    }
}

// Диапазон значений целого типа (для проверки констант-инициализаторов на
// выход за пределы). Возвращает 1 и кладёт [мин, макс], если тип проверяемый;
// 0 для непроверяемых (целое64 — не вмещается в long-сравнение надёжно,
// вещественное). Символ берём как объединение signed/unsigned char.
static int диапазон_целого(ТипТокена тип, int беззнаковый, long *мин, long *макс)
{
    switch (тип) {
        case ТОКЕН_ЦЕЛОЕ8:
            if (беззнаковый) { *мин = 0; *макс = 255; }
            else { *мин = -128; *макс = 127; }
            return 1;
        case ТОКЕН_ЦЕЛОЕ16:
            if (беззнаковый) { *мин = 0; *макс = 65535; }
            else { *мин = -32768; *макс = 32767; }
            return 1;
        case ТОКЕН_ЦЕЛОЕ32:
            if (беззнаковый) { *мин = 0; *макс = 4294967295L; }
            else { *мин = -2147483648L; *макс = 2147483647L; }
            return 1;
        case ТОКЕН_БАЙТ:
            *мин = 0; *макс = 255; return 1;
        case ТОКЕН_ТИП_СИМВОЛ:
            *мин = -128; *макс = 255; return 1;
        default:
            return 0;
    }
}

static void пометить_изменяемой(Анализатор *а, const Токен *имя)
{
    if (переменная_изменяемая(а, имя->начало, имя->длина)) return;
    // Fail-closed: не записать мутацию — значит потом ложно снять проверку границ
    // (класс §43 Ф1 / урок 17.07). Поэтому переполнение здесь — ошибка, а не
    // тихий пропуск (тихий пропуск оставил бы элизию включённой = небезопасно).
    if (а->число_изменяемых >= МАКС_СИМВОЛОВ) {
        переполнение_таблицы(а, имя, "изменяемых переменных в функции",
                             МАКС_СИМВОЛОВ);
        return;
    }
    а->изменяемые[а->число_изменяемых++] = (ИмяСсылка){ имя->начало, имя->длина };
}

static void собрать_изменяемые(Анализатор *а, Узел *узел)
{
    if (!узел) return;
    if (узел->тип == УЗЕЛ_ПРИСВАИВАНИЕ || узел->тип == УЗЕЛ_ИНКРЕМЕНТ) {
        Узел *цель = узел_ребёнок(узел, 0);
        if (цель && цель->тип == УЗЕЛ_ИДЕНТИФИКАТОР)
            пометить_изменяемой(а, &цель->токен);
    }
    // Передача в «изменяемый»/«вывод» меняет переменную БЕЗ присваивания в коде.
    // Без этого её значение осталось бы «известной константой», и элиминация
    // проверки границ сработала бы по ложному основанию — реальный выход за
    // границы кучи (ловилось ASan) в языке, где это должно быть невозможно.
    if (узел->тип == УЗЕЛ_ВЫЗОВ) {
        const СигнатураФункции *сиг =
            найти_сигнатуру_по_имени(а, узел->токен.начало, узел->токен.длина);
        if (сиг) {
            for (size_t i = 0; i < узел_число_детей(узел)
                               && i < сиг->число_параметров; ++i) {
                Узел *арг = узел_ребёнок(узел, i);
                if (сиг->параметры[i].по_ссылке > 0
                    && арг && арг->тип == УЗЕЛ_ИДЕНТИФИКАТОР)
                    пометить_изменяемой(а, &арг->токен);
            }
        }
        // Встроенные «добавить»/«перевыделить» МУТИРУЮТ 1-й аргумент-буфер
        // (по ссылке): та же логика, что и §43 Ф1 — без пометки мутация была бы
        // невидима BCE/анализу гонок (добавить в «параллельно для» = гонка realloc).
        if ((токен_текст_равен(&узел->токен, "добавить")
             || токен_текст_равен(&узел->токен, "перевыделить"))
            && узел_число_детей(узел) >= 1) {
            Узел *арг0 = узел_ребёнок(узел, 0);
            // «добавить(б, …)» — мутируется переменная-буфер; «добавить(s.поле, …)»
            // — базовая переменная структуры (её буфер-поле растёт).
            while (арг0 && арг0->тип == УЗЕЛ_ПОЛЕ && узел_число_детей(арг0) > 0)
                арг0 = узел_ребёнок(арг0, 0);
            if (арг0 && арг0->тип == УЗЕЛ_ИДЕНТИФИКАТОР)
                пометить_изменяемой(а, &арг0->токен);
        }
    }
    for (size_t i = 0; i < узел_число_детей(узел); ++i)
        собрать_изменяемые(а, узел_ребёнок(узел, i));
}

// ─── связи массивов и ограничения длины ─────────────────────────────────────

static void ограничения_сохранить(Анализатор *а)
{
    if (а->глубина_ограничений >= МАКС_ГЛУБИНА_ОГРАНИЧЕНИЙ) return;
    а->ограничения[а->глубина_ограничений++] = (ОграничениеДлины){0};
}

static void ограничения_восстановить(Анализатор *а)
{
    if (а->глубина_ограничений > 0) а->глубина_ограничений--;
}

static void ограничение_установить(Анализатор *а,
                                    const char *переменная, size_t длина_имени,
                                    long минимальная_длина)
{
    if (а->глубина_ограничений == 0) return;
    ОграничениеДлины *o = &а->ограничения[а->глубина_ограничений - 1];
    size_t n = длина_имени < МАКС_ИМЯ - 1 ? длина_имени : МАКС_ИМЯ - 1;
    memcpy(o->переменная, переменная, n);
    o->переменная[n] = '\0';
    o->минимальная_длина = минимальная_длина;
    o->известна = 1;
}

static long минимальная_длина_для(const Анализатор *а,
                                   const char *имя, size_t длина_имени)
{
    for (size_t i = а->глубина_ограничений; i > 0; --i) {
        const ОграничениеДлины *o = &а->ограничения[i - 1];
        if (o->известна
            && байты_равны(o->переменная, strlen(o->переменная), имя, длина_имени))
            return o->минимальная_длина;
    }
    return 0;
}

// Есть ли у указателя зарегистрированная переменная-длина (связь
// «аргументы»↔«количество_аргументов»)? В отличие от известна_длина_массива
// это не зависит от ограничений в области — длина (argc) известна всегда, что
// и позволяет вставить рантайм-проверку при динамическом индексе.
static int у_указателя_есть_длина(const Анализатор *а,
                                   const char *имя, size_t длина_имени)
{
    for (size_t i = 0; i < а->число_связей; ++i)
        if (байты_равны(а->связи[i].массив, strlen(а->связи[i].массив),
                        имя, длина_имени))
            return 1;
    return 0;
}

static int известна_длина_массива(const Анализатор *а,
                                   const char *имя_массива, size_t длина_имени,
                                   long *минимальная_длина)
{
    const char *имя_длины = nullptr;
    for (size_t i = 0; i < а->число_связей; ++i) {
        if (байты_равны(а->связи[i].массив, strlen(а->связи[i].массив),
                        имя_массива, длина_имени)) {
            имя_длины = а->связи[i].длина;
            break;
        }
    }
    if (!имя_длины) return 0;
    long m = минимальная_длина_для(а, имя_длины, strlen(имя_длины));
    if (m <= 0) return 0;
    *минимальная_длина = m;
    return 1;
}

static void проверить_доступ_к_массиву(Анализатор *а, const Токен *t,
                                         const char *имя, size_t длина_имени,
                                         long индекс)
{
    long минимум = 0;
    if (!известна_длина_массива(а, имя, длина_имени, &минимум)) {
        char msg[256];
        snprintf(msg, sizeof(msg),
                 "доступ к массиву «%.*s»: длина неизвестна на этапе компиляции",
                 (int)длина_имени, имя);
        ошибка_семантики(а, t, msg);
        return;
    }
    if (индекс < 0 || индекс >= минимум) {
        char msg[256];
        snprintf(msg, sizeof(msg),
                 "индекс %ld вне границ: при текущих условиях длина не меньше %ld",
                 индекс, минимум);
        ошибка_семантики(а, t, msg);
    }
}

// ─── вывод и проверка типов выражений ───────────────────────────────────────

// Выводит тип узла-выражения И выполняет все семантические проверки.
static ИнфоТипа типизировать_выражение(Анализатор *а, Узел *узел);
static size_t число_ведущих_типоаргументов(const Узел *узел);

// Если узел — доступ «s.поле» к полю-БУФЕРУ, возвращает его ПолеСтруктуры*
// (для «добавить»/«перевыделить»/гейта вида по полю), иначе nullptr.
static const ПолеСтруктуры *поле_буфер_из_узла(Анализатор *а, Узел *узел)
{
    if (!узел || узел->тип != УЗЕЛ_ПОЛЕ || узел_число_детей(узел) == 0)
        return nullptr;
    ИнфоТипа база = типизировать_выражение(а, узел_ребёнок(узел, 0));
    if (база.тип != ТОКЕН_СТРУКТУРА || база.индекс_структуры < 0)
        return nullptr;
    ОписаниеСтруктуры *с = &а->структуры[база.индекс_структуры];
    for (size_t i = 0; i < с->число_полей; ++i) {
        const ПолеСтруктуры *п = &с->поля[i];
        if (байты_равны(п->имя, strlen(п->имя),
                        узел->токен.начало, узел->токен.длина))
            return п->буфер ? п : nullptr;
    }
    return nullptr;
}
static ИнфоТипа вывести_обобщённый_вызов(Анализатор *а, Узел *вызов,
                                         СигнатураФункции *сиг);

// Содержит ли выражение вызов функции (в т.ч. в поддереве)? Используется, чтобы
// запретить индексацию на месте владеющего временного среза из результата вызова.
static int выражение_содержит_вызов(const Узел *узел)
{
    if (!узел) return 0;
    if (узел->тип == УЗЕЛ_ВЫЗОВ) return 1;
    for (size_t i = 0; i < узел_число_детей(узел); ++i)
        if (выражение_содержит_вызов(узел_ребёнок(узел, i))) return 1;
    return 0;
}
static int это_выделить(const Узел *узел);
static int это_клон(const Узел *узел);
static int это_запустить(const Узел *узел);

// Число ведущих детей-УЗЕЛ_ТИПОАРГУМЕНТ узла (явные «<>» на вызове).
static size_t число_ведущих_типоаргументов(const Узел *узел)
{
    size_t n = 0;
    for (size_t i = 0; i < узел_число_детей(узел); ++i) {
        const Узел *р = узел_ребёнок(узел, i);
        if (р && р->тип == УЗЕЛ_ТИПОАРГУМЕНТ) n++;
        else break;
    }
    return n;
}

static int инфотипы_совпадают(ИнфоТипа а, ИнфоТипа б)
{
    return а.тип == б.тип && а.указатели == б.указатели
        && а.беззнаковый == б.беззнаковый && а.срез == б.срез
        && а.индекс_структуры == б.индекс_структуры;
}

// Присваивает узлу-тип-аргументу имя именованного типа (структура/перечисление)
// в OWNED-строке (переживёт освобождение анализатора — мономорфизация читает её).
static void типоаргумент_имя(Узел *та, const char *имя)
{
    та->имя_типа_строка = strdup(имя);
    if (та->имя_типа_строка) {
        та->имя_типа.тип = ТОКЕН_ИДЕНТИФИКАТОР;
        та->имя_типа.начало = та->имя_типа_строка;
        та->имя_типа.длина = strlen(имя);
    }
}

// Проход вывода: типизирует аргументы обобщённого вызова и, если КАЖДЫЙ
// тип-параметр выводится из «голого»-T параметра с КОНКРЕТНЫМ типом аргумента,
// дописывает ведущие УЗЕЛ_ТИПОАРГУМЕНТ на узел вызова (мономорфизация примет их
// как явные «<>»). Иначе оставляет вызов как есть — «нужны явные тип-аргументы»
// сообщит проход 2. Возвращает подставленный тип возврата (для вложенных вызовов).
static ИнфоТипа вывести_обобщённый_вызов(Анализатор *а, Узел *вызов,
                                         СигнатураФункции *сиг)
{
    size_t на = узел_число_детей(вызов);
    if (на != сиг->число_параметров || сиг->число_типопарам == 0)
        return ТИП_НЕИЗВЕСТЕН_V;

    ИнфоТипа типы_арг[МАКС_ПАРАМЕТРОВ];
    for (size_t i = 0; i < на && i < МАКС_ПАРАМЕТРОВ; ++i)
        типы_арг[i] = типизировать_выражение(а, узел_ребёнок(вызов, i));

    ИнфоТипа вывод[8];
    int выведен[8] = {0};
    for (size_t p = 0; p < сиг->число_параметров && p < МАКС_ПАРАМЕТРОВ; ++p) {
        if (сиг->имя_типопарам_параметра[p].длина == 0) continue;  // не «голый» T
        ИнфоТипа т = типы_арг[p];
        // Тип аргумента должен быть КОНКРЕТНЫМ: не тип-параметр, не «неизвестно»,
        // и не переменная обобщённой-структурного типа (ИнфоТипа неотличима от
        // конкретной специализации — вывели бы имя шаблона).
        if (т.тип == ТОКЕН_НЕИЗВЕСТНЫЙ || т.тип == ТОКЕН_ТИПОПАРАМЕТР)
            return ТИП_НЕИЗВЕСТЕН_V;
        if (т.тип == ТОКЕН_СТРУКТУРА && т.индекс_структуры >= 0
            && а->структуры[т.индекс_структуры].обобщённая)
            return ТИП_НЕИЗВЕСТЕН_V;
        for (size_t k = 0; k < сиг->число_типопарам; ++k) {
            if (!байты_равны(сиг->типопарам[k].начало, сиг->типопарам[k].длина,
                             сиг->имя_типопарам_параметра[p].начало,
                             сиг->имя_типопарам_параметра[p].длина))
                continue;
            if (выведен[k]) {
                if (!инфотипы_совпадают(вывод[k], т)) return ТИП_НЕИЗВЕСТЕН_V;
            } else {
                вывод[k] = т; выведен[k] = 1;
            }
            break;
        }
    }
    for (size_t k = 0; k < сиг->число_типопарам; ++k)
        if (!выведен[k]) return ТИП_НЕИЗВЕСТЕН_V;  // T не выводится — нужны явные «<>»

    // Делаем тип-аргументы ведущими детьми вызова (перед аргументами).
    size_t старых = узел_число_детей(вызов);
    Узел **буфер = старых ? malloc(старых * sizeof(Узел *)) : nullptr;
    for (size_t i = 0; i < старых; ++i) буфер[i] = узел_ребёнок(вызов, i);
    вызов->дети.длина = 0;  // очистка без освобождения указателей (они вернутся)
    for (size_t k = 0; k < сиг->число_типопарам; ++k) {
        Узел *та = узел_создать(УЗЕЛ_ТИПОАРГУМЕНТ);
        та->тип_данных  = вывод[k].тип;
        та->беззнаковый = вывод[k].беззнаковый;
        та->указатели   = вывод[k].указатели;
        та->срез        = вывод[k].срез;
        if (вывод[k].тип == ТОКЕН_СТРУКТУРА && вывод[k].индекс_структуры >= 0)
            типоаргумент_имя(та, а->структуры[вывод[k].индекс_структуры].имя);
        else if (вывод[k].тип == ТОКЕН_ПЕРЕЧИСЛЕНИЕ && вывод[k].индекс_структуры >= 0)
            типоаргумент_имя(та, а->перечисления[вывод[k].индекс_структуры].имя);
        узел_добавить_ребёнка(вызов, та);
    }
    for (size_t i = 0; i < старых; ++i) узел_добавить_ребёнка(вызов, буфер[i]);
    free(буфер);

    // Тип результата — подставленный тип возврата (если возврат — «голый» T).
    if (сиг->имя_типопарам_возврата.длина > 0)
        for (size_t k = 0; k < сиг->число_типопарам; ++k)
            if (байты_равны(сиг->типопарам[k].начало, сиг->типопарам[k].длина,
                            сиг->имя_типопарам_возврата.начало,
                            сиг->имя_типопарам_возврата.длина))
                return вывод[k];
    return (ИнфоТипа){ сиг->тип_возврата, сиг->указатели_возврата,
                       сиг->беззнаковый, сиг->срез, сиг->индекс_структуры_возврата };
}

// Корневая переменная lvalue-цепочки проекций: «т.а.б» → т, «с[i]» → с,
// «т.поле[i].х» → т. nullptr — если цепочка укоренена не в переменной
// (временное: «функция()[i]», литерал и т.п.) — такое по ссылке нельзя:
// владеющее временное умерло бы до конца вызова.
static const Токен *корень_lvalue(const Узел *у)
{
    while (у) {
        switch (у->тип) {
            case УЗЕЛ_ИДЕНТИФИКАТОР:
                return &у->токен;
            case УЗЕЛ_ПОЛЕ:
                у = узел_число_детей(у) > 0 ? узел_ребёнок((Узел *)у, 0) : nullptr;
                continue;
            case УЗЕЛ_ИНДЕКС:
                // Новая форма (2 ребёнка): [база-выражение, индекс] — спуск в базу.
                // Старая форма: имя переменной в токене самого узла.
                if (узел_число_детей(у) == 2) {
                    у = узел_ребёнок((Узел *)у, 0);
                    continue;
                }
                return &у->токен;
            default:
                return nullptr;
        }
    }
    return nullptr;
}

// Может ли выражение-указатель дать НУЛЕВОЙ указатель (для null-safety и
// null-narrowing)? Это ровно те источники, дереф которых без охранника опасен:
//  • литерал «нуль»;
//  • переменная-«возможно», ещё не сужённая охранником (Символ.может_быть_нуль);
//  • вызов функции, тип возврата которой — «возможно<T*>» (сигнатура несёт бит).
// Всё прочее (ненулевой по умолчанию указатель, сужённая переменная, вызов
// функции с ненулевым возвратом) — доказанно ненулевое → 0. КЛЮЧЕВОЕ: без учёта
// вызова тут был TOCTOU/null-дереф — «п = найти()» (найти → возможно<T*>) считался
// ненулевым, и «если (п != нуль){ п = найти(); п.поле }» дереферил возможный нуль.
static int выражение_может_быть_нуль(Анализатор *а, Узел *выр)
{
    if (!выр) return 0;
    if (выр->тип == УЗЕЛ_НУЛЬ) return 1;
    if (выр->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
        Символ *ис = найти_символ(а, выр->токен.начало, выр->токен.длина);
        return ис && ис->может_быть_нуль;
    }
    if (выр->тип == УЗЕЛ_ВЫЗОВ) {
        const СигнатураФункции *сиг =
            найти_сигнатуру_по_имени(а, выр->токен.начало, выр->токен.длина);
        return сиг && сиг->возврат_возможно;
    }
    return 0;
}

// ─── memory_order для атомиков (§49) ────────────────────────────────────────
// Пять контекстных имён порядка памяти — распознаются ТОЛЬКО в позиции
// аргумента-порядка встроенных загрузить/сохранить/обменять (имён у кода не
// отнимают). Возвращает C-имя memory_order или nullptr; через флаги — допустим
// ли порядок для загрузки/сохранения (RMW-обменять принимает любой из пяти).
static const char *порядок_памяти(const Токен *t, int *грузить_ок, int *хранить_ок)
{
    int l = 0, s = 0; const char *c = nullptr;
    if (токен_текст_равен(t, "расслабленный"))          { c = "memory_order_relaxed"; l = 1; s = 1; }
    else if (токен_текст_равен(t, "получить"))           { c = "memory_order_acquire"; l = 1; s = 0; }
    else if (токен_текст_равен(t, "освободить"))         { c = "memory_order_release"; l = 0; s = 1; }
    else if (токен_текст_равен(t, "получить_освободить")) { c = "memory_order_acq_rel"; l = 0; s = 0; }
    else if (токен_текст_равен(t, "последовательный"))    { c = "memory_order_seq_cst"; l = 1; s = 1; }
    if (грузить_ок) *грузить_ок = l;
    if (хранить_ок) *хранить_ок = s;
    return c;
}

// Встроенные атом-операции с явным порядком: загрузить(а, порядок),
// сохранить(а, знач, порядок), обменять(а, знач, порядок). Диспатчится только
// когда 1-й аргумент — реально атомик (иначе имена свободны для кода). Помечает
// узел вызова (узел->атом=1) для кодогена. Возврат: загрузить/обменять → T (тип
// атомика), сохранить → ничего (void).
static ИнфоТипа типизировать_атом_операцию(Анализатор *а, Узел *узел, Символ *с)
{
    int это_сохранить = токен_текст_равен(&узел->токен, "сохранить");
    int это_грузить   = токен_текст_равен(&узел->токен, "загрузить");
    size_t ожид = это_грузить ? 2 : 3;   // (а, порядок) или (а, знач, порядок)
    if (узел_число_детей(узел) != ожид) {
        ошибка_семантики(а, &узел->токен, это_грузить
            ? "«загрузить» принимает (атомик, порядок)"
            : (это_сохранить ? "«сохранить» принимает (атомик, значение, порядок)"
                             : "«обменять» принимает (атомик, значение, порядок)"));
        return ТИП_НЕИЗВЕСТЕН_V;
    }
    ИнфоТипа тип_атома = { с->тип, 0, с->беззнаковый, 0, -1 };
    // Значение (сохранить/обменять) — совместимо с T, без сужения (как присваивание).
    if (!это_грузить) {
        Узел *зу = узел_ребёнок(узел, 1);
        ИнфоТипа тз = типизировать_выражение(а, зу);
        if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
        if (тз.тип != ТОКЕН_НЕИЗВЕСТНЫЙ
            && (!совместимы_для_присваивания(тип_атома, тз)
                || сужение_запрещено(а, тип_атома, зу, тз))) {
            char тт[64], тзс[64];
            описание_типа(тип_атома, тт, sizeof тт);
            описание_типа(тз, тзс, sizeof тзс);
            char m[256];
            snprintf(m, sizeof m,
                "значение атом-операции («%s») несовместимо с типом атомика «%s» "
                "(при сужении нужно «как<%s>(…)»)", тзс, тт, тт);
            ошибка_семантики(а, &зу->токен, m);
            return ТИП_НЕИЗВЕСТЕН_V;
        }
        // Константа, не влезающая в тип атомика (как «целое8 x = 300») — ошибка:
        // иначе atomic_store_explicit тихо усёк бы её (реюз проверки диапазона).
        long кз;
        long мин = 0, макс = 0;
        if (тз.тип != ТОКЕН_НЕИЗВЕСТНЫЙ && вычислить_константу(а, зу, &кз)
            && диапазон_целого(с->тип, с->беззнаковый, &мин, &макс)
            && (кз < мин || кз > макс)) {
            char тт[64], m[224];
            описание_типа(тип_атома, тт, sizeof тт);
            snprintf(m, sizeof m,
                "значение %ld не помещается в тип атомика «%s» ([%ld, %ld])",
                кз, тт, мин, макс);
            ошибка_семантики(а, &зу->токен, m);
            return ТИП_НЕИЗВЕСТЕН_V;
        }
    }
    // Порядок (последний аргумент) — контекстное имя; НЕ типизируем как выражение.
    Узел *пу = узел_последний_ребёнок(узел);
    int грузить_ок = 0, хранить_ок = 0;
    if (!пу || пу->тип != УЗЕЛ_ИДЕНТИФИКАТОР
        || !порядок_памяти(&пу->токен, &грузить_ок, &хранить_ок)) {
        ошибка_семантики(а, пу ? &пу->токен : &узел->токен,
            "ожидался порядок памяти: расслабленный / получить / освободить / "
            "получить_освободить / последовательный");
        return ТИП_НЕИЗВЕСТЕН_V;
    }
    if (это_грузить && !грузить_ок) {
        ошибка_семантики(а, &пу->токен, "«загрузить» допускает только "
            "расслабленный / получить / последовательный");
        return ТИП_НЕИЗВЕСТЕН_V;
    }
    if (это_сохранить && !хранить_ок) {
        ошибка_семантики(а, &пу->токен, "«сохранить» допускает только "
            "расслабленный / освободить / последовательный");
        return ТИП_НЕИЗВЕСТЕН_V;
    }
    узел->атом = 1;   // метка для кодогена: это атом-операция, а не обычный вызов
    return это_сохранить ? (ИнфоТипа){ ТОКЕН_НИЧЕГО, 0, 0, 0, -1 } : тип_атома;
}

static ИнфоТипа типизировать_выражение(Анализатор *а, Узел *узел)
{
    if (!узел || а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;

    switch (узел->тип) {

        case УЗЕЛ_ЧИСЛО:
            // Логические литералы «истина»/«ложь» — тип «логический».
            if (узел->токен.тип == ТОКЕН_ИСТИНА || узел->токен.тип == ТОКЕН_ЛОЖЬ)
                return (ИнфоТипа){ ТОКЕН_ЛОГИЧЕСКИЙ, 0, 0, 0, -1 };
            return ТИП_ЦЕЛОЕ32_V;

        case УЗЕЛ_СТРОКА:
            // Коэрция литерала в срез<символ> (§37): семантика на сайте вызова
            // могла проставить узел->срез=1 — тогда тип «срез<символ>» вместо
            // «символ*». Без флага — прежний C-строковый литерал.
            if (узел->срез) return (ИнфоТипа){ ТОКЕН_ТИП_СИМВОЛ, 0, 0, 1, -1 };
            return (ИнфоТипа){ ТОКЕН_ТИП_СИМВОЛ, 1, 0, 0, -1 };  // const char*

        case УЗЕЛ_СИМВОЛ: {
            // «'x'» — скаляр типа «символ» (char). Escape уже собран лексером;
            // проверяем лишь завершённость: пустой «''» или незакрытый (лексер
            // обрывает на переводе строки) — ошибка Konda с позицией.
            const char *т = узел->токен.начало;
            size_t дл = узел->токен.длина;
            if (дл < 3 || т[дл - 1] != '\'') {
                ошибка_семантики(а, &узел->токен,
                    "незавершённый или пустой символьный литерал «'…'»");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            return (ИнфоТипа){ ТОКЕН_ТИП_СИМВОЛ, 0, 0, 0, -1 };  // символ (char)
        }

        case УЗЕЛ_F_СТРОКА: {
            // Типизируем каждую вставку «\(выр)» и сохраняем её тип на холдере
            // (для выбора спецификатора в кодогене). Срез/структуру вставлять
            // нельзя — нет однозначного текстового представления.
            for (size_t i = 0; i < узел_число_детей(узел); ++i) {
                Узел *реб = узел_ребёнок(узел, i);
                if (!реб || реб->тип != УЗЕЛ_ИНТЕРПОЛЯЦИЯ) continue;
                Узел *выр = узел_число_детей(реб) > 0 ? узел_ребёнок(реб, 0) : nullptr;
                if (!выр) {
                    ошибка_семантики(а, &реб->токен,
                        "пустая интерполяция «\\()» в строке");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                ИнфоТипа т = типизировать_выражение(а, выр);
                if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                if (т.срез || (т.тип == ТОКЕН_СТРУКТУРА && т.указатели == 0)) {
                    // Координаты вставки — из под-лексера (фрагмент), поэтому для
                    // диагностики берём позицию самой f-строки (реб->токен = *t).
                    ошибка_семантики(а, &реб->токен,
                        "в интерполяцию строки нельзя поставить срез или структуру");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                реб->тип_данных = т.тип;
                реб->беззнаковый = т.беззнаковый;
                реб->указатели = т.указатели;
                реб->срез = т.срез;
            }
            // Коэрция f-строки в срез<символ> (§37): семантика на сайте вызова
            // могла проставить узел->срез=1 — тогда тип «срез<символ>» вместо
            // «символ*». Без флага — обычный сгенерированный C-строковый буфер.
            if (узел->срез) return (ИнфоТипа){ ТОКЕН_ТИП_СИМВОЛ, 0, 0, 1, -1 };
            return (ИнфоТипа){ ТОКЕН_ТИП_СИМВОЛ, 1, 0, 0, -1 };  // char*
        }

        case УЗЕЛ_НУЛЬ:
            return (ИнфоТипа){ ТОКЕН_НУЛ_УКАЗАТЕЛЬ, 1, 0, 0, -1 };

        case УЗЕЛ_НЕБЕЗОПАСНО: {
            // Выражение-форма «небезопасно { ВЫР }»: типизируем ВЫР под гейтом
            // (глубина_небезопасно++), значение узла = тип ВЫР. Даёт узкий
            // небезопасно для реинтерпрета «как<T*>(void*)» в инициализаторе.
            Узел *дитя = узел_число_детей(узел) > 0 ? узел_ребёнок(узел, 0) : nullptr;
            if (!дитя || дитя->тип == УЗЕЛ_БЛОК) {
                // Блок-форма как выражение не бывает (это оператор).
                ошибка_семантики(а, &узел->токен,
                    "«небезопасно { … }» в позиции выражения ожидает одно выражение");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            а->глубина_небезопасно++;
            ИнфоТипа т = типизировать_выражение(а, дитя);
            а->глубина_небезопасно--;
            return т;
        }

        case УЗЕЛ_ПРИВЕДЕНИЕ: {
            ИнфоТипа ист = типизировать_выражение(а, узел_ребёнок(узел, 0));
            if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
            // Приводить можно только скаляры: числа, указатели, перечисления.
            int ок = ист.тип == ТОКЕН_НЕИЗВЕСТНЫЙ || тип_арифметический(ист)
                  || тип_указатель(ист) || ист.тип == ТОКЕН_ПЕРЕЧИСЛЕНИЕ;
            if (ист.срез || ист.тип == ТОКЕН_СТРУКТУРА || !ок) {
                ошибка_семантики(а, &узел->токен,
                    "приведение «как» применимо только к числам, указателям "
                    "и перечислениям");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            // Именованный тип-цель («как<Точка*>»): разрешаем индекс структуры
            // из имя_типа — иначе результат не совместим с «Точка* п = …».
            int инд_цели = -1;
            if (узел->тип_данных == ТОКЕН_СТРУКТУРА && узел->имя_типа.длина > 0)
                инд_цели = найти_индекс_структуры(а, &узел->имя_типа);
            ИнфоТипа цель = { узел->тип_данных, узел->указатели,
                              узел->беззнаковый, 0, инд_цели };
            // Запрет создания указателя из целого/перечисления: это позволило бы
            // сфабриковать произвольный адрес и разыменовать его (обход всех
            // проверок). Допустимы указатель→указатель и «нуль»→указатель.
            if (тип_указатель(цель) && !тип_указатель(ист)
                && ист.тип != ТОКЕН_НЕИЗВЕСТНЫЙ) {
                ошибка_семантики(а, &узел->токен,
                    "нельзя приводить целое/перечисление к указателю: фабрикация "
                    "произвольного указателя небезопасна (приводите указатель к "
                    "указателю или используйте «нуль»)");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            // Реинтерпретация указателя к указателю другого типа (или другой
            // глубины) обходит типобезопасность: биты, размещённые как один тип,
            // читаются как другой (type confusion). Разрешено только в
            // «небезопасно { }». Указатель того же типа (напр. смена знаковости) —
            // no-op и не считается реинтерпретацией.
            if (тип_указатель(цель) && тип_указатель(ист)
                && ист.тип != ТОКЕН_НУЛ_УКАЗАТЕЛЬ
                && (цель.тип != ист.тип || цель.указатели != ист.указатели)
                && а->глубина_небезопасно == 0) {
                ошибка_семантики(а, &узел->токен,
                    "реинтерпретация указателя к другому типу небезопасна "
                    "(type confusion): оберните в «небезопасно { … }»");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            return цель;
        }

        case УЗЕЛ_РАЗМЕР: {
            // размер_обьекта(тип) — sizeof() в C. Результат всегда целое64
            // (size_t — беззнаковый long, помещается в int64).
            (void)узел;
            return (ИнфоТипа){ ТОКЕН_ЦЕЛОЕ64, 0, 0, 0, -1 };
        }

        case УЗЕЛ_ИДЕНТИФИКАТОР: {
            Символ *с = найти_символ(а, узел->токен.начало, узел->токен.длина);
            if (!с) {
                // Идентификатор может быть вариантом перечисления — это значение
                // соответствующего enum-типа (константа).
                int ие = найти_вариант(а, узел->токен.начало, узел->токен.длина,
                                       nullptr);
                if (ие >= 0) {
                    return (ИнфоТипа){ ТОКЕН_ПЕРЕЧИСЛЕНИЕ, 0, 0, 0, ие };
                }
                char msg[256];
                snprintf(msg, sizeof(msg), "неизвестная переменная «%.*s»",
                         (int)узел->токен.длина, узел->токен.начало);
                ошибка_семантики(а, &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            if (с->перемещён) {
                char msg[256];
                if (с->токен_move.строка > 0) {
                    snprintf(msg, sizeof(msg),
                             "срез «%.*s» использован после передачи владения "
                             "(move на строке %d)",
                             (int)узел->токен.длина, узел->токен.начало,
                             с->токен_move.строка);
                } else {
                    snprintf(msg, sizeof(msg),
                             "срез «%.*s» использован после передачи владения (move)",
                             (int)узел->токен.длина, узел->токен.начало);
                }
                ошибка_семантики(а, &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            if (!с->инициализирована) {
                char msg[256];
                snprintf(msg, sizeof(msg),
                         "переменная «%.*s» используется до инициализации",
                         (int)узел->токен.длина, узел->токен.начало);
                ошибка_семантики(а, &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            return (ИнфоТипа){ с->тип, с->указатели, с->беззнаковый, с->срез, с->индекс_структуры };
        }

        case УЗЕЛ_ПОЛЕ: {
            ИнфоТипа база = типизировать_выражение(а, узел_ребёнок(узел, 0));
            if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
            // Доступ «.» — у структуры или указателя на структуру (авто-«->»).
            if (база.тип != ТОКЕН_СТРУКТУРА || база.индекс_структуры < 0
                || база.указатели > 1) {
                ошибка_семантики(а, &узел->токен,
                    "доступ к полю «.» возможен только у структуры");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            // Для кодогена: доступ через указатель → «->», иначе «.».
            узел->указатели = (база.указатели == 1) ? 1 : 0;
            // Разыменование nullable-указателя на структуру: «у.поле» — это
            // «у->поле» в C, то есть разыменование. Если база — указатель-
            // переменная, которая может быть нулём на каком-то пути (объявлена
            // «возможно<T*>» и не сужена охранником), доступ к полю запрещён —
            // так же, как индексирование nullable-указателя выше. Внутри
            // «если (у != нуль) …» null-narrowing снимает может_быть_нуль.
            if (база.указатели == 1) {
                Узел *баз_узел = узел_ребёнок(узел, 0);
                if (баз_узел && баз_узел->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                    Символ *бс = найти_символ(а, баз_узел->токен.начало,
                                              баз_узел->токен.длина);
                    if (бс && бс->может_быть_нуль) {
                        char msg[320];
                        snprintf(msg, sizeof(msg),
                            "разыменование указателя «%.*s», который может быть "
                            "нулевым: доступ к полю «%.*s» только под охранником "
                            "«если (%.*s != нуль) …»",
                            (int)баз_узел->токен.длина, баз_узел->токен.начало,
                            (int)узел->токен.длина, узел->токен.начало,
                            (int)баз_узел->токен.длина, баз_узел->токен.начало);
                        ошибка_семантики(а, &узел->токен, msg);
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                } else if (баз_узел && баз_узел->тип == УЗЕЛ_ВЫЗОВ
                           && выражение_может_быть_нуль(а, баз_узел)) {
                    // Прямой дереф результата вызова с «возможно<T*>»-возвратом
                    // («найти(5).поле»): временный нельзя сузить охранником —
                    // сперва присвоить в переменную. Раньше не ловилось → null-дереф.
                    ошибка_семантики(а, &узел->токен,
                        "разыменование результата вызова, который может быть "
                        "нулевым («возможно<T*>»): присвойте его в переменную и "
                        "проверьте «если (x != нуль) …»");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
            }
            ОписаниеСтруктуры *с = &а->структуры[база.индекс_структуры];
            // Доступ к члену «союза» — type confusion: члены разделяют память,
            // и чтение неактивного члена интерпретирует чужие биты как свой тип.
            // Транспилятор не отслеживает активный член, поэтому такой доступ
            // разрешён только в «небезопасно { }» (проверка статическая, без
            // рантайм-цены). Безопасная альтернатива — «перечисление» + «выбор»
            // (тег отслеживается, читается только активный вариант).
            if (с->это_союз && а->глубина_небезопасно == 0) {
                char msg[400];
                snprintf(msg, sizeof(msg),
                    "доступ к члену «%.*s» союза «%s» небезопасен (type "
                    "confusion: активный член не отслеживается) — оберните в "
                    "«небезопасно { … }» или используйте перечисление+выбор",
                    (int)узел->токен.длина, узел->токен.начало, с->имя);
                ошибка_семантики(а, &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            for (size_t i = 0; i < с->число_полей; ++i) {
                ПолеСтруктуры *п = &с->поля[i];
                if (байты_равны(п->имя, strlen(п->имя),
                                узел->токен.начало, узел->токен.длина)) {
                    // Поле-массив: помечаем узел доступа (массив+длина) — тогда
                    // «с.поле[i]» индексируется через ту же машинерию фикс.массива
                    // (двухдетная форма УЗЕЛ_ИНДЕКС смотрит на узел базы).
                    if (п->массив) {
                        узел->массив = 1;
                        узел->размер_массива = п->размер_массива;
                    }
                    return (ИнфоТипа){ п->тип, п->указатели, п->беззнаковый, п->срез,
                                       п->индекс_структуры };
                }
            }
            char msg[256];
            snprintf(msg, sizeof(msg),
                     "у структуры «%s» нет поля «%.*s»",
                     с->имя, (int)узел->токен.длина, узел->токен.начало);
            ошибка_семантики(а, &узел->токен, msg);
            return ТИП_НЕИЗВЕСТЕН_V;
        }

        case УЗЕЛ_ИНДЕКС: {
            // Индексация произвольного lvalue: «структура.поле[i]», «функция()[i]».
            // Новая форма узла — дети [база-выражение, индекс]. Поддержана только
            // срезовая база (у среза длина при себе → рантайм-проверка границ без
            // символа). Массив/указатель на месте не индексируем (нет длины/символа).
            if (узел_число_детей(узел) == 2) {
                ИнфоТипа тбазы = типизировать_выражение(а, узел_ребёнок(узел, 0));
                if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                Узел *индекс2 = узел_ребёнок(узел, 1);
                ИнфоТипа тинд = типизировать_выражение(а, индекс2);
                if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                if (тинд.тип != ТОКЕН_НЕИЗВЕСТНЫЙ && !тип_целочисленный(тинд)) {
                    ошибка_семантики(а, &узел->токен,
                        "индекс должен быть целым числом");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                Узел *база_узел2 = узел_ребёнок(узел, 0);
                // Поле-массив/элемент фикс. размера на месте: «с.поле[i]»,
                // «таблица[i].поле[j]». База помечена массивом (УЗЕЛ_ПОЛЕ/ИНДЕКС),
                // длина известна статически — прямой доступ с проверкой границ.
                if (!тбазы.срез && база_узел2->массив
                    && база_узел2->размер_массива > 0) {
                    узел->массив = 1;
                    узел->тип_данных = тбазы.тип;
                    узел->беззнаковый = тбазы.беззнаковый;
                    узел->указатели = тбазы.указатели;
                    узел->размер_массива = база_узел2->размер_массива;
                    // Элемент-структура: имя типа — с базы (для каста кодогена).
                    if (тбазы.тип == ТОКЕН_СТРУКТУРА
                        && тбазы.индекс_структуры >= 0) {
                        узел->имя_типа =
                            а->структуры[тбазы.индекс_структуры].имя_токен;
                    }
                    long idx;
                    int конст = вычислить_константу(а, индекс2, &idx);
                    if (конст && (idx < 0 || idx >= база_узел2->размер_массива)) {
                        char msg[160];
                        snprintf(msg, sizeof msg,
                            "индекс %ld вне границ поля-массива длины %ld",
                            idx, база_узел2->размер_массива);
                        ошибка_семантики(а, &индекс2->токен, msg);
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    // Индекс: доказано-безопасный (константа/канонический
                    // счётчик) → прямой доступ, безопасный_индекс=1. Иначе:
                    //   • 2D-ряд (база_узел2 несёт размер_массива_2 > 0) —
                    //     разрешаем dyn: кодоген эмитит массив_доступ_2d;
                    //   • обычное поле-массив (не 2D) — dyn пока не поддержан
                    //     (нет рантайм-пути для s.f[i] на месте).
                    int безопасен = (конст && idx >= 0
                                     && idx < база_узел2->размер_массива)
                        || индекс_безопасен_(а, индекс2, &база_узел2->токен, 1,
                                             база_узел2->размер_массива);
                    if (безопасен) {
                        узел->безопасный_индекс = 1;
                    } else if (база_узел2->размер_массива_2 <= 0) {
                        // Не 2D-ряд и не безопасный — ошибка (v1 поля-массивы).
                        ошибка_семантики(а, &узел->токен,
                            "индекс поля-массива на месте пока только константный "
                            "или канонический счётчик цикла (динамический — "
                            "присвойте поле/срез в переменную)");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    return (ИнфоТипа){ тбазы.тип, тбазы.указатели, тбазы.беззнаковый,
                                       0, тбазы.индекс_структуры };
                }
                // P2: сырое индексирование УКАЗАТЕЛЯ на месте («call()[i]»,
                // «(ptr)[i]») ПОД «небезопасно». В отличие от среза, у указателя
                // нет ВЛАДЕЮЩЕГО временного (он заимствован/сырой) — утечки нет,
                // это обычная raw-pointer-операция за гейтом. Частый паттерн:
                // «errno = X» → «(__errno_location())[0] = X». Результат —
                // разыменованный элемент (указатели−1). Кодоген — прямой C
                // «(база)[индекс]» (ветка узел->массив && !узел->срез).
                if (!тбазы.срез && тбазы.указатели > 0
                    && а->глубина_небезопасно > 0) {
                    узел->массив = 1;
                    узел->тип_данных = тбазы.тип;
                    узел->беззнаковый = тбазы.беззнаковый;
                    узел->указатели = тбазы.указатели - 1;
                    if (тбазы.тип == ТОКЕН_СТРУКТУРА && тбазы.индекс_структуры >= 0)
                        узел->имя_типа = а->структуры[тбазы.индекс_структуры].имя_токен;
                    return (ИнфоТипа){ тбазы.тип, тбазы.указатели - 1,
                                       тбазы.беззнаковый, 0, тбазы.индекс_структуры };
                }
                if (!тбазы.срез) {
                    // Указатель без гейта — подсказать про «небезопасно».
                    if (тбазы.указатели > 0)
                        ошибка_семантики(а, &узел->токен,
                            "индексирование указателя на месте — только внутри "
                            "«небезопасно { }» (сырая операция без проверки границ)");
                    else
                        ошибка_семантики(а, &узел->токен,
                            "индексирование на месте поддержано только для среза "
                            "(для массива/указателя присвойте в переменную)");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                // §3: индексация результата вызова на месте («функция()[i]»).
                // Кодоген эмитит «срез_доступ(f(), i, sizeof(T), стр)» — вызов
                // МАТЕРИАЛИЗУЕТСЯ РОВНО ОДИН РАЗ (Срез передаётся по значению),
                // так что двойного вызова нет. Единственная опасность —
                // ВЛАДЕЮЩИЙ временный срез: его .данные никто не освободит
                // (утечка). Поэтому разрешаем ТОЛЬКО когда база — ПРЯМОЙ вызов
                // функции с ЗАИМСТВОВАННЫМ возвратом (вид в чужую память: .rodata
                // / срез вызывающего) — освобождать нечего, утечки нет (§37 п.6,
                // бит возврат_заимствован на call-узле). Вызов, спрятанный в
                // цепочке поля/индекса, или владеющий возврат — по-прежнему
                // ошибка: присвойте результат в переменную (autofree освободит).
                {
                    const Узел *база3 = узел_ребёнок(узел, 0);
                    int заим_вызов = база3 && база3->тип == УЗЕЛ_ВЫЗОВ
                                     && база3->возврат_заимствован;
                    if (!заим_вызов && выражение_содержит_вызов(база3)) {
                        ошибка_семантики(а, &узел->токен,
                            "нельзя индексировать на месте срез из результата "
                            "ВЛАДЕЮЩЕГО вызова (временный утёк бы): присвойте его "
                            "в переменную (autofree освободит). Заимствующий-"
                            "возврат вызов индексировать на месте можно");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                }
                // Кодоген отличает срезовый доступ по флагу и типу элемента.
                узел->срез = 1;
                узел->тип_данных = тбазы.тип;
                узел->беззнаковый = тбазы.беззнаковый;
                узел->указатели = тбазы.указатели;   // косвенность элемента (срез<T*>)
                // Имя типа элемента-структуры — для каста кодогена «(Точка*)…».
                if (тбазы.тип == ТОКЕН_СТРУКТУРА && тбазы.индекс_структуры >= 0)
                    узел->имя_типа = а->структуры[тбазы.индекс_структуры].имя_токен;
                return (ИнфоТипа){ тбазы.тип, тбазы.указатели, тбазы.беззнаковый, 0,
                                   тбазы.индекс_структуры };
            }
            Символ *база = найти_символ(а, узел->токен.начало, узел->токен.длина);
            if (!база) {
                char msg[256];
                snprintf(msg, sizeof(msg), "неизвестная переменная «%.*s»",
                         (int)узел->токен.длина, узел->токен.начало);
                ошибка_семантики(а, &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            if (!база->срез && база->указатели == 0 && база->массив == 0) {
                char msg[256];
                snprintf(msg, sizeof(msg),
                         "индексирование «%.*s»: тип не является срезом, указателем или массивом",
                         (int)узел->токен.длина, узел->токен.начало);
                ошибка_семантики(а, &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            if (база->перемещён) {
                char msg[256];
                if (база->токен_move.строка > 0) {
                    snprintf(msg, sizeof(msg),
                             "срез «%.*s» использован после передачи владения "
                             "(move на строке %d)",
                             (int)узел->токен.длина, узел->токен.начало,
                             база->токен_move.строка);
                } else {
                    snprintf(msg, sizeof(msg),
                             "срез «%.*s» использован после передачи владения (move)",
                             (int)узел->токен.длина, узел->токен.начало);
                }
                ошибка_семантики(а, &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            // Нулевое разыменование: индексирование указателя, который может быть
            // «нуль» на каком-то пути исполнения (объявлен «= нуль», без
            // инициализатора, переприсвоен «нуль», либо после if/цикла остаётся
            // нулевым хотя бы на одной ветви). Срезы/массивы сюда не попадают —
            // у них своя проверка границ.
            if (база->указатели > 0 && !база->срез && !база->массив
                && база->может_быть_нуль) {
                char msg[256];
                snprintf(msg, sizeof(msg),
                         "разыменование указателя «%.*s», который может быть "
                         "нулевым (нуль на одном из путей исполнения)",
                         (int)узел->токен.длина, узел->токен.начало);
                ошибка_семантики(а, &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            Узел *индекс = узел_ребёнок(узел, 0);
            // Тип индекса должен быть целочисленным.
            ИнфоТипа тип_инд = типизировать_выражение(а, индекс);
            if (!а->диаг->ошибка && тип_инд.тип != ТОКЕН_НЕИЗВЕСТНЫЙ
                && !тип_целочисленный(тип_инд)) {
                char тб[64];
                описание_типа(тип_инд, тб, sizeof(тб));
                char msg[256];
                snprintf(msg, sizeof(msg),
                         "индекс должен быть целым числом, получен «%s»", тб);
                ошибка_семантики(а, &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }

            if (база->срез) {
                // Кодоген отличает срезовый доступ по флагу и типу элемента.
                узел->срез = 1;
                узел->тип_данных = база->тип;
                узел->беззнаковый = база->беззнаковый;
                узел->указатели = база->указатели;   // косвенность элемента (срез<T*>)
                // Имя типа элемента-структуры — для каста кодогена «(Точка*)…».
                if (база->тип == ТОКЕН_СТРУКТУРА && база->индекс_структуры >= 0)
                    узел->имя_типа = а->структуры[база->индекс_структуры].имя_токен;
                long idx;
                int конст = вычислить_константу(а, индекс, &idx);
                // Статическая проверка границ для константного индекса.
                if (база->длина_известна && конст
                    && (idx < 0 || idx >= база->длина)) {
                    char msg[256];
                    snprintf(msg, sizeof(msg),
                             "индекс %ld вне границ среза «%.*s» длины %ld",
                             idx, (int)узел->токен.длина, узел->токен.начало,
                             база->длина);
                    ошибка_семантики(а, &индекс->токен, msg);
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                // Элиминация проверки: безопасно, если константный индекс в
                // границах известной длины, либо индекс цикла по этому срезу.
                if (!а->режим_вывода
                    && ((база->длина_известна && конст && idx >= 0 && idx < база->длина)
                    || индекс_в_безопасном_контексте(а, узел,
                                                      база->длина_известна, база->длина))) {
                    узел->безопасный_индекс = 1;
                }
                // Косвенный доступ «база[индексы[j]]» (индекс-буфер): если
                // «индексы» доказан в границах базы через «утверждать_в_границах»,
                // значение индексы[j] ∈ [0, длина(база)) → безопасно (прямой
                // доступ без проверки в горячем цикле). Имя индекс-среза — из
                // самого индекс-выражения (одно/двух-детная форма УЗЕЛ_ИНДЕКС).
                if (!а->режим_вывода && !узел->безопасный_индекс
                    && индекс && индекс->тип == УЗЕЛ_ИНДЕКС) {
                    const Токен *инд_база = &индекс->токен;
                    if (узел_число_детей(индекс) == 2) {
                        Узел *б = узел_ребёнок(индекс, 0);
                        if (б && б->тип == УЗЕЛ_ИДЕНТИФИКАТОР) инд_база = &б->токен;
                    }
                    if (индекс_срез_в_границах(а, инд_база->начало, инд_база->длина,
                                               узел->токен.начало, узел->токен.длина))
                        узел->безопасный_индекс = 1;
                }
                return (ИнфоТипа){ база->тип, база->указатели, база->беззнаковый, 0,
                                   база->индекс_структуры };
            }

            // Массив фикс. размера (длина известна компайл-тайм) ИЛИ массив с
            // выводимым размером «имя[]» из «встроить»/#embed (длину знает лишь C).
            // В обоих случаях доступ безопасен: кодоген берёт длину через sizeof.
            // Для известной длины — статическая проверка/элизия; для выводимой —
            // всегда рантайм-проверка (sizeof) без статических доказательств.
            if (база->массив) {
                узел->массив = 1;
                узел->тип_данных = база->тип;
                узел->беззнаковый = база->беззнаковый;
                узел->указатели = база->указатели;
                if (база->тип == ТОКЕН_СТРУКТУРА && база->индекс_структуры >= 0)
                    узел->имя_типа = а->структуры[база->индекс_структуры].имя_токен;
                long idx;
                int конст = вычислить_константу(а, индекс, &idx);
                if (база->длина_известна && конст && (idx < 0 || idx >= база->длина)) {
                    char msg[256];
                    snprintf(msg, sizeof(msg),
                             "индекс %ld вне границ массива «%.*s» длины %ld",
                             idx, (int)узел->токен.длина, узел->токен.начало,
                             база->длина);
                    ошибка_семантики(а, &индекс->токен, msg);
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                if (!а->режим_вывода && база->длина_известна
                    && ((конст && idx >= 0 && idx < база->длина)
                    || индекс_в_безопасном_контексте(а, узел,
                                                      база->длина_известна, база->длина))) {
                    узел->безопасный_индекс = 1;
                }
                // 2D-массив «T a[N][M]»: первый индекс даёт «ряд» (1D-массив
                // длины M). Безопасность обоих измерений: если индекс доказано
                // безопасен (константа/канонический счётчик) — прямой доступ
                // «a[i][j]» без рантайм-проверок; иначе кодоген эмитит
                // «массив_доступ_2d» с рантайм-проверкой. Инвариант №1 цел:
                // цена — только на пути, где статика не сработала.
                if (база->длина_2 > 0) {
                    // «Ряд» несёт размер второй оси — outer [j] проверит его.
                    узел->размер_массива = база->длина_2;
                    // Кодоген смотрит на безопасный_индекс: 1 → прямой a[i],
                    // 0 → рантайм-путь через массив_доступ_2d (при dyn на любой
                    // из осей). Флаг «второе_измерение» отличает 2D-ряд от
                    // обычного 1D-массива в OUTER-ветке.
                    узел->размер_массива_2 = база->длина_2;
                    return (ИнфоТипа){ база->тип, база->указатели, база->беззнаковый, 0,
                                       база->индекс_структуры };
                }
                return (ИнфоТипа){ база->тип, база->указатели, база->беззнаковый, 0,
                                   база->индекс_структуры };
            }

            // Указатель/массив-параметр: проверка границ только при
            // зарегистрированной длине (аргументы ↔ количество_аргументов).
            // Указатель с зарегистрированной длиной («аргументы» ↔ argc) —
            // безопасная обёртка над argv. Константный индекс при наличии
            // ограничения проверяется статически (и при доказанной безопасности
            // доступ прямой); динамический или недоказанный — рантайм-проверкой.
            if (у_указателя_есть_длина(а, узел->токен.начало, узел->токен.длина)) {
                long idx, мин;
                int проверен_статически = 0;
                if (вычислить_константу(а, индекс, &idx)
                    && известна_длина_массива(а, узел->токен.начало,
                                              узел->токен.длина, &мин)) {
                    проверить_доступ_к_массиву(а, &индекс->токен,
                        узел->токен.начало, узел->токен.длина, idx);
                    проверен_статически = 1;  // доказан в границах → прямой доступ
                }
                if (!проверен_статически && !а->режим_вывода) {
                    узел->проверка_аргументов = 1;  // рантайм-проверка границ
                }
            } else if (а->глубина_небезопасно == 0) {
                // Индексация сырого указателя без известной длины — доступ к
                // памяти без проверки границ. Разрешено только в «небезопасно».
                // (Срезы, массивы фикс. размера и argv сюда не попадают — у них
                // длина известна и проверка границ есть.) Гейт статический.
                char msg[256];
                snprintf(msg, sizeof(msg),
                    "индексация сырого указателя «%.*s» запрещена в безопасном "
                    "коде (нет проверки границ): используйте «срез<T>» или "
                    "оберните в «небезопасно { … }»",
                    (int)узел->токен.длина, узел->токен.начало);
                ошибка_семантики(а, &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            int ур = база->указатели > 0 ? база->указатели - 1 : 0;
            return (ИнфоТипа){ база->тип, ур, база->беззнаковый, 0, -1 };
        }

        case УЗЕЛ_СРЕЗ_ДИАПАЗОН: {
            // §42: «база[начало:конец]» — заимствованный ВИД над срезом. База
            // обязана быть срезом (у среза есть длина → безопасная проверка границ
            // без символа). Индексы БАЙТОВЫЕ; для «срез<символ>» кодоген
            // дополнительно проверяет попадание на границу UTF-8-символа.
            Узел *база_узел = узел_ребёнок(узел, 0);
            ИнфоТипа тбазы = типизировать_выражение(а, база_узел);
            if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
            if (!тбазы.срез) {
                ошибка_семантики(а, &узел->токен,
                    "срез-диапазон «[a:b]» применим только к срезу "
                    "(строке / срез<T>)");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            // Растущий буфер: заимствованный ВИД «б[a:b]» указывал бы в его память,
            // а «добавить»/«перевыделить» через realloc МОГУТ её переместить →
            // вид повис бы (use-after-free). Статически запрещаем (v1): нужна
            // владеющая КОПИЯ — «копия(б[a:b])» — или приведите буфер к срезу как
            // аргумент вызова (borrow на время вызова, роста в это время нет).
            int база_буфер = 0;
            if (база_узел->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                Символ *сб = найти_символ(а, база_узел->токен.начало,
                                          база_узел->токен.длина);
                база_буфер = сб && сб->буфер;
            } else if (база_узел->тип == УЗЕЛ_ПОЛЕ) {
                база_буфер = поле_буфер_из_узла(а, база_узел) != nullptr;
                if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
            }
            if (база_буфер) {
                ошибка_семантики(а, &узел->токен,
                    "нельзя брать заимствованный вид «[a:b]» растущего буфера "
                    "(рост через realloc сделал бы вид висячим): используйте "
                    "«копия(...)» для владеющей копии или передайте буфер как "
                    "аргумент функции, принимающей срез");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            // Владеющий временный из вызова индексировать нельзя (утёк бы) — как и
            // при обычной индексации на месте: присвойте результат в переменную.
            if (выражение_содержит_вызов(база_узел)) {
                ошибка_семантики(а, &узел->токен,
                    "нельзя брать вид от среза-результата вызова "
                    "(владеющий временный утёк бы): присвойте его в переменную");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            // Границы — целые (если заданы). Пустой конец = длина, пустое начало = 0;
            // отрицательные значения = отсчёт с конца (нормализует кодоген).
            size_t реб = 1;
            if (узел->есть_начало) {
                ИнфоТипа тн = типизировать_выражение(а, узел_ребёнок(узел, реб++));
                if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                if (тн.тип != ТОКЕН_НЕИЗВЕСТНЫЙ && !тип_целочисленный(тн)) {
                    ошибка_семантики(а, &узел->токен,
                        "начало среза-диапазона должно быть целым числом");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
            }
            if (узел->есть_конец) {
                ИнфоТипа тк = типизировать_выражение(а, узел_ребёнок(узел, реб++));
                if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                if (тк.тип != ТОКЕН_НЕИЗВЕСТНЫЙ && !тип_целочисленный(тк)) {
                    ошибка_семантики(а, &узел->токен,
                        "конец среза-диапазона должен быть целым числом");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
            }
            // Тип ЭЛЕМЕНТА — кодогену (эл_размер, каст). Результат — срез того же
            // типа, ЗАИМСТВОВАННЫЙ (autofree его не трогает).
            узел->срез = 1;
            узел->тип_данных = тбазы.тип;
            узел->беззнаковый = тбазы.беззнаковый;
            узел->указатели = тбазы.указатели;
            if (тбазы.тип == ТОКЕН_СТРУКТУРА && тбазы.индекс_структуры >= 0)
                узел->имя_типа = а->структуры[тбазы.индекс_структуры].имя_токен;
            return (ИнфоТипа){ тбазы.тип, тбазы.указатели, тбазы.беззнаковый, 1,
                               тбазы.индекс_структуры };
        }

        case УЗЕЛ_УНОП: {
            ИнфоТипа операнд = типизировать_выражение(а, узел_ребёнок(узел, 0));
            if (!а->диаг->ошибка && токен_текст_равен(&узел->токен, "-")) {
                if (!тип_арифметический(операнд) && операнд.тип != ТОКЕН_НЕИЗВЕСТНЫЙ) {
                    ошибка_семантики(а, &узел->токен,
                        "унарный «-» применим только к арифметическим типам");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
            }
            if (!а->диаг->ошибка && токен_текст_равен(&узел->токен, "~")) {
                if (!тип_целочисленный(операнд) && операнд.тип != ТОКЕН_НЕИЗВЕСТНЫЙ) {
                    ошибка_семантики(а, &узел->токен,
                        "унарное побитовое «~» применимо только к целочисленным типам");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
            }
            return операнд;
        }

        case УЗЕЛ_БИНОП: {
            ИнфоТипа л = типизировать_выражение(а, узел_ребёнок(узел, 0));
            ИнфоТипа п = типизировать_выражение(а, узел_ребёнок(узел, 1));
            if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;

            // Перегрузка оператора: если хоть один операнд — структура-значение,
            // встроенного оператора для него нет. Ищем пользовательскую
            // перегрузку по манглированному имени; нашли → вызов (кодоген через
            // собственное_имя узла), нет → понятная ошибка вместо битого C.
            if (тип_структура_значение(л) || тип_структура_значение(п)) {
                char имя[МАКС_ИМЯ * 3];
                СигнатураФункции *сп = nullptr;
                if (имя_перегрузки_из_инфо(а, &узел->токен, л, п, имя, sizeof имя))
                    сп = найти_сигнатуру_по_имени(а, имя, strlen(имя));
                if (сп) {
                    free(узел->собственное_имя);
                    узел->собственное_имя = strdup(имя);  // имя вызова для кодогена
                    return (ИнфоТипа){ сп->тип_возврата, сп->указатели_возврата,
                                       сп->беззнаковый, сп->срез,
                                       сп->индекс_структуры_возврата };
                }
                char тл[64], тп[64];
                описание_типа(л, тл, sizeof тл);
                описание_типа(п, тп, sizeof тп);
                char msg[512];
                snprintf(msg, sizeof msg,
                    "нет перегрузки оператора «%.*s» для «%s» и «%s» "
                    "(объявите «Тип оператор%.*s(Л а, П б) { … }»)",
                    (int)узел->токен.длина, узел->токен.начало, тл, тп,
                    (int)узел->токен.длина, узел->токен.начало);
                ошибка_семантики(а, &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }

            const Токен *оп = &узел->токен;
            int деление = токен_текст_равен(оп, "/") || токен_текст_равен(оп, "%");
            int сдвиг   = токен_текст_равен(оп, "<<") || токен_текст_равен(оп, ">>");
            int слож_выч_умн = токен_текст_равен(оп, "+")
                            || токен_текст_равен(оп, "-")
                            || токен_текст_равен(оп, "*");

            // Свёртка операндов (если они константны) — для статических проверок
            // деления/сдвига/переполнения без рантайма.
            long л0, п0;
            int кл = вычислить_константу(а, узел_ребёнок(узел, 0), &л0);
            int кп = вычислить_константу(а, узел_ребёнок(узел, 1), &п0);

            // Деление/остаток на константный ноль.
            if (деление && кп && п0 == 0) {
                ошибка_семантики(а, &узел_ребёнок(узел, 1)->токен,
                    "деление на ноль: делитель константно равен нулю");
                return ТИП_НЕИЗВЕСТЕН_V;
            }

            // Гейт арифметики указателей: «ptr ± целое» и «ptr − ptr» уводят
            // указатель за пределы объекта без проверки границ — разрешено только
            // в «небезопасно { }». Сравнения указателей (>,<,==) безопасны и не
            // гейтятся. Проверка статическая, без рантайм-цены.
            {
                int аоп = токен_текст_равен(оп, "+") || токен_текст_равен(оп, "-");
                if (аоп && (тип_указатель(л) || тип_указатель(п))
                    && а->глубина_небезопасно == 0) {
                    ошибка_семантики(а, оп,
                        "арифметика указателей запрещена в безопасном коде: "
                        "используйте «срез<T>» с индексацией или оберните в "
                        "«небезопасно { … }»");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
            }

            // Проверка совместимости операндов.
            if (л.тип != ТОКЕН_НЕИЗВЕСТНЫЙ && п.тип != ТОКЕН_НЕИЗВЕСТНЫЙ) {
                ИнфоТипа рез;
                if (!тип_бинопа(л, п, оп, &рез)) {
                    char тл[64], тп[64];
                    описание_типа(л, тл, sizeof(тл));
                    описание_типа(п, тп, sizeof(тп));
                    char msg[256];
                    snprintf(msg, sizeof(msg),
                             "несовместимые типы для «%.*s»: «%s» и «%s»",
                             (int)узел->токен.длина, узел->токен.начало, тл, тп);
                    ошибка_семантики(а, &узел->токен, msg);
                    return ТИП_НЕИЗВЕСТЕН_V;
                }

                // Инициализация нулём: мин/макс читаются только под
                // «есть_диапазон» (тогда диапазон_целого их и записал), но
                // компилятор этого не доказывает → -Wmaybe-uninitialized.
                long мин = 0, макс = 0;
                int есть_диапазон = диапазон_целого(рез.тип, рез.беззнаковый,
                                                    &мин, &макс);

                // Сдвиг на константное число бит вне [0, ширина): UB в C.
                if (сдвиг && кп) {
                    int ширина = ширина_бит(л);
                    if (ширина > 0 && (п0 < 0 || п0 >= ширина)) {
                        char msg[256];
                        snprintf(msg, sizeof(msg),
                            "сдвиг на %ld бит вне диапазона [0, %d) для типа операнда",
                            п0, ширина);
                        ошибка_семантики(а, оп, msg);
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                }

                // Переполнение деления: МИН_типа / -1 (или % -1) — UB.
                if (деление && кл && кп && п0 == -1
                    && есть_диапазон && мин < 0 && л0 == мин) {
                    ошибка_семантики(а, оп,
                        "переполнение деления: минимальное значение типа делится на -1");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }

                // Переполнение константного «+/-/*» относительно типа результата.
                if (слож_выч_умн && кл && кп) {
                    long r;
                    int пер = токен_текст_равен(оп, "+")
                                ? __builtin_add_overflow(л0, п0, &r)
                            : токен_текст_равен(оп, "-")
                                ? __builtin_sub_overflow(л0, п0, &r)
                                : __builtin_mul_overflow(л0, п0, &r);
                    if (пер || (есть_диапазон && (r < мин || r > макс))) {
                        char тр[64];
                        описание_типа(рез, тр, sizeof(тр));
                        char msg[256];
                        snprintf(msg, sizeof(msg),
                            "переполнение в константном выражении типа «%s»", тр);
                        ошибка_семантики(а, оп, msg);
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                }

                // Неконстантный делитель/сдвиг — статически не доказать; кодоген
                // вставит одну рантайм-проверку (деление на ноль / диапазон бит).
                // В проходе вывода тип-аргументов кодоген-подсказки НЕ пишем: там
                // символы без «значение_известно», подсказка была бы ложной и
                // пережила бы до кодогена (проход 2 её не сбрасывает).
                if (а->режим_вывода) {
                    // только тип — без побочных пометок для кодогена
                } else if (деление && !кп && тип_целочисленный(рез)) {
                    // Только ЦЕЛОЧИСЛЕННОЕ деление UB-опасно (÷0, МИН/-1). Деление
                    // вещественных ÷0 определено (inf/nan) → НЕ гейтим (иначе
                    // (long)double усекал бы результат — старый баг отладки).
                    узел->проверка_бинопа = 1;
                    узел->размер_массива = ширина_бит(рез);  // разрядность (для MIN/-1)
                    узел->беззнаковый = рез.беззнаковый;      // знак: MIN/-1 только знак.
                } else if (сдвиг && !кп) {
                    узел->проверка_бинопа = 2;
                    узел->размер_массива = ширина_бит(л);  // разрядность для guard
                } else if (слож_выч_умн && !(кл && кп)
                           && тип_целочисленный(л) && тип_целочисленный(п)
                           && !рез.беззнаковый) {
                    // Неконстантное «+/-/*» знаковых целых: подписанное
                    // переполнение — UB в C (константы уже проверены выше).
                    // Кодоген вставит один checked-builtin (стиль Rust): при
                    // выходе результата за диапазон типа → сообщение и abort.
                    // Беззнаковые исключены: их перенос определён в C (wrap).
                    // Арифметика указателей исключена: рез — указатель, не
                    // целочисленный. Разность указателей (рез = целое32) тоже
                    // исключена — операнды не целочисленны.
                    int ш = ширина_бит(рез);
                    if (ш > 0) {
                        узел->проверка_бинопа = 3;
                        узел->размер_массива = ш;  // разрядность результата
                    }
                }
                return рез;
            }
            return л.тип != ТОКЕН_НЕИЗВЕСТНЫЙ ? л : п;
        }

        case УЗЕЛ_ИНКРЕМЕНТ: {
            // Постфиксный «цель++»/«цель--» (Go-стиль: только оператор). Проверки
            // как у присваивания-мутации: цель — присваиваемый lvalue и не «конст».
            Узел *цель = узел_ребёнок(узел, 0);
            ИнфоТипа т = типизировать_выражение(а, цель);  // читает цель (ловит неиниц.)
            if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
            Узел *корень = цель;
            while (корень && корень->тип == УЗЕЛ_ПОЛЕ) корень = узел_ребёнок(корень, 0);
            if (!корень || (корень->тип != УЗЕЛ_ИДЕНТИФИКАТОР
                            && корень->тип != УЗЕЛ_ИНДЕКС)) {
                ошибка_семантики(а, &узел->токен,
                    "инкремент/декремент применим только к переменной, элементу "
                    "среза/массива или полю структуры");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            Символ *кс = найти_символ(а, корень->токен.начало, корень->токен.длина);
            if (кс && кс->неизменяемый) {
                ошибка_семантики(а, &узел->токен,
                    "переменная «конст» неизменяема: инкремент/декремент запрещён "
                    "(объявите без «конст», если нужна изменяемость)");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            // Мутация переменной рвёт связь «длина(с) == цель» (как присваивание):
            // после «с = выделить(n); n++» снятие проверки по «и < n» пустило бы
            // запись за границы. Только для простого идентификатора.
            if (цель->тип == УЗЕЛ_ИДЕНТИФИКАТОР)
                сбросить_связь_длины(а, &цель->токен);
            // Тип цели: указатель → арифметика указателя (только «небезопасно»);
            // знаковое целое → guard переполнения в отладке (+1 у МАКС / −1 у МИН —
            // UB без -fwrapv); беззнаковое/вещественное — нативно, без guard.
            if (тип_указатель(т)) {
                if (а->глубина_небезопасно == 0) {
                    ошибка_семантики(а, &узел->токен,
                        "арифметика указателей запрещена в безопасном коде: "
                        "инкремент указателя — только внутри «небезопасно { … }»");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
            } else if (тип_целочисленный(т)) {
                if (!т.беззнаковый) {
                    int ш = ширина_бит(т);
                    if (ш > 0) { узел->проверка_бинопа = 3; узел->размер_массива = ш; }
                }
            } else if (т.тип == ТОКЕН_ВЕЩЕСТВЕННОЕ || т.тип == ТОКЕН_ВЕЩЕСТВЕННОЕ64) {
                // float++ — нативно (переполнения-UB нет)
            } else {
                char тб[64]; описание_типа(т, тб, sizeof тб);
                char msg[256];
                snprintf(msg, sizeof msg,
                    "инкремент/декремент неприменим к типу «%s» "
                    "(нужно целое, вещественное или указатель)", тб);
                ошибка_семантики(а, &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            return т;  // тип = тип цели (значение оператора не используется)
        }

        case УЗЕЛ_ПРИСВАИВАНИЕ: {
            Узел *цель_у = узел_ребёнок(узел, 0);
            Узел *знач_у = узел_ребёнок(узел, 1);
            // Присваивание рвёт связь «длина(с) == н» (если такая была) — иначе
            // после «с = выделить(н); н = 100» снятие проверки по «и < н»
            // пустило бы запись за границы среза.
            if (цель_у && цель_у->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                сбросить_связь_длины(а, &цель_у->токен);
                // Реассайн среза рвёт и группы равной длины «утверждать_равные»
                // (его длина могла измениться → доказательство недействительно).
                сбросить_группы_с(а, цель_у->токен.начало, цель_у->токен.длина);
            }
            // Иммутабельность («конст»): переприсваивание переменной или мутация
            // её элемента/поля запрещены статически. Ищем корневую переменную
            // lvalue (идентификатор/индекс/цепочка полей).
            {
                Узел *корень = цель_у;
                while (корень && корень->тип == УЗЕЛ_ПОЛЕ)
                    корень = узел_ребёнок(корень, 0);
                if (корень && (корень->тип == УЗЕЛ_ИДЕНТИФИКАТОР
                               || корень->тип == УЗЕЛ_ИНДЕКС)) {
                    Символ *кс = найти_символ(а, корень->токен.начало,
                                              корень->токен.длина);
                    if (кс && кс->неизменяемый) {
                        ошибка_семантики(а, цель_у ? &цель_у->токен : &узел->токен,
                            "переменная «конст» неизменяема: переприсваивание/"
                            "изменение запрещено (объявите без «конст», если нужна "
                            "изменяемость)");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                }
            }
            // Простой идентификатор-цель присваивается → инициализирован.
            // Помечаем до типизации цели, чтобы (1) сама цель не считалась
            // «чтением до инициализации» и (2) последующее использование было
            // законным. Источник (знач_у) типизируется ниже и его чтения
            // неинициализированных переменных по-прежнему ловятся.
            if (цель_у && цель_у->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                Символ *цс0 = найти_символ(а, цель_у->токен.начало,
                                           цель_у->токен.длина);
                if (цс0) цс0->инициализирована = 1;
            }
            // Присваивание переменной-указателю на функцию: «оп = функ | указ | нуль».
            if (цель_у && цель_у->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                Символ *цфп = найти_символ(а, цель_у->токен.начало,
                                           цель_у->токен.длина);
                if (цфп && цфп->тип == ТОКЕН_ФУНКУКАЗАТЕЛЬ) {
                    int idx = цфп->индекс_структуры;
                    if (знач_у->тип == УЗЕЛ_НУЛЬ) {
                        цфп->может_быть_нуль = 1;
                    } else if (знач_у->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                        СигнатураФункции *сф = найти_сигнатуру_по_имени(а,
                            знач_у->токен.начало, знач_у->токен.длина);
                        Символ *ис = найти_символ(а, знач_у->токен.начало,
                                                  знач_у->токен.длина);
                        if (сф && idx >= 0 && сигнатура_совпадает_с_типфункцией(сф,
                                &а->типыфункций[idx])) {
                            цфп->может_быть_нуль = 0;
                        } else if (сф) {
                            ошибка_семантики(а, &знач_у->токен,
                                "сигнатура функции не совпадает с типом-указателем");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        } else if (ис && ис->тип == ТОКЕН_ФУНКУКАЗАТЕЛЬ
                                   && ис->индекс_структуры == idx) {
                            цфп->может_быть_нуль = ис->может_быть_нуль;
                        } else {
                            ошибка_семантики(а, &знач_у->токен,
                                "указателю на функцию присваивается имя подходящей "
                                "функции, указатель того же типа или «нуль»");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                    } else {
                        ошибка_семантики(а, &знач_у->токен,
                            "указателю на функцию присваивается имя функции или «нуль»");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    return (ИнфоТипа){ ТОКЕН_ФУНКУКАЗАТЕЛЬ, 0, 0, 0, idx };
                }
            }
            // Запрет записи в строковый литерал: «с[i] = …», где «с» — указатель
            // из строкового литерала (.rodata только для чтения).
            if (цель_у && цель_у->тип == УЗЕЛ_ИНДЕКС) {
                Символ *цб = найти_символ(а, цель_у->токен.начало,
                                          цель_у->токен.длина);
                if (цб && цб->из_литерала) {
                    ошибка_семантики(а, &цель_у->токен,
                        "запись в строковый литерал запрещена (данные только для "
                        "чтения); скопируйте в срез/массив, если нужна изменяемость");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
            }

            ИнфоТипа тц = типизировать_выражение(а, цель_у);
            if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;

            // Структуру-значение с деструктором копировать нельзя: оба экземпляра
            // вызвали бы деструктор (двойное освобождение ресурса).
            if (структура_с_деструктором(а, тц)) {
                ошибка_семантики(а, цель_у ? &цель_у->токен : &узел->токен,
                    "структуру с деструктором нельзя присваивать "
                    "(привело бы к двойному вызову деструктора)");
                return ТИП_НЕИЗВЕСТЕН_V;
            }

            // Переприсваивание срезу: старое значение освобождается (кодоген
            // вставит free), затем цель получает новое владение. Источником может
            // быть «выделить»/«клон» (новая память), вызов функции-среза или
            // другой владеющий срез (move). Цель остаётся владельцем.
            if (тц.срез) {
                if (цель_у->тип != УЗЕЛ_ИДЕНТИФИКАТОР) {
                    // Цель — не простой идентификатор (например, поле «о.данные»):
                    // берём токен цели, у него есть позиция; токен узла-присваивания
                    // не задаётся парсером (иначе «строка 0, колонка 0»). Заодно
                    // подсказываем, что срез-поле нельзя переприсваивать.
                    ошибка_семантики(а, &цель_у->токен,
                        "срезу можно присваивать только по имени переменной; "
                        "переприсваивание срез-поля структуры не поддерживается "
                        "(структура — единственный владелец на весь свой срок)");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                Символ *цс = найти_символ(а, цель_у->токен.начало, цель_у->токен.длина);
                // ЗАПРЕТ (§37 п.1): цель — ВЛАДЕЮЩИЙ «срез<символ>», источник —
                // литерал/f-строка → буфер утёк бы, а autofree попытался бы
                // free borrow-память (.rodata/стек). Даём понятную ошибку до
                // общей «срезу можно присвоить только срез».
                if (цс && цс->владеет_срезом && цс->тип == ТОКЕН_ТИП_СИМВОЛ
                    && цс->указатели == 0 && знач_у
                    && (знач_у->тип == УЗЕЛ_СТРОКА
                        || знач_у->тип == УЗЕЛ_F_СТРОКА)) {
                    ошибка_семантики(а, &цель_у->токен,
                        "нельзя присвоить строковый литерал/f-строку ВЛАДЕЮЩЕМУ "
                        "срезу «срез<символ>»: буфер бы утёк и autofree попытался "
                        "бы освободить borrow-память (.rodata/стек); используйте "
                        "заимствованный срез (объявленный как «срез<символ> с = …») "
                        "или освободите буфер явно до переприсваивания");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                // Переприсваивание «срез<символ>»-переменной строковым литералом
                // (§37): если цель — ЗАИМСТВОВАННЫЙ срез (не владеет) И источник —
                // строковый литерал, это безопасно (borrow ← borrow над .rodata:
                // ни утечки, ни free .rodata). Метим литерал, обновляем провенанс
                // цели, эмитим как обычное присваивание («с = (Срез){…}»).
                if (цс && !цс->владеет_срезом && цс->тип == ТОКЕН_ТИП_СИМВОЛ
                    && цс->указатели == 0 && знач_у
                    && (знач_у->тип == УЗЕЛ_СТРОКА
                        || знач_у->тип == УЗЕЛ_F_СТРОКА)) {
                    знач_у->срез = 1;                 // кодогену: эмитить срез
                    // Провенанс: литерал → .rodata (из_литерала, запись «с[i]=…»
                    // ловится). f-строка → стек-буфер (изменяемая память, из
                    // литерала НЕ ставим). Возврат наружу небезопасен в обоих
                    // случаях: rodata переживёт, но семантика возврата = передача
                    // владения → крах при autofree.
                    цс->из_литерала = (знач_у->тип == УЗЕЛ_СТРОКА);
                    цс->безопасен_для_возврата = (знач_у->тип == УЗЕЛ_СТРОКА);
                    цс->с_нулем = 1;  // литерал и f-строка оба NUL-терминированы
                    цс->длина_известна = 0;
                    // узел->срез оставляем 0: НЕТ спецпути «free старого» —
                    // borrow не освобождается, обычная запись дескриптора.
                    return (ИнфоТипа){ ТОКЕН_ТИП_СИМВОЛ, 0, 0, 1, -1 };
                }
                if (!цс || !цс->владеет_срезом) {
                    ошибка_семантики(а, &цель_у->токен,
                        "переприсваивать можно только владеющий срез "
                        "(заимствованный параметр нельзя)");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                // Переприсваивание кастомно-аллоцированного среза (v1 не поддержан):
                // требует освободить старое И выделить новое через тот же аллокатор.
                if (цс->аллокатор.длина > 0) {
                    ошибка_семантики(а, &цель_у->токен,
                        "переприсваивание среза с кастомным аллокатором пока не "
                        "поддержано (v1): объявите новый «срез<T> в Имя»");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                узел->срез = 1;  // метка для кодогена: освободить старое + присвоить
                узел->тип_данных = цс->тип;       // тип элемента — для sizeof
                узел->беззнаковый = цс->беззнаковый;
                // После переприсваивания длина консервативно неизвестна:
                // присваивание могло быть условным, поэтому статическую длину
                // не сохраняем (доступы пойдут через рантайм-проверку).
                цс->длина_известна = 0;

                if (это_выделить(знач_у) || это_клон(знач_у)) {
                    if (узел_число_детей(знач_у) != 1) {
                        ошибка_семантики(а, &знач_у->токен,
                            "встроенная функция принимает один аргумент");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    Узел *арг = узел_ребёнок(знач_у, 0);
                    ИнфоТипа та = типизировать_выражение(а, арг);
                    if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                    if (это_выделить(знач_у)) {
                        if (та.тип != ТОКЕН_НЕИЗВЕСТНЫЙ && !тип_целочисленный(та)) {
                            ошибка_семантики(а, &знач_у->токен,
                                "количество элементов в «выделить» должно быть целым");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                        // Знаковость количества → кодогену (выбор срез_выделить_бз).
                        арг->беззнаковый = та.беззнаковый;
                    } else if (!та.срез) {
                        ошибка_семантики(а, &знач_у->токен,
                            "«клон» применим только к срезу");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                } else {
                    ИнфоТипа тз = типизировать_выражение(а, знач_у);
                    if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                    if (!тз.срез) {
                        ошибка_семантики(а, &знач_у->токен,
                            "срезу можно присвоить только срез");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    if (тз.тип != цс->тип || тз.беззнаковый != цс->беззнаковый) {
                        ошибка_семантики(а, &знач_у->токен,
                            "тип элемента не совпадает с типом цели");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    if (знач_у->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                        Символ *ис = найти_символ(а, знач_у->токен.начало,
                                                  знач_у->токен.длина);
                        if (!ис || !ис->владеет_срезом) {
                            ошибка_семантики(а, &знач_у->токен,
                                "нельзя переместить заимствованный срез");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                        // В теле цикла move из объемлющей области запрещён:
                        // на втором витке источник уже перемещён → use-after-
                        // move; однопроходный анализ это не гарантирует без
                        // фикс-точки. Вне цикла move из внешней области
                        // разрешён — слияние в если/иначе следит за
                        // согласованностью между ветвями.
                        if (ис->глубина < а->глубина && а->глубина_цикла > 0) {
                            ошибка_семантики(а, &знач_у->токен,
                                "перемещение среза из объемлющей области "
                                "внутри цикла запрещено (на втором витке "
                                "источник уже перемещён)");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                        ис->перемещён = 1;
                        ис->токен_move = знач_у->токен;
                    }
                }
                return тц;
            }

            ИнфоТипа тз = типизировать_выражение(а, знач_у);
            if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;

            // Коэрция строкового литерала ИЛИ f-строки в «срез<символ>» на
            // присваивании (§37): «с = "…"» / «с = f"…\(x)…"» при цели-срезе-
            // символов принимается — источник становится заимствованным срезом
            // (литерал → над .rodata; f-строка → над стек-буфером той же функции).
            // ЗАПРЕТ: цель — ВЛАДЕЮЩИЙ срез (из «выделить»): переприсваивание
            // (а) утекло бы буфер, (б) autofree в конце области попытался бы
            // free borrow-памяти (.rodata/стек) → крах. Понятная ошибка.
            if (знач_у && (знач_у->тип == УЗЕЛ_СТРОКА || знач_у->тип == УЗЕЛ_F_СТРОКА)
                && тц.срез && тц.тип == ТОКЕН_ТИП_СИМВОЛ && тц.указатели == 0
                && цель_у && цель_у->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                Символ *цс_с = найти_символ(а, цель_у->токен.начало,
                                             цель_у->токен.длина);
                if (цс_с && цс_с->владеет_срезом) {
                    ошибка_семантики(а, &цель_у->токен,
                        "нельзя присвоить строковый литерал/f-строку ВЛАДЕЮЩЕМУ "
                        "срезу «срез<символ>»: буфер бы утёк и autofree попытался "
                        "бы освободить borrow-память (.rodata/стек); используйте "
                        "заимствованный срез (объявленный как «срез<символ> с = …») "
                        "или освободите буфер явно до переприсваивания");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
            }
            if (коэрция_литерал_в_срез_символ(тц, знач_у)) {
                тз = (ИнфоТипа){ ТОКЕН_ТИП_СИМВОЛ, 0, 0, 1, -1 };
                // Переприсваивание литералом: обновляем провенанс цели, чтобы
                // из_литерала было верным (запись «с[i]=…» правильно ловилась).
                if (цель_у && цель_у->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                    Символ *цс_л = найти_символ(а, цель_у->токен.начало,
                                                 цель_у->токен.длина);
                    if (цс_л) {
                        цс_л->из_литерала = 1;
                        цс_л->безопасен_для_возврата = 1;
                    }
                }
            }

            if (!совместимы_для_присваивания(тц, тз)) {
                char тл[64], тп[64];
                описание_типа(тц, тл, sizeof(тл));
                описание_типа(тз, тп, sizeof(тп));
                char msg[256];
                snprintf(msg, sizeof(msg),
                         "несовместимые типы при присваивании: «%s» ← «%s»", тл, тп);
                ошибка_семантики(а,
                    цель_у ? &цель_у->токен : &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }

            if (сужение_запрещено(а, тц, знач_у, тз)) {
                char тл[64], тп[64];
                описание_типа(тц, тл, sizeof(тл));
                описание_типа(тз, тп, sizeof(тп));
                char msg[400];
                snprintf(msg, sizeof(msg),
                    "неявное сужение «%s» ← «%s» теряет данные; используйте "
                    "явное приведение «как<%s>(…)»", тл, тп, тл);
                ошибка_семантики(а, цель_у ? &цель_у->токен : &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }

            // Сырой указатель-цель: переприсвоение «нуль» снова делает его
            // доказанно нулевым; провенанс строкового литерала обновляем так же.
            if (цель_у && цель_у->тип == УЗЕЛ_ИДЕНТИФИКАТОР
                && тц.указатели > 0 && !тц.срез) {
                Символ *цс = найти_символ(а, цель_у->токен.начало,
                                          цель_у->токен.длина);
                // Non-null по умолчанию: обычному указателю «нуль» присвоить
                // нельзя. Присвоение nullable-источника («возможно») тоже
                // отвергается — сузьте под охранником или объявьте «возможно<T*>».
                // Nullable-значение (нуль-литерал, несужённая «возможно»-переменная
                // ИЛИ вызов функции с возвратом «возможно<T*>») нельзя присвоить
                // ненулевому указателю. Раньше вызов не учитывался → null-дереф.
                if (цс && !цс->возможно && знач_у
                    && выражение_может_быть_нуль(а, знач_у)) {
                    ошибка_семантики(а, &цель_у->токен,
                        знач_у->тип == УЗЕЛ_НУЛЬ
                        ? "указатель ненулевой по умолчанию: «нуль» ему присвоить "
                          "нельзя (объявите «возможно<T*>» для nullable)"
                        : "nullable-значение нельзя присвоить ненулевому указателю: "
                          "сузьте под охранником «если (x != нуль)» или объявите "
                          "«возможно<T*>»");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                if (цс) {
                    // Для «возможно»-цели: нулевой, если источник может быть нулём
                    // (нуль-литерал / несужённая переменная / вызов с «возможно»-
                    // возвратом). Обычный указатель всегда ненулевой (nullable
                    // источник отвергнут выше).
                    int ист_нуль = выражение_может_быть_нуль(а, знач_у);
                    цс->может_быть_нуль = цс->возможно && ист_нуль;
                    цс->из_литерала = знач_у && (знач_у->тип == УЗЕЛ_СТРОКА
                        || (знач_у->тип == УЗЕЛ_ИДЕНТИФИКАТОР
                            && указатель_из_литерала(а, знач_у)));
                    // Borrow-провенанс переприсваивается ВСЕГДА (закрываем дыру:
                    // «п = параметр» затем «п = strchr(…)» должно снять безопасность).
                    цс->безопасен_для_возврата = знач_у &&
                        ((знач_у->тип == УЗЕЛ_НУЛЬ)
                         || (знач_у->тип == УЗЕЛ_СТРОКА)
                         || (знач_у->тип == УЗЕЛ_ИДЕНТИФИКАТОР
                             && указатель_безопасен_для_возврата(а, знач_у)));
                }
            }
            return тц;
        }

        case УЗЕЛ_ВЫЗОВ: {
            // Вызов ВЫРАЖЕНИЯ-указателя на функцию: «т[i].функ(x)», «с.поле()».
            // ребёнок[0] — callee (должен типизироваться в ФУНКУКАЗАТЕЛЬ),
            // остальные — аргументы. Результат — тип возврата псевдонима.
            if (узел->вызов_выражения) {
                Узел *callee = узел_ребёнок(узел, 0);
                ИнфоТипа тк = типизировать_выражение(а, callee);
                if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                if (тк.тип != ТОКЕН_ФУНКУКАЗАТЕЛЬ || тк.индекс_структуры < 0) {
                    ошибка_семантики(а, &узел->токен,
                        "вызывать можно функцию или указатель на функцию");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                ОписаниеТипфункции *т = &а->типыфункций[тк.индекс_структуры];
                size_t наргов = узел_число_детей(узел) - 1;  // без callee
                if (наргов != т->число_параметров) {
                    char msg[256];
                    snprintf(msg, sizeof msg,
                        "указатель на функцию ожидает %zu аргумент(ов), передано %zu",
                        т->число_параметров, наргов);
                    ошибка_семантики(а, &узел->токен, msg);
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                for (size_t i = 0; i < наргов; ++i) {
                    ИнфоТипа та = типизировать_выражение(а, узел_ребёнок(узел, i + 1));
                    if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                    ИнфоТипа тп = { т->параметры[i].тип, т->параметры[i].указатели,
                                    т->параметры[i].беззнаковый, т->параметры[i].срез, -1 };
                    if (та.тип != ТОКЕН_НЕИЗВЕСТНЫЙ
                        && !совместимы_для_присваивания(тп, та)) {
                        ошибка_семантики(а, &узел_ребёнок(узел, i + 1)->токен,
                            "тип аргумента не совпадает с параметром указателя на функцию");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                }
                return (ИнфоТипа){ т->тип_возврата, т->указатели_возврата,
                                   т->беззнаковый_возврата, 0,
                                   т->индекс_структуры_возврата };
            }
            // Вызов через указатель на функцию: имя вызова — переменная-указатель
            // на функцию. Проверяем не-нулевой (иначе крах), число и типы
            // аргументов по сигнатуре; тип результата — тип возврата псевдонима.
            {
                Символ *фпс = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (фпс && фпс->тип == ТОКЕН_ФУНКУКАЗАТЕЛЬ) {
                    if (фпс->может_быть_нуль) {
                        ошибка_семантики(а, &узел->токен,
                            "вызов указателя на функцию, который может быть «нуль» "
                            "(присвойте функцию перед вызовом)");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    // Сигнатура псевдонима ещё не разрешена (индекс -1 — напр. в
                    // проходе вывода тип-аргументов): НЕ образуем &типыфункций[-1]
                    // (UB, ловится UBSan). Тип результата неизвестен; полную
                    // проверку проводит настоящий проход семантики. Индексировать
                    // только при индекс >= 0 — как в присваивании фп (idx >= 0).
                    if (фпс->индекс_структуры < 0)
                        return ТИП_НЕИЗВЕСТЕН_V;
                    ОписаниеТипфункции *т = &а->типыфункций[фпс->индекс_структуры];
                    if (узел_число_детей(узел) != т->число_параметров) {
                        char msg[256];
                        snprintf(msg, sizeof msg,
                            "указатель на функцию ожидает %zu аргумент(ов), передано %zu",
                            т->число_параметров, узел_число_детей(узел));
                        ошибка_семантики(а, &узел->токен, msg);
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    for (size_t i = 0; i < узел_число_детей(узел); ++i) {
                        ИнфоТипа та = типизировать_выражение(а, узел_ребёнок(узел, i));
                        if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                        ИнфоТипа тп = { т->параметры[i].тип, т->параметры[i].указатели,
                                        т->параметры[i].беззнаковый, т->параметры[i].срез, -1 };
                        if (та.тип != ТОКЕН_НЕИЗВЕСТНЫЙ
                            && !совместимы_для_присваивания(тп, та)) {
                            ошибка_семантики(а, &узел->токен,
                                "несовместимый тип аргумента при вызове указателя на функцию");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                    }
                    return (ИнфоТипа){ т->тип_возврата, т->указатели_возврата,
                                       т->беззнаковый_возврата, 0,
                                       т->индекс_структуры_возврата };
                }
            }
            // Встроенные атом-операции загрузить/сохранить/обменять (§49) —
            // диспатч ТОЛЬКО если 1-й аргумент реально атомик (иначе эти имена
            // остаются свободны для пользовательских функций).
            if ((токен_текст_равен(&узел->токен, "загрузить")
                 || токен_текст_равен(&узел->токен, "сохранить")
                 || токен_текст_равен(&узел->токен, "обменять"))
                && узел_число_детей(узел) >= 1) {
                Узел *а0 = узел_ребёнок(узел, 0);
                Символ *с0 = (а0 && а0->тип == УЗЕЛ_ИДЕНТИФИКАТОР)
                    ? найти_символ(а, а0->токен.начало, а0->токен.длина) : nullptr;
                if (с0 && с0->атом)
                    return типизировать_атом_операцию(а, узел, с0);
            }
            // Встроенная «утверждать_равные(a, b, …)» → ничего (statement-effect).
            // Проверяет РАВНОДЛИННОСТЬ срезов в рантайме ОДИН раз (вне цикла) и
            // регистрирует их как группу равной длины: далее в каноническом
            // цикле «и < длина(a)» доступ «b[и]»/«c[и]» доказанно-безопасен →
            // прямой доступ без проверки (векторизуется). Инвариант №1 цел.
            if (токен_текст_равен(&узел->токен, "утверждать_равные")) {
                size_t н = узел_число_детей(узел);
                if (н < 2) {
                    ошибка_семантики(а, &узел->токен,
                        "«утверждать_равные» принимает 2+ срезов равной длины");
                    return ТИП_НИЧЕГО_V;
                }
                if (н > МАКС_ЧЛЕНОВ_ГРУППЫ) н = МАКС_ЧЛЕНОВ_ГРУППЫ;
                int все_ок = 1;
                for (size_t i = 0; i < узел_число_детей(узел); ++i) {
                    Узел *ар = узел_ребёнок(узел, i);
                    if (!ар || ар->тип != УЗЕЛ_ИДЕНТИФИКАТОР) {
                        ошибка_семантики(а, &узел->токен,
                            "аргументы «утверждать_равные» — имена срезов");
                        все_ок = 0; break;
                    }
                    ИнфоТипа т = типизировать_выражение(а, ар);
                    if (а->диаг->ошибка) return ТИП_НИЧЕГО_V;
                    if (!т.срез) {
                        ошибка_семантики(а, &ар->токен,
                            "«утверждать_равные» применима только к срезам");
                        все_ок = 0; break;
                    }
                }
                // Регистрируем группу только в РЕАЛЬНОМ проходе анализа тела
                // (не в проходе вывода тип-аргументов — там нет исполнения).
                if (все_ок && !а->режим_вывода
                    && а->число_групп_длины < МАКС_ГРУПП_ДЛИНЫ) {
                    ГруппаРавнойДлины *гр = &а->группы_длины[а->число_групп_длины++];
                    гр->число_членов = 0;
                    гр->глубина = а->глубина;
                    гр->активна = 1;
                    for (size_t i = 0; i < узел_число_детей(узел)
                                       && гр->число_членов < МАКС_ЧЛЕНОВ_ГРУППЫ; ++i) {
                        Узел *ар = узел_ребёнок(узел, i);
                        гр->члены[гр->число_членов++] =
                            (ИмяСсылка){ ар->токен.начало, ар->токен.длина };
                    }
                }
                return ТИП_НИЧЕГО_V;
            }
            // Встроенная «утверждать_в_границах(индексы, длина(база))» → ничего.
            // Проверяет в рантайме ОДИН раз, что все элементы среза «индексы»
            // ∈ [0, длина(база)); регистрирует факт, после которого косвенный
            // доступ «база[индексы[i]]» доказанно-безопасен (прямой, без проверки
            // в горячем цикле — индекс-буфер 3D). Инвариант №1 цел.
            if (токен_текст_равен(&узел->токен, "утверждать_в_границах")) {
                if (узел_число_детей(узел) != 2) {
                    ошибка_семантики(а, &узел->токен,
                        "«утверждать_в_границах» принимает (индексы, длина(база))");
                    return ТИП_НИЧЕГО_V;
                }
                Узел *инд = узел_ребёнок(узел, 0);
                Узел *грань = узел_ребёнок(узел, 1);
                // 1-й аргумент — имя среза-индексов (целочисленного элемента).
                if (!инд || инд->тип != УЗЕЛ_ИДЕНТИФИКАТОР) {
                    ошибка_семантики(а, &узел->токен,
                        "1-й аргумент «утверждать_в_границах» — имя среза-индексов");
                    return ТИП_НИЧЕГО_V;
                }
                ИнфоТипа ти = типизировать_выражение(а, инд);
                if (а->диаг->ошибка) return ТИП_НИЧЕГО_V;
                // Элемент среза — целочисленный (тип элемента, не самого среза).
                ИнфоТипа элем_и = (ИнфоТипа){ ти.тип, 0, ти.беззнаковый, 0, -1 };
                if (!ти.срез || ти.указатели != 0 || !тип_целочисленный(элем_и)) {
                    ошибка_семантики(а, &инд->токен,
                        "срез-индексов должен быть «срез<целое…>» (целочисленный)");
                    return ТИП_НИЧЕГО_V;
                }
                // 2-й аргумент — строго «длина(база)», база — имя среза.
                if (!грань || грань->тип != УЗЕЛ_ВЫЗОВ
                    || !токен_текст_равен(&грань->токен, "длина")
                    || узел_число_детей(грань) != 1
                    || узел_ребёнок(грань, 0)->тип != УЗЕЛ_ИДЕНТИФИКАТОР) {
                    ошибка_семантики(а, &узел->токен,
                        "2-й аргумент «утверждать_в_границах» — «длина(база)» (имя среза)");
                    return ТИП_НИЧЕГО_V;
                }
                Узел *база_у = узел_ребёнок(грань, 0);
                ИнфоТипа тб = типизировать_выражение(а, база_у);
                if (а->диаг->ошибка) return ТИП_НИЧЕГО_V;
                if (!тб.срез) {
                    ошибка_семантики(а, &база_у->токен,
                        "база в «утверждать_в_границах» должна быть срезом");
                    return ТИП_НИЧЕГО_V;
                }
                // Запоминаем размер элемента индекса на узле — для кодогена
                // (чтение ((T*)индексы.данные)[k] в валидирующем цикле).
                узел->тип_данных = ти.тип;
                узел->беззнаковый = ти.беззнаковый;
                if (!а->режим_вывода
                    && а->число_границ_индексов < МАКС_ГРАНИЦ_ИНДЕКСОВ) {
                    ГраницаИндексов *г =
                        &а->границы_индексов[а->число_границ_индексов++];
                    г->индекс_срез = (ИмяСсылка){ инд->токен.начало, инд->токен.длина };
                    г->база_срез = (ИмяСсылка){ база_у->токен.начало, база_у->токен.длина };
                    г->глубина = а->глубина;
                    г->активна = 1;
                }
                return ТИП_НИЧЕГО_V;
            }
            // Встроенная «длина(срез)» → целое32 (поле .длина).
            if (токен_текст_равен(&узел->токен, "длина")) {
                if (узел_число_детей(узел) != 1) {
                    ошибка_семантики(а, &узел->токен,
                        "«длина» принимает ровно один аргумент-срез");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                ИнфоТипа арг = типизировать_выражение(а, узел_ребёнок(узел, 0));
                if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                if (!арг.срез && арг.тип != ТОКЕН_НЕИЗВЕСТНЫЙ) {
                    ошибка_семантики(а, &узел->токен,
                        "«длина» применима только к срезу");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                return ТИП_ЦЕЛОЕ32_V;
            }
            // Встроенные «добавить(буфер, значение)» / «перевыделить(буфер, N)» —
            // рост владеющего «буфер<T>». 1-й аргумент ОБЯЗАН быть переменной-
            // буфером (мутируется по ссылке; кодоген сам ставит «&»). Возвращают
            // «ничего» (операторы-выражения). Приведение буфера к срезу как
            // аргумента здесь НЕ включаем — это сам буфер.
            {
                int это_добавить = токен_текст_равен(&узел->токен, "добавить");
                int это_перевыд  = токен_текст_равен(&узел->токен, "перевыделить");
                if (это_добавить || это_перевыд) {
                    const char *имяб = это_добавить ? "добавить" : "перевыделить";
                    if (узел_число_детей(узел) != 2) {
                        char msg[160];
                        snprintf(msg, sizeof msg,
                            "«%s» принимает два аргумента: буфер и %s", имяб,
                            это_добавить ? "добавляемое значение" : "новый размер");
                        ошибка_семантики(а, &узел->токен, msg);
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    // Источник буфера: переменная-буфер ИЛИ поле-буфер «s.поле».
                    Узел *арг0 = узел_ребёнок(узел, 0);
                    ТипТокена эл_тип = ТОКЕН_НЕИЗВЕСТНЫЙ;
                    int эл_указ = 0, эл_беззн = 0, эл_идх = -1;
                    int это_буфер = 0, неизм = 0, перемещён = 0;
                    if (арг0 && арг0->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                        Символ *сб = найти_символ(а, арг0->токен.начало,
                                                  арг0->токен.длина);
                        if (сб && сб->буфер) {
                            это_буфер = 1;
                            эл_тип = сб->тип; эл_указ = сб->указатели;
                            эл_беззн = сб->беззнаковый; эл_идх = сб->индекс_структуры;
                            неизм = сб->неизменяемый; перемещён = сб->перемещён;
                        }
                    } else if (арг0 && арг0->тип == УЗЕЛ_ПОЛЕ) {
                        const ПолеСтруктуры *пб = поле_буфер_из_узла(а, арг0);
                        if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                        if (пб) {
                            это_буфер = 1;
                            эл_тип = пб->тип; эл_указ = пб->указатели;
                            эл_беззн = пб->беззнаковый; эл_идх = пб->индекс_структуры;
                        }
                    }
                    if (!это_буфер) {
                        char msg[200];
                        snprintf(msg, sizeof msg,
                            "1-й аргумент «%s» должен быть «буфер<T>» — переменной "
                            "или полем-буфером структуры («s.поле»)", имяб);
                        ошибка_семантики(а, &узел->токен, msg);
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    if (неизм) {
                        ошибка_семантики(а, &арг0->токен,
                            "«конст» буфер неизменяем — рост запрещён");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    if (перемещён) {
                        ошибка_семантики(а, &арг0->токен,
                            "буфер перемещён (владение ушло) — рост запрещён");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    // Помечаем узел: кодоген эмитит буфер_добавить/буфер_перевыделить
                    // с «&(буфер)» и sizeof(T). Тип элемента — с буфера/поля.
                    узел->буфер = 1;
                    узел->тип_данных = эл_тип;
                    узел->указатели = эл_указ;
                    узел->беззнаковый = эл_беззн;
                    ИнфоТипа арг1 = типизировать_выражение(а, узел_ребёнок(узел, 1));
                    if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                    if (это_добавить) {
                        // Значение обязано подходить типу элемента буфера (те же
                        // правила, что присваивание элементу — без сужения).
                        ИнфоТипа эл = { эл_тип, эл_указ, эл_беззн, 0, эл_идх };
                        if (арг1.тип != ТОКЕН_НЕИЗВЕСТНЫЙ
                            && !совместимы_для_присваивания(эл, арг1)) {
                            ошибка_семантики(а, &узел->токен,
                                "тип добавляемого значения не совпадает с элементом буфера");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                    } else {
                        if (арг1.тип != ТОКЕН_НЕИЗВЕСТНЫЙ && !тип_целочисленный(арг1)) {
                            ошибка_семантики(а, &узел->токен,
                                "новый размер в «перевыделить» должен быть целым");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                    }
                    return ТИП_НИЧЕГО_V;
                }
            }
            // Встроенная «вкси(строка)» → символ* (§37 п.4): NUL-хелпер для
            // передачи строки-среза в C-функции, ждущие NUL-терминированную
            // «символ*». Zero-cost для литералов/f-строк (с_нулем=1) — кодоген
            // отдаёт «.данные» напрямую; для прочих — копия в стек-буфер + NUL.
            // Аргумент — «срез<символ>» (срез, тип=символ, указатели=0).
            if (токен_текст_равен(&узел->токен, "вкси")) {
                if (узел_число_детей(узел) != 1) {
                    ошибка_семантики(а, &узел->токен,
                        "«вкси» принимает ровно один аргумент — «срез<символ>» (строка)");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                Узел *арг_у = узел_ребёнок(узел, 0);
                // Литерал/f-строка на месте — коэрция в срез<символ> (§37):
                // метим до типизации, чтобы тип получился «срез<символ>».
                if (арг_у->тип == УЗЕЛ_СТРОКА || арг_у->тип == УЗЕЛ_F_СТРОКА) {
                    арг_у->срез = 1;
                }
                ИнфоТипа арг = типизировать_выражение(а, арг_у);
                if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                if (арг.тип != ТОКЕН_НЕИЗВЕСТНЫЙ
                    && !(арг.срез && арг.тип == ТОКЕН_ТИП_СИМВОЛ && арг.указатели == 0)) {
                    ошибка_семантики(а, &узел->токен,
                        "«вкси» применима только к «срез<символ>» (строке)");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                // Аннотация для кодогена: аргумент гарантированно NUL-терминирован
                // (литерал/f-строка на месте — их .данные уже с NUL; переменная,
                // помеченная «с_нулем=1» — производная от литерала/f-строки).
                // Тогда кодоген «вкси» отдаёт .данные напрямую (zero cost);
                // иначе — рантайм-копия в стек-буфер + NUL.
                узел->с_нулем = 0;
                if (арг_у->тип == УЗЕЛ_СТРОКА || арг_у->тип == УЗЕЛ_F_СТРОКА) {
                    узел->с_нулем = 1;
                } else if (арг_у->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                    Символ *с = найти_символ(а, арг_у->токен.начало,
                                              арг_у->токен.длина);
                    if (с && с->с_нулем) узел->с_нулем = 1;
                }
                // Результат — «символ*» (borrow: живёт в источнике или в
                // стек-буфере текущей функции; в обоих случаях достаточно долго
                // для передачи в C-функцию в том же выражении).
                return (ИнфоТипа){ ТОКЕН_ТИП_СИМВОЛ, 1, 0, 0, -1 };
            }
            // Встроенная «присоединить(п)»: ждёт поток и забирает результат.
            // Дескриптор ПОТРЕБЛЯЕТСЯ (move) — двойной join ловится как
            // use-after-move существующим анализом владения.
            if (токен_текст_равен(&узел->токен, "присоединить")) {
                if (узел_число_детей(узел) != 1) {
                    ошибка_семантики(а, &узел->токен,
                        "«присоединить» принимает ровно один аргумент — поток");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                Узел *арг = узел_ребёнок(узел, 0);
                if (арг->тип != УЗЕЛ_ИДЕНТИФИКАТОР) {
                    ошибка_семантики(а, &узел->токен,
                        "«присоединить» принимает переменную-поток");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                Символ *с = найти_символ(а, арг->токен.начало, арг->токен.длина);
                if (!с) {
                    ошибка_семантики(а, &арг->токен, "неизвестная переменная");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                if (!с->поток) {
                    ошибка_семантики(а, &узел->токен,
                        "«присоединить» применимо только к «поток<T>»");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                if (с->перемещён) {
                    ошибка_семантики(а, &арг->токен,
                        "поток уже присоединён: дескриптор потреблён "
                        "(повторное «присоединить» — использование после перемещения)");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                с->перемещён = 1;          // join потребляет дескриптор
                с->токен_move = узел->токен;
                // Аннотируем узел типом результата: своей таблицы символов у
                // кодогена нет, а ему нужно знать T, чтобы прочесть «*(T*)кадр».
                // §2: срез-результат — узел->срез=1, кодоген прочтёт sizeof(Срез).
                узел->тип_данных = с->тип;
                узел->беззнаковый = с->беззнаковый;
                узел->срез = с->срез;
                ИнфоТипа р = { с->тип, с->указатели, с->беззнаковый, с->срез,
                               с->индекс_структуры };
                return р;                  // тип результата потока (поток=0)
            }
            // «запустить(ф, арг)» допустимо только как инициализатор объявления
            // «поток<T>» (там известен тип результата) — см. УЗЕЛ_ОБЪЯВЛЕНИЕ.
            if (это_запустить(узел)) {
                ошибка_семантики(а, &узел->токен,
                    "«запустить» допустимо только при объявлении потока: "
                    "поток<T> имя = запустить(функция, аргумент)");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            // Встроенная «выделить(N)» допустима только как инициализатор
            // объявления среза (там известен тип элемента) — см. УЗЕЛ_ОБЪЯВЛЕНИЕ.
            if (токен_текст_равен(&узел->токен, "выделить")) {
                ошибка_семантики(а, &узел->токен,
                    "«выделить» допустимо только при объявлении среза: "
                    "срез<T> имя = выделить(N)");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            if (токен_текст_равен(&узел->токен, "клон")) {
                ошибка_семантики(а, &узел->токен,
                    "«клон» допустим только при объявлении среза: "
                    "срез<T> имя = клон(другой)");
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            // Конструирование варианта sum-типа: «Вариант(арг…)». Имя вызова —
            // вариант с полезной нагрузкой; сверяем число/типы аргументов с полями
            // варианта, результат — само перечисление.
            {
                const ОписаниеПеречисления *сп = nullptr;
                const ВариантПеречисления *св = nullptr;
                int сэ = найти_вариант_подробно(а, узел->токен.начало,
                                                 узел->токен.длина, &сп, &св, nullptr);
                if (сэ >= 0 && св->число_полей > 0) {
                    if (узел_число_детей(узел) != св->число_полей) {
                        char msg[256];
                        snprintf(msg, sizeof msg,
                            "вариант «%s» ожидает %zu значений(я), передано %zu",
                            св->имя, св->число_полей, узел_число_детей(узел));
                        ошибка_семантики(а, &узел->токен, msg);
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    for (size_t k = 0; k < св->число_полей; ++k) {
                        ИнфоТипа та = типизировать_выражение(а, узел_ребёнок(узел, k));
                        if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                        ИнфоТипа тп = { св->поля[k].тип, св->поля[k].указатели,
                                        св->поля[k].беззнаковый, 0,
                                        св->поля[k].индекс_структуры };
                        if (та.тип != ТОКЕН_НЕИЗВЕСТНЫЙ
                            && !совместимы_для_присваивания(тп, та)) {
                            char msg[256];
                            snprintf(msg, sizeof msg,
                                "тип аргумента %zu не совпадает с полем «%s» варианта «%s»",
                                k + 1, св->поля[k].имя, св->имя);
                            ошибка_семантики(а, &узел->токен, msg);
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                    }
                    return (ИнфоТипа){ ТОКЕН_ПЕРЕЧИСЛЕНИЕ, 0, 0, 0, сэ };
                }
            }
            // Сигнатура (если функция известна) — нужна для «владеет»-параметров.
            СигнатураФункции *сиг = nullptr;
            for (size_t i = 0; i < а->число_функций; ++i) {
                if (байты_равны(а->функции[i].имя, strlen(а->функции[i].имя),
                                узел->токен.начало, узел->токен.длина)) {
                    сиг = &а->функции[i];
                    break;
                }
            }

            // Проход вывода тип-аргументов: вызов обобщённой функции без явных
            // «<>» — выводим T из конкретных аргументов и дописываем
            // УЗЕЛ_ТИПОАРГУМЕНТ на узел (мономорфизация подхватит как явные). Вне
            // режима вывода ветка не активна — там дерево уже мономорфизировано.
            if (а->режим_вывода && сиг && сиг->обобщённая
                && число_ведущих_типоаргументов(узел) == 0) {
                return вывести_обобщённый_вызов(а, узел, сиг);
            }

            // Функция не объявлена ни в Konda, ни в подключённых заголовках —
            // предупреждение с позицией в .конда (вместо тихого делегирования
            // компилятору C, который сообщил бы об ошибке по сгенерированному
            // .c). Только когда заголовки сканировались (иначе не знаем, что
            // валидно из C, и молчим — escape-hatch для interop).
            const ВнешняяФункция *внеш = а->внешние
                ? найти_внешнюю(а->внешние, узел->токен.начало, узел->токен.длина)
                : nullptr;
            // Небезопасная функция libc (неограниченная запись в буфер): вызов в
            // безопасном коде запрещён. Разрешено только в «небезопасно { }».
            // Проверяем лишь когда имя НЕ перекрыто локальной Konda-функцией
            // (иначе это своя проверенная функция с тем же именем).
            if (!сиг && а->глубина_небезопасно == 0
                && libc_небезопасна(узел->токен.начало, узел->токен.длина)) {
                char msg[384];
                snprintf(msg, sizeof(msg),
                    "функция «%.*s» из C небезопасна (возможно переполнение "
                    "буфера): используйте безопасный аналог (напр. срез<T>) или "
                    "оберните вызов в «небезопасно { … }»",
                    (int)узел->токен.длина, узел->токен.начало);
                ошибка_семантики(а, &узел->токен, msg);
                return ТИП_НЕИЗВЕСТЕН_V;
            }
            if (а->внешние && !сиг && !внеш) {
                char msg[256];
                snprintf(msg, sizeof(msg),
                    "функция «%.*s» не объявлена: не найдена ни среди функций "
                    "Konda, ни в подключённых заголовках (проверьте имя и "
                    "«#содержит»)",
                    (int)узел->токен.длина, узел->токен.начало);
                предупреждение_семантики(а, &узел->токен, msg);
            }
            // Известная не-вариативная функция (Konda или C): сверяем число
            // аргументов. Вариативные и функции с неизвестной арностью («()»)
            // пропускаем. Для C-функций типы не сверяем (отображение C→Konda
            // лоссовое) — только количество.
            if (внеш && !сиг && !внеш->переменное_число
                && внеш->число_параметров >= 0
                && (int)узел_число_детей(узел) != внеш->число_параметров) {
                char msg[256];
                snprintf(msg, sizeof(msg),
                    "функция «%.*s» ожидает %d аргумент(ов), передано %zu",
                    (int)узел->токен.длина, узел->токен.начало,
                    внеш->число_параметров, узел_число_детей(узел));
                предупреждение_семантики(а, &узел->токен, msg);
            }

            // Аргументы типизируются (заодно проверки use-after-move и т.п.).
            // Аргумент, идущий в «владеет»-параметр, перемещается в функцию.
            for (size_t i = 0; i < узел_число_детей(узел); ++i) {
                Узел *арг = узел_ребёнок(узел, i);
                // Аргумент в параметр по ссылке («изменяемый»/«вывод»): должен
                // быть переменной (lvalue) совпадающего типа. «изменяемый» — уже
                // инициализированной (читается); «вывод» — не обязательно (тело
                // присвоит), и после вызова переменная считается инициализированной.
                if (сиг && i < сиг->число_параметров
                    && сиг->параметры[i].по_ссылке > 0) {
                    int режим = сиг->параметры[i].по_ссылке;
                    // Функция изменит переменную по ссылке — присваивания в коде
                    // не видно, но связь «длина(с) == н» этим тоже рвётся.
                    // «чтение» (режим 3) НЕ мутирует — связь цела.
                    if (арг->тип == УЗЕЛ_ИДЕНТИФИКАТОР && режим != 3)
                        сбросить_связь_длины(а, &арг->токен);
                    if (арг->тип != УЗЕЛ_ИДЕНТИФИКАТОР) {
                        // ── Ссылка на ПРОЕКЦИЮ: поле структуры / элемент
                        // среза/массива («ф(изменяемый т.х)», «ф(вывод с[и])»).
                        // Безопасно без borrow-checker (second-class reference):
                        // база живёт в кадре вызывающего и заморожена на время
                        // вызова; границы среза проверяются при ФОРМИРОВАНИИ
                        // ссылки (тот же срез_доступ); утечь ссылке некуда —
                        // нет сырого «&», глобалов и замыканий. Мутация
                        // элемента/поля не меняет НИ ОДНОЙ переменной-дескриптора
                        // (длина среза, связи «длина(с)==н», известные константы
                        // целы), поэтому анализы снятия проверок не обманываются
                        // (урок 17.07: они обязаны видеть все мутации ПЕРЕМЕННЫХ —
                        // здесь мутируется содержимое, не переменная).
                        if (арг->тип != УЗЕЛ_ПОЛЕ && арг->тип != УЗЕЛ_ИНДЕКС) {
                            ошибка_семантики(а, &узел->токен, режим == 2
                                ? "аргумент для «вывод» должен быть переменной, "
                                  "полем или элементом среза/массива (lvalue)"
                                : "аргумент для «изменяемый» должен быть переменной, "
                                  "полем или элементом среза/массива (lvalue)");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                        const Токен *корень = корень_lvalue(арг);
                        if (!корень) {
                            ошибка_семантики(а, &арг->токен,
                                "по ссылке можно передать только проекцию "
                                "ПЕРЕМЕННОЙ (поле/элемент); временное значение "
                                "умерло бы до конца вызова");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                        Символ *кс = найти_символ(а, корень->начало, корень->длина);
                        if (!кс) {
                            char msg[256];
                            snprintf(msg, sizeof msg, "неизвестная переменная «%.*s»",
                                     (int)корень->длина, корень->начало);
                            ошибка_семантики(а, корень, msg);
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                        // Иммутабельность базы: запись в поле/элемент «конст»
                        // запрещена — и через ссылку тоже. «чтение» (3) не пишет.
                        if (кс->неизменяемый && режим != 3) {
                            ошибка_семантики(а, корень, режим == 2
                                ? "поле/элемент «конст»-переменной нельзя передать "
                                  "в «вывод» (он был бы изменён)"
                                : "поле/элемент «конст»-переменной нельзя передать "
                                  "в «изменяемый» (он был бы изменён)");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                        // Срез-база не должна быть перемещена «владеет»-аргументом
                        // ЭТОГО ЖЕ вызова (иначе вызываемый освободит данные при
                        // живой ссылке — use-after-free). Порядок «владеет раньше
                        // ссылки» ловится обычным use-after-move при типизации
                        // ниже; здесь — обратный порядок (владеет ПОСЛЕ ссылки).
                        if (кс->срез) {
                            for (size_t j = 0; j < узел_число_детей(узел); ++j) {
                                if (j == i) continue;
                                Узел *дт = узел_ребёнок(узел, j);
                                if (дт && дт->тип == УЗЕЛ_ИДЕНТИФИКАТОР
                                    && j < сиг->число_параметров
                                    && сиг->владеет_параметра[j]
                                    && байты_равны(дт->токен.начало, дт->токен.длина,
                                                   корень->начало, корень->длина)) {
                                    ошибка_семантики(а, &арг->токен,
                                        "срез перемещается «владеет»-аргументом этого "
                                        "же вызова: ссылка на его элемент повисла бы "
                                        "(вызываемый освободит данные)");
                                    return ТИП_НЕИЗВЕСТЕН_V;
                                }
                            }
                        }
                        // Полная типизация проекции: границы (формирование ссылки
                        // = проверенный доступ), use-after-move, нуль-narrowing,
                        // гейт союза — всё как у обычного чтения этого lvalue.
                        ИнфоТипа тп = типизировать_выражение(а, арг);
                        if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                        if (тп.срез) {
                            ошибка_семантики(а, &арг->токен,
                                "поле-срез нельзя передать по ссылке (дескриптор "
                                "владеет памятью; передайте срез по значению — "
                                "это заимствование)");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                        ИнфоПараметра *пп = &сиг->параметры[i];
                        if (тп.тип != пп->тип || тп.указатели != пп->указатели
                            || тп.беззнаковый != пп->беззнаковый
                            || (тп.тип == ТОКЕН_СТРУКТУРА
                                && тп.индекс_структуры != пп->индекс_структуры)) {
                            ошибка_семантики(а, &арг->токен,
                                "тип аргумента не совпадает с типом параметра по ссылке");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                        continue;
                    }
                    Символ *ас = найти_символ(а, арг->токен.начало, арг->токен.длина);
                    if (!ас) {
                        char msg[256];
                        snprintf(msg, sizeof msg, "неизвестная переменная «%.*s»",
                                 (int)арг->токен.длина, арг->токен.начало);
                        ошибка_семантики(а, &арг->токен, msg);
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    ИнфоПараметра *п = &сиг->параметры[i];
                    // «изменяемый буфер<T>»: аргумент — буфер того же элемента.
                    // Передаётся по ссылке (Срез*), функция растит его. Обычный
                    // срез по ссылке по-прежнему запрещён (ас->срез && !ас->буфер).
                    int буфер_по_ссылке = ас->буфер && п->буфер;
                    if (ас->тип != п->тип || ас->указатели != п->указатели
                        || ас->беззнаковый != п->беззнаковый
                        || (ас->срез && !буфер_по_ссылке)
                        || (ас->тип == ТОКЕН_СТРУКТУРА
                            && ас->индекс_структуры != п->индекс_структуры)) {
                        ошибка_семантики(а, &арг->токен,
                            "тип аргумента не совпадает с типом параметра по ссылке");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    // Буфер, переданный «изменяемый», не «перемещается» — вызывающий
                    // остаётся владельцем (функция лишь растит по ссылке). Move-
                    // пометки тут не ставим (в отличие от передачи буфера ПО ЗНАЧЕНИЮ).
                    // «конст»-переменную нельзя передать в «изменяемый»/«вывод»:
                    // функция изменила бы её (нарушение иммутабельности).
                    // «чтение» (const-ссылка) иммутабельность сохраняет — можно.
                    if (ас->неизменяемый && режим != 3) {
                        ошибка_семантики(а, &арг->токен, режим == 2
                            ? "«конст»-переменную нельзя передать в «вывод» "
                              "(она была бы изменена)"
                            : "«конст»-переменную нельзя передать в «изменяемый» "
                              "(она была бы изменена)");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    if ((режим == 1 || режим == 3) && !ас->инициализирована) {
                        char msg[256];
                        snprintf(msg, sizeof msg,
                            "«изменяемый»-аргумент «%.*s» должен быть инициализирован "
                            "до вызова", (int)арг->токен.длина, арг->токен.начало);
                        ошибка_семантики(а, &арг->токен, msg);
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    ас->инициализирована = 1;  // out присвоит; ref мог изменить
                    continue;
                }
                // Аргумент в параметр-указатель на функцию: имя подходящей функции
                // (в общем случае имя функции — не значение, обычная типизация дала
                // бы «неизвестная переменная») или указатель того же типа.
                if (сиг && i < сиг->число_параметров
                    && сиг->параметры[i].тип == ТОКЕН_ФУНКУКАЗАТЕЛЬ
                    && арг->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                    int idx = сиг->параметры[i].индекс_структуры;
                    СигнатураФункции *сф = найти_сигнатуру_по_имени(а,
                        арг->токен.начало, арг->токен.длина);
                    Символ *ис = найти_символ(а, арг->токен.начало, арг->токен.длина);
                    if (idx >= 0 && сф && сигнатура_совпадает_с_типфункцией(сф,
                            &а->типыфункций[idx])) {
                        continue;  // валидная функция-аргумент
                    }
                    if (ис && ис->тип == ТОКЕН_ФУНКУКАЗАТЕЛЬ
                        && ис->индекс_структуры == idx) {
                        continue;  // указатель того же типа
                    }
                    ошибка_семантики(а, &арг->токен,
                        "аргумент не подходит к параметру-указателю на функцию: "
                        "нужна функция с совпадающей сигнатурой или указатель того же типа");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                ИнфоТипа тарг = типизировать_выражение(а, арг);
                if (а->диаг->ошибка) return ТИП_НЕИЗВЕСТЕН_V;
                // Структуру с деструктором по значению передавать нельзя
                // (копия → двойной вызов деструктора) — только по указателю.
                if (структура_с_деструктором(а, тарг)) {
                    ошибка_семантики(а, &арг->токен,
                        "структуру с деструктором нельзя передавать по значению "
                        "(передавайте по указателю «Имя*»)");
                    return ТИП_НЕИЗВЕСТЕН_V;
                }
                // Коэрция строкового литерала ИЛИ f-строки в «срез<символ>»-
                // параметр (§37): «ф("…")» / «ф(f"…\(x)…")» при параметре
                // срез<символ> → метим источник (арг->срез=1), кодоген эмитит
                // его как заимствованный срез (литерал — .rodata; f-строка —
                // стек-буфер). Без коэрции C-сборка ловила бы «char* → Срез».
                // ЗАПРЕТ: параметр «владеет» — функция освободила бы borrow.
                if (сиг && i < сиг->число_параметров
                    && сиг->параметры[i].срез
                    && сиг->параметры[i].тип == ТОКЕН_ТИП_СИМВОЛ
                    && сиг->параметры[i].указатели == 0
                    && (арг->тип == УЗЕЛ_СТРОКА || арг->тип == УЗЕЛ_F_СТРОКА)) {
                    if (сиг->владеет_параметра[i]) {
                        ошибка_семантики(а, &арг->токен,
                            "строковый литерал/f-строку нельзя передать в «владеет»-"
                            "параметр «срез<символ>»: функция освободила бы borrow-"
                            "память (.rodata/стек); передайте владеющую строку "
                            "(из «выделить» + запись + move)");
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                    арг->срез = 1;
                }

                // Авто-конверсия массива в срез: если параметр объявлен
                // «срез<T>», а аргумент — переменная-массив `T[N]`, на месте
                // вызова кодоген построит дескриптор {&арр[0], N, sizeof(T)}.
                // Бесплатно: массив остаётся на стеке, никаких аллокаций.
                if (сиг && i < сиг->число_параметров
                    && сиг->параметры[i].срез
                    && арг->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                    Символ *ис = найти_символ(а, арг->токен.начало, арг->токен.длина);
                    if (ис && ис->массив && ис->длина_известна) {
                        ИнфоПараметра *п = &сиг->параметры[i];
                        if (ис->тип != п->тип || ис->беззнаковый != п->беззнаковый
                            || ис->указатели != п->указатели) {
                            char msg[256];
                            snprintf(msg, sizeof(msg),
                                "тип элементов массива «%.*s» не совпадает с типом "
                                "среза-параметра %zu функции «%.*s»",
                                (int)арг->токен.длина, арг->токен.начало,
                                i + 1,
                                (int)узел->токен.длина, узел->токен.начало);
                            ошибка_семантики(а, &арг->токен, msg);
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                        // Аннотация для кодогена: «здесь нужна авто-конверсия
                        // массива в Срез». Сам массив остаётся доступен через имя.
                        арг->массив = 1;
                        арг->размер_массива = ис->длина;
                        арг->тип_данных = ис->тип;
                        арг->беззнаковый = ис->беззнаковый;
                        арг->указатели = ис->указатели;
                    }
                }
                // Передача массива в СЫРОЙ указательный параметр известной
                // функции теряет длину → в теле возможен выход за границы без
                // проверки. Требуем срез<T> (у него есть длина и рантайм-проверки).
                // Для внешних (C) функций сигнатуры нет → decay сохраняется.
                if (сиг && i < сиг->число_параметров
                    && !сиг->параметры[i].срез
                    && сиг->параметры[i].указатели > 0
                    && арг->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                    Символ *ис = найти_символ(а, арг->токен.начало, арг->токен.длина);
                    if (ис && ис->массив && ис->длина_известна) {
                        char msg[256];
                        snprintf(msg, sizeof(msg),
                            "передача массива «%.*s» в сырой указательный параметр "
                            "теряет длину (риск выхода за границы в теле); объявите "
                            "параметр как «срез<T>»",
                            (int)арг->токен.длина, арг->токен.начало);
                        ошибка_семантики(а, &арг->токен, msg);
                        return ТИП_НЕИЗВЕСТЕН_V;
                    }
                }
                if (сиг && i < сиг->число_параметров && сиг->владеет_параметра[i]
                    && арг->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                    Символ *ис = найти_символ(а, арг->токен.начало, арг->токен.длина);
                    if (ис && ис->срез) {
                        if (!ис->владеет_срезом) {
                            ошибка_семантики(а, &арг->токен,
                                "нельзя передать заимствованный срез в параметр "
                                "«владеет»: владелец находится снаружи");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                        // Функция-потребитель освободит срез дефолтным free (она не
                        // знает кастомный аллокатор) → запрещаем передачу (v1).
                        // Заимствование (обычный срез-параметр) по-прежнему можно.
                        if (ис->аллокатор.длина > 0) {
                            ошибка_семантики(а, &арг->токен,
                                "срез<T> в Имя нельзя передать в «владеет»-параметр "
                                "(v1): потребитель освободил бы его не тем аллокатором; "
                                "передайте как обычный (заимствованный) срез");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                        // Как и для move-через-присваивание: передача владельца
                        // из объемлющей области в «владеет»-параметр внутри цикла
                        // запрещена — на втором витке источник уже перемещён
                        // (use-after-move), а однопроходный анализ это без
                        // фикс-точки не гарантирует.
                        if (ис->глубина < а->глубина && а->глубина_цикла > 0) {
                            ошибка_семантики(а, &арг->токен,
                                "перемещение среза из объемлющей области "
                                "внутри цикла запрещено (на втором витке "
                                "источник уже перемещён)");
                            return ТИП_НЕИЗВЕСТЕН_V;
                        }
                        ис->перемещён = 1;  // владение ушло в функцию-потребитель
                        ис->токен_move = арг->токен;
                    }
                }
            }

            if (сиг) {
                // §37 п.6 — переносим свойство «возврат заимствован» с сигнатуры
                // на call-узел, чтобы кодоген на «срез с = ф()» решил про autofree
                // без обращения к таблицам (работает и для библиотечных функций
                // из «.и»). Нулевая рантайм-цена — только флаг компайл-тайма.
                узел->возврат_заимствован = сиг->срез && сиг->возврат_заимствован;
                return (ИнфоТипа){ сиг->тип_возврата, сиг->указатели_возврата,
                                   сиг->беззнаковый, сиг->срез,
                                   сиг->индекс_структуры_возврата };
            }
            return ТИП_НЕИЗВЕСТЕН_V;
        }

        default:
            return ТИП_НЕИЗВЕСТЕН_V;
    }
}

// Узел является вызовом встроенной «выделить»?
static int это_выделить(const Узел *узел)
{
    return узел && узел->тип == УЗЕЛ_ВЫЗОВ
        && токен_текст_равен(&узел->токен, "выделить");
}

// Узел является вызовом встроенной «запустить» (создание потока)?
static int это_запустить(const Узел *узел)
{
    return узел && узел->тип == УЗЕЛ_ВЫЗОВ
        && токен_текст_равен(&узел->токен, "запустить");
}

// ─── безопасность потоков: модель «передача владения» ────────────────────────
//
// Гонки данных невозможны ПО ПОСТРОЕНИЮ: поток получает данные только по
// значению (копия) или перемещением владения (у запускающего доступа больше
// нет — ловит существующий move-анализ). Разделяемое изменяемое состояние
// просто нельзя выразить, поэтому синхронизация не нужна, а проверки —
// статические (нулевая рантайм-цена, инвариант №1).
//
// Здесь проверяется сама СИГНАТУРА функции потока: она не должна принимать
// ничего, что является ссылкой в кадр запускающего или заимствованием.
static int проверить_сигнатуру_потока(Анализатор *а, const СигнатураФункции *сиг,
                                       const Токен *где)
{
    for (size_t i = 0; i < сиг->число_параметров; ++i) {
        const ИнфоПараметра *п = &сиг->параметры[i];
        char msg[512];
        // «изменяемый»/«вывод» — указатель в кадр вызывающего. Поток пережил бы
        // кадр → висячий указатель И гонка за ту же переменную.
        if (п->по_ссылке) {
            snprintf(msg, sizeof msg,
                "функция потока «%s» не может иметь параметр «%s» — это ссылка "
                "в кадр запускающего (висячий указатель и гонка); передавайте "
                "по значению или перемещением «владеет срез<T>»",
                сиг->имя, п->по_ссылке == 2 ? "вывод" : "изменяемый");
            ошибка_семантики(а, где, msg);
            return 0;
        }
        // Срез без «владеет» — заимствование: запускающий сохранил бы доступ к
        // той же памяти → гонка и возможный use-after-free.
        if (п->срез && !сиг->владеет_параметра[i]) {
            snprintf(msg, sizeof msg,
                "функция потока «%s» принимает срез без «владеет» — запускающий "
                "сохранит доступ к той же памяти (гонка); объявите параметр как "
                "«владеет срез<T>», чтобы владение перешло потоку",
                сиг->имя);
            ошибка_семантики(а, где, msg);
            return 0;
        }
        // Сырой указатель — заимствование чужой памяти с той же проблемой.
        if (п->указатели > 0) {
            snprintf(msg, sizeof msg,
                "функция потока «%s» принимает указатель — это заимствование, "
                "которое поток может пережить (висячий указатель и гонка); "
                "передавайте по значению или «владеет срез<T>»",
                сиг->имя);
            ошибка_семантики(а, где, msg);
            return 0;
        }
    }
    return 1;
}

// Узел является вызовом встроенной «клон»?
static int это_клон(const Узел *узел)
{
    return узел && узел->тип == УЗЕЛ_ВЫЗОВ
        && токен_текст_равен(&узел->токен, "клон");
}

// ─── анализ операторов ───────────────────────────────────────────────────────

static void анализ_блока(Анализатор *а, Узел *блок);
static void анализ_оператора(Анализатор *а, Узел *узел);

// «п» в условии сравнения с «нуль»? Возвращает символ указателя, если условие
// имеет вид «п <оп> нуль» или «нуль <оп> п» (п — идентификатор-указатель).
static Символ *указатель_в_сравнении_с_нулём(Анализатор *а, Узел *условие)
{
    if (!условие || условие->тип != УЗЕЛ_БИНОП) return nullptr;
    Узел *л = узел_ребёнок(условие, 0);
    Узел *п = узел_ребёнок(условие, 1);
    Узел *пер = nullptr;
    if (л && л->тип == УЗЕЛ_ИДЕНТИФИКАТОР && п && п->тип == УЗЕЛ_НУЛЬ) пер = л;
    else if (п && п->тип == УЗЕЛ_ИДЕНТИФИКАТОР && л && л->тип == УЗЕЛ_НУЛЬ) пер = п;
    if (!пер) return nullptr;
    return найти_символ(а, пер->токен.начало, пер->токен.длина);
}

// Типизированные слушатели: определены ниже (после таблиц), объявляем заранее.
static int найти_экземпляр_слушателя(const Анализатор *а, const Токен *имя);

// «слушать(add_fn, объект, экземпляр, данные)» — тип «данные» ДОЛЖЕН совпасть с
// userdata-типом T экземпляра: иначе каст void*→T в трампулине неверен. Это и
// есть тип-безопасность колбэков (связка на месте регистрации).
static void анализ_слушать(Анализатор *а, Узел *узел)
{
    if (узел_число_детей(узел) != 4) {
        ошибка_семантики(а, &узел->токен,
            "«слушать» принимает 4 аргумента: (add_функция, объект, экземпляр, данные)");
        return;
    }
    Узел *объект = узел_ребёнок(узел, 1);
    Узел *экз    = узел_ребёнок(узел, 2);
    Узел *данные = узел_ребёнок(узел, 3);
    int иэ = (экз->тип == УЗЕЛ_ИДЕНТИФИКАТОР)
        ? найти_экземпляр_слушателя(а, &экз->токен) : -1;
    if (иэ < 0) {
        ошибка_семантики(а, &экз->токен,
            "третий аргумент «слушать» — имя объявленного экземпляра слушателя");
        return;
    }
    ОписаниеСлушателя *ст =
        &а->слушатель_типы[а->слушатель_экземпляры[иэ].индекс_типа];
    типизировать_выражение(а, объект);          // ловим ошибки в выражении объекта
    if (а->диаг->ошибка) return;
    ИнфоТипа тд = типизировать_выражение(а, данные);
    if (а->диаг->ошибка) return;
    int ок = (тд.тип == ст->userdata_тип);
    if (ст->userdata_тип == ТОКЕН_СТРУКТУРА)
        ок = ок && (тд.индекс_структуры == ст->userdata_индекс);
    // «данные» — сам объект T (по значению, кодоген возьмёт «&данные») ЛИБО
    // указатель T* (кодоген передаст как есть). Идиома C всегда даёт T*.
    ок = ок && (тд.указатели == 0 || тд.указатели == 1);
    if (!ок) {
        ошибка_семантики(а, &данные->токен,
            "тип «данные» не совпадает с userdata-типом T слушателя "
            "(ожидается T или T*; тип-безопасность колбэков держится на этом)");
        return;
    }
    узел->указатели = тд.указатели;   // кодоген: >0 → передать без «&»
}

// ─── статическая проверка недостижимого кода (противоречивые условия) ────────
// Разбор атома-сравнения «имя == C» / «имя != C» (в любом порядке операндов).
// Одна сторона — голый идентификатор-ПЕРЕМЕННАЯ (символ, не сворачиваемый в
// константу), другая — компайл-тайм константа. Возвращает 1 и заполняет «ф».
static int атом_из_сравнения(Анализатор *а, Узел *ср, Факт *ф)
{
    if (!ср || ср->тип != УЗЕЛ_БИНОП) return 0;
    int равно;
    if (ср->токен.тип == ТОКЕН_РАВНО && ср->токен.длина == 2) равно = 1;          // ==
    else if (ср->токен.тип == ТОКЕН_ВОСКЛИЦАТЕЛЬНЫЙ_ЗНАК && ср->токен.длина == 2)
        равно = 0;                                                                // !=
    else return 0;
    Узел *л = узел_ребёнок(ср, 0);
    Узел *п = узел_ребёнок(ср, 1);
    Узел *ид = nullptr;
    long значение;
    // Одна сторона — голый идентификатор-ПЕРЕМЕННАЯ (символ в таблице), другая —
    // компайл-тайм константа (число/конст/вариант перечисления). Порядок любой.
    // Идентификатор может и сам быть известной константой (напр. «целое32 x = 2»
    // после распространения) — это лишь усиливает факт, не мешает.
    if (л && л->тип == УЗЕЛ_ИДЕНТИФИКАТОР && л->токен.длина < МАКС_ИМЯ
        && найти_символ(а, л->токен.начало, л->токен.длина)
        && вычислить_константу(а, п, &значение)) {
        ид = л;
    } else if (п && п->тип == УЗЕЛ_ИДЕНТИФИКАТОР && п->токен.длина < МАКС_ИМЯ
        && найти_символ(а, п->токен.начало, п->токен.длина)
        && вычислить_константу(а, л, &значение)) {
        ид = п;
    } else {
        return 0;
    }
    memcpy(ф->переменная, ид->токен.начало, ид->токен.длина);
    ф->переменная[ид->токен.длина] = '\0';
    ф->значение = значение;
    ф->равно = равно;
    ф->активен = 1;
    ф->позиция = ид->токен;
    return 1;
}

// Противоречат ли два факта об ОДНОЙ переменной?
//   ==a vs ==b (a≠b) → да;  ==a vs !=a → да;  !=a vs !=b → нет (совместимо).
static int факты_противоречат(const Факт *X, const Факт *Y)
{
    if (X->равно && Y->равно)   return X->значение != Y->значение;
    if (!X->равно && !Y->равно) return 0;
    long равен = X->равно ? X->значение : Y->значение;   // сторона «== равен»
    long неравен = X->равно ? Y->значение : X->значение; // сторона «!= неравен»
    return равен == неравен;
}

// Собрать гарантированно-истинные атомы условия then-ветви: конъюнкты AND-дерева.
// Через «||» не спускаемся (его операнды не гарантированы) — так проверка звучна:
// ложные срабатывания невозможны, лишь пропуск части случаев.
static void собрать_конъюнкт_атомы(Анализатор *а, Узел *усл,
                                   Факт *буф, int *n, int макс)
{
    if (!усл || *n >= макс) return;
    if (усл->тип == УЗЕЛ_БИНОП && токен_текст_равен(&усл->токен, "&&")) {
        собрать_конъюнкт_атомы(а, узел_ребёнок(усл, 0), буф, n, макс);
        собрать_конъюнкт_атомы(а, узел_ребёнок(усл, 1), буф, n, макс);
        return;
    }
    Факт ф;
    if (атом_из_сравнения(а, усл, &ф) && *n < макс) буф[(*n)++] = ф;
}

// Проверка недостижимого кода: если конъюнкт нового условия противоречит уже
// установленному факту (из объемлющего if) или другому конъюнкту того же условия
// — условие никогда не истинно → ошибка транспиляции с позицией. 0 рантайма.
static void проверить_противоречие_условия(Анализатор *а, Узел *условие)
{
    if (а->диаг->ошибка) return;
    Факт локальные[МАКС_КОНЪЮНКТОВ];
    int n = 0;
    собрать_конъюнкт_атомы(а, условие, локальные, &n, МАКС_КОНЪЮНКТОВ);
    for (int i = 0; i < n; ++i) {
        Факт *A = &локальные[i];
        const Факт *конфликт = nullptr;
        // против накопленных фактов объемлющих if (только активные)
        for (size_t k = 0; k < а->число_фактов && !конфликт; ++k) {
            const Факт *F = &а->факты[k];
            if (F->активен && strcmp(F->переменная, A->переменная) == 0
                && факты_противоречат(F, A))
                конфликт = F;
        }
        // против ранее увиденных конъюнктов ЭТОГО же условия («x == 2 и x == 0»)
        for (int j = 0; j < i && !конфликт; ++j)
            if (strcmp(локальные[j].переменная, A->переменная) == 0
                && факты_противоречат(&локальные[j], A))
                конфликт = &локальные[j];
        if (конфликт) {
            char msg[256];
            snprintf(msg, sizeof(msg),
                "условие никогда не истинно: «%s %s %ld» противоречит ранее "
                "установленному «%s %s %ld» — код недостижим",
                A->переменная, A->равно ? "==" : "!=", A->значение,
                конфликт->переменная, конфликт->равно ? "==" : "!=",
                конфликт->значение);
            ошибка_семантики(а, &A->позиция, msg);
            return;
        }
    }
}

// Протолкнуть факты then-ветви условия в стек (конъюнкты AND-дерева).
static void протолкнуть_факты_условия(Анализатор *а, Узел *условие)
{
    Факт локальные[МАКС_КОНЪЮНКТОВ];
    int n = 0;
    собрать_конъюнкт_атомы(а, условие, локальные, &n, МАКС_КОНЪЮНКТОВ);
    for (int i = 0; i < n && а->число_фактов < МАКС_ФАКТОВ; ++i)
        а->факты[а->число_фактов++] = локальные[i];
}

// Протолкнуть НЕГАТИВНЫЙ факт для else-ветви: только когда условие — единственный
// атом «имя == C» (тогда в else доказано «имя != C») либо «имя != C» (→ «== C»).
// Для конъюнкции/дизъюнкции отрицание — не простой факт, ничего не добавляем.
static void протолкнуть_факт_иначе(Анализатор *а, Узел *условие)
{
    Факт ф;
    if (а->число_фактов < МАКС_ФАКТОВ && атом_из_сравнения(а, условие, &ф)) {
        ф.равно = !ф.равно;   // отрицание: ==↔!=
        а->факты[а->число_фактов++] = ф;
    }
}

// Деактивировать факты, чью переменную мутирует оператор (присваивание/++/
// изменяемый-вывод) — консервативно, на остаток области. Так после возможной
// мутации переменной её факт больше не используется (никаких ложных «недостижим»).
static int имя_изменяется_в(Анализатор *а, Узел *узел,
                            const char *имя, size_t длина_имени);
static void инвалидировать_факты_мутацией(Анализатор *а, Узел *оператор)
{
    for (size_t k = 0; k < а->число_фактов; ++k) {
        Факт *F = &а->факты[k];
        if (F->активен && имя_изменяется_в(а, оператор, F->переменная,
                                           strlen(F->переменная)))
            F->активен = 0;
    }
}

static void установить_ограничение_из_условия(Анализатор *а, Узел *условие)
{
    // Null-narrowing (разворот «возможно»): «если (п != нуль)» доказывает, что в
    // then-ветви «п» ненулевой → в этой ветви его можно разыменовать. Снимок пути
    // (анализ_если) восстановит может_быть_нуль для else/после if.
    if (условие && условие->тип == УЗЕЛ_БИНОП
        && условие->токен.тип == ТОКЕН_ВОСКЛИЦАТЕЛЬНЫЙ_ЗНАК
        && условие->токен.длина == 2) {
        Символ *с = указатель_в_сравнении_с_нулём(а, условие);
        if (с) с->может_быть_нуль = 0;
    }
    if (условие->тип != УЗЕЛ_БИНОП || условие->токен.тип != ТОКЕН_СТРЕЛКА_ВПРАВО)
        return;
    Узел *лево = узел_ребёнок(условие, 0);
    Узел *право = узел_ребёнок(условие, 1);
    if (!лево || !право
        || лево->тип != УЗЕЛ_ИДЕНТИФИКАТОР
        || право->тип != УЗЕЛ_ЧИСЛО)
        return;
    long порог = значение_целого_литерала(право->токен.начало, право->токен.длина);
    long минимум = токен_текст_равен(&условие->токен, ">=") ? порог : порог + 1;
    ограничение_установить(а, лево->токен.начало, лево->токен.длина, минимум);
}

static void проверить_условие(Анализатор *а, Узел *условие)
{
    ИнфоТипа тип = типизировать_выражение(а, условие);
    if (а->диаг->ошибка) return;
    if (тип.тип != ТОКЕН_НЕИЗВЕСТНЫЙ && !тип_скалярный(тип)) {
        char тб[64];
        описание_типа(тип, тб, sizeof(тб));
        char msg[256];
        snprintf(msg, sizeof(msg),
                 "условие должно быть скалярным типом, получен «%s»", тб);
        ошибка_семантики(а, &условие->токен, msg);
    }
}

// Присваивается ли имени (или объявляется заново) где-либо в поддереве?
// Консервативно: затенение тем же именем тоже считается изменением. КЛЮЧЕВОЕ
// для безопасности элиминации проверки границ (BCE): «мутация без присваивания
// в тексте» — это передача имени в «изменяемый»/«вывод»-параметр (кодоген сам
// подставит «&имя», функция изменит переменную вызывающего). Не увидев её,
// анализ снял бы проверку границ по ложному основанию — реальный выход за
// границы (ASan ловил такой heap-overflow, когда индекс цикла увеличивался
// через ref внутри тела). Резолвим сигнатуру вызываемой функции ровно как
// собрать_изменяемые: по режиму параметра, без ложных срабатываний на вызовах
// по значению (печатать("%d", и) быстрый путь сохраняет).
static int имя_изменяется_в(Анализатор *а, Узел *узел,
                            const char *имя, size_t длина_имени)
{
    if (!узел) return 0;
    // Присваивание ИЛИ инкремент «цель++»/«цель--» цели-идентификатора = мутация.
    // Без учёта «++» тело канонического цикла с лишним «и++» обошло бы элизию
    // границ (тот же класс, что §43 Ф1) → выход за границы.
    if (узел->тип == УЗЕЛ_ПРИСВАИВАНИЕ || узел->тип == УЗЕЛ_ИНКРЕМЕНТ) {
        Узел *цель = узел_ребёнок(узел, 0);
        if (цель && цель->тип == УЗЕЛ_ИДЕНТИФИКАТОР
            && байты_равны(цель->токен.начало, цель->токен.длина, имя, длина_имени))
            return 1;
    }
    if (узел->тип == УЗЕЛ_ОБЪЯВЛЕНИЕ
        && байты_равны(узел->токен.начало, узел->токен.длина, имя, длина_имени))
        return 1;
    // Передача имени в «изменяемый»/«вывод»-параметр = мутация переменной.
    if (узел->тип == УЗЕЛ_ВЫЗОВ) {
        const СигнатураФункции *сиг =
            найти_сигнатуру_по_имени(а, узел->токен.начало, узел->токен.длина);
        if (сиг) {
            for (size_t i = 0; i < узел_число_детей(узел)
                               && i < сиг->число_параметров; ++i) {
                Узел *арг = узел_ребёнок(узел, i);
                if (сиг->параметры[i].по_ссылке > 0
                    && арг && арг->тип == УЗЕЛ_ИДЕНТИФИКАТОР
                    && байты_равны(арг->токен.начало, арг->токен.длина,
                                   имя, длина_имени))
                    return 1;
            }
        }
    }
    for (size_t i = 0; i < узел_число_детей(узел); ++i)
        if (имя_изменяется_в(а, узел_ребёнок(узел, i), имя, длина_имени))
            return 1;
    return 0;
}

// Распознаёт канонический цикл «для (T и = c0; и < длина(с); и = и + ш)»,
// где c0 ≥ 0 и ш > 0 — константы, а тело не меняет ни «и», ни «с». В этом
// случае любой доступ «с[и]» доказанно в границах [0, длина): добавляет пару
// (с, и) в стек безопасных. Возвращает 1, если пара добавлена.
static int распознать_безопасный_цикл(Анализатор *а, Узел *иниц,
                                       Узел *условие, Узел *шаг, Узел *тело)
{
    if (а->число_безопасных >= МАКС_БЕЗОПАСНЫХ) return 0;

    // Инициализация: «T и = c0», c0 — константа ≥ 0.
    if (!иниц || иниц->тип != УЗЕЛ_ОБЪЯВЛЕНИЕ || иниц->срез || иниц->массив
        || узел_число_детей(иниц) != 1)
        return 0;
    long c0;
    if (!вычислить_константу(а, узел_ребёнок(иниц, 0), &c0) || c0 < 0)
        return 0;
    const char *и_имя = иниц->токен.начало;
    size_t и_длина = иниц->токен.длина;

    // Условие: «и < длина(с)» (режим среза) или «и < N» (режим предела).
    if (!условие || условие->тип != УЗЕЛ_БИНОП
        || !токен_текст_равен(&условие->токен, "<"))
        return 0;
    Узел *лево = узел_ребёнок(условие, 0);
    Узел *право = узел_ребёнок(условие, 1);
    if (!лево || лево->тип != УЗЕЛ_ИДЕНТИФИКАТОР
        || !байты_равны(лево->токен.начало, лево->токен.длина, и_имя, и_длина))
        return 0;

    const char *с_имя = nullptr;
    size_t с_длина = 0;
    int есть_срез = 0;
    long предел = 0;
    int есть_предел = 0;
    const char *п_имя = nullptr; size_t п_длина = 0;
    int есть_перем = 0;

    if (право && право->тип == УЗЕЛ_ВЫЗОВ
        && токен_текст_равен(&право->токен, "длина")
        && узел_число_детей(право) == 1) {
        Узел *аргумент = узел_ребёнок(право, 0);
        if (!аргумент || аргумент->тип != УЗЕЛ_ИДЕНТИФИКАТОР)
            return 0;
        с_имя = аргумент->токен.начало;
        с_длина = аргумент->токен.длина;
        есть_срез = 1;
    } else if (вычислить_константу(а, право, &предел) && предел > 0) {
        есть_предел = 1;
    } else if (право && право->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
        // «и < н»: сработает только для срезов, созданных как «выделить(н)»
        // (проверяется на доступе). Иначе о связи длины и «н» ничего не знаем.
        п_имя = право->токен.начало;
        п_длина = право->токен.длина;
        есть_перем = 1;
    } else {
        return 0;
    }

    // Шаг: «и = и + ш» (ш — константа > 0) ИЛИ «и++» (постфиксный инкремент = +1).
    if (!шаг) return 0;
    if (шаг->тип == УЗЕЛ_ИНКРЕМЕНТ) {
        Узел *цель = узел_ребёнок(шаг, 0);
        int инкремент = шаг->токен.длина == 2 && шаг->токен.начало[0] == '+';
        // Только «и++» (шаг +1, возрастающий); «и--» уменьшает индекс — не канон.
        if (!инкремент || !цель || цель->тип != УЗЕЛ_ИДЕНТИФИКАТОР
            || !байты_равны(цель->токен.начало, цель->токен.длина, и_имя, и_длина))
            return 0;
    } else if (шаг->тип == УЗЕЛ_ПРИСВАИВАНИЕ) {
        Узел *цель = узел_ребёнок(шаг, 0);
        Узел *выраж = узел_ребёнок(шаг, 1);
        if (!цель || цель->тип != УЗЕЛ_ИДЕНТИФИКАТОР
            || !байты_равны(цель->токен.начало, цель->токен.длина, и_имя, и_длина))
            return 0;
        if (!выраж || выраж->тип != УЗЕЛ_БИНОП || !токен_текст_равен(&выраж->токен, "+"))
            return 0;
        Узел *ш_лево = узел_ребёнок(выраж, 0);
        Узел *ш_право = узел_ребёнок(выраж, 1);
        if (!ш_лево || ш_лево->тип != УЗЕЛ_ИДЕНТИФИКАТОР
            || !байты_равны(ш_лево->токен.начало, ш_лево->токен.длина, и_имя, и_длина))
            return 0;
        long ш;
        if (!вычислить_константу(а, ш_право, &ш) || ш <= 0)
            return 0;
    } else {
        return 0;
    }

    // Тело не должно менять индекс (иначе граница не гарантирована). Мутация —
    // и присваивание, и передача в «изменяемый»/«вывод» (см. имя_изменяется_в).
    if (имя_изменяется_в(а, тело, и_имя, и_длина))
        return 0;
    // В режиме среза тело не должно переназначать сам срез (иначе его длина,
    // а с ней и верхняя граница, могут измениться).
    if (есть_срез && имя_изменяется_в(а, тело, с_имя, с_длина))
        return 0;
    // Режим переменной: «н» не должна меняться в теле, иначе верхняя граница в
    // момент доступа уже другая.
    if (есть_перем && имя_изменяется_в(а, тело, п_имя, п_длина))
        return 0;

    а->безопасные[а->число_безопасных++] = (БезопаснаяПара){
        .индекс = { и_имя, и_длина },
        .срез = { с_имя, с_длина },
        .есть_срез = есть_срез,
        .предел = предел,
        .есть_предел = есть_предел,
        .перем = { п_имя, п_длина },
        .есть_перем = есть_перем,
    };
    return 1;
}

// Условие «если (и < длина(с))» или «если (и < N)» с БЕЗЗНАКОВЫМ индексом «и»
// доказывает и ∈ [0, верх) в then-ветви: и ≥ 0 — из беззнаковости, и < верх —
// из условия. Пока анализируется then-блок, добавляет безопасную пару (доступ
// «с[и]» напрямую, без рантайм-проверки границ — устранение проверки без потери
// безопасности). Возвращает 1, если пара добавлена (снять после блока). Индекс
// (и в режиме среза — сам срез) не должен меняться в теле, иначе верхняя граница
// в момент доступа не гарантирована.
static int распознать_безопасное_условие(Анализатор *а, Узел *условие, Узел *тело)
{
    if (а->число_безопасных >= МАКС_БЕЗОПАСНЫХ) return 0;
    if (!условие || условие->тип != УЗЕЛ_БИНОП
        || !токен_текст_равен(&условие->токен, "<"))
        return 0;
    Узел *лево = узел_ребёнок(условие, 0);
    Узел *право = узел_ребёнок(условие, 1);
    if (!лево || лево->тип != УЗЕЛ_ИДЕНТИФИКАТОР) return 0;
    // Беззнаковый индекс: гарантирует и ≥ 0 (для знакового отрицательное «и»
    // прошло бы «и < верх», но было бы вне границ снизу).
    Символ *ис = найти_символ(а, лево->токен.начало, лево->токен.длина);
    if (!ис || !ис->беззнаковый || ис->срез || ис->указатели) return 0;
    const char *и_имя = лево->токен.начало;
    size_t и_длина = лево->токен.длина;

    const char *с_имя = nullptr; size_t с_длина = 0;
    int есть_срез = 0; long предел = 0; int есть_предел = 0;
    if (право && право->тип == УЗЕЛ_ВЫЗОВ
        && токен_текст_равен(&право->токен, "длина")
        && узел_число_детей(право) == 1) {
        Узел *аргумент = узел_ребёнок(право, 0);
        if (!аргумент || аргумент->тип != УЗЕЛ_ИДЕНТИФИКАТОР) return 0;
        с_имя = аргумент->токен.начало; с_длина = аргумент->токен.длина;
        есть_срез = 1;
    } else if (вычислить_константу(а, право, &предел) && предел > 0) {
        есть_предел = 1;
    } else {
        return 0;
    }
    if (имя_изменяется_в(а, тело, и_имя, и_длина)) return 0;
    if (есть_срез && имя_изменяется_в(а, тело, с_имя, с_длина)) return 0;

    а->безопасные[а->число_безопасных++] = (БезопаснаяПара){
        .индекс = { и_имя, и_длина },
        .срез = { с_имя, с_длина },
        .есть_срез = есть_срез,
        .предел = предел,
        .есть_предел = есть_предел,
    };
    return 1;
}

// ─── путь-чувствительные флаги (definite assignment + нулевость) ─────────────
// Снимок флагов «инициализирована»/«может_быть_нуль» для каждого слота таблицы
// символов. Сливается на стыке ветвей: переменная инициализирована после if,
// только если она инициализирована на ВСЕХ путях (AND); указатель может быть
// нулём, если он нулевой хотя бы на ОДНОМ пути (OR).
typedef struct { int иниц; int нуль; int безоп; } ФлагиПути;
typedef struct {
    ФлагиПути эл[МАКС_СИМВОЛОВ];
    size_t число;
} СнимокПути;

static void снять_снимок_пути(const Анализатор *а, СнимокПути *с)
{
    с->число = а->число_символов;
    for (size_t i = 0; i < а->число_символов; ++i) {
        с->эл[i].иниц = а->символы[i].инициализирована;
        с->эл[i].нуль = а->символы[i].может_быть_нуль;
        с->эл[i].безоп = а->символы[i].безопасен_для_возврата;
    }
}

static void восстановить_снимок_пути(Анализатор *а, const СнимокПути *с)
{
    size_t n = с->число < а->число_символов ? с->число : а->число_символов;
    for (size_t i = 0; i < n; ++i) {
        а->символы[i].инициализирована = с->эл[i].иниц;
        а->символы[i].может_быть_нуль = с->эл[i].нуль;
        а->символы[i].безопасен_для_возврата = с->эл[i].безоп;
    }
}

// Слияние двух ветвей if. Ветвь-sink (заканчивается «вернуть») не вливается в
// fallthrough — берём состояние только из не-sink ветви. «база» используется,
// если обе ветви sink (код после if недостижим, состояние неважно).
static void слить_снимки_пути(Анализатор *а, int т_sink, int и_sink,
                               const СнимокПути *тогда, const СнимокПути *иначе,
                               const СнимокПути *база)
{
    for (size_t i = 0; i < а->число_символов; ++i) {
        int иниц, нуль, безоп;
        if (т_sink && и_sink) {
            иниц = база->эл[i].иниц;  нуль = база->эл[i].нуль;  безоп = база->эл[i].безоп;
        } else if (т_sink) {
            иниц = иначе->эл[i].иниц; нуль = иначе->эл[i].нуль; безоп = иначе->эл[i].безоп;
        } else if (и_sink) {
            иниц = тогда->эл[i].иниц; нуль = тогда->эл[i].нуль; безоп = тогда->эл[i].безоп;
        } else {
            иниц = тогда->эл[i].иниц && иначе->эл[i].иниц;  // init на всех путях
            нуль = тогда->эл[i].нуль || иначе->эл[i].нуль;  // нуль на любом пути
            безоп = тогда->эл[i].безоп && иначе->эл[i].безоп; // безопасен на ВСЕХ путях
        }
        а->символы[i].инициализирована = иниц;
        а->символы[i].может_быть_нуль = нуль;
        а->символы[i].безопасен_для_возврата = безоп;
    }
}

// Слияние для цикла: тело может не выполниться ни разу. Поэтому инициализацию
// внутри тела НЕ засчитываем как гарантированную (берём состояние до цикла), а
// зануление указателя в теле, наоборот, учитываем (мог стать нулём).
static void слить_цикл_путь(Анализатор *а, const СнимокПути *до,
                             const СнимокПути *тело)
{
    for (size_t i = 0; i < а->число_символов; ++i) {
        а->символы[i].инициализирована = до->эл[i].иниц;
        а->символы[i].может_быть_нуль = до->эл[i].нуль || тело->эл[i].нуль;
        // Указатель безопасен для возврата после цикла, только если безопасен и
        // до цикла, и после тела (тело могло переприсвоить его небезопасным).
        а->символы[i].безопасен_для_возврата =
            до->эл[i].безоп && тело->эл[i].безоп;
    }
}

static void анализ_если(Анализатор *а, Узел *узел)
{
    Узел *условие = узел_ребёнок(узел, 0);
    Узел *тогда   = узел_ребёнок(узел, 1);
    Узел *иначе   = узел_ребёнок(узел, 2);

    // Snapshot владения перед ветвлением: каждая ветвь работает со своей
    // копией, потом сливаем по правилу «во всех ветвях одинаково — иначе
    // ошибка». Это работает без рантайма: если итог одинаков, autofree
    // получает однозначное состояние на выходе из if; иначе мы отказываем.
    СостояниеВладения до, после_тогда, после_иначе;
    СнимокПути пдо, после_тогда_п, после_иначе_п;
    снять_состояние_владения(а, &до);
    снять_снимок_пути(а, &пдо);

    // Недостижимый код: условие then-ветви, противоречащее фактам объемлющих if
    // («если x==2 { если x==0 {…} }»), никогда не истинно → ошибка (инвариант №5).
    проверить_противоречие_условия(а, условие);

    ограничения_сохранить(а);
    установить_ограничение_из_условия(а, условие);
    проверить_условие(а, условие);
    // Устранение проверки границ: «если (и < длина(с))» с беззнаковым «и»
    // доказывает и ∈ [0, длина(с)) в then-ветви → доступ «с[и]» прямой.
    int снять_безопасную = распознать_безопасное_условие(а, условие, тогда);
    size_t сн_фактов = а->число_фактов;
    протолкнуть_факты_условия(а, условие);   // факты then-ветви на время анализа
    анализ_блока(а, тогда);
    а->число_фактов = сн_фактов;             // снять факты этой ветви
    if (снять_безопасную) а->число_безопасных--;
    ограничения_восстановить(а);
    снять_состояние_владения(а, &после_тогда);
    снять_снимок_пути(а, &после_тогда_п);
    int тогда_sink = блок_завершается_возвратом(тогда);

    int иначе_sink = 0;
    if (иначе) {
        восстановить_состояние_владения(а, &до);
        восстановить_снимок_пути(а, &пдо);
        // Null-narrowing симметрично: «если (п == нуль) { … } иначе { … }» —
        // в else-ветви «п» доказанно ненулевой (его можно разыменовать).
        if (условие && условие->тип == УЗЕЛ_БИНОП
            && условие->токен.тип == ТОКЕН_РАВНО && условие->токен.длина == 2) {
            Символ *с = указатель_в_сравнении_с_нулём(а, условие);
            if (с) с->может_быть_нуль = 0;
        }
        ограничения_сохранить(а);
        size_t сн_фактов_иначе = а->число_фактов;
        протолкнуть_факт_иначе(а, условие);   // else одиночного «==»/«!=» даёт факт
        анализ_блока(а, иначе);
        а->число_фактов = сн_фактов_иначе;
        ограничения_восстановить(а);
        снять_состояние_владения(а, &после_иначе);
        снять_снимок_пути(а, &после_иначе_п);
        иначе_sink = блок_завершается_возвратом(иначе);
    } else {
        // Нет ветви «иначе» — для слияния её эквивалент = состояние до if
        // (ветвь «не вошли в if» не делает ничего с владением).
        после_иначе = до;
        после_иначе_п = пдо;
    }

    // Sink: ветвь с безусловным «вернуть» не вливается в fallthrough.
    // Заменяем её снимок на «до», чтобы merge видел: «эта ветвь как будто не
    // меняла владения для тех, кто продолжает после if». autofree кодогена
    // на это не сломается: drop перед «вернуть» уже вставлен внутри ветви, а
    // в outer-scope-выход в этой ветви управление просто не попадает.
    СостояниеВладения для_слияния_тогда = тогда_sink ? до : после_тогда;
    СостояниеВладения для_слияния_иначе = иначе_sink ? до : после_иначе;

    // Восстанавливаем «до», чтобы слияние писало в чистый базовый снимок.
    восстановить_состояние_владения(а, &до);
    слить_состояния_владения(а, &до, &для_слияния_тогда, &для_слияния_иначе);

    // Путь-чувствительное слияние definite-assignment и нулевости указателей.
    слить_снимки_пути(а, тогда_sink, иначе_sink,
                      &после_тогда_п, &после_иначе_п, &пдо);
}

// Цикл «для (T и = c0; и < предел; …)» доказуемо выполняется хотя бы раз?
// Тело гарантированно исполняется, если входное условие истинно при и = c0:
// предел — константа (или длина среза с известной длиной) и c0 < предел
// (для «<») либо c0 <= предел (для «<=»). Тогда инициализацию/ненулевость,
// установленные в теле, можно засчитать и после цикла (снимаем консервативность).
static int цикл_для_выполнится(Анализатор *а, Узел *иниц, Узел *условие)
{
    if (!иниц || иниц->тип != УЗЕЛ_ОБЪЯВЛЕНИЕ || узел_число_детей(иниц) != 1)
        return 0;
    long c0;
    if (!вычислить_константу(а, узел_ребёнок(иниц, 0), &c0))
        return 0;
    if (!условие || условие->тип != УЗЕЛ_БИНОП)
        return 0;
    int меньше = токен_текст_равен(&условие->токен, "<");
    int меньше_равно = токен_текст_равен(&условие->токен, "<=");
    if (!меньше && !меньше_равно)
        return 0;
    Узел *лево = узел_ребёнок(условие, 0);
    Узел *право = узел_ребёнок(условие, 1);
    if (!лево || лево->тип != УЗЕЛ_ИДЕНТИФИКАТОР
        || !байты_равны(лево->токен.начало, лево->токен.длина,
                        иниц->токен.начало, иниц->токен.длина))
        return 0;
    long предел;
    if (вычислить_константу(а, право, &предел))
        return меньше ? (c0 < предел) : (c0 <= предел);
    // «и < длина(с)» с известной на этапе компиляции длиной среза.
    if (право && право->тип == УЗЕЛ_ВЫЗОВ
        && токен_текст_равен(&право->токен, "длина")
        && узел_число_детей(право) == 1) {
        Узел *арг = узел_ребёнок(право, 0);
        if (арг && арг->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
            Символ *с = найти_символ(а, арг->токен.начало, арг->токен.длина);
            if (с && с->длина_известна)
                return меньше ? (c0 < с->длина) : (c0 <= с->длина);
        }
    }
    return 0;
}

// «выбор выр { ВАРИАНТ { … } … }» — match по перечислению с проверкой
// исчерпываемости: выражение должно быть перечислением, каждая ветка —
// существующий вариант этого enum без повторов, и покрыты все варианты (или
// есть ветка «_»). Путь-чувствительное слияние ветвей — как у if, обобщённое
// на N ветвей (init на всех ветвях, нуль — на любой).
static void анализ_выбор(Анализатор *а, Узел *узел)
{
    Узел *выр = узел_ребёнок(узел, 0);
    ИнфоТипа т = типизировать_выражение(а, выр);
    if (а->диаг->ошибка) return;
    if (т.тип != ТОКЕН_ПЕРЕЧИСЛЕНИЕ || т.индекс_структуры < 0
        || (size_t)т.индекс_структуры >= а->число_перечислений) {
        ошибка_семантики(а, &выр->токен,
            "«выбор» применим только к выражению-перечислению");
        return;
    }
    const ОписаниеПеречисления *п = &а->перечисления[т.индекс_структуры];

    int покрыт[МАКС_ВАРИАНТОВ] = {0};
    int есть_умолчание = 0;

    СнимокПути пдо;
    снять_снимок_пути(а, &пдо);
    СнимокПути acc;
    acc.число = а->число_символов;
    for (size_t i = 0; i < а->число_символов; ++i) { acc.эл[i].иниц = 1; acc.эл[i].нуль = 0; }
    int есть_живая = 0;

    for (size_t b = 1; b < узел_число_детей(узел); ++b) {
        Узел *ветка = узел_ребёнок(узел, b);
        if (!ветка || ветка->тип != УЗЕЛ_ВЕТКА_ВЫБОРА) continue;

        int нашли = -1;
        size_t число_привязок = узел_число_детей(ветка) - 1;  // все, кроме блока
        if (байты_равны(ветка->токен.начало, ветка->токен.длина, "_", 1)) {
            есть_умолчание = 1;
            if (число_привязок > 0) {
                ошибка_семантики(а, &ветка->токен,
                    "ветка «_» не может привязывать полезную нагрузку");
                return;
            }
        } else {
            for (size_t j = 0; j < п->число_вариантов; ++j) {
                if (байты_равны(п->варианты[j].имя, strlen(п->варианты[j].имя),
                                ветка->токен.начало, ветка->токен.длина)) {
                    нашли = (int)j; break;
                }
            }
            if (нашли < 0) {
                ошибка_семантики(а, &ветка->токен,
                    "вариант не принадлежит перечислению выбираемого выражения");
                return;
            }
            if (покрыт[нашли]) {
                ошибка_семантики(а, &ветка->токен,
                    "дублирующаяся ветка варианта в «выбор»");
                return;
            }
            покрыт[нашли] = 1;
            // Привязка полезной нагрузки: число имён должно совпадать с числом
            // полей варианта (либо 0 — нагрузка игнорируется).
            const ВариантПеречисления *в = &п->варианты[нашли];
            if (число_привязок > 0 && число_привязок != в->число_полей) {
                char msg[256];
                snprintf(msg, sizeof msg,
                    "вариант «%s» несёт %zu поле(й), привязано %zu",
                    в->имя, в->число_полей, число_привязок);
                ошибка_семантики(а, &ветка->токен, msg);
                return;
            }
        }

        восстановить_снимок_пути(а, &пдо);
        Узел *блок_ветки = узел_последний_ребёнок(ветка);
        // Область для привязок нагрузки: объявляем b1,b2,… с типами полей
        // варианта; видны только в блоке этой ветки.
        войти_в_область(а);
        if (нашли >= 0 && число_привязок > 0) {
            const ВариантПеречисления *в = &п->варианты[нашли];
            for (size_t k = 0; k < число_привязок; ++k) {
                Узел *имя_узел = узел_ребёнок(ветка, k);
                const ПолеВарианта *пв = &в->поля[k];
                объявить_символ(а, имя_узел->токен.начало, имя_узел->токен.длина,
                    пв->тип, пв->указатели, 0, пв->беззнаковый, 0, 0, 0,
                    &имя_узел->токен, 0, 0);
                Символ *с = найти_символ(а, имя_узел->токен.начало,
                                         имя_узел->токен.длина);
                if (с) с->индекс_структуры = пв->индекс_структуры;
            }
        }
        анализ_блока(а, блок_ветки);
        выйти_из_области(а);
        if (а->диаг->ошибка) return;
        if (!блок_завершается_возвратом(блок_ветки)) {
            есть_живая = 1;
            for (size_t i = 0; i < а->число_символов; ++i) {
                acc.эл[i].иниц &= а->символы[i].инициализирована;
                acc.эл[i].нуль |= а->символы[i].может_быть_нуль;
            }
        }
    }

    // Исчерпываемость: без «_» должны быть покрыты все варианты.
    if (!есть_умолчание) {
        for (size_t j = 0; j < п->число_вариантов; ++j) {
            if (!покрыт[j]) {
                char msg[256];
                snprintf(msg, sizeof(msg),
                    "«выбор» не исчерпывающий: не обработан вариант «%s» "
                    "(добавьте ветку или «_»)", п->варианты[j].имя);
                ошибка_семантики(а, &выр->токен, msg);
                return;
            }
        }
    }

    // Слияние ветвей: применяем накопленное состояние живых ветвей.
    восстановить_снимок_пути(а, &пдо);
    if (есть_живая) {
        for (size_t i = 0; i < а->число_символов; ++i) {
            а->символы[i].инициализирована = acc.эл[i].иниц;
            а->символы[i].может_быть_нуль = acc.эл[i].нуль;
        }
    }
}

static void анализ_пока(Анализатор *а, Узел *узел)
{
    Узел *условие = узел_ребёнок(узел, 0);
    Узел *тело    = узел_ребёнок(узел, 1);

    // Недостижимый код: «если x==2 { пока x==0 {…} }» — тело цикла не выполнится.
    // Факты в тело НЕ проталкиваем (цикл обычно мутирует переменную условия).
    проверить_противоречие_условия(а, условие);
    ограничения_сохранить(а);
    установить_ограничение_из_условия(а, условие);
    проверить_условие(а, условие);
    а->глубина_цикла++;
    СнимокПути до_тела;
    снять_снимок_пути(а, &до_тела);
    анализ_блока(а, тело);
    СнимокПути после_тела;
    снять_снимок_пути(а, &после_тела);
    слить_цикл_путь(а, &до_тела, &после_тела);
    а->глубина_цикла--;
    ограничения_восстановить(а);
}

// ─── «параллельно для»: параллелизм данных без разделяемого состояния ────────
//
// Диапазон цикла дробится на непересекающиеся куски по потокам. Гонок нет ПО
// ПОСТРОЕНИЮ, если каждая итерация пишет только «в свой» элемент: чтение общих
// данных безопасно (никто их не меняет), а запись наружу — уже гонка.
//
// Отсюда правила (все статические, нулевая рантайм-цена):
//   * писать можно только в «база[и]» по переменной цикла, либо в переменные,
//     объявленные ВНУТРИ тела (они у каждой итерации свои);
//   * «прервать»/«продолжить»/«вернуть» из тела запрещены (у кусков нет общего
//     порядка, и выход из середины параллельного диапазона не имеет смысла);
//   * вызывать можно только ЧИСТЫЕ функции (чистота выводится — см.
//     «вывести_чистоту»): чистая не пишет наружу, значит гонки не создаст;
//   * писать во внешнюю переменную можно только как в аккумулятор редукции
//     («редукция(итог)»): у каждого куска он свой, свёртка — после join.

// Копирует текст токена в буфер имени (для диагностики).
static void скопировать_имя_токена(char *куда, const Токен *т)
{
    size_t n = т->длина < МАКС_ИМЯ - 1 ? т->длина : МАКС_ИМЯ - 1;
    memcpy(куда, т->начало, n);
    куда[n] = '\0';
}

// Складывает объяснение, ПОЧЕМУ функция не чистая: без причины диагностика
// («нельзя вызывать») не подсказывает, что чинить. «в» == nullptr — сигнатуры
// нет вовсе (внешняя/libc).
static void объяснить_нечистоту(const СигнатураФункции *в, const Токен *вызов,
                                 char *буфер, size_t размер)
{
    char имя[МАКС_ИМЯ];
    скопировать_имя_токена(имя, вызов);
    const char *что = в ? в->имя_эффекта : "";
    char почему[320];
    switch (в ? в->вид_эффекта : ЭФФЕКТ_ВНЕШНЯЯ) {
        case ЭФФЕКТ_ССЫЛОЧНЫЙ_ПАРАМЕТР:
            snprintf(почему, sizeof почему,
                "имеет параметр «%s» с «изменяемый»/«вывод» — пишет в кадр "
                "вызывающего", что);
            break;
        case ЭФФЕКТ_УКАЗАТЕЛЬ_ПАРАМЕТР:
            snprintf(почему, sizeof почему,
                "принимает указатель «%s» — может писать в чужую память", что);
            break;
        case ЭФФЕКТ_ВЛАДЕЕТ_ПАРАМЕТР:
            snprintf(почему, sizeof почему,
                "принимает «владеет»-параметр «%s» — потребляет срез, а он общий "
                "у всех кусков", что);
            break;
        case ЭФФЕКТ_ЗАПИСЬ_В_СРЕЗ:
            snprintf(почему, sizeof почему,
                "пишет в срез-параметр «%s» — это общие данные", что);
            break;
        case ЭФФЕКТ_ПОТОК:
            snprintf(почему, sizeof почему, "сама запускает потоки");
            break;
        case ЭФФЕКТ_ВЫДЕЛЕНИЕ:
            snprintf(почему, sizeof почему,
                "выделяет память («%s»)", что[0] ? что : "выделить");
            break;
        case ЭФФЕКТ_НЕБЕЗОПАСНО:
            snprintf(почему, sizeof почему,
                "содержит «небезопасно» — там возможен сырой указатель");
            break;
        case ЭФФЕКТ_ВЫЗОВ_НЕЧИСТОЙ:
            snprintf(почему, sizeof почему,
                "вызывает нечистую «%s»", что);
            break;
        default:
            snprintf(почему, sizeof почему,
                "внешняя — её эффекты транспилятору неизвестны");
            break;
    }
    snprintf(буфер, размер,
        "в «параллельно для» можно вызывать только чистые функции, а «%s» %s; "
        "это могло бы быть гонкой", имя, почему);
}

// Операция редукции обязана быть ассоциативной И коммутативной: куски
// сворачиваются в произвольном порядке. «-» не годится — свёртка частичных
// разностей потребовала бы другой операции, а не той же.
static int операция_редукции(ТипТокена т)
{
    return т == ТОКЕН_ПЛЮС || т == ТОКЕН_ЗВЕЗДА || т == ТОКЕН_ПРЯМАЯ_ЧЕРТА
        || т == ТОКЕН_СТРЕЛКА_ВВЕРХ || т == ТОКЕН_АМПЕРСАНД;
}

// Имя объявлено внутри тела цикла (тогда оно у каждой итерации своё)?
static int объявлено_в_теле(const Узел *тело, const Токен *имя)
{
    if (!тело) return 0;
    if (тело->тип == УЗЕЛ_ОБЪЯВЛЕНИЕ && тело->токен.длина == имя->длина
        && memcmp(тело->токен.начало, имя->начало, имя->длина) == 0)
        return 1;
    for (size_t i = 0; i < узел_число_детей(тело); ++i)
        if (объявлено_в_теле(узел_ребёнок(тело, i), имя)) return 1;
    return 0;
}

static int токены_равны_(const Токен *а, const Токен *б)
{
    return а->длина == б->длина && memcmp(а->начало, б->начало, а->длина) == 0;
}

// Имя упоминается в поддереве? Нужно, чтобы запретить чтение частичного
// аккумулятора: его значение зависит от раскладки кусков по потокам.
static int упоминается_имя(const Узел *у, const Токен *имя)
{
    if (!у) return 0;
    if (у->тип == УЗЕЛ_ИДЕНТИФИКАТОР && токены_равны_(&у->токен, имя)) return 1;
    // У «с[и]» старой формы имя базы лежит в ТОКЕНЕ узла-индекса.
    if (у->тип == УЗЕЛ_ИНДЕКС && узел_число_детей(у) == 1
        && токены_равны_(&у->токен, имя)) return 1;
    for (size_t i = 0; i < узел_число_детей(у); ++i)
        if (упоминается_имя(узел_ребёнок(у, i), имя)) return 1;
    return 0;
}

// Оператор вида «итог = итог <оп> выражение» (или «итог = выражение <оп> итог»)?
// Возвращает операцию через «оп» и подвыражение-вклад через «вклад».
// Только такая форма даёт корректную свёртку: у куска свой аккумулятор,
// стартующий с единицы операции, и порядок слияния кусков не важен.
static int канонический_оператор_редукции(Анализатор *а, Узел *у,
                                           const Токен *цель, ТипТокена *оп,
                                           Узел **вклад)
{
    Узел *знач = узел_число_детей(у) > 1 ? узел_ребёнок(у, 1) : nullptr;
    if (!знач || знач->тип != УЗЕЛ_БИНОП || !операция_редукции(знач->токен.тип)) {
        ошибка_семантики(а, &у->токен,
            "аккумулятор редукции меняется только как «имя = имя <оп> выражение», "
            "где <оп> — одна из «+ * | ^ &» (ассоциативных и коммутативных): "
            "куски сворачиваются в произвольном порядке");
        return 0;
    }
    Узел *л = узел_ребёнок(знач, 0);
    Узел *п = узел_ребёнок(знач, 1);
    Узел *сам = nullptr;
    Узел *другой = nullptr;
    if (л && л->тип == УЗЕЛ_ИДЕНТИФИКАТОР && токены_равны_(&л->токен, цель)) {
        сам = л; другой = п;
    } else if (п && п->тип == УЗЕЛ_ИДЕНТИФИКАТОР
               && токены_равны_(&п->токен, цель)) {
        сам = п; другой = л;
    }
    if (!сам) {
        ошибка_семантики(а, &у->токен,
            "в редукции одним из операндов обязан быть сам аккумулятор: "
            "«имя = имя <оп> выражение»");
        return 0;
    }
    if (упоминается_имя(другой, цель)) {
        ошибка_семантики(а, &у->токен,
            "аккумулятор редукции упоминается в правой части дважды: его частичное "
            "значение зависит от раскладки кусков по потокам (недетерминировано)");
        return 0;
    }
    *оп = знач->токен.тип;
    *вклад = другой;
    return 1;
}

// Проверяет тело «параллельно для» на отсутствие гонок и запрещённых выходов.
// «цикл» — узел «параллельно для» (несёт сведения о редукции).
static void проверить_параллельное_тело(Анализатор *а, Узел *у, Узел *цикл,
                                         Узел *тело, const Токен *перем_цикла)
{
    if (!у) return;
    // Любое упоминание аккумулятора ВНЕ канонического оператора редукции — это
    // чтение частичной суммы куска; она зависит от того, как диапазон лёг на
    // потоки, то есть недетерминирована. Канонический оператор до сюда не
    // доходит: он разбирается в УЗЕЛ_ПРИСВАИВАНИЕ и возвращается сразу.
    if (цикл->редукция && у->тип == УЗЕЛ_ИДЕНТИФИКАТОР
        && токены_равны_(&у->токен, &цикл->редукция_имя)) {
        ошибка_семантики(а, &у->токен,
            "аккумулятор редукции читается вне «имя = имя <оп> выражение»: у каждого "
            "куска он свой и виден только частично — результат зависел бы от числа "
            "ядер (недетерминированно); используйте его после цикла");
        return;
    }
    switch (у->тип) {
        case УЗЕЛ_ПРЕРВАТЬ:
        case УЗЕЛ_ПРОДОЛЖИТЬ:
        case УЗЕЛ_ВОЗВРАТ:
            ошибка_семантики(а, &у->токен,
                "«прервать»/«продолжить»/«вернуть» запрещены в «параллельно для»: "
                "итерации идут кусками в разных потоках, общего порядка у них нет");
            return;
        case УЗЕЛ_ВЫЗОВ:
            // «длина(с)» — встроенная и чистая. Остальные пускаем, если чистота
            // ВЫВЕДЕНА: чистая функция не пишет наружу, значит гонки создать не
            // может. Нечистую отвергаем, называя причину и позицию эффекта.
            if (!токен_текст_равен(&у->токен, "длина")) {
                const СигнатураФункции *в =
                    найти_сигнатуру_по_имени(а, у->токен.начало, у->токен.длина);
                if (!в || !в->чистая) {
                    char msg[768];
                    объяснить_нечистоту(в, &у->токен, msg, sizeof msg);
                    ошибка_семантики(а, &у->токен, msg);
                    return;
                }
            }
            break;
        case УЗЕЛ_ИНКРЕМЕНТ: {
            // «цель++» — запись; те же правила, что для присваивания (кроме
            // редукции: она требует явного «имя = имя <оп> выражение»).
            Узел *цель = узел_ребёнок(у, 0);
            if (цель && цель->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                if (!объявлено_в_теле(тело, &цель->токен)) {
                    ошибка_семантики(а, &цель->токен,
                        "инкремент внешней переменной из «параллельно для» — гонка: "
                        "потоки писали бы в одну ячейку (для суммирования используйте "
                        "«редукция(имя)» через «имя = имя + …»)");
                    return;
                }
            } else if (цель && цель->тип == УЗЕЛ_ИНДЕКС) {
                Узел *инд = узел_число_детей(цель) == 2 ? узел_ребёнок(цель, 1)
                                                        : узел_ребёнок(цель, 0);
                if (!инд || инд->тип != УЗЕЛ_ИДЕНТИФИКАТОР
                    || !токены_равны_(&инд->токен, перем_цикла)) {
                    ошибка_семантики(а, &цель->токен,
                        "в «параллельно для» инкрементировать можно только «база[и]» "
                        "по переменной цикла (иначе непересечение кусков не доказать)");
                    return;
                }
            } else if (цель) {
                ошибка_семантики(а, &цель->токен,
                    "недопустимая цель инкремента в «параллельно для»");
                return;
            }
            return;  // цель проверена; в неё не спускаемся
        }
        case УЗЕЛ_ПРИСВАИВАНИЕ: {
            Узел *цель = узел_ребёнок(у, 0);
            if (цель && цель->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                // Аккумулятор редукции — ЕДИНСТВЕННОЕ исключение из запрета
                // писать наружу: у каждого куска он свой (в его кадре), общей
                // ячейки нет, а свёртка идёт после join в одном потоке.
                if (цикл->редукция
                    && токены_равны_(&цель->токен, &цикл->редукция_имя)) {
                    ТипТокена оп;
                    Узел *вклад = nullptr;
                    if (!канонический_оператор_редукции(а, у, &цикл->редукция_имя,
                                                         &оп, &вклад))
                        return;
                    if (цикл->редукция_оп != ТОКЕН_НЕИЗВЕСТНЫЙ
                        && цикл->редукция_оп != оп) {
                        ошибка_семантики(а, &у->токен,
                            "в одной редукции смешаны разные операции: свёртка "
                            "кусков стала бы неоднозначной");
                        return;
                    }
                    цикл->редукция_оп = оп;
                    // В сам аккумулятор не спускаемся (иначе сработает запрет
                    // чтения); проверяем только вклад.
                    проверить_параллельное_тело(а, вклад, цикл, тело, перем_цикла);
                    return;
                }
                // Переменная, объявленная в теле, — своя у каждой итерации.
                if (!объявлено_в_теле(тело, &цель->токен)) {
                    ошибка_семантики(а, &цель->токен,
                        "запись во внешнюю переменную из «параллельно для» — гонка: "
                        "потоки писали бы в одну ячейку; пишите в «база[и]», "
                        "объявите переменную внутри тела или заведите редукцию "
                        "«редукция(имя)»");
                    return;
                }
            } else if (цель && цель->тип == УЗЕЛ_ИНДЕКС) {
                // Писать можно только «база[и]» — по переменной цикла: такие
                // элементы у разных итераций разные, значит куски не пересекаются.
                Узел *инд = узел_число_детей(цель) == 2 ? узел_ребёнок(цель, 1)
                                                        : узел_ребёнок(цель, 0);
                if (!инд || инд->тип != УЗЕЛ_ИДЕНТИФИКАТОР
                    || !токены_равны_(&инд->токен, перем_цикла)) {
                    ошибка_семантики(а, &цель->токен,
                        "в «параллельно для» писать можно только в «база[и]» по "
                        "переменной цикла: иначе непересечение кусков не доказать "
                        "(возможна гонка)");
                    return;
                }
            } else if (цель) {
                ошибка_семантики(а, &цель->токен,
                    "недопустимая цель записи в «параллельно для»");
                return;
            }
            break;
        }
        default: break;
    }
    for (size_t i = 0; i < узел_число_детей(у); ++i)
        проверить_параллельное_тело(а, узел_ребёнок(у, i), цикл, тело, перем_цикла);
}

// Цель «редукция(имя)» пригодна? Проверяем ДО тела, чтобы ошибка была одна.
static int проверить_цель_редукции(Анализатор *а, Узел *цикл,
                                    const Токен *перем_цикла)
{
    const Токен *имя = &цикл->редукция_имя;
    if (токены_равны_(имя, перем_цикла)) {
        ошибка_семантики(а, имя,
            "переменная цикла не может быть аккумулятором редукции: её значение "
            "задаёт разбиение на куски");
        return 0;
    }
    Символ *с = найти_символ(а, имя->начало, имя->длина);
    if (!с) {
        ошибка_семантики(а, имя,
            "аккумулятор редукции должен быть объявлен до цикла");
        return 0;
    }
    if (с->неизменяемый) {
        ошибка_семантики(а, имя,
            "аккумулятор редукции не может быть «конст»: цикл его меняет");
        return 0;
    }
    ИнфоТипа т = { с->тип, с->указатели, с->беззнаковый, с->срез,
                   с->индекс_структуры };
    if (!тип_целочисленный(т) || с->массив) {
        // Вещественная редукция дала бы разный ответ на разном числе ядер:
        // сложение/умножение float не ассоциативно. Предсказуемость важнее —
        // как и в побитовых операциях, отвергаем нецелые.
        ошибка_семантики(а, имя,
            "редукция поддержана только для целочисленных типов: у вещественных "
            "сложение и умножение не ассоциативны, поэтому результат зависел бы от "
            "числа ядер и раскладки кусков (недетерминированно)");
        return 0;
    }
    return 1;
}

// Собирает внешние переменные, которые читает тело, как дети-УЗЕЛ_ЗАХВАТ.
// Кодогену они нужны, чтобы построить кадр потока: своей таблицы символов у
// него нет, а типы известны только здесь.
static void захватить_имя(Анализатор *а, Узел *цикл, Узел *тело,
                           const Токен *имя, const Токен *перем_цикла)
{
    if (токены_равны_(имя, перем_цикла) || объявлено_в_теле(тело, имя)) return;
    for (size_t i = 4; i < узел_число_детей(цикл); ++i)   // уже захвачено?
        if (токены_равны_(&узел_ребёнок(цикл, i)->токен, имя)) return;
    Символ *с = найти_символ(а, имя->начало, имя->длина);
    if (!с) return;                                        // не переменная
    Узел *з = узел_создать(УЗЕЛ_ЗАХВАТ);
    з->токен = *имя;
    з->тип_данных = с->тип;
    з->беззнаковый = с->беззнаковый;
    з->указатели = с->указатели;
    з->срез = с->срез;
    з->имя_типа = *имя;
    // Аккумулятор редукции захватывается как обычная переменная (тип, поле кадра
    // и подстановка «_к->имя» работают даром), но в кадр кладётся ЕДИНИЦА
    // операции, а не копия внешнего значения, и после join идёт свёртка.
    if (цикл->редукция && токены_равны_(имя, &цикл->редукция_имя)) {
        з->редукция = 1;
        з->редукция_оп = цикл->редукция_оп;
    }
    узел_добавить_ребёнка(цикл, з);
}

static void собрать_захваты(Анализатор *а, Узел *цикл, Узел *у, Узел *тело,
                             const Токен *перем_цикла)
{
    if (!у) return;
    if (у->тип == УЗЕЛ_ИДЕНТИФИКАТОР)
        захватить_имя(а, цикл, тело, &у->токен, перем_цикла);
    // У «с[и]» старой формы имя базы лежит в ТОКЕНЕ узла-индекса, а не в
    // дочернем идентификаторе, — иначе сам срез не был бы захвачен.
    if (у->тип == УЗЕЛ_ИНДЕКС && узел_число_детей(у) == 1)
        захватить_имя(а, цикл, тело, &у->токен, перем_цикла);
    for (size_t i = 0; i < узел_число_детей(у); ++i)
        собрать_захваты(а, цикл, узел_ребёнок(у, i), тело, перем_цикла);
}

static void анализ_для(Анализатор *а, Узел *узел)
{
    Узел *инициализация = узел_ребёнок(узел, 0);
    Узел *условие       = узел_ребёнок(узел, 1);
    Узел *шаг           = узел_ребёнок(узел, 2);
    Узел *тело          = узел_ребёнок(узел, 3);

    войти_в_область(а);
    анализ_оператора(а, инициализация);
    ограничения_сохранить(а);
    установить_ограничение_из_условия(а, условие);
    проверить_условие(а, условие);
    типизировать_выражение(а, шаг);

    // «параллельно для» требует канонической формы: только у неё известно, что
    // «и» пробегает диапазон ровно по разу, — на этом держится непересечение
    // кусков. Проверяем ДО анализа тела, чтобы ошибка была одна и понятная.
    if (узел->параллельно) {
        if (!инициализация || инициализация->тип != УЗЕЛ_ОБЪЯВЛЕНИЕ) {
            ошибка_семантики(а, &узел->токен,
                "«параллельно для» требует канонической формы: "
                "«параллельно для (целое32 и = 0; и < предел; и = и + 1)»");
        } else if (узел->редукция
                   && !проверить_цель_редукции(а, узел, &инициализация->токен)) {
            // Ошибка уже выдана: тело не проверяем, чтобы не сыпать вторичным.
        } else {
            // Можно ли в шиме сравнивать счётчик с границей куска в ЕГО типе?
            // Обычный «для» и так сравнивает в типе счётчика (`и < длина(с)` →
            // `int32 < int32`), а шим хранит границы куска как long и тем самым
            // отклоняется: под -fwrapv компилятор обязан допустить перенос
            // счётчика, число итераций становится недоказуемым и SIMD пропадает.
            // Приводить границу к типу счётчика можно, только если она не шире —
            // иначе (напр. `целое32 и < целое64 предел`) C расширяет сравнение до
            // 64 бит, и сужение изменило бы поведение.
            ИнфоТипа тс = { инициализация->тип_данных, инициализация->указатели,
                            инициализация->беззнаковый, инициализация->срез, -1 };
            int ш_счётчика = ширина_бит(тс);
            int ш_границы = 0;
            if (условие && условие->тип == УЗЕЛ_БИНОП
                && узел_число_детей(условие) == 2)
                ш_границы = ширина_бит(типизировать_выражение(а,
                                            узел_ребёнок(условие, 1)));
            узел->граница_в_типе_счётчика =
                ш_счётчика > 0 && ш_границы > 0 && ш_границы <= ш_счётчика;
            узел->редукция_оп = ТОКЕН_НЕИЗВЕСТНЫЙ;
            проверить_параллельное_тело(а, тело, узел, тело,
                                        &инициализация->токен);
            if (!а->диаг->ошибка)
                собрать_захваты(а, узел, тело, тело, &инициализация->токен);
        }
    }

    // Если это канонический цикл по срезу/массиву, доступы по индексу цикла
    // внутри тела безопасны — анализ тела проставит им безопасный_индекс.
    int безопасный = распознать_безопасный_цикл(а, инициализация, условие, шаг, тело);
    int выполнится = цикл_для_выполнится(а, инициализация, условие);
    а->глубина_цикла++;
    СнимокПути до_тела;
    снять_снимок_пути(а, &до_тела);
    анализ_блока(а, тело);
    // Доказуемо ≥1 итерация: состояние после цикла = состояние конца тела
    // (последняя итерация), оставляем как есть. Иначе — консервативное слияние
    // с «тело могло не выполниться».
    if (!выполнится) {
        СнимокПути после_тела;
        снять_снимок_пути(а, &после_тела);
        слить_цикл_путь(а, &до_тела, &после_тела);
    }
    а->глубина_цикла--;
    if (безопасный) а->число_безопасных--;

    ограничения_восстановить(а);
    выйти_из_области(а);
}

// foreach: «для_каждого (имя из коллекция) { … }».
// Семантика:
//   1. Типизировать коллекцию: срез<T> или массив T[N].
//   2. Завести «имя» в области тела с типом T (копия элемента).
//   3. Тело анализируется как тело цикла (глубина_цикла++, чтобы move
//      исходника из внешней области был запрещён, как в обычном «для»).
// На узле УЗЕЛ_ДЛЯ_КАЖДОГО сохраняем элементный тип — пригодится кодогену
// (он генерит C-цикл с прямым доступом, не зная типа коллекции отдельно).
static void анализ_для_каждого(Анализатор *а, Узел *узел)
{
    Узел *коллекция = узел_ребёнок(узел, 0);
    Узел *тело      = узел_ребёнок(узел, 1);

    ИнфоТипа тип_к = типизировать_выражение(а, коллекция);
    if (а->диаг->ошибка) return;

    int это_срез = тип_к.срез;
    int это_массив = 0;
    long длина_массива = 0;

    // Массив-переменная: тип идёт не через ИнфоТипа (массив там не отражается),
    // а через символ исходного идентификатора (как в авто-конверсии массива в
    // срез при вызове функции).
    if (!это_срез && коллекция->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
        Символ *с = найти_символ(а, коллекция->токен.начало, коллекция->токен.длина);
        if (с && с->массив && с->длина_известна) {
            это_массив = 1;
            длина_массива = с->длина;
        }
    }

    if (!это_срез && !это_массив) {
        ошибка_семантики(а, &коллекция->токен,
            "«для_каждого» работает только со срезом или массивом фикс. размера");
        return;
    }

    // Метаданные элемента сохраняем на самом узле foreach — для кодогена.
    узел->тип_данных = тип_к.тип;
    узел->беззнаковый = тип_к.беззнаковый;
    узел->указатели = тип_к.указатели;
    узел->срез = это_срез;
    узел->массив = это_массив;
    узел->размер_массива = длина_массива;
    // Имя типа элемента-структуры — кодогену для C-типа связываемой переменной
    // (иначе тип_токена_в_си дал бы «int» вместо имени структуры).
    if (тип_к.тип == ТОКЕН_СТРУКТУРА && тип_к.индекс_структуры >= 0)
        узел->имя_типа = а->структуры[тип_к.индекс_структуры].имя_токен;

    // Тело — со своей областью видимости. Имя элемента (узел->токен) живёт
    // только внутри неё.
    войти_в_область(а);

    // Длина элемента известна, только если он сам массив — а вложенные
    // массивы пока не поддерживаются, так что длина_известна = 0.
    объявить_символ(а,
        узел->токен.начало, узел->токен.длина,
        тип_к.тип, тип_к.указатели, /*массив=*/0,
        тип_к.беззнаковый, /*срез=*/0,
        /*длина_известна=*/0, /*длина=*/0,
        &узел->токен,
        /*значение_известно=*/0, /*значение=*/0);
    // Элемент-структура: связанная переменная несёт индекс типа — для «т.поле».
    if (тип_к.тип == ТОКЕН_СТРУКТУРА && тип_к.индекс_структуры >= 0) {
        Символ *эл = найти_символ(а, узел->токен.начало, узел->токен.длина);
        if (эл) эл->индекс_структуры = тип_к.индекс_структуры;
    }

    // Доказуемо ≥1 итерация: массив фикс. размера (его размер — положительный
    // литерал, всегда > 0) или срез с известной длиной > 0. Тогда тело
    // гарантированно исполняется → снимаем консервативность после цикла.
    int выполнится = 0;
    if (это_массив && длина_массива > 0) {
        выполнится = 1;
    } else if (это_срез && коллекция->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
        Символ *с = найти_символ(а, коллекция->токен.начало, коллекция->токен.длина);
        if (с && с->длина_известна && с->длина > 0) выполнится = 1;
    }

    а->глубина_цикла++;
    СнимокПути до_тела;
    снять_снимок_пути(а, &до_тела);
    анализ_блока(а, тело);
    if (!выполнится) {
        СнимокПути после_тела;
        снять_снимок_пути(а, &после_тела);
        слить_цикл_путь(а, &до_тела, &после_тела);
    }
    а->глубина_цикла--;

    выйти_из_области(а);
}

// «асм(…)» — вставка ассемблера. Гейт: только в «небезопасно» (сырой доступ к
// регистрам/памяти — по определению небезопасен, инвариант №2). Операнды —
// обычные Konda-выражения; выходные помечаем изменяемыми/инициализированными
// (asm пишет в них — иначе анализ считал бы их неизменной константой / читал бы
// «до инициализации»). Число выходов — в размер_массива, входов — в размер_массива_2.
static void анализ_асм(Анализатор *а, Узел *узел)
{
    if (а->глубина_небезопасно == 0) {
        ошибка_семантики(а, &узел->токен,
            "«асм(…)» допустима только внутри «небезопасно { }» "
            "(ассемблер — сырой доступ к регистрам/памяти)");
        return;
    }
    long выходов = узел->размер_массива;
    for (size_t i = 0; i < узел_число_детей(узел); ++i) {
        Узел *реб = узел_ребёнок(узел, i);
        if (!реб || реб->тип != УЗЕЛ_АСМ_ОПЕРАНД) continue;  // порча-строки пропускаем
        Узел *выр = узел_число_детей(реб) > 0 ? узел_ребёнок(реб, 0) : nullptr;
        if (!выр) continue;
        // Выходной операнд — сначала помечаем инициализированным (asm его ЗАПИШЕТ),
        // чтобы типизация lvalue не ругалась на «использование до инициализации».
        int это_выход = (long)i < выходов;
        if (это_выход && выр->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
            Символ *с = найти_символ(а, выр->токен.начало, выр->токен.длина);
            if (с) { с->инициализирована = 1; пометить_изменяемой(а, &выр->токен); }
        }
        типизировать_выражение(а, выр);
    }
}

static void анализ_оператора(Анализатор *а, Узел *узел)
{
    if (!узел || а->диаг->ошибка) return;

    switch (узел->тип) {
        case УЗЕЛ_ЕСЛИ:
            анализ_если(а, узел);
            break;

        case УЗЕЛ_СЛУШАТЬ:
            анализ_слушать(а, узел);
            break;

        case УЗЕЛ_СЛУШАТЕЛЬ_ЭКЗ:
            // Экземпляры собраны пред-проходом (собрать_экземпляры_слушателей);
            // здесь ничего не делаем (в C — статический литерал через кодоген).
            break;

        case УЗЕЛ_ВЫБОР:
            анализ_выбор(а, узел);
            break;

        case УЗЕЛ_ПОКА:
            анализ_пока(а, узел);
            break;

        case УЗЕЛ_ДЛЯ:
            анализ_для(а, узел);
            break;

        case УЗЕЛ_ДЛЯ_КАЖДОГО:
            анализ_для_каждого(а, узел);
            break;

        case УЗЕЛ_ПРЕРВАТЬ:
            if (а->глубина_цикла == 0)
                ошибка_семантики(а, &узел->токен,
                    "«прервать» вне цикла");
            break;

        case УЗЕЛ_ПРОДОЛЖИТЬ:
            if (а->глубина_цикла == 0)
                ошибка_семантики(а, &узел->токен,
                    "«продолжить» вне цикла");
            break;

        case УЗЕЛ_ВОЗВРАТ: {
            // Все «вывод»-параметры обязаны быть присвоены до этого возврата.
            проверить_вывод_присвоен(а, &узел->токен);
            // Функция «ничего» (void) не возвращает значение: «вернуть выр» в ней —
            // ошибка (в C это несовместимость типа возврата).
            if (а->тип_возврата == ТОКЕН_НИЧЕГО && узел_число_детей(узел) > 0) {
                ошибка_семантики(а, &узел->токен,
                    "функция типа «ничего» не может возвращать значение");
                break;
            }
            if (узел_число_детей(узел) > 0) {
                Узел *выр = узел_ребёнок(узел, 0);
                ИнфоТипа тип_выр = типизировать_выражение(а, выр);
                if (а->диаг->ошибка) break;

                ИнфоТипа тип_рет = {
                    а->тип_возврата,
                    а->указатели_возврата,
                    а->беззнаковый_возврата,
                    а->срез_возврата,
                    а->индекс_структуры_возврата
                };
                // F-строка в возврате — ВСЕГДА ошибка: её буфер на стеке ЭТОЙ
                // функции, умирает при возврате (dangling) независимо от
                // классификации.
                if (выр->тип == УЗЕЛ_F_СТРОКА
                    && тип_рет.срез && тип_рет.тип == ТОКЕН_ТИП_СИМВОЛ
                    && тип_рет.указатели == 0) {
                    ошибка_семантики(а, &выр->токен,
                        "нельзя вернуть f-строку как «срез<символ>»: её буфер "
                        "живёт на стеке ЭТОЙ функции и умирает при возврате. "
                        "Верните владеющую строку («срез<символ> с = выделить(N); "
                        "…; вернуть с»)");
                    break;
                }
                // §42: заимствованный ВИД среза «s[a:b]» напрямую вернуть нельзя —
                // его владение на call-site статически неизвестно (вызывающий не
                // знал бы, освобождать ли). Для подстроки-возврата сделайте
                // владеющую копию отдельным объявлением, затем верните её.
                if (выр->тип == УЗЕЛ_СРЕЗ_ДИАПАЗОН) {
                    ошибка_семантики(а, &выр->токен,
                        "нельзя вернуть заимствованный вид среза «[a:b]» напрямую: "
                        "сделайте владеющую копию и верните её "
                        "(«строка т = клон(s[a:b]); … вернуть т»)");
                    break;
                }
                // Возврат «вернуть "литерал"» → срез<символ> (§37 п.6): литерал
                // ЗАИМСТВОВАН (над .rodata, живёт бесконечно). Пред-проход
                // «вывести_владение_возврата» уже классифицировал ЭТУ функцию:
                //  • заимствует-возврат (все возвраты — литералы/borrow) → ОК:
                //    метим литерал как срез (кодоген выдаст (Срез){лит,sizeof-1}),
                //    на call-site результат НЕ регистрируется в autofree;
                //  • смешанный (есть и владеющий возврат) → ошибка: вызывающий
                //    делает ОДНО статическое решение об autofree, поэтому функция
                //    обязана возвращать единообразно. Ноль рантайма — копию не
                //    навязываем; программист явно делает ветки одинаковыми.
                if (выр->тип == УЗЕЛ_СТРОКА
                    && тип_рет.срез && тип_рет.тип == ТОКЕН_ТИП_СИМВОЛ
                    && тип_рет.указатели == 0) {
                    if (а->возврат_заимствован_текущей) {
                        выр->срез = 1;  // кодоген: эмитить как заимствованный срез
                        break;          // тип совместим по построению — дальше не идём
                    }
                    ошибка_семантики(а, &выр->токен,
                        "функция возвращает и ВЛАДЕЮЩИЙ, и ЗАИМСТВОВАННЫЙ срез — "
                        "нужно единообразно (вызывающий делает одно решение об "
                        "освобождении). Сделайте владеющую строку и в этой ветке "
                        "(«срез<символ> с = выделить(N); …; вернуть с») ИЛИ верните "
                        "литерал во всех ветках");
                    break;
                }
                if (тип_рет.тип != ТОКЕН_НЕИЗВЕСТНЫЙ
                    && тип_выр.тип != ТОКЕН_НЕИЗВЕСТНЫЙ
                    && !совместимы_для_присваивания(тип_рет, тип_выр)) {
                    char тф[64], тв[64];
                    описание_типа(тип_рет, тф, sizeof(тф));
                    описание_типа(тип_выр, тв, sizeof(тв));
                    char msg[256];
                    snprintf(msg, sizeof(msg),
                             "несовместимый тип возврата: функция возвращает «%s», выражение «%s»",
                             тф, тв);
                    ошибка_семантики(а, &выр->токен, msg);
                    break;
                }

                // Безопасность указательного возврата: вернуть можно только
                // указатель на память, которая переживёт возврат и принадлежит
                // вызывающему/статике (borrow) — параметр, «аргументы», строковый
                // литерал, «нуль» или их индексация. Возврат указателя на локальные
                // данные, результата C-функции или неизвестного происхождения —
                // ошибка: иначе висячий указатель или ручное управление памятью.
                // Проверяем ВСЕГДА (в т.ч. при неизвестном типе выражения —
                // напр. прямой «вернуть strchr(…)»: тип результата C-функции
                // неизвестен, но происхождение всё равно небезопасно).
                if (а->указатели_возврата > 0 && !а->срез_возврата
                    && !выражение_безопасно_для_возврата(а, выр)) {
                    ошибка_семантики(а, &выр->токен,
                        "нельзя вернуть этот указатель: его память не переживёт "
                        "возврат (локальные данные / результат C-функции / "
                        "неизвестное происхождение). Безопасно вернуть можно "
                        "указатель-параметр, «аргументы», строковый литерал или «нуль»");
                    break;
                }

                // Возврат среза = передача владения вызывающему. Возвращать можно
                // только то, чем владеем: заимствованный (параметр) срез вернуть
                // нельзя — иначе вызывающий получил бы чужое владение (double-free).
                if (а->срез_возврата && выр->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                    Символ *с = найти_символ(а, выр->токен.начало, выр->токен.длина);
                    if (с && с->срез && !с->владеет_срезом) {
                        char msg[256];
                        snprintf(msg, sizeof(msg),
                            "нельзя вернуть заимствованный срез «%.*s»: "
                            "функция не владеет им",
                            (int)выр->токен.длина, выр->токен.начало);
                        ошибка_семантики(а, &выр->токен, msg);
                        break;
                    }
                    // Кастомный аллокатор не переносится через сигнатуру возврата →
                    // вызывающий освободил бы срез дефолтным free (v1: запрет).
                    if (с && с->аллокатор.длина > 0) {
                        ошибка_семантики(а, &выр->токен,
                            "срез<T> в Имя нельзя вернуть из функции (v1): аннотация "
                            "аллокатора не переносится через границу — освободите его "
                            "в этой же области");
                        break;
                    }
                    // Владение уходит наружу — источник больше не используется.
                    if (с) { с->перемещён = 1; с->токен_move = выр->токен; }
                }
            }
            break;
        }

        case УЗЕЛ_ОБЪЯВЛЕНИЕ: {
            long значение = 0;
            int значение_известно = 0;
            int длина_известна = 0;
            long длина_среза = 0;
            int длина_из_переменной_новая = 0;   // «выделить(н)»: длина == «н»
            Токен длина_токен_новый = { 0 };
            int владеет_новый = 0;  // объявляемый срез становится владельцем
            int поток_новый = 0;    // объявляемая переменная — дескриптор потока
            int строка_литерал_срез = 0;  // «срез<символ> с = "лит"» (borrow .rodata)
            int индекс_стр = -1;

            // «атом<T>» имеет смысл только как ГЛОБАЛ (разделяемое состояние);
            // локальный атомик бесполезен (нечего разделять) и здесь запрещён.
            if (узел->атом) {
                ошибка_семантики(а, &узел->токен,
                    "«атом<T>» допустим только как глобал верхнего уровня "
                    "(локальный атомик бессмыслен — разделять нечего)");
                break;
            }
            // «буфер<T>» v1: элемент — примитив/указатель (не структура). Структура-
            // элемент требовала бы протаскивать имя типа в «добавить»/«перевыделить»
            // и поэлементную деструкцию при сжатии (как срез<структура> §22/§53) —
            // отложено. Дадим понятную ошибку вместо битого C.
            if (узел->буфер && узел->тип_данных == ТОКЕН_СТРУКТУРА) {
                ошибка_семантики(а, &узел->токен,
                    "«буфер<структура>» пока не поддержан (v1): элемент буфера — "
                    "примитив или указатель; для структур используйте срез<T>");
                break;
            }

            // «выровнять(N)» (C23 alignas): N — положительная степень двойки
            // (требование C для alignas). Проверяем здесь — понятная ошибка Konda
            // вместо более позднего диагноза C-компилятора.
            if (узел->выравнивание != 0
                && (узел->выравнивание <= 0
                    || (узел->выравнивание & (узел->выравнивание - 1)) != 0)) {
                char msg[160];
                snprintf(msg, sizeof(msg),
                    "«выровнять(%ld)»: выравнивание должно быть положительной "
                    "степенью двойки (1, 2, 4, 8, 16, …)", узел->выравнивание);
                ошибка_семантики(а, &узел->токен, msg);
                break;
            }

            // «имя[]» (выводимый размер) допустим ТОЛЬКО с инициализатором
            // «встроить(…)»: иначе размер неоткуда взять. Ловим здесь понятной
            // ошибкой (без инициализатора или с обычным литералом).
            if (узел->выводимый_размер) {
                Узел *и0 = узел_число_детей(узел) > 0 ? узел_ребёнок(узел, 0) : nullptr;
                if (!и0 || и0->тип != УЗЕЛ_ВСТРОИТЬ) {
                    ошибка_семантики(а, &узел->токен,
                        "массив с пустыми «[]» (выводимый размер) допустим только с "
                        "инициализатором «встроить(\"файл\")»; иначе укажите размер «[N]»");
                    break;
                }
            }

            // Переменная-указатель на функцию: «БинарОп оп [= функ | нуль]».
            // Инициализатор — имя подходящей функции (сверяем сигнатуру),
            // указатель того же типа, или «нуль». Без инициализатора — нулевой.
            if (узел->тип_данных == ТОКЕН_ФУНКУКАЗАТЕЛЬ) {
                int idx = найти_индекс_типфункции(а, &узел->имя_типа);
                if (idx < 0) {
                    char msg[256];
                    snprintf(msg, sizeof msg,
                        "неизвестный тип-указатель на функцию «%.*s»",
                        (int)узел->имя_типа.длина, узел->имя_типа.начало);
                    ошибка_семантики(а, &узел->имя_типа, msg);
                    break;
                }
                int может_нуль = 1;
                if (узел_число_детей(узел) > 0) {
                    Узел *инит = узел_ребёнок(узел, 0);
                    if (инит->тип == УЗЕЛ_НУЛЬ) {
                        может_нуль = 1;
                    } else if (инит->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                        СигнатураФункции *сф = найти_сигнатуру_по_имени(а,
                            инит->токен.начало, инит->токен.длина);
                        Символ *ис = найти_символ(а, инит->токен.начало,
                                                  инит->токен.длина);
                        if (сф && сигнатура_совпадает_с_типфункцией(сф,
                                &а->типыфункций[idx])) {
                            может_нуль = 0;  // присвоена конкретная функция
                        } else if (сф) {
                            ошибка_семантики(а, &инит->токен,
                                "сигнатура функции не совпадает с типом-указателем");
                            break;
                        } else if (ис && ис->тип == ТОКЕН_ФУНКУКАЗАТЕЛЬ
                                   && ис->индекс_структуры == idx) {
                            может_нуль = ис->может_быть_нуль;  // копия указателя
                        } else {
                            ошибка_семантики(а, &инит->токен,
                                "инициализатор указателя на функцию — имя "
                                "подходящей функции, указатель того же типа или «нуль»");
                            break;
                        }
                    } else {
                        // Инициализатор — ВЫРАЖЕНИЕ, дающее указатель на функцию:
                        // доступ к полю «т[i].функ», элемент массива, копия
                        // (диспетч-таблицы). Принимаем при совпадении сигнатуры.
                        ИнфоТипа ти = типизировать_выражение(а, инит);
                        if (а->диаг->ошибка) break;
                        if (ти.тип == ТОКЕН_ФУНКУКАЗАТЕЛЬ && ти.индекс_структуры >= 0
                            && типфункции_совместимы(
                                   &а->типыфункций[ти.индекс_структуры],
                                   &а->типыфункций[idx])) {
                            может_нуль = 0;  // из поля/элемента — ненулевой (borrow)
                        } else {
                            ошибка_семантики(а, &инит->токен,
                                "инициализатор указателя на функцию — имя функции, "
                                "указатель/поле того же типа или «нуль»");
                            break;
                        }
                    }
                }
                объявить_символ(а, узел->токен.начало, узел->токен.длина,
                    ТОКЕН_ФУНКУКАЗАТЕЛЬ, 0, 0, 0, 0, 0, 0, &узел->токен, 0, 0);
                Символ *с = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (с) {
                    с->индекс_структуры = idx;
                    с->может_быть_нуль = может_нуль;
                    с->инициализирована = 1;
                    с->неизменяемый = узел->неизменяемый;
                }
                break;
            }

            // «Ящик<T>» — одиночный владеющий heap-объект. Внутри указатель на T
            // (указатели≥1), но ВЛАДЕЮЩИЙ: конструируется «выделить()» (без арг),
            // move как у среза, autofree делает free. Обрабатываем ДО веток
            // структуры/среза (у него тип_данных структуры и указатели, но своя
            // семантика владения).
            // «срез<T> в Имя»: кастомный аллокатор для среза — имя должно быть
            // объявлено. Владение и autofree — та же машинерия, что у обычного
            // среза; отличается лишь функция выделения/освобождения (кодоген).
            if (узел->срез && узел->аллокатор.длина > 0
                && !найти_аллокатор(а, &узел->аллокатор)) {
                ошибка_семантики(а, &узел->аллокатор,
                    "неизвестный аллокатор (объявите «аллокатор Имя { … }»)");
                break;
            }
            if (узел->ящик) {
                // Кастомный аллокатор «Ящик<T> в Имя»: имя должно быть объявлено.
                if (узел->аллокатор.длина > 0 && !найти_аллокатор(а, &узел->аллокатор)) {
                    ошибка_семантики(а, &узел->аллокатор,
                        "неизвестный аллокатор (объявите «аллокатор Имя { … }»)");
                    break;
                }
                int инд_я = найти_индекс_структуры(а, &узел->имя_типа);
                if (узел->тип_данных != ТОКЕН_СТРУКТУРА || инд_я < 0) {
                    ошибка_семантики(а, &узел->токен,
                        "«Ящик<T>»: T — известная структура (v1: примитивы/"
                        "указатели-содержимое пока не поддержаны)");
                    break;
                }
                // Транзитивная деструкция (Задача 7) не реализована: free(box)
                // освобождает саму структуру, но НЕ её владеющие поля (срез/
                // деструктор) → утечка. Такой Ящик отвергаем.
                if (структура_индекс_нужна_деструкция(а, инд_я, 0)) {
                    ошибка_семантики(а, &узел->токен,
                        "«Ящик<структуры с владеющими полями>» пока не поддержан: "
                        "free не вызывает деструкторы полей (была бы утечка)");
                    break;
                }
                int влад_box = 0;   // получатель становится владельцем
                if (узел_число_детей(узел) > 0) {
                    Узел *ин = узел_ребёнок(узел, 0);
                    if (это_выделить(ин)) {
                        if (узел_число_детей(ин) != 0) {
                            ошибка_семантики(а, &ин->токен,
                                "«Ящик<T> б = выделить()» — без аргументов "
                                "(одиночный объект); для массива нужен «срез<T>»");
                            break;
                        }
                        влад_box = 1;
                    } else if (ин->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                        // Move из другого Ящика того же типа.
                        Символ *ист = найти_символ(а, ин->токен.начало,
                                                    ин->токен.длина);
                        if (!ист || !ист->ящик || ист->индекс_структуры != инд_я) {
                            ошибка_семантики(а, &ин->токен,
                                "инициализатор «Ящик<T>» — «выделить()» или Ящик "
                                "того же типа (перемещение)");
                            break;
                        }
                        // Аллокатор — часть идентичности типа: move разрешён только
                        // между одним и тем же аллокатором (иначе autofree
                        // получателя освободил бы память НЕ тем аллокатором →
                        // порча). Оба пустые (дефолт) — тоже совпадают.
                        if (ист->аллокатор.длина != узел->аллокатор.длина
                            || (узел->аллокатор.длина > 0
                                && memcmp(ист->аллокатор.начало, узел->аллокатор.начало,
                                          узел->аллокатор.длина) != 0)) {
                            ошибка_семантики(а, &ин->токен,
                                "перемещение «Ящик» между разными аллокаторами "
                                "запрещено (освобождение не тем аллокатором)");
                            break;
                        }
                        if (ист->глубина < а->глубина && а->глубина_цикла > 0) {
                            ошибка_семантики(а, &ин->токен,
                                "перемещение «Ящик» из объемлющей области внутри "
                                "цикла запрещено (на втором витке источник пуст)");
                            break;
                        }
                        ист->перемещён = 1;
                        ист->токен_move = ин->токен;
                        влад_box = 1;
                    } else {
                        ошибка_семантики(а, &узел->токен,
                            "инициализатор «Ящик<T>» — «выделить()» или Ящик того "
                            "же типа (перемещение)");
                        break;
                    }
                } else {
                    ошибка_семантики(а, &узел->токен,
                        "«Ящик<T>» требует инициализатор «= выделить()»");
                    break;
                }
                объявить_символ(а, узел->токен.начало, узел->токен.длина,
                    ТОКЕН_СТРУКТУРА, узел->указатели, 0, 0, 0, 0, 0,
                    &узел->токен, 0, 0);
                Символ *сб = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (сб) {
                    сб->ящик = 1;
                    сб->индекс_структуры = инд_я;
                    сб->владеет_срезом = влад_box;  // autofree через ту же машинерию
                    сб->может_быть_нуль = 0;         // Ящик всегда размещён
                    сб->инициализирована = 1;
                    сб->неизменяемый = узел->неизменяемый;
                    сб->аллокатор = узел->аллокатор;  // кастомный аллокатор (или пусто)
                }
                break;
            }

            // Тип-структура: проверяем существование и (для не-указателя)
            // объявляем переменную; инициализатор пока не поддерживается.
            // «срез<структура>»/«срез<структура*>» сюда НЕ попадают (узел->срез):
            // у среза тип_данных == ТОКЕН_СТРУКТУРА тоже, но это элемент, а не
            // переменная-структура — обработку ведёт срезовая ветка ниже.
            if (узел->тип_данных == ТОКЕН_СТРУКТУРА && !узел->срез) {
                индекс_стр = найти_индекс_структуры(а, &узел->имя_типа);
                if (индекс_стр < 0) {
                    char msg[256];
                    snprintf(msg, sizeof(msg), "неизвестная структура «%.*s»",
                             (int)узел->имя_типа.длина, узел->имя_типа.начало);
                    ошибка_семантики(а, &узел->имя_типа, msg);
                    break;
                }
                // «внешний тип» непрозрачен: размер неизвестен даже C-стороне
                // Konda, значение по месту не создать — только указатель.
                if (а->структуры[индекс_стр].внешний && узел->указатели == 0) {
                    char msg[256];
                    snprintf(msg, sizeof(msg),
                             "«%.*s» — внешний тип: его устройство скрыто в C, "
                             "переменная возможна только как указатель «%.*s*»",
                             (int)узел->имя_типа.длина, узел->имя_типа.начало,
                             (int)узел->имя_типа.длина, узел->имя_типа.начало);
                    ошибка_семантики(а, &узел->имя_типа, msg);
                    break;
                }
                // Массив структур «Точка пс[N]»: индексация/поле через ту же
                // машинерию, что примитивные массивы (границы) + индекс типа
                // элемента. §1 (Задача 7): элемент МОЖЕТ владеть ресурсом
                // (срез/деструктор) — кодоген при выходе из области эмитит цикл
                // поэлементной деструкции (память массива на стеке занулена
                // «= {0}» / хвостом частичного литерала → free(NULL) безопасен).
                // Инициализатор — литерал массива структур «{ {…}, {…} }»,
                // проверяется общей веткой массива-литерала ниже.
                if (узел->массив && узел->указатели == 0) {
                    // Литерал массива структур — «{ {…}, {…}, … }». Каждый
                    // элемент — литерал полей структуры (для 2D — литерал
                    // МАССИВА струк-литералов). Глубокая проверка полей идёт
                    // общей веткой struct-литерала; здесь минимум-контроль.
                    if (узел_число_детей(узел) > 0) {
                        Узел *инит = узел_ребёнок(узел, 0);
                        if (инит->тип != УЗЕЛ_ЛИТЕРАЛ_МАССИВА) {
                            ошибка_семантики(а, &узел->токен,
                                "инициализатор массива структур — литерал «{ {…}, … }»");
                            break;
                        }
                        if ((long)узел_число_детей(инит) > узел->размер_массива) {
                            ошибка_семантики(а, &узел->токен,
                                "слишком много инициализаторов для массива структур");
                            break;
                        }
                        int сбой = 0;
                        long M = узел->размер_массива_2;
                        for (size_t i = 0; i < узел_число_детей(инит); ++i) {
                            Узел *элем = узел_ребёнок(инит, i);
                            if (M > 0) {
                                // 2D: элемент — литерал массива, содержащий
                                // М struct-литералов (недостаток — C занулит).
                                if (элем->тип != УЗЕЛ_ЛИТЕРАЛ_МАССИВА) {
                                    ошибка_семантики(а, &элем->токен,
                                        "строка 2D-массива структур — литерал «{ {…}, … }»");
                                    сбой = 1; break;
                                }
                                if ((long)узел_число_детей(элем) > M) {
                                    ошибка_семантики(а, &элем->токен,
                                        "слишком много инициализаторов в строке 2D-массива");
                                    сбой = 1; break;
                                }
                                for (size_t k = 0; k < узел_число_детей(элем); ++k) {
                                    if (узел_ребёнок(элем, k)->тип != УЗЕЛ_ЛИТЕРАЛ_СТРУКТУРЫ) {
                                        ошибка_семантики(а, &узел_ребёнок(элем, k)->токен,
                                            "элемент массива структур — литерал полей «{ … }»");
                                        сбой = 1; break;
                                    }
                                }
                                if (сбой) break;
                            } else {
                                if (элем->тип != УЗЕЛ_ЛИТЕРАЛ_СТРУКТУРЫ) {
                                    ошибка_семантики(а, &элем->токен,
                                        "элемент массива структур — литерал полей «{ … }»");
                                    сбой = 1; break;
                                }
                            }
                        }
                        if (сбой) break;
                    }
                    объявить_символ(а, узел->токен.начало, узел->токен.длина,
                        ТОКЕН_СТРУКТУРА, 0, /*массив=*/1, 0, 0,
                        /*длина_известна=*/1, /*длина=*/узел->размер_массива,
                        &узел->токен, 0, 0);
                    Символ *нм = найти_символ(а, узел->токен.начало, узел->токен.длина);
                    if (нм) {
                        нм->индекс_структуры = индекс_стр;
                        // 2D: длина_2 → для «м[i][j].поле».
                        if (узел->размер_массива_2 > 0)
                            нм->длина_2 = узел->размер_массива_2;
                    }
                    break;
                }

                // Инициализатор — литерал полей «{ поле = выражение, … }» либо
                // выражение-структура того же типа (вызов функции, другая
                // переменная-структура, доступ к полю-структуре): последнее —
                // обычное копирование значения. Копию разрешаем, только если
                // структуре НЕ нужна деструкция; иначе скопировался бы дескриптор
                // владения (срез/деструктор) и оба экземпляра освободили бы одну
                // память (double-free). Функция, возвращающая структуру, уже
                // гарантированно не требует деструкции (проверка в анализ_функции).
                if (узел_число_детей(узел) > 0) {
                    Узел *лит = узел_ребёнок(узел, 0);
                    if (лит->тип != УЗЕЛ_ЛИТЕРАЛ_СТРУКТУРЫ) {
                        if (узел->указатели > 0) {
                            // «Структура* п = выражение» — законно, если тип
                            // выражения — указатель на ТУ ЖЕ структуру той же
                            // косвенности (например, возврат «внешней»
                            // C-функции: холст* х = холст_создать(640)).
                            ИнфоТипа т_ист = типизировать_выражение(а, лит);
                            if (а->диаг->ошибка) break;
                            // «возможно<Структура*> п = нуль» — nullable-указатель
                            // на структуру/«внешний тип». Обычный «Структура* п»
                            // (не возможно) нуль не принимает — non-null по умолч.
                            int инит_нуль = (т_ист.тип == ТОКЕН_НУЛ_УКАЗАТЕЛЬ);
                            // «может быть нулём» шире литерала «нуль»: сюда же —
                            // несужённая «возможно»-переменная и вызов функции с
                            // возвратом «возможно<T*>». Без учёта вызова была дыра:
                            // «возможно<Узел*> п = найти(5)» (найти → возможно)
                            // считался ненулевым и дереферился без охранника.
                            int инит_может_нуль = выражение_может_быть_нуль(а, лит);
                            if (инит_может_нуль && !узел->возможно) {
                                ошибка_семантики(а, &узел->токен, инит_нуль
                                    ? "указатель ненулевой по умолчанию: «нуль» ему "
                                      "присвоить нельзя — объявите «возможно<T*>» "
                                      "для nullable-указателя"
                                    : "nullable-значение нельзя присвоить ненулевому "
                                      "указателю на структуру: сузьте под охранником "
                                      "«если (x != нуль)» или объявите «возможно<T*>»");
                                break;
                            }
                            if (!инит_нуль
                                && (т_ист.тип != ТОКЕН_СТРУКТУРА
                                    || т_ист.указатели != узел->указатели
                                    || т_ист.индекс_структуры != индекс_стр)) {
                                ошибка_семантики(а, &узел->токен,
                                    "инициализатор указателя на структуру должен "
                                    "быть указателем на ту же структуру той же "
                                    "косвенности");
                                break;
                            }
                            объявить_символ(а, узел->токен.начало,
                                узел->токен.длина, ТОКЕН_СТРУКТУРА,
                                узел->указатели, 0, 0, 0, 0, 0, &узел->токен,
                                0, 0);
                            Символ *ук = найти_символ(а, узел->токен.начало,
                                                      узел->токен.длина);
                            if (ук) {
                                ук->индекс_структуры = индекс_стр;
                                ук->возможно = узел->возможно;
                                ук->может_быть_нуль = узел->возможно && инит_может_нуль;
                            }
                            break;
                        }
                        ИнфоТипа тип_ист = типизировать_выражение(а, лит);
                        if (а->диаг->ошибка) break;
                        ИнфоТипа тип_цель = { ТОКЕН_СТРУКТУРА, 0, 0, 0, индекс_стр };
                        if (!совместимы_для_присваивания(тип_цель, тип_ист)) {
                            ошибка_семантики(а, &узел->токен,
                                "несовместимый тип инициализатора структуры "
                                "(ожидалась структура этого типа, литерал полей "
                                "«{ … }» или вызов функции)");
                            break;
                        }
                        if (структура_с_деструктором(а, тип_ист)) {
                            ошибка_семантики(а, &узел->токен,
                                "нельзя копировать структуру, которой нужна "
                                "деструкция (владеет срезом/имеет деструктор): "
                                "копия привела бы к двойному освобождению");
                            break;
                        }
                        объявить_символ(а, узел->токен.начало, узел->токен.длина,
                            ТОКЕН_СТРУКТУРА, 0, 0, 0, 0, 0, 0, &узел->токен, 0, 0);
                        Символ *нов = найти_символ(а, узел->токен.начало, узел->токен.длина);
                        if (нов) нов->индекс_структуры = индекс_стр;
                        break;
                    }
                    if (узел->указатели > 0) {
                        ошибка_семантики(а, &узел->токен,
                            "литералом инициализируется только сама структура, "
                            "не указатель на неё");
                        break;
                    }
                    ОписаниеСтруктуры *оп = &а->структуры[индекс_стр];
                    int был_сбой = 0;
                    for (size_t i = 0; i < узел_число_детей(лит); ++i) {
                        Узел *иниц = узел_ребёнок(лит, i);
                        // Позиционный элемент (токен пуст) сопоставляется полю по
                        // индексу; именованный — по имени.
                        ПолеСтруктуры *поле = nullptr;
                        if (иниц->токен.длина == 0) {
                            if (i >= оп->число_полей) {
                                char msg[256];
                                snprintf(msg, sizeof(msg),
                                    "у структуры «%s» %zu полей, а значений в "
                                    "литерале больше", оп->имя, оп->число_полей);
                                ошибка_семантики(а, &иниц->токен, msg);
                                был_сбой = 1;
                                break;
                            }
                            поле = &оп->поля[i];
                        } else {
                            for (size_t j = 0; j < оп->число_полей; ++j) {
                                if (байты_равны(оп->поля[j].имя, strlen(оп->поля[j].имя),
                                                иниц->токен.начало, иниц->токен.длина)) {
                                    поле = &оп->поля[j];
                                    break;
                                }
                            }
                        }
                        if (!поле) {
                            char msg[256];
                            snprintf(msg, sizeof(msg),
                                     "у структуры «%s» нет поля «%.*s»", оп->имя,
                                     (int)иниц->токен.длина, иниц->токен.начало);
                            ошибка_семантики(а, &иниц->токен, msg);
                            был_сбой = 1;
                            break;
                        }
                        Узел *знач_поля = узел_ребёнок(иниц, 0);
                        // Поле-срез: «выделить(N)»/«клон(x)» — структура становится
                        // владельцем (как «срез<T> имя = выделить(N)» для локальной
                        // переменной), поэтому типизируем аргумент напрямую, минуя
                        // общую типизацию выражения (которая эти встроенные вне
                        // объявления среза отклоняет как несуществующие функции).
                        if (поле->срез && (это_выделить(знач_поля) || это_клон(знач_поля))) {
                            if (узел_число_детей(знач_поля) != 1) {
                                ошибка_семантики(а, &знач_поля->токен,
                                    "встроенная функция принимает один аргумент");
                                был_сбой = 1;
                                break;
                            }
                            Узел *арг = узел_ребёнок(знач_поля, 0);
                            ИнфоТипа та = типизировать_выражение(а, арг);
                            if (а->диаг->ошибка) { был_сбой = 1; break; }
                            if (это_выделить(знач_поля)) {
                                if (та.тип != ТОКЕН_НЕИЗВЕСТНЫЙ && !тип_целочисленный(та)) {
                                    ошибка_семантики(а, &знач_поля->токен,
                                        "количество элементов в «выделить» должно быть целым");
                                    был_сбой = 1;
                                    break;
                                }
                                // Знаковость количества → кодогену (срез_выделить_бз).
                                арг->беззнаковый = та.беззнаковый;
                            } else if (!та.срез) {
                                ошибка_семантики(а, &знач_поля->токен,
                                    "«клон» применим только к срезу");
                                был_сбой = 1;
                                break;
                            }
                            continue;
                        }
                        if (поле->срез) {
                            ошибка_семантики(а, &знач_поля->токен,
                                "поле-срез инициализируется только «выделить(N)» "
                                "или «клон(x)» — структура становится владельцем");
                            был_сбой = 1;
                            break;
                        }
                        // Поле-указатель на функцию: значение — ИМЯ функции
                        // (совпадающей сигнатуры), «нуль» или выражение-указатель
                        // того же типа (диспетч-таблицы: «{ функ = привет }»).
                        if (поле->тип == ТОКЕН_ФУНКУКАЗАТЕЛЬ) {
                            if (знач_поля->тип == УЗЕЛ_НУЛЬ) continue;
                            if (знач_поля->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                                СигнатураФункции *сф = найти_сигнатуру_по_имени(а,
                                    знач_поля->токен.начало, знач_поля->токен.длина);
                                if (сф && поле->индекс_структуры >= 0
                                    && сигнатура_совпадает_с_типфункцией(сф,
                                           &а->типыфункций[поле->индекс_структуры]))
                                    continue;
                            }
                            ИнфоТипа тзф = типизировать_выражение(а, знач_поля);
                            if (!а->диаг->ошибка
                                && тзф.тип == ТОКЕН_ФУНКУКАЗАТЕЛЬ
                                && тзф.индекс_структуры >= 0
                                && поле->индекс_структуры >= 0
                                && типфункции_совместимы(
                                       &а->типыфункций[тзф.индекс_структуры],
                                       &а->типыфункций[поле->индекс_структуры]))
                                continue;
                            if (!а->диаг->ошибка)
                                ошибка_семантики(а, &знач_поля->токен,
                                    "значение поля-указателя на функцию — имя функции, "
                                    "указатель того же типа или «нуль»");
                            был_сбой = 1;
                            break;
                        }
                        ИнфоТипа тип_зн = типизировать_выражение(а, знач_поля);
                        if (а->диаг->ошибка) { был_сбой = 1; break; }
                        ИнфоТипа тип_поля = { поле->тип, поле->указатели,
                            поле->беззнаковый, поле->срез, поле->индекс_структуры };
                        if (!совместимы_для_присваивания(тип_поля, тип_зн)) {
                            char msg[256];
                            snprintf(msg, sizeof(msg),
                                     "несовместимый тип значения поля «%s»", поле->имя);
                            ошибка_семантики(а, &знач_поля->токен, msg);
                            был_сбой = 1;
                            break;
                        }
                        // Инициализация поля значением структуры, которой нужна
                        // деструкция (владеет срезом/имеет деструктор), скопировала
                        // бы дескриптор владения — и объемлющая структура, и
                        // источник освободили бы одну память (double-free). Тот же
                        // запрет, что для присваивания/передачи по значению.
                        if (структура_с_деструктором(а, тип_зн)) {
                            char msg[512];
                            snprintf(msg, sizeof(msg),
                                "поле «%s»: нельзя инициализировать значением "
                                "структуры, которой нужна деструкция (владеет "
                                "срезом/имеет деструктор) — копия дескриптора "
                                "владения привела бы к двойному освобождению",
                                поле->имя);
                            ошибка_семантики(а, &знач_поля->токен, msg);
                            был_сбой = 1;
                            break;
                        }
                    }
                    if (был_сбой) break;
                }
                объявить_символ(а, узел->токен.начало, узел->токен.длина,
                    ТОКЕН_СТРУКТУРА, узел->указатели, 0, 0, 0, 0, 0,
                    &узел->токен, 0, 0);
                Символ *нов = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (нов) {
                    нов->индекс_структуры = индекс_стр;
                    // Структура с деструктором (и не указатель) владеет ресурсом:
                    // autofree вызовет деструктор при выходе из области.
                    if (узел->указатели == 0
                        && структура_индекс_нужна_деструкция(а, индекс_стр, 0)) {
                        нов->владеет_срезом = 1;
                    }
                }
                break;
            }

            // Индекс типа-структуры/перечисления элемента (для «срез<Структура>»/
            // «срез<Структура*>» и обычных перечислений). Для примитивов — -1.
            int индекс_эл = -1;
            if (узел->тип_данных == ТОКЕН_СТРУКТУРА) {
                индекс_эл = найти_индекс_структуры(а, &узел->имя_типа);
                if (индекс_эл < 0) {
                    char msg[256];
                    snprintf(msg, sizeof(msg), "неизвестная структура «%.*s»",
                             (int)узел->имя_типа.длина, узел->имя_типа.начало);
                    ошибка_семантики(а, &узел->имя_типа, msg);
                    break;
                }
                // §1 (Задача 7): «срез<структура-с-владеющими-полями>» ТЕПЕРЬ
                // поддержан. срез_выделить использует calloc (элементы занулены),
                // а кодоген при выходе из области эмитит цикл поэлементной
                // деструкции (эмит_освобождение → эл_тип_деструкции) перед
                // free(.данные) — транзитивная деструкция реализована, утечки/
                // двойного освобождения нет. Для «срез<структура*>» (указатель)
                // деструкции элементов по-прежнему нет (заимствованные указатели).
            }
            ИнфоТипа тип_объявления = {
                узел->тип_данных, узел->указатели, узел->беззнаковый, узел->срез,
                узел->тип_данных == ТОКЕН_ПЕРЕЧИСЛЕНИЕ
                    ? найти_индекс_перечисления(а, &узел->имя_типа) : индекс_эл
            };
            if (узел->тип_данных == ТОКЕН_ПЕРЕЧИСЛЕНИЕ
                && тип_объявления.индекс_структуры < 0) {
                ошибка_семантики(а, &узел->токен, "неизвестное перечисление");
                break;
            }

            // Массив фиксированного размера «тип имя[N]»: длина известна сразу.
            if (узел->массив && узел->размер_массива > 0) {
                длина_известна = 1;
                длина_среза = узел->размер_массива;
            }

            // «статический срез» невозможен: инициализатор «выделить» — не
            // константа, а статическая длительность требует константного init.
            if (узел->статический && узел->срез) {
                ошибка_семантики(а, &узел->токен,
                    "статические срезы не поддерживаются: "
                    "статическая переменная требует константного инициализатора");
                break;
            }

            if (узел_число_детей(узел) > 0) {
                Узел *инит = узел_ребёнок(узел, 0);

                // «встроить("файл")» (C23 #embed): только как инициализатор
                // байтового массива с ВЫВОДИМЫМ размером — «неподписанный целое8
                // имя[] = встроить("путь")». Размер вычислит C-компилятор из
                // содержимого файла; типизировать нечего (это сырые байты).
                if (инит->тип == УЗЕЛ_ВСТРОИТЬ) {
                    if (!(узел->массив && узел->выводимый_размер)) {
                        ошибка_семантики(а, &узел->токен,
                            "«встроить(…)» допустимо только как инициализатор массива "
                            "с выводимым размером: «неподписанный целое8 имя[] = встроить(\"файл\")»");
                        break;
                    }
                    if (!(узел->тип_данных == ТОКЕН_ЦЕЛОЕ8 && узел->беззнаковый
                          && узел->указатели == 0 && !узел->срез)) {
                        ошибка_семантики(а, &узел->токен,
                            "тип элемента для «встроить(…)» должен быть «неподписанный целое8» "
                            "(файл встраивается как байты)");
                        break;
                    }
                    // Длина неизвестна транспилятору (выводит C) → индексация идёт
                    // через рантайм-проверку по sizeof. Всё ок, символ объявится ниже.
                }
                else
                // Массив фикс. размера + литерал значений: проверяем количество
                // (не больше размера; меньше — допустимо, остальное C занулит)
                // и совместимость типа каждого элемента с типом массива.
                if (узел->массив && инит->тип == УЗЕЛ_ЛИТЕРАЛ_МАССИВА) {
                    size_t n_иниц = узел_число_детей(инит);
                    if ((long)n_иниц > узел->размер_массива) {
                        char msg[256];
                        snprintf(msg, sizeof(msg),
                            "слишком много инициализаторов для массива «%.*s» "
                            "размера %ld (передано %zu)",
                            (int)узел->токен.длина, узел->токен.начало,
                            узел->размер_массива, n_иниц);
                        ошибка_семантики(а, &узел->токен, msg);
                        break;
                    }
                    ИнфоТипа тип_элемента = {
                        узел->тип_данных, узел->указатели, узел->беззнаковый, 0, -1
                    };
                    int был_сбой = 0;
                    for (size_t i = 0; i < n_иниц; ++i) {
                        Узел *эл = узел_ребёнок(инит, i);
                        ИнфоТипа тип_эл = типизировать_выражение(а, эл);
                        if (а->диаг->ошибка) { был_сбой = 1; break; }
                        if (!совместимы_для_присваивания(тип_элемента, тип_эл)) {
                            char тл[64], тп[64];
                            описание_типа(тип_элемента, тл, sizeof(тл));
                            описание_типа(тип_эл, тп, sizeof(тп));
                            char msg[256];
                            snprintf(msg, sizeof(msg),
                                "несовместимый тип элемента [%zu] массива «%.*s»: "
                                "«%s» ← «%s»",
                                i, (int)узел->токен.длина, узел->токен.начало,
                                тл, тп);
                            ошибка_семантики(а, &эл->токен, msg);
                            был_сбой = 1;
                            break;
                        }
                    }
                    if (был_сбой) break;
                } else
                // «поток<T> п = запустить(ф, арг)»: создание потока.
                // Модель — передача владения: поток получает данные по значению
                // или перемещением, поэтому разделяемого состояния нет и гонки
                // невозможны по построению (проверки статические).
                if (узел->поток) {
                    if (!это_запустить(инит)) {
                        ошибка_семантики(а, &узел->токен,
                            "«поток<T>» инициализируется только «запустить(функция, аргумент)»");
                        break;
                    }
                    if (узел_число_детей(инит) < 1 || узел_число_детей(инит) > 2) {
                        ошибка_семантики(а, &инит->токен,
                            "«запустить» принимает функцию и не более одного аргумента");
                        break;
                    }
                    Узел *фу = узел_ребёнок(инит, 0);
                    if (фу->тип != УЗЕЛ_ИДЕНТИФИКАТОР) {
                        ошибка_семантики(а, &инит->токен,
                            "первый аргумент «запустить» — имя функции потока");
                        break;
                    }
                    const СигнатураФункции *сиг =
                        найти_сигнатуру_по_имени(а, фу->токен.начало,
                                                  фу->токен.длина);
                    if (!сиг) {
                        ошибка_семантики(а, &фу->токен,
                            "неизвестная функция потока");
                        break;
                    }
                    if (!проверить_сигнатуру_потока(а, сиг, &инит->токен)) break;
                    size_t дано = узел_число_детей(инит) - 1;
                    if (дано != сиг->число_параметров) {
                        char msg[320];
                        snprintf(msg, sizeof msg,
                            "функция потока «%s» ожидает %zu аргумент(ов), передано %zu",
                            сиг->имя, сиг->число_параметров, дано);
                        ошибка_семантики(а, &инит->токен, msg);
                        break;
                    }
                    // Тип результата потока обязан совпасть с «поток<T>».
                    // §2: T может быть срезом («поток<срез<E>>»): совпасть должны
                    // и элемент (тип_возврата/беззнаковый), и флаг срез. Срез-
                    // результат маршалится как скаляр — дескриптор Срез лежит
                    // первым полем кадра, «присоединить» memcpy'ит sizeof(Срез).
                    if (сиг->тип_возврата != узел->тип_данных
                        || сиг->беззнаковый != узел->беззнаковый
                        || сиг->срез != узел->срез) {
                        ошибка_семантики(а, &узел->токен,
                            "тип результата функции не совпадает с «поток<T>»");
                        break;
                    }
                    // §2: срез-результат обязан быть ВЛАДЕЮЩИМ. Модель потоков —
                    // передача владения: результат переживает поток и переходит
                    // получателю (авто-join освобождает его .данные). Заимствующий
                    // срез (вид в .rodata/чужую память) сюда не годится: его стек-
                    // родитель уже мёртв, а освобождение .данные было бы неверным.
                    if (сиг->срез && сиг->возврат_заимствован) {
                        ошибка_семантики(а, &узел->токен,
                            "функция потока должна возвращать ВЛАДЕЮЩИЙ срез "
                            "(модель передачи владения): заимствующий-возврат срез "
                            "как результат потока не поддержан");
                        break;
                    }
                    if (дано == 1) {
                        Узел *арг = узел_ребёнок(инит, 1);
                        ИнфоТипа та = типизировать_выражение(а, арг);
                        if (а->диаг->ошибка) break;
                        const ИнфоПараметра *п0 = &сиг->параметры[0];
                        if (та.тип != ТОКЕН_НЕИЗВЕСТНЫЙ
                            && (та.тип != п0->тип || та.срез != п0->срез
                                || та.беззнаковый != п0->беззнаковый)) {
                            ошибка_семантики(а, &арг->токен,
                                "тип аргумента не совпадает с параметром функции потока");
                            break;
                        }
                        // Аргумент-срез перемещается в поток: у запускающего
                        // доступа больше нет (иначе была бы гонка за ту же
                        // память). Переиспользуем общий move-анализ.
                        if (п0->срез && сиг->владеет_параметра[0]
                            && арг->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                            Символ *са = найти_символ(а, арг->токен.начало,
                                                       арг->токен.длина);
                            if (са && са->владеет_срезом) {
                                са->перемещён = 1;
                                са->токен_move = арг->токен;
                            }
                        }
                    }
                    // Дескриптор, объявленный в цикле, авто-join'ится в конце
                    // ИТЕРАЦИИ (его область — тело цикла), поэтому потоки идут
                    // строго по очереди: код выглядит параллельным, компилируется
                    // и не ускоряет ничего. Присоединить его вне цикла нельзя —
                    // имя туда не видно, — значит ложных срабатываний нет.
                    if (а->глубина_цикла > 0) {
                        предупреждение_семантики(а, &узел->токен,
                            "поток объявлен в теле цикла: он присоединяется в конце "
                            "итерации, поэтому потоки выполняются последовательно "
                            "и ускорения нет; для параллелизма по данным используйте "
                            "«параллельно для»");
                    }
                    поток_новый = 1;
                } else
                // «срез<T> имя = выделить(N)»: спец-обработка инициализатора.
                if (узел->срез && это_выделить(инит)) {
                    if (узел_число_детей(инит) != 1) {
                        ошибка_семантики(а, &инит->токен,
                            "«выделить» принимает ровно один аргумент — количество элементов");
                        break;
                    }
                    Узел *кол = узел_ребёнок(инит, 0);
                    ИнфоТипа тип_кол = типизировать_выражение(а, кол);
                    if (а->диаг->ошибка) break;
                    if (тип_кол.тип != ТОКЕН_НЕИЗВЕСТНЫЙ && !тип_целочисленный(тип_кол)) {
                        ошибка_семантики(а, &инит->токен,
                            "количество элементов в «выделить» должно быть целым");
                        break;
                    }
                    // Кодогену нужна знаковость количества, чтобы выбрать вариант
                    // без знак-клампа (срез_выделить_бз): беззнаковое ≥ 0 всегда.
                    // Узел-идентификатор сам знаковость не несёт (только символ) —
                    // проставляем из выведенного типа.
                    кол->беззнаковый = тип_кол.беззнаковый;
                    // Если количество — константа И срез не переназначается
                    // позже, длину знаем на этапе компиляции (иначе после «д = e»
                    // сохранённая длина устарела бы — статическую длину не берём).
                    long n;
                    if (вычислить_константу(а, кол, &n)) {
                        if (n < 0) {
                            ошибка_семантики(а, &инит->токен,
                                "количество элементов в «выделить» не может быть отрицательным");
                            break;
                        }
                        // Статическая проверка переполнения размера: n * sizeof(T).
                        ИнфоТипа эл = { узел->тип_данных, узел->указатели,
                                        узел->беззнаковый, 0, -1 };
                        long эр = размер_типа(эл), всего;
                        if (эр > 0 && __builtin_mul_overflow(n, эр, &всего)) {
                            ошибка_семантики(а, &инит->токен,
                                "размер выделения переполняется (количество × размер элемента)");
                            break;
                        }
                        // Буфер: длина ИЗМЕНЯЕМА («добавить»/«перевыделить») —
                        // статическую длину не берём (b[i] всегда рантайм-проверка,
                        // иначе перевыделить-сжатие обмануло бы снятую проверку).
                        if (!узел->буфер
                            && !переменная_изменяемая(а, узел->токен.начало, узел->токен.длина)) {
                            длина_известна = 1;
                            длина_среза = n;
                        }
                    } else if (!узел->буфер && кол && кол->тип == УЗЕЛ_ИДЕНТИФИКАТОР
                               && !переменная_изменяемая(а, узел->токен.начало,
                                                          узел->токен.длина)) {
                        // Количество — простая переменная «н»: длина среза равна
                        // ЕЙ. Пока ни срез, ни «н» не переприсваивались, условие
                        // «и < н» доказывает границы так же, как «и < длина(с)»,
                        // и рантайм-проверку можно снять (нулевая цена вместо
                        // вызова с ветвью на abort в каждом доступе).
                        длина_из_переменной_новая = 1;
                        длина_токен_новый = кол->токен;
                    }
                    владеет_новый = 1;  // «выделить» создаёт владеющий срез
                } else if (узел->срез && это_клон(инит)) {
                    // «срез<T> б = клон(а)»: глубокая копия — новый владелец с
                    // собственными данными. Источник остаётся жив (не move).
                    if (узел_число_детей(инит) != 1) {
                        ошибка_семантики(а, &инит->токен,
                            "«клон» принимает ровно один аргумент — срез");
                        break;
                    }
                    Узел *арг = узел_ребёнок(инит, 0);
                    ИнфоТипа тип_арг = типизировать_выражение(а, арг);
                    if (а->диаг->ошибка) break;
                    if (!тип_арг.срез) {
                        ошибка_семантики(а, &инит->токен,
                            "«клон» применим только к срезу");
                        break;
                    }
                    if (тип_арг.тип != узел->тип_данных
                        || тип_арг.беззнаковый != узел->беззнаковый
                        || тип_арг.указатели != узел->указатели
                        || тип_арг.индекс_структуры != индекс_эл) {
                        ошибка_семантики(а, &узел->токен,
                            "тип элемента клона не совпадает с типом объявления");
                        break;
                    }
                    // Длина копии равна длине источника, если та известна.
                    if (арг->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                        Символ *ист = найти_символ(а, арг->токен.начало, арг->токен.длина);
                        if (ист && ист->длина_известна) {
                            длина_известна = 1;
                            длина_среза = ист->длина;
                        }
                    }
                    владеет_новый = 1;  // клон создаёт нового владельца
                } else if (узел->срез
                           && (инит->тип == УЗЕЛ_СТРОКА || инит->тип == УЗЕЛ_F_СТРОКА)
                           && узел->тип_данных == ТОКЕН_ТИП_СИМВОЛ
                           && узел->указатели == 0) {
                    // «срез<символ> с = "литерал"» / «= f"…\(x)…"»: заимствованный
                    // срез над .rodata (литерал) ИЛИ над стек-буфером текущей
                    // функции (f-строка). Оба НЕ владеют — autofree не трогает.
                    // Литерал: длина через sizeof(лит)-1, безопасен для возврата,
                    // .данные годна как C-строка (NUL сохранён). f-строка: длина
                    // от snprintf (клампится на sizeof буфера), .данные годна как
                    // C-строка (snprintf всегда пишет NUL), но НЕ безопасна для
                    // возврата (стек умрёт вместе с функцией — блокируется на
                    // сайте возврата). Типизацию выражения инициализатора
                    // (для сайд-эффектов проверки f-строки: типы вставок и т.п.)
                    // выполняем явно ниже — семантике этого хватает.
                    if (инит->тип == УЗЕЛ_F_СТРОКА) {
                        (void)типизировать_выражение(а, инит);
                        if (а->диаг->ошибка) break;
                    }
                    строка_литерал_срез = 1;
                    инит->срез = 1;  // кодогену: эмитить как срез, а не «"…"»
                } else {
                    ИнфоТипа тип_инит = типизировать_выражение(а, инит);
                    if (а->диаг->ошибка) break;

                    // Проверка совместимости типов.
                    if (!совместимы_для_присваивания(тип_объявления, тип_инит)) {
                        char тл[64], тп[64];
                        описание_типа(тип_объявления, тл, sizeof(тл));
                        описание_типа(тип_инит, тп, sizeof(тп));
                        char msg[256];
                        snprintf(msg, sizeof(msg),
                                 "несовместимые типы при объявлении «%.*s»: «%s» ← «%s»",
                                 (int)узел->токен.длина, узел->токен.начало, тл, тп);
                        ошибка_семантики(а, &узел->токен, msg);
                        break;
                    }

                    if (сужение_запрещено(а, тип_объявления, инит, тип_инит)) {
                        char тл[64], тп[64];
                        описание_типа(тип_объявления, тл, sizeof(тл));
                        описание_типа(тип_инит, тп, sizeof(тп));
                        char msg[400];
                        snprintf(msg, sizeof(msg),
                            "неявное сужение при объявлении «%.*s»: «%s» ← «%s» "
                            "теряет данные; используйте «как<%s>(…)»",
                            (int)узел->токен.длина, узел->токен.начало, тл, тп, тл);
                        ошибка_семантики(а, &узел->токен, msg);
                        break;
                    }

                    // Срез ← срез: получение владения. От срез-переменной это
                    // перемещение (move): источник становится недействительным.
                    // От вызова функции, возвращающей срез, — приём нового
                    // владения. Данные не копируются (только дескриптор).
                    if (узел->срез && инит->тип == УЗЕЛ_СРЕЗ_ДИАПАЗОН) {
                        // §42: «строка под = s[a:b]» — заимствованный ВИД. Получатель
                        // НЕ владеет памятью (владеет_новый остаётся 0 → autofree его
                        // не трогает); длина, как правило, рантайм (a/b — выражения).
                        // Аннотация аллокатора к виду неприменима (память чужая).
                        if (узел->аллокатор.длина > 0) {
                            ошибка_семантики(а, &узел->токен,
                                "«срез<T> в Имя» нельзя инициализировать видом «[a:b]» "
                                "(v1): вид заимствует чужую память — аллокатор к нему "
                                "неприменим");
                            break;
                        }
                    } else if (узел->срез) {
                        if (инит->тип == УЗЕЛ_ИДЕНТИФИКАТОР) {
                            Символ *ист = найти_символ(а, инит->токен.начало,
                                                       инит->токен.длина);
                            if (!ист || !ист->владеет_срезом) {
                                char msg[256];
                                snprintf(msg, sizeof(msg),
                                    "нельзя переместить «%.*s»: это заимствованный срез, "
                                    "владелец находится снаружи",
                                    (int)инит->токен.длина, инит->токен.начало);
                                ошибка_семантики(а, &инит->токен, msg);
                                break;
                            }
                            // В теле цикла move из объемлющей области запрещён
                            // (см. ту же проверку в УЗЕЛ_ПРИСВАИВАНИЕ).
                            if (ист->глубина < а->глубина && а->глубина_цикла > 0) {
                                ошибка_семантики(а, &инит->токен,
                                    "перемещение среза из объемлющей области "
                                    "внутри цикла запрещено (на втором витке "
                                    "источник уже перемещён)");
                                break;
                            }
                            // Аллокатор — часть идентичности типа: move разрешён
                            // только между тем же аллокатором (иначе autofree
                            // освободил бы данные НЕ тем аллокатором). Оба пустые
                            // (дефолт) тоже совпадают.
                            if (ист->аллокатор.длина != узел->аллокатор.длина
                                || (узел->аллокатор.длина > 0
                                    && memcmp(ист->аллокатор.начало,
                                              узел->аллокатор.начало,
                                              узел->аллокатор.длина) != 0)) {
                                ошибка_семантики(а, &инит->токен,
                                    "перемещение среза между разными аллокаторами "
                                    "запрещено (освобождение не тем аллокатором)");
                                break;
                            }
                            ист->перемещён = 1;   // источник недействителен после move
                            ист->токен_move = инит->токен;
                            // Длину переносим — статическая проверка/элиминация
                            // продолжат работать после перемещения.
                            if (ист->длина_известна) {
                                длина_известна = 1;
                                длина_среза = ист->длина;
                            }
                        } else if (инит->тип != УЗЕЛ_ВЫЗОВ) {
                            ошибка_семантики(а, &узел->токен,
                                "источником среза может быть срез-переменная или "
                                "вызов функции, возвращающей срез");
                            break;
                        } else if (узел->аллокатор.длина > 0) {
                            // Приём среза от функции: её возврат не несёт аннотации
                            // аллокатора → неизвестно, чем выделен. Освобождать
                            // кастомным аллокатором такой срез небезопасно.
                            ошибка_семантики(а, &узел->токен,
                                "срез<T> в Имя нельзя инициализировать вызовом функции "
                                "(v1): источник аллокатора неизвестен — используйте "
                                "«выделить»/«клон»");
                            break;
                        }
                        владеет_новый = 1;     // получатель становится владельцем
                    } else {
                        if (!переменная_изменяемая(а, узел->токен.начало, узел->токен.длина))
                            значение_известно = вычислить_константу(а, инит, &значение);

                        // Статическая переменная требует константного инициализатора
                        // (как в C: объект статической длительности). Допустимы также
                        // строковый литерал и «нуль».
                        if (узел->статический) {
                            long _к;
                            int конст = вычислить_константу(а, инит, &_к)
                                || инит->тип == УЗЕЛ_СТРОКА
                                || инит->тип == УЗЕЛ_НУЛЬ;
                            if (!конст) {
                                ошибка_семантики(а, &узел->токен,
                                    "инициализатор статической переменной должен быть "
                                    "константой");
                                break;
                            }
                        }
                    }
                }
            }

            // Константа-инициализатор скаляра вне диапазона объявленного
            // целого типа — ошибка (тихое усечение в C). Только сворачиваемые
            // в константу значения; переменные/выражения не трогаем.
            if (узел_число_детей(узел) > 0 && !узел->массив && !узел->срез
                && узел->указатели == 0 && узел->тип_данных != ТОКЕН_СТРУКТУРА) {
                long знач_к, лм, вм;
                if (вычислить_константу(а, узел_ребёнок(узел, 0), &знач_к)
                    && диапазон_целого(узел->тип_данных, узел->беззнаковый, &лм, &вм)
                    && (знач_к < лм || знач_к > вм)) {
                    char тип_оп[64];
                    ИнфоТипа ти = { узел->тип_данных, 0, узел->беззнаковый, 0, -1 };
                    описание_типа(ти, тип_оп, sizeof(тип_оп));
                    char msg[256];
                    snprintf(msg, sizeof(msg),
                        "константа %ld вне диапазона типа «%s» [%ld..%ld]",
                        знач_к, тип_оп, лм, вм);
                    ошибка_семантики(а, &узел->токен, msg);
                    break;
                }
            }

            объявить_символ(а,
                узел->токен.начало, узел->токен.длина,
                узел->тип_данных, узел->указатели, узел->массив,
                узел->беззнаковый, узел->срез, длина_известна, длина_среза,
                &узел->токен, значение_известно, значение);

            // Отметить нового владельца среза (после объявления символа).
            if (узел->срез && владеет_новый) {
                Символ *нов = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (нов) нов->владеет_срезом = 1;
            }
            // Растущий буфер: помечаем символ, чтобы «добавить»/«перевыделить»
            // приняли его 1-м аргументом, а приведение к «срез<T>» гейтилось.
            if (узел->буфер) {
                Символ *нов = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (нов) нов->буфер = 1;
            }
            // 2D-массив «T a[N][M]»: длина_2 = M на символе. Дальнейшая
            // индексация «a[i][j]» проверяет обе границы через эту пару.
            if (узел->массив && узел->размер_массива_2 > 0) {
                Символ *нов2 = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (нов2) нов2->длина_2 = узел->размер_массива_2;
            }

            // «срез<символ> с = "литерал"» / «= f"…"»: заимствованный срез.
            // НЕ владеет (autofree не применяется). Литерал → над .rodata: из
            // литерала (запись «с[i]=…» запрещена), безопасен для возврата,
            // с_нулем (NUL за длиной в .rodata). f-строка → над стек-буфером:
            // изменяемая (не из_литерала), НЕ безопасна для возврата (стек
            // умрёт вместе с функцией), но с_нулем (snprintf терминирует).
            if (строка_литерал_срез) {
                Узел *инит0 = узел_число_детей(узел) > 0 ? узел_ребёнок(узел, 0) : nullptr;
                int это_литерал = инит0 && инит0->тип == УЗЕЛ_СТРОКА;
                Символ *нов = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (нов) {
                    нов->владеет_срезом = 0;
                    нов->из_литерала = это_литерал;
                    нов->безопасен_для_возврата = это_литерал;
                    нов->с_нулем = 1;  // литерал и f-строка оба NUL-терминированы
                }
            }

            // Кастомный аллокатор среза: сохранить на символе (для autofree-хука
            // и проверки равенства при move — как у Ящик<T>).
            if (узел->срез && узел->аллокатор.длина > 0) {
                Символ *нов = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (нов) нов->аллокатор = узел->аллокатор;
            }

            // «срез<Структура>»/«срез<Структура*>»: символ несёт индекс типа
            // элемента, чтобы доступ «с[i]» вернул структуру (для «с[i].поле»),
            // а кодоген знал имя типа для каста (через таблицу структур).
            if (узел->срез && индекс_эл >= 0) {
                Символ *нов = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (нов) нов->индекс_структуры = индекс_эл;
            }

            // Связь «длина(с) == н» из «выделить(н)» — для снятия проверки
            // границ по условию «и < н» (см. индекс_в_безопасном_контексте).
            if (длина_из_переменной_новая) {
                Символ *нов = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (нов) {
                    нов->длина_из_переменной = 1;
                    нов->длина_токен = длина_токен_новый;
                }
            }

            // Дескриптор потока: помечаем символ, чтобы «присоединить» его
            // нашло и потребило (повторный join = use-after-move). §2: сохраняем
            // и флаг срез (поток<срез<E>>) — «присоединить» вернёт срез<E>.
            if (поток_новый) {
                Символ *нов = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (нов) { нов->поток = 1; нов->срез = узел->срез; }
            }

            // Переменная-перечисление: сохранить индекс enum-типа в символе
            // (тот же слот, что у структур; тип их различает).
            if (узел->тип_данных == ТОКЕН_ПЕРЕЧИСЛЕНИЕ) {
                Символ *нов = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (нов) нов->индекс_структуры = тип_объявления.индекс_структуры;
            }

            // Сырой указатель доказанно нулевой, если объявлен без инициализатора
            // (кодоген занулит его в nullptr) либо инициализирован «нуль».
            // Индексирование такого указателя ловится как нулевое разыменование.
            if (узел->указатели > 0 && !узел->срез) {
                Узел *инит0 = узел_число_детей(узел) > 0
                    ? узел_ребёнок(узел, 0) : nullptr;
                int инит_нуль = (инит0 == nullptr) || (инит0->тип == УЗЕЛ_НУЛЬ);
                // «Может быть нулём» шире литерала «нуль»: сюда же несужённая
                // «возможно»-переменная и вызов функции с возвратом «возможно<T*>»
                // (иначе «целое32* п = f()» при f→возможно давал бы null-дереф).
                int инит_может_нуль = (инит0 == nullptr)
                    || выражение_может_быть_нуль(а, инит0);
                // Non-null по умолчанию: обычный «T*» не может быть нулевым —
                // ни «= нуль»/nullable-значение, ни объявление без инициализатора
                // (кодоген занулил бы его в nullptr). Для nullable нужен «возможно<T*>».
                if (!узел->возможно && инит_может_нуль) {
                    ошибка_семантики(а, &узел->токен, !инит0
                        ? "указатель ненулевой по умолчанию: инициализируйте "
                          "ненулевым значением или объявите «возможно<T*>»"
                        : инит_нуль
                          ? "указатель ненулевой по умолчанию: «нуль» ему присвоить "
                            "нельзя — объявите «возможно<T*>» для nullable-указателя"
                          : "nullable-значение нельзя присвоить ненулевому указателю: "
                            "сузьте под охранником «если (x != нуль)» или объявите "
                            "«возможно<T*>»");
                }
                Символ *псим = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (псим) {
                    псим->возможно = узел->возможно;
                    // Обычный указатель гарантированно ненулевой (нуль отвергнут
                    // выше); «возможно» — нулевой, если так инициализирован.
                    псим->может_быть_нуль = узел->возможно ? инит_может_нуль : 0;
                    // Провенанс строкового литерала: прямой литерал или копия
                    // указателя, который сам из литерала (запись → .rodata).
                    псим->из_литерала = инит0 && (инит0->тип == УЗЕЛ_СТРОКА
                        || (инит0->тип == УЗЕЛ_ИДЕНТИФИКАТОР
                            && указатель_из_литерала(а, инит0)));
                    // Borrow-провенанс (безопасно ли вернуть): «нуль», строковый
                    // литерал, либо копия указателя, который сам безопасен для
                    // возврата (параметр/argv/литерал). Всё остальное (результат
                    // C-функции, неизвестное) — по умолчанию 0: вернуть нельзя.
                    псим->безопасен_для_возврата =
                        (инит0 == nullptr)                         // зануляется в nullptr
                        || (инит0->тип == УЗЕЛ_НУЛЬ)
                        || (инит0->тип == УЗЕЛ_СТРОКА)
                        || (инит0->тип == УЗЕЛ_ИДЕНТИФИКАТОР
                            && указатель_безопасен_для_возврата(а, инит0));
                }
            }

            // Definite assignment: скалярная арифметическая переменная,
            // объявленная без инициализатора (не массив/срез/структура/указатель —
            // те зануляются), считается неинициализированной до первого
            // присваивания; её чтение — ошибка. Указатели идут своим путём
            // (нулевое разыменование), массивы/структуры зануляются.
            if (узел_число_детей(узел) == 0
                && !узел->массив && !узел->срез && узел->указатели == 0
                && узел->тип_данных != ТОКЕН_СТРУКТУРА) {
                Символ *ссим = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (ссим) ссим->инициализирована = 0;
            }
            // Иммутабельность («конст»): помечаем переменную неизменяемой. Такая
            // переменная должна быть инициализирована при объявлении (иначе её
            // нельзя было бы задать вовсе — переприсваивание запрещено).
            if (узел->неизменяемый) {
                Символ *кс = найти_символ(а, узел->токен.начало, узел->токен.длина);
                if (кс) кс->неизменяемый = 1;
                if (узел_число_детей(узел) == 0) {
                    ошибка_семантики(а, &узел->токен,
                        "«конст»-переменная должна быть инициализирована при "
                        "объявлении (переприсваивание запрещено)");
                }
            }
            break;
        }

        case УЗЕЛ_ПРИСВАИВАНИЕ:
        case УЗЕЛ_ВЫЗОВ:
        case УЗЕЛ_ИНКРЕМЕНТ:
            типизировать_выражение(а, узел);
            break;

        case УЗЕЛ_БЛОК:
            анализ_блока(а, узел);
            break;

        case УЗЕЛ_НЕБЕЗОПАСНО:
            // Внутри блока разрешены операции с сырыми указателями; учёт глубины
            // включает/выключает статический гейт. Область видимости и autofree
            // обеспечивает анализ_блока (как у обычного блока).
            а->глубина_небезопасно++;
            анализ_блока(а, узел_ребёнок(узел, 0));
            а->глубина_небезопасно--;
            break;

        case УЗЕЛ_АСМ:
            анализ_асм(а, узел);
            break;

        default:
            break;
    }
}

static void анализ_блока(Анализатор *а, Узел *блок)
{
    if (!блок) return;
    войти_в_область(а);
    for (size_t i = 0; i < узел_число_детей(блок); ++i) {
        if (а->диаг->ошибка) break;  // не-батч режим: стоп на первой ошибке
        // Снимок «рабочего» состояния до оператора — чтобы в батч-режиме после
        // ошибки восстановиться и продолжить со следующего оператора, не
        // повреждая таблицу символов и стек областей (иначе рассинхрон глубины
        // → порча). Значения — только индексы в фикс. массивах, восстановление
        // безопасно (никаких висячих указателей).
        size_t сн_символов   = а->число_символов;
        int    сн_глубина    = а->глубина;
        int    сн_глуб_цикла = а->глубина_цикла;
        size_t сн_безопасных = а->число_безопасных;
        size_t сн_связей     = а->число_связей;
        size_t сн_ограничений = а->глубина_ограничений;
        size_t сн_фактов     = а->число_фактов;

        Узел *оператор = узел_ребёнок(блок, i);
        анализ_оператора(а, оператор);
        // Мутация переменной этим оператором снимает её факт для последующих
        // операторов области (в т.ч. вложенных if): консервативно, без ложных
        // «недостижим». Условие самого оператора уже проверено выше по стеку.
        инвалидировать_факты_мутацией(а, оператор);

        if (а->диаг->ошибка && а->ошибки) {
            собрать_ошибку(а);  // сохранить и сбросить
            // Откатить «рабочее» состояние к снимку до оператора.
            а->число_символов    = сн_символов;
            а->глубина           = сн_глубина;
            а->глубина_цикла     = сн_глуб_цикла;
            а->число_безопасных  = сн_безопасных;
            а->число_связей      = сн_связей;
            а->глубина_ограничений = сн_ограничений;
            а->число_фактов      = сн_фактов;
        }
    }
    выйти_из_области(а);
}

static void анализ_функции(Анализатор *а, Узел *функция)
{
    войти_в_область(а);

    // Базовая линия ошибок: чтобы проверку «возврат по всем путям» запускать
    // только на функции, тело которой разобралось без ошибок (иначе — каскад).
    size_t ошибок_до = а->ошибки ? а->ошибки->длина : 0;

    а->тип_возврата       = функция->тип_данных;
    а->беззнаковый_возврата = функция->беззнаковый;
    а->указатели_возврата = функция->указатели;  // косвенность типа возврата «Тип*»
    а->срез_возврата      = функция->срез;
    а->индекс_структуры_возврата = -1;
    // §37 п.6 — классификация возврата этой функции (выведена пред-проходом).
    а->возврат_заимствован_текущей = 0;
    а->возврат_смешанный_текущей   = 0;
    if (функция->срез && !функция->это_main) {
        СигнатураФункции *сс = найти_сигнатуру_по_имени(а, функция->токен.начало,
                                                         функция->токен.длина);
        if (сс) {
            а->возврат_заимствован_текущей = сс->возврат_заимствован;
            а->возврат_смешанный_текущей   = сс->возврат_смешанный;
        }
    }

    // Тип возврата — пользовательская структура/перечисление: разрешаем, но
    // структуру, которой нужна деструкция (собственная или транзитивная),
    // возвращать по значению пока нельзя — это move-семантика возврата
    // (аналогично «владеет»-параметру среза), отдельная от простого
    // копирования POD-структуры; сделать её безопасно «на скорую руку»
    // рискованно (двойной вызов деструктора), поэтому явная ошибка вместо
    // тихой генерации некорректного/небезопасного кода.
    if (функция->тип_данных == ТОКЕН_СТРУКТУРА) {
        а->индекс_структуры_возврата = найти_индекс_структуры(а, &функция->имя_типа);
        if (а->индекс_структуры_возврата < 0) {
            char msg[256];
            snprintf(msg, sizeof(msg), "неизвестная структура «%.*s» в типе возврата",
                     (int)функция->имя_типа.длина, функция->имя_типа.начало);
            ошибка_семантики(а, &функция->имя_типа, msg);
            выйти_из_области(а);
            return;
        }
        if (функция->указатели == 0
            && а->структуры[а->индекс_структуры_возврата].внешний) {
            ошибка_семантики(а, &функция->имя_типа,
                "внешний тип нельзя возвращать по значению (его устройство "
                "скрыто в C) — верните указатель «Тип*»");
            выйти_из_области(а);
            return;
        }
        if (структура_индекс_нужна_деструкция(а, а->индекс_структуры_возврата, 0)) {
            ошибка_семантики(а, &функция->имя_типа,
                "структуру, которой нужна деструкция (собственная или через "
                "поле), нельзя возвращать по значению; возвращайте через "
                "указательный параметр «Тип*»");
            выйти_из_области(а);
            return;
        }
    } else if (функция->тип_данных == ТОКЕН_ПЕРЕЧИСЛЕНИЕ) {
        а->индекс_структуры_возврата = найти_индекс_перечисления(а, &функция->имя_типа);
        if (а->индекс_структуры_возврата < 0) {
            char msg[256];
            snprintf(msg, sizeof(msg), "неизвестное перечисление «%.*s» в типе возврата",
                     (int)функция->имя_типа.длина, функция->имя_типа.начало);
            ошибка_семантики(а, &функция->имя_типа, msg);
            выйти_из_области(а);
            return;
        }
    }

    а->число_изменяемых = 0;
    собрать_изменяемые(а, функция);

    if (функция->это_main) {
        // Сигнатура точки входа — ровно один параметр «срез<символ*> аргументы»
        // (argv, ВКЛЮЧАЯ имя программы; длина(аргументы) == argc). Срез — та же
        // безопасная абстракция, что и везде: индексация проверяется по границам
        // (рантайм), для срезов доказанно-безопасный доступ элидируется. Старая
        // форма «(целое32 количество_аргументов, символ** аргументы)» снята.
        size_t пар_счёт = 0;
        Узел *арг_пар = nullptr;
        for (size_t i = 0; i + 1 < узел_число_детей(функция); ++i) {
            Узел *p = узел_ребёнок(функция, i);
            if (p && p->тип == УЗЕЛ_ПАРАМЕТР) { пар_счёт++; арг_пар = p; }
        }
        int ок = пар_счёт == 1 && арг_пар && арг_пар->срез
                 && арг_пар->тип_данных == ТОКЕН_ТИП_СИМВОЛ
                 && арг_пар->указатели == 1
                 && !арг_пар->по_ссылке && !арг_пар->владеет;
        if (!ок) {
            ошибка_семантики(а, &функция->токен,
                "точка_входа должна иметь ровно один параметр "
                "«срез<символ*> аргументы» (аргументы командной строки, включая "
                "имя программы; длина(аргументы) == число аргументов)");
            выйти_из_области(а);
            return;
        }
    }

    size_t n = узел_число_детей(функция);
    for (size_t i = 0; i + 1 < n; ++i) {
        Узел *пар = узел_ребёнок(функция, i);
        if (пар && пар->тип == УЗЕЛ_ПАРАМЕТР && пар->токен.длина > 0) {
            if (пар->владеет && !пар->срез) {
                ошибка_семантики(а, &пар->токен,
                    "«владеет» применимо только к параметру-срезу");
                выйти_из_области(а);
                return;
            }
            // Параметр по ссылке (ref/out): обычные срезы не поддержаны (у них своя
            // move-семантика владения). НО «изменяемый буфер<T>» разрешён: функция
            // РАСТИТ буфер вызывающего («добавить»/«перевыделить» обновляют
            // дескриптор {данные,длина,ёмкость} по ссылке). «вывод»/«владеет» с
            // буфером — бессмысленны (буфер уже создан у вызывающего).
            if (пар->по_ссылке && пар->срез && !пар->буфер) {
                ошибка_семантики(а, &пар->токен,
                    "«изменяемый»/«вывод» не применимы к срезу (у среза своя "
                    "семантика владения)");
                выйти_из_области(а);
                return;
            }
            if (пар->буфер && пар->по_ссылке == 2) {
                ошибка_семантики(а, &пар->токен,
                    "«вывод» не применим к буферу: буфер создаётся у вызывающего "
                    "(«буфер<T> = выделить(...)»), функция лишь растит его — "
                    "используйте «изменяемый буфер<T>»");
                выйти_из_области(а);
                return;
            }
            объявить_символ(а,
                пар->токен.начало, пар->токен.длина,
                пар->тип_данных, пар->указатели, пар->массив,
                пар->беззнаковый, пар->срез, 0, 0, &пар->токен, 0, 0);
            Символ *с = найти_символ(а, пар->токен.начало, пар->токен.длина);
            // «изменяемый буфер<T>»-параметр: помечаем символ буфером, чтобы
            // «добавить»/«перевыделить» в теле приняли его (растит буфер вызывающего).
            if (с && пар->буфер) с->буфер = 1;
            // Параметр по ссылке: «изменяемый» приходит инициализированным
            // (вызывающий передал значение), «вывод» — нет (тело обязано присвоить).
            if (с && пар->по_ссылке) {
                с->по_ссылке = пар->по_ссылке;
                // «изменяемый»(1) и «чтение»(3) приходят инициализированными
                // (вызывающий передал значение-lvalue); «вывод»(2) — нет (тело
                // обязано присвоить до возврата).
                с->инициализирована = (пар->по_ссылке == 2) ? 0 : 1;
                // «чтение» — const-ссылка второго класса: тело НЕ может писать в
                // объект вызывающего (иммутабельность, как у «конст»-переменной;
                // запись ловит существующая проверка неизменяемости). Ссылке
                // некуда утечь (нет сырого «&»/глобалов), связи длины не рвутся
                // (не мутация) — безопасно и для СВОИХ функций, не только
                // «внешняя». Нулевая рантайм-цена: передаётся Тип* без копии.
                if (пар->по_ссылке == 3) с->неизменяемый = 1;
            }
            // Указатель-параметр указывает в память вызывающего → его безопасно
            // вернуть (borrow): память переживёт возврат, освобождать не нужно.
            if (с && пар->указатели > 0) {
                с->безопасен_для_возврата = 1;
                // «возможно<T*>»-параметр может быть нулевым → разыменование в
                // теле только под охранником. Обычный указатель-параметр ненулевой.
                с->возможно = пар->возможно;
                с->может_быть_нуль = пар->возможно ? 1 : 0;
            }
            // Параметр-структура: запоминаем её описание для доступа к полям.
            if (с && пар->тип_данных == ТОКЕН_СТРУКТУРА) {
                с->индекс_структуры = найти_индекс_структуры(а, &пар->имя_типа);
                // «внешний тип» по значению не передать: размера нет и в C.
                if (с->индекс_структуры >= 0 && пар->указатели == 0
                    && а->структуры[с->индекс_структуры].внешний) {
                    char msg[256];
                    snprintf(msg, sizeof(msg),
                             "«%.*s» — внешний тип: параметр возможен только "
                             "как указатель «%.*s*»",
                             (int)пар->имя_типа.длина, пар->имя_типа.начало,
                             (int)пар->имя_типа.длина, пар->имя_типа.начало);
                    ошибка_семантики(а, &пар->токен, msg);
                }
            }
            // Параметр-перечисление: сохраняем индекс enum-типа (для сравнений).
            if (с && пар->тип_данных == ТОКЕН_ПЕРЕЧИСЛЕНИЕ) {
                с->индекс_структуры = найти_индекс_перечисления(а, &пар->имя_типа);
            }
            // Параметр-указатель на функцию: индекс псевдонима; параметр считается
            // не-нулевым (вызывающий передаёт функцию), вызов через него разрешён.
            if (с && пар->тип_данных == ТОКЕН_ФУНКУКАЗАТЕЛЬ) {
                с->индекс_структуры = найти_индекс_типфункции(а, &пар->имя_типа);
                с->может_быть_нуль = 0;
            }
            // «владеет»-параметр: функция забирает владение → освобождается
            // внутри (autofree), и его можно перемещать/возвращать.
            if (пар->владеет && с) {
                с->владеет_срезом = 1;
            }
            // Срез-аргументы точки входа (argv) живёт всё время работы программы:
            // это заимствованный (не владеющий) срез, элементы которого — символ*
            // в память, переживающую возврат → указатель из «аргументы[i]» и сам
            // «аргументы» безопасно возвращать (borrow-провенанс).
            if (функция->это_main && пар->срез && с) {
                с->безопасен_для_возврата = 1;
                с->владеет_срезом = 0;
            }
        }
    }

    Узел *тело = nullptr;
    if (n > 0) {
        тело = узел_ребёнок(функция, n - 1);
        if (тело && тело->тип == УЗЕЛ_БЛОК)
            анализ_блока(а, тело);
        else
            тело = nullptr;
    }

    // Возврат значения по всем путям обязателен для любой non-«ничего» функции
    // (включая точка_входа): молчаливый fall-through в C возвращает мусор (UB).
    // Проверяем только если тело разобралось без ошибок — иначе неполный AST дал
    // бы ложную диагностику поверх настоящей.
    int тело_чистое = !а->диаг->ошибка
        && (!а->ошибки || а->ошибки->длина == ошибок_до);
    if (функция->тип_данных != ТОКЕН_НИЧЕГО && тело_чистое
        && !все_пути_возвращают(тело)) {
        char тип[64];
        описание_типа((ИнфоТипа){ функция->тип_данных, 0, функция->беззнаковый,
                                  функция->срез, а->индекс_структуры_возврата },
                      тип, sizeof(тип));
        char msg[256];
        snprintf(msg, sizeof(msg),
            "функция типа «%s» не возвращает значение по всем путям "
            "(добавьте «вернуть»)", тип);
        ошибка_семантики(а, &функция->токен, msg);
    }

    // «вывод»-параметры на fall-through пути в конце тела: если тело может
    // «выпасть» из функции (не гарантирует возврат по всем путям), out обязан
    // быть присвоен и на этом пути. Если все пути возвращают — они уже проверены
    // на каждом «вернуть», а конец тела недостижим.
    if (тело_чистое && тело && !все_пути_возвращают(тело)) {
        проверить_вывод_присвоен(а, &функция->токен);
    }

    выйти_из_области(а);
}

// Собирает сигнатуры всех функций до анализа тел, чтобы вызовы (в т.ч. вперёд)
// знали тип возврата — особенно для приёма возвращаемого среза.
// Проверка и манглинг перегрузки оператора в собрать_сигнатуры: заменяет токен
// функции (символ оператора) на манглированное C-имя, чтобы всё ниже по потоку
// (сигнатура, кодоген) работало как с обычной функцией. Возвращает 0 при
// нарушении правил (ошибка уже выдана).
static int подготовить_оператор(Анализатор *а, Узел *узел)
{
    if (!операторкод(&узел->токен)) {
        ошибка_семантики(а, &узел->токен,
            "этот оператор не перегружается (доступны + - * / %% == != < > <= >=)");
        return 0;
    }
    // Ровно два параметра-значения, хотя бы один — структура.
    Узел *п[2] = { nullptr, nullptr };
    size_t число = 0;
    size_t всего = узел_число_детей(узел);
    for (size_t j = 0; j + 1 < всего; ++j) {
        Узел *пар = узел_ребёнок(узел, j);
        if (пар && пар->тип == УЗЕЛ_ПАРАМЕТР) {
            if (число < 2) п[число] = пар;
            число++;
        }
    }
    if (число != 2) {
        ошибка_семантики(а, &узел->токен,
            "перегрузка оператора должна иметь ровно два параметра");
        return 0;
    }
    for (int k = 0; k < 2; ++k) {
        if (п[k]->по_ссылке || п[k]->владеет || п[k]->указатели > 0 || п[k]->срез) {
            ошибка_семантики(а, &п[k]->токен,
                "параметр перегрузки оператора — только по значению "
                "(без изменяемый/вывод/владеет/указателя/среза)");
            return 0;
        }
    }
    if (п[0]->тип_данных != ТОКЕН_СТРУКТУРА && п[1]->тип_данных != ТОКЕН_СТРУКТУРА) {
        ошибка_семантики(а, &узел->токен,
            "хотя бы один операнд перегрузки должен быть структурой "
            "(встроенные операторы примитивов не переопределяются)");
        return 0;
    }
    char имя[МАКС_ИМЯ * 3];
    if (!манглированное_имя_оператора(&узел->токен,
            п[0]->тип_данных, п[0]->беззнаковый, п[0]->указатели, п[0]->срез,
            &п[0]->имя_типа,
            п[1]->тип_данных, п[1]->беззнаковый, п[1]->указатели, п[1]->срез,
            &п[1]->имя_типа, имя, sizeof имя)) {
        ошибка_семантики(а, &узел->токен,
            "не удалось построить имя перегрузки оператора");
        return 0;
    }
    // Заменяем токен-символ на манглированное имя (владеющая строка в
    // собственное_имя — как у мономорфизации).
    free(узел->собственное_имя);
    узел->собственное_имя = strdup(имя);
    if (узел->собственное_имя) {
        узел->токен.начало = узел->собственное_имя;
        узел->токен.длина = strlen(узел->собственное_имя);
    }
    return 1;
}

static void собрать_сигнатуры(Анализатор *а, Узел *корень)
{
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *узел = узел_ребёнок(корень, i);
        if (узел->тип != УЗЕЛ_ФУНКЦИЯ || узел->это_main) continue;
        if (а->число_функций >= МАКС_ФУНКЦИЙ)
            return (void)переполнение_таблицы(а, &узел->токен,
                                              "функций в программе", МАКС_ФУНКЦИЙ);
        // Перегрузка оператора: превращаем символ оператора в манглированное
        // C-имя ДО копирования имени в сигнатуру (дальше — как обычная функция).
        // В проходе вывода тип-аргументов оператор-функции пропускаем: их
        // сигнатуры для вывода не нужны, а подготовить_оператор МУТИРУЕТ токен
        // (манглинг не идемпотентен) — второй прогон в настоящем анализе двойно
        // манглил бы и падал «оператор не перегружается».
        if (узел->это_оператор) {
            if (а->режим_вывода) continue;
            if (!подготовить_оператор(а, узел)) {
                if (а->ошибки) собрать_ошибку(а);
                continue;
            }
        }
        if (узел->токен.длина == 0) continue;
        if (имя_слишком_длинное(а, &узел->токен, узел->токен.длина)) continue;
        СигнатураФункции *с = &а->функции[а->число_функций++];
        size_t n = узел->токен.длина < МАКС_ИМЯ - 1 ? узел->токен.длина : МАКС_ИМЯ - 1;
        memcpy(с->имя, узел->токен.начало, n);
        с->имя[n] = '\0';
        с->тип_возврата = узел->тип_данных;
        с->беззнаковый = узел->беззнаковый;
        с->указатели_возврата = узел->указатели;  // косвенность типа возврата
        с->возврат_возможно = узел->возможно;  // «возможно<T*>» → результат nullable
        с->срез = узел->срез;
        с->индекс_структуры_возврата = -1;
        if (узел->тип_данных == ТОКЕН_СТРУКТУРА) {
            с->индекс_структуры_возврата = найти_индекс_структуры(а, &узел->имя_типа);
        } else if (узел->тип_данных == ТОКЕН_ПЕРЕЧИСЛЕНИЕ) {
            с->индекс_структуры_возврата = найти_индекс_перечисления(а, &узел->имя_типа);
        }
        // Обобщённая функция-шаблон: ведущие дети — УЗЕЛ_ТИПОПАРАМЕТР. Собираем
        // имена тип-параметров (для вывода тип-аргументов); имя возврата-T тоже.
        с->обобщённая = 0;
        с->число_типопарам = 0;
        с->имя_типопарам_возврата.длина = 0;
        for (size_t j = 0; j < узел_число_детей(узел); ++j) {
            Узел *реб = узел_ребёнок(узел, j);
            if (!реб || реб->тип != УЗЕЛ_ТИПОПАРАМЕТР) break;
            с->обобщённая = 1;
            if (с->число_типопарам < 8)
                с->типопарам[с->число_типопарам++] = реб->токен;
        }
        if (с->обобщённая && узел->тип_данных == ТОКЕН_ТИПОПАРАМЕТР
            && узел->указатели == 0)
            с->имя_типопарам_возврата = узел->имя_типа;
        // Параметры (без тела — последнего ребёнка; у «внешняя» тела нет,
        // поэтому там дети — сплошь параметры): отмечаем «владеет».
        с->число_параметров = 0;
        size_t всего = узел_число_детей(узел);
        size_t предел = узел->внешняя ? всего : (всего ? всего - 1 : 0);
        for (size_t j = 0; j < предел; ++j) {
            Узел *пар = узел_ребёнок(узел, j);
            if (!пар || пар->тип != УЗЕЛ_ПАРАМЕТР) continue;
            if (с->число_параметров >= МАКС_ПАРАМЕТРОВ) break;
            с->владеет_параметра[с->число_параметров] = пар->владеет;
            с->параметры[с->число_параметров] = (ИнфоПараметра){
                пар->тип_данных, пар->беззнаковый, пар->указатели, пар->срез,
                пар->буфер,
                пар->тип_данных == ТОКЕН_ФУНКУКАЗАТЕЛЬ
                    ? найти_индекс_типфункции(а, &пар->имя_типа)
                : пар->тип_данных == ТОКЕН_СТРУКТУРА
                    ? найти_индекс_структуры(а, &пар->имя_типа) : -1,
                пар->по_ссылке
            };
            // Имя тип-параметра, если тип параметра — «голый» T (для вывода).
            // Длина 0 — параметр не «голый» тип-параметр (по нему не выводим).
            с->имя_типопарам_параметра[с->число_параметров].длина = 0;
            if (пар->тип_данных == ТОКЕН_ТИПОПАРАМЕТР && пар->указатели == 0
                && !пар->срез)
                с->имя_типопарам_параметра[с->число_параметров] = пар->имя_типа;
            с->число_параметров++;
        }
    }
}

// ─── вывод чистоты функций ───────────────────────────────────────────────────
// Чистая функция не может создать гонку, поэтому её вызов разрешён в теле
// «параллельно для». Чистота ВЫВОДИТСЯ, а не объявляется: новое ключевое слово
// отняло бы имя у программиста, а вывод работает и на уже написанном коде.
//
// Вывод возможен только потому, что в языке НЕТ глобальных переменных
// (инвариант №4): единственные каналы наружу — «изменяемый»/«вывод», запись в
// срез-параметр (общие данные), указатель, «небезопасно» и вызов нечистой или
// внешней функции. Их полный перечень и даёт полноту анализа.

// Помечает нечистой; возвращает 1, если состояние изменилось (для fixpoint).
// Первая найденная причина побеждает — она же показывается пользователю.
static int пометить_нечистой(СигнатураФункции *с, ВидЭффекта вид,
                              const Токен *где, const Токен *имя)
{
    if (!с->чистая) return 0;
    с->чистая = 0;
    с->вид_эффекта = вид;
    if (где) с->где_эффект = *где;
    с->имя_эффекта[0] = '\0';
    if (имя) скопировать_имя_токена(с->имя_эффекта, имя);
    return 1;
}

// Прямые эффекты в теле — те, что видны без знания о вызываемых функциях.
static void искать_прямой_эффект(СигнатураФункции *с, Узел *у,
                                  const Токен **срез_пар, size_t число_срезов)
{
    if (!у || !с->чистая) return;
    // «параллельно для» внутри функции — сам по себе запуск потоков.
    if (у->тип == УЗЕЛ_ДЛЯ && у->параллельно) {
        пометить_нечистой(с, ЭФФЕКТ_ПОТОК, &у->токен, nullptr);
        return;
    }
    switch (у->тип) {
        case УЗЕЛ_НЕБЕЗОПАСНО:
            // За гейтом возможен сырой указатель — доказать отсутствие эффекта
            // нельзя, поэтому вся функция считается нечистой.
            пометить_нечистой(с, ЭФФЕКТ_НЕБЕЗОПАСНО, &у->токен, nullptr);
            return;
        case УЗЕЛ_ВЫЗОВ:
            if (токен_текст_равен(&у->токен, "выделить")
                || токен_текст_равен(&у->токен, "клон")) {
                пометить_нечистой(с, ЭФФЕКТ_ВЫДЕЛЕНИЕ, &у->токен, &у->токен);
                return;
            }
            if (токен_текст_равен(&у->токен, "запустить")
                || токен_текст_равен(&у->токен, "присоединить")) {
                пометить_нечистой(с, ЭФФЕКТ_ПОТОК, &у->токен, &у->токен);
                return;
            }
            break;
        case УЗЕЛ_ИНКРЕМЕНТ:      // «срез_парам[i]++» — тоже запись в срез вызывающего
        case УЗЕЛ_ПРИСВАИВАНИЕ: {
            // Запись в срез-параметр — это запись в данные вызывающего, общие
            // для всех потоков: непересечение индексов здесь не доказать.
            Узел *цель = узел_ребёнок(у, 0);
            if (цель && цель->тип == УЗЕЛ_ИНДЕКС) {
                // У старой формы «с[и]» имя базы лежит в ТОКЕНЕ узла-индекса,
                // у новой — в дочернем идентификаторе.
                const Токен *база = &цель->токен;
                if (узел_число_детей(цель) == 2) {
                    Узел *б = узел_ребёнок(цель, 0);
                    if (б && б->тип == УЗЕЛ_ИДЕНТИФИКАТОР) база = &б->токен;
                }
                for (size_t i = 0; i < число_срезов; ++i) {
                    if (токены_равны_(база, срез_пар[i])) {
                        пометить_нечистой(с, ЭФФЕКТ_ЗАПИСЬ_В_СРЕЗ, база, база);
                        return;
                    }
                }
            }
            break;
        }
        default: break;
    }
    for (size_t i = 0; i < узел_число_детей(у); ++i)
        искать_прямой_эффект(с, узел_ребёнок(у, i), срез_пар, число_срезов);
}

// Эффекты через вызовы. Возвращает 1, если что-то пометили (шаг fixpoint).
static int искать_эффект_вызовов(Анализатор *а, СигнатураФункции *с, Узел *у)
{
    if (!у || !с->чистая) return 0;
    if (у->тип == УЗЕЛ_ВЫЗОВ && !токен_текст_равен(&у->токен, "длина")) {
        СигнатураФункции *в = найти_сигнатуру_по_имени(а, у->токен.начало,
                                                        у->токен.длина);
        if (!в) {
            // Внешняя/libc (в т.ч. printf) — об эффектах ничего не известно.
            return пометить_нечистой(с, ЭФФЕКТ_ВНЕШНЯЯ, &у->токен, &у->токен);
        }
        if (!в->чистая) {
            return пометить_нечистой(с, ЭФФЕКТ_ВЫЗОВ_НЕЧИСТОЙ, &у->токен,
                                     &у->токен);
        }
    }
    int изменилось = 0;
    for (size_t i = 0; i < узел_число_детей(у); ++i)
        изменилось |= искать_эффект_вызовов(а, с, узел_ребёнок(у, i));
    return изменилось;
}

// Тело функции — последний ребёнок узла (после типопараметров и параметров).
static Узел *тело_функции(Узел *функция)
{
    size_t n = узел_число_детей(функция);
    return n > 0 ? узел_ребёнок(функция, n - 1) : nullptr;
}

// Заполняет «чистая» у всех сигнатур. Оптимистичный fixpoint: сперва все
// чистые, затем помечаем нечистыми, пока есть изменения. Так само- и взаимно
// рекурсивные чистые функции остаются чистыми (наивный обход зациклился бы
// или объявил их нечистыми).
static void вывести_чистоту(Анализатор *а, Узел *корень)
{
    int есть_тело[МАКС_ФУНКЦИЙ] = { 0 };

    for (size_t i = 0; i < а->число_функций; ++i) {
        а->функции[i].чистая = 1;
        а->функции[i].вид_эффекта = ЭФФЕКТ_НЕТ;
        а->функции[i].имя_эффекта[0] = '\0';
    }

    // Прямые эффекты: сигнатура + тело. «внешняя» тела не имеет — она попадёт
    // в ветку «без тела → консервативно нечистая» ниже (об эффектах C-функции
    // ничего не известно).
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *узел = узел_ребёнок(корень, i);
        if (узел->тип != УЗЕЛ_ФУНКЦИЯ || узел->это_main || узел->внешняя) continue;
        СигнатураФункции *с = найти_сигнатуру_по_имени(а, узел->токен.начало,
                                                        узел->токен.длина);
        if (!с) continue;
        есть_тело[с - а->функции] = 1;

        const Токен *срез_пар[МАКС_ПАРАМЕТРОВ];
        size_t число_срезов = 0;
        size_t всего = узел_число_детей(узел);
        for (size_t j = 0; j + 1 < всего; ++j) {
            Узел *пар = узел_ребёнок(узел, j);
            if (!пар || пар->тип != УЗЕЛ_ПАРАМЕТР) continue;
            if (пар->по_ссылке) {
                // «изменяемый»/«вывод» — запись в кадр вызывающего.
                пометить_нечистой(с, ЭФФЕКТ_ССЫЛОЧНЫЙ_ПАРАМЕТР, &пар->токен,
                                  &пар->токен);
                break;
            }
            if (пар->указатели > 0) {
                пометить_нечистой(с, ЭФФЕКТ_УКАЗАТЕЛЬ_ПАРАМЕТР, &пар->токен,
                                  &пар->токен);
                break;
            }
            if (пар->владеет) {
                // Потребление среза — эффект: в общих данных дало бы double-free.
                пометить_нечистой(с, ЭФФЕКТ_ВЛАДЕЕТ_ПАРАМЕТР, &пар->токен,
                                  &пар->токен);
                break;
            }
            if (пар->срез && число_срезов < МАКС_ПАРАМЕТРОВ)
                срез_пар[число_срезов++] = &пар->токен;
        }
        if (с->чистая)
            искать_прямой_эффект(с, тело_функции(узел), срез_пар, число_срезов);
    }

    // Сигнатура без тела (из интерфейса библиотеки `.и`) — тело не проверить,
    // формат `.и` чистоту не переносит, поэтому консервативно нечистая.
    for (size_t i = 0; i < а->число_функций; ++i)
        if (!есть_тело[i])
            пометить_нечистой(&а->функции[i], ЭФФЕКТ_ВНЕШНЯЯ, nullptr, nullptr);

    // Fixpoint по вызовам: нечистота распространяется вверх, пока не стабильно.
    // Итераций не больше числа функций — каждая проходка метит хотя бы одну.
    for (size_t шаг = 0; шаг <= а->число_функций; ++шаг) {
        int изменилось = 0;
        for (size_t i = 0; i < узел_число_детей(корень); ++i) {
            Узел *узел = узел_ребёнок(корень, i);
            if (узел->тип != УЗЕЛ_ФУНКЦИЯ || узел->это_main || узел->внешняя)
                continue;
            СигнатураФункции *с = найти_сигнатуру_по_имени(а, узел->токен.начало,
                                                            узел->токен.длина);
            if (!с || !с->чистая) continue;
            изменилось |= искать_эффект_вызовов(а, с, тело_функции(узел));
        }
        if (!изменилось) break;
    }
}

// §37 п.6 — вывод «владеет-ли-возврат» на функцию (аналог чистоты; без ключевого
// слова, нулевая рантайм-цена). Классификация возврата среза: литерал → ЗАИМСТВ.
// (borrow над .rodata); «выделить»/«клон»/владеющий идентификатор → ВЛАДЕЮЩИЙ;
// «вернуть G()» → наследует свойство G (fixpoint). Функция заимствует-возврат,
// если ВСЕ возвраты заимствованные и НЕ владеющие; смешанный (и то, и то) —
// ошибка на месте возврата (единообразие, ноль рантайма — copy не навязываем).
// f-строка-возврат — dangling (стек умрёт), её ловит проверка возврата в теле.
static void классифицировать_возвраты_функции(Анализатор *а, Узел *узел,
                                               const int *влад_ф, const int *заим_ф,
                                               int *влад, int *заим)
{
    if (!узел) return;
    if (узел->тип == УЗЕЛ_ВОЗВРАТ) {
        if (узел_число_детей(узел) > 0) {
            const Узел *в = узел_ребёнок(узел, 0);
            if (в->тип == УЗЕЛ_СТРОКА) {
                *заим = 1;
            } else if (в->тип == УЗЕЛ_F_СТРОКА) {
                // dangling — тело-анализ отвергнет; на классификацию не влияет.
            } else if (в->тип == УЗЕЛ_ВЫЗОВ
                       && !токен_текст_равен(&в->токен, "выделить")
                       && !токен_текст_равен(&в->токен, "клон")) {
                СигнатураФункции *g = найти_сигнатуру_по_имени(а, в->токен.начало,
                                                                в->токен.длина);
                if (g && g->срез) {
                    size_t gi = (size_t)(g - а->функции);
                    *влад |= влад_ф[gi];
                    *заим |= заим_ф[gi];
                } else {
                    *влад = 1;  // не-срез/неизвестно → консервативно владеющий
                }
            } else {
                *влад = 1;  // «выделить»/«клон»/владеющий идентификатор
            }
        }
        return;  // внутрь возврата не спускаемся
    }
    for (size_t i = 0; i < узел_число_детей(узел); ++i)
        классифицировать_возвраты_функции(а, узел_ребёнок(узел, i),
                                           влад_ф, заим_ф, влад, заим);
}

static void вывести_владение_возврата(Анализатор *а, Узел *корень)
{
    static int влад_ф[МАКС_ФУНКЦИЙ];
    static int заим_ф[МАКС_ФУНКЦИЙ];
    int есть_тело[МАКС_ФУНКЦИЙ] = { 0 };
    for (size_t i = 0; i < а->число_функций; ++i) { влад_ф[i] = 0; заим_ф[i] = 0; }

    // Функции с телом: пометить, что они анализируемы (у безтеловых —
    // библиотечных из «.и» — флаги уже проставлены внедрить_интерфейс_сигнатуры
    // и остаются фиксированными: их тел мы не видим).
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *узел = узел_ребёнок(корень, i);
        if (узел->тип != УЗЕЛ_ФУНКЦИЯ || узел->это_main || узел->внешняя) continue;
        СигнатураФункции *с = найти_сигнатуру_по_имени(а, узел->токен.начало,
                                                        узел->токен.длина);
        if (с) есть_тело[с - а->функции] = 1;
    }
    // Библиотечные (без тела) сигнатуры несут бит из «.и».
    for (size_t i = 0; i < а->число_функций; ++i)
        if (!есть_тело[i] && а->функции[i].срез)
            заим_ф[i] = а->функции[i].возврат_заимствован;

    // Fixpoint: пересчитываем влад/заим по возвратам, «вернуть G()» подхватывает
    // текущие флаги G. Итераций ≤ число функций (монотонно к стабильности).
    for (size_t шаг = 0; шаг <= а->число_функций; ++шаг) {
        int изменилось = 0;
        for (size_t i = 0; i < узел_число_детей(корень); ++i) {
            Узел *узел = узел_ребёнок(корень, i);
            if (узел->тип != УЗЕЛ_ФУНКЦИЯ || узел->это_main || узел->внешняя)
                continue;
            if (!узел->срез) continue;  // не возвращает срез — не интересует
            СигнатураФункции *с = найти_сигнатуру_по_имени(а, узел->токен.начало,
                                                            узел->токен.длина);
            if (!с) continue;
            size_t idx = (size_t)(с - а->функции);
            int в = 0, з = 0;
            классифицировать_возвраты_функции(а, тело_функции(узел),
                                               влад_ф, заим_ф, &в, &з);
            if (в != влад_ф[idx] || з != заим_ф[idx]) {
                влад_ф[idx] = в; заим_ф[idx] = з; изменилось = 1;
            }
        }
        if (!изменилось) break;
    }

    // Финальная запись в сигнатуры + на AST-узел функции (для сериализации в
    // «.и»; кодоген сам бит функции не читает — он читает бит на call-узле).
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *узел = узел_ребёнок(корень, i);
        if (узел->тип != УЗЕЛ_ФУНКЦИЯ || узел->это_main || узел->внешняя) continue;
        if (!узел->срез) continue;
        СигнатураФункции *с = найти_сигнатуру_по_имени(а, узел->токен.начало,
                                                        узел->токен.длина);
        if (!с) continue;
        size_t idx = (size_t)(с - а->функции);
        с->возврат_заимствован = заим_ф[idx] && !влад_ф[idx];
        с->возврат_смешанный   = заим_ф[idx] && влад_ф[idx];
        узел->возврат_заимствован = с->возврат_заимствован;
    }
}

// Собирает описания структур (имена и поля) до анализа функций.
// Собирает объявления «аллокатор Имя { … }» верхнего уровня.
static void собрать_аллокаторы(Анализатор *а, Узел *корень)
{
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *у = узел_ребёнок(корень, i);
        if (у->тип != УЗЕЛ_АЛЛОКАТОР) continue;
        if (найти_аллокатор(а, &у->токен)) {
            ошибка_семантики(а, &у->токен, "аллокатор с таким именем уже объявлен");
            continue;
        }
        if (а->число_аллокаторов < МАКС_АЛЛОКАТОРОВ)
            а->аллокаторы[а->число_аллокаторов++] = у;
        else
            return (void)переполнение_таблицы(а, &у->токен,
                "кастомных аллокаторов", МАКС_АЛЛОКАТОРОВ);
    }
}

static void собрать_перечисления(Анализатор *а, Узел *корень)
{
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *узел = узел_ребёнок(корень, i);
        if (узел->тип != УЗЕЛ_ПЕРЕЧИСЛЕНИЕ || узел->токен.длина == 0) continue;
        if (найти_индекс_перечисления(а, &узел->токен) >= 0) {
            ошибка_семантики(а, &узел->токен,
                "перечисление с таким именем уже объявлено");
            return;
        }
        if (а->число_перечислений >= МАКС_ПЕРЕЧИСЛЕНИЙ)
            return (void)переполнение_таблицы(а, &узел->токен,
                                              "перечислений", МАКС_ПЕРЕЧИСЛЕНИЙ);
        ОписаниеПеречисления *п = &а->перечисления[а->число_перечислений];
        size_t n = узел->токен.длина < МАКС_ИМЯ - 1 ? узел->токен.длина : МАКС_ИМЯ - 1;
        memcpy(п->имя, узел->токен.начало, n);
        п->имя[n] = '\0';
        п->число_вариантов = 0;
        п->это_sum = 0;
        // Регистрируем до заполнения вариантов, чтобы «B = A + 1» мог сослаться
        // на предыдущий вариант этого же перечисления через свёртку констант.
        а->число_перечислений++;
        long текущее = 0;
        for (size_t j = 0; j < узел_число_детей(узел); ++j) {
            Узел *вар = узел_ребёнок(узел, j);
            if (!вар || вар->тип != УЗЕЛ_ВАРИАНТ) continue;
            if (найти_вариант(а, вар->токен.начало, вар->токен.длина, nullptr) >= 0) {
                ошибка_семантики(а, &вар->токен,
                    "вариант перечисления с таким именем уже объявлен");
                return;
            }
            if (п->число_вариантов >= МАКС_ВАРИАНТОВ) {
                переполнение_таблицы(а, &вар->токен, "вариантов перечисления",
                                     МАКС_ВАРИАНТОВ);
                return;
            }
            ВариантПеречисления *в = &п->варианты[п->число_вариантов++];
            в->число_полей = 0;
            size_t m = вар->токен.длина < МАКС_ИМЯ - 1 ? вар->токен.длина : МАКС_ИМЯ - 1;
            memcpy(в->имя, вар->токен.начало, m);
            в->имя[m] = '\0';
            // Полезная нагрузка sum-типа: дети-УЗЕЛ_ПАРАМЕТР. Иначе (ребёнок-
            // выражение) — явное «= значение» C-стиля enum.
            Узел *перв = узел_ребёнок(вар, 0);
            if (перв && перв->тип == УЗЕЛ_ПАРАМЕТР) {
                п->это_sum = 1;
                for (size_t k = 0; k < узел_число_детей(вар); ++k) {
                    Узел *пл = узел_ребёнок(вар, k);
                    if (!пл || пл->тип != УЗЕЛ_ПАРАМЕТР) continue;
                    // Ограничения v1: без срезов (владение) и без ref/out.
                    if (пл->срез) {
                        ошибка_семантики(а, &пл->токен,
                            "поле-срез в варианте sum-типа запрещено (владение "
                            "неоднозначно); используйте примитивы или указатели");
                        return;
                    }
                    if (пл->по_ссылке || пл->владеет) {
                        ошибка_семантики(а, &пл->токен,
                            "модификаторы «владеет»/«изменяемый»/«вывод» неприменимы "
                            "к полю варианта");
                        return;
                    }
                    // Поле варианта обязано быть именованным: оно становится
                    // полем union в C, а безымянное поле — невалидный C
                    // («struct { int32_t ; }»). Раньше это молча доезжало до
                    // компилятора C; теперь — ошибка Konda с позицией.
                    // (У «типфункции» безымянные параметры законны — там они
                    // задают только типы и в структуры не превращаются.)
                    if (пл->токен.длина == 0) {
                        char msg[320];
                        snprintf(msg, sizeof msg,
                            "поле варианта «%.*s» требует имя: «%.*s(тип имя)» — "
                            "имя нужно, чтобы поле существовало в C; связывание в "
                            "«выбор» задаётся отдельно (например «%.*s(х)»)",
                            (int)вар->токен.длина, вар->токен.начало,
                            (int)вар->токен.длина, вар->токен.начало,
                            (int)вар->токен.длина, вар->токен.начало);
                        ошибка_семантики(а, &вар->токен, msg);
                        return;
                    }
                    if (в->число_полей >= МАКС_ПОЛЕЙ_ВАРИАНТА) {
                        переполнение_таблицы(а, &вар->токен, "полей варианта",
                                             МАКС_ПОЛЕЙ_ВАРИАНТА);
                        return;
                    }
                    ПолеВарианта *пв = &в->поля[в->число_полей++];
                    size_t im = пл->токен.длина < МАКС_ИМЯ - 1 ? пл->токен.длина : МАКС_ИМЯ - 1;
                    memcpy(пв->имя, пл->токен.начало, im);
                    пв->имя[im] = '\0';
                    пв->тип = пл->тип_данных;
                    пв->беззнаковый = пл->беззнаковый;
                    пв->указатели = пл->указатели;
                    пв->индекс_структуры =
                        (пл->тип_данных == ТОКЕН_СТРУКТУРА)
                            ? найти_индекс_структуры(а, &пл->имя_типа)
                        : (пл->тип_данных == ТОКЕН_ПЕРЕЧИСЛЕНИЕ)
                            ? найти_индекс_перечисления(а, &пл->имя_типа)
                        : -1;
                }
            } else if (перв) {
                // Явное значение «= выражение» → константа (только C-стиль enum).
                long зн;
                if (!вычислить_константу(а, перв, &зн)) {
                    ошибка_семантики(а, &вар->токен,
                        "значение варианта перечисления должно быть константой");
                    return;
                }
                текущее = зн;
            }
            в->значение = текущее;
            текущее++;
        }
    }
}

// Регистрирует именованные типы-указатели на функцию (сигнатуры для сверки).
static void собрать_типыфункций(Анализатор *а, Узел *корень)
{
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *узел = узел_ребёнок(корень, i);
        if (узел->тип != УЗЕЛ_ТИПФУНКЦИИ || узел->токен.длина == 0) continue;
        if (найти_индекс_типфункции(а, &узел->токен) >= 0) {
            ошибка_семантики(а, &узел->токен,
                "тип-указатель на функцию с таким именем уже объявлен");
            return;
        }
        if (а->число_типовфункций >= МАКС_ТИПФУНКЦИЙ)
            return (void)переполнение_таблицы(а, &узел->токен,
                                              "типов-функций", МАКС_ТИПФУНКЦИЙ);
        ОписаниеТипфункции *т = &а->типыфункций[а->число_типовфункций++];
        size_t n = узел->токен.длина < МАКС_ИМЯ - 1 ? узел->токен.длина : МАКС_ИМЯ - 1;
        memcpy(т->имя, узел->токен.начало, n);
        т->имя[n] = '\0';
        т->тип_возврата = узел->тип_данных;
        т->беззнаковый_возврата = узел->беззнаковый;
        т->указатели_возврата = узел->указатели;
        т->индекс_структуры_возврата =
            (узел->тип_данных == ТОКЕН_СТРУКТУРА)
                ? найти_индекс_структуры(а, &узел->имя_типа)
            : (узел->тип_данных == ТОКЕН_ПЕРЕЧИСЛЕНИЕ)
                ? найти_индекс_перечисления(а, &узел->имя_типа)
            : -1;
        т->число_параметров = 0;
        for (size_t j = 0; j < узел_число_детей(узел); ++j) {
            Узел *п = узел_ребёнок(узел, j);
            if (!п || п->тип != УЗЕЛ_ПАРАМЕТР) continue;
            if (т->число_параметров >= МАКС_ПАРАМЕТРОВ) break;
            ИнфоПараметра *ип = &т->параметры[т->число_параметров++];
            ип->тип = п->тип_данных;
            ип->беззнаковый = п->беззнаковый;
            ип->указатели = п->указатели;
            ип->срез = п->срез;
        }
    }
}

static void собрать_структуры(Анализатор *а, Узел *корень)
{
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *узел = узел_ребёнок(корень, i);
        if (узел->тип != УЗЕЛ_СТРУКТУРА || узел->токен.длина == 0) continue;
        if (найти_индекс_структуры(а, &узел->токен) >= 0) {
            ошибка_семантики(а, &узел->токен, "структура с таким именем уже объявлена");
            return;
        }
        if (а->число_структур >= МАКС_СТРУКТУР)
            return (void)переполнение_таблицы(а, &узел->токен,
                                              "структур", МАКС_СТРУКТУР);
        ОписаниеСтруктуры *с = &а->структуры[а->число_структур];
        size_t n = узел->токен.длина < МАКС_ИМЯ - 1 ? узел->токен.длина : МАКС_ИМЯ - 1;
        memcpy(с->имя, узел->токен.начало, n);
        с->имя[n] = '\0';
        с->имя_токен = узел->токен;  // указывает в исходник → переживёт до кодогена
        с->число_полей = 0;
        с->это_союз = узел->это_союз;
        с->внешний = узел->внешняя;
        // Шаблон «структура Имя<T>»: ведущие дети — УЗЕЛ_ТИПОПАРАМЕТР.
        с->обобщённая = узел_число_детей(узел) > 0
            && узел_ребёнок(узел, 0)
            && узел_ребёнок(узел, 0)->тип == УЗЕЛ_ТИПОПАРАМЕТР;
        // Деструктор из «[удалить = …]» (хранится в имя_типа узла структуры).
        с->есть_деструктор = узел->имя_типа.длина > 0;
        if (с->есть_деструктор) {
            size_t d = узел->имя_типа.длина < МАКС_ИМЯ - 1
                ? узел->имя_типа.длина : МАКС_ИМЯ - 1;
            memcpy(с->деструктор, узел->имя_типа.начало, d);
            с->деструктор[d] = '\0';
        }
        for (size_t j = 0; j < узел_число_детей(узел); ++j) {
            Узел *поле = узел_ребёнок(узел, j);
            if (!поле || поле->тип != УЗЕЛ_ПАРАМЕТР) continue;
            if (с->число_полей >= МАКС_ПОЛЕЙ) {
                переполнение_таблицы(а, &узел->токен, "полей структуры",
                                     МАКС_ПОЛЕЙ);
                return;
            }
            // Безопасность союза: поле-срез владело бы памятью, но какой член
            // активен — неизвестно, поэтому autofree/деструкция союза
            // невозможны без риска утечки/двойного free. Запрещаем.
            if (узел->это_союз && поле->срез) {
                ошибка_семантики(а, &поле->токен,
                    "поле-срез в союзе запрещено: владение памятью в союзе "
                    "небезопасно (неизвестно, какой член активен)");
            }
            ПолеСтруктуры *п = &с->поля[с->число_полей++];
            size_t m = поле->токен.длина < МАКС_ИМЯ - 1 ? поле->токен.длина : МАКС_ИМЯ - 1;
            memcpy(п->имя, поле->токен.начало, m);
            п->имя[m] = '\0';
            п->тип = поле->тип_данных;
            п->беззнаковый = поле->беззнаковый;
            п->указатели = поле->указатели;
            п->срез = поле->срез;
            п->буфер = поле->буфер;   // поле-«буфер<T>»: растущий буфер, владеет структура
            п->массив = поле->массив;
            п->размер_массива = поле->размер_массива;
            п->индекс_структуры =
                (поле->тип_данных == ТОКЕН_СТРУКТУРА)
                    ? найти_индекс_структуры(а, &поле->имя_типа)
                : (поле->тип_данных == ТОКЕН_ПЕРЕЧИСЛЕНИЕ)
                    ? найти_индекс_перечисления(а, &поле->имя_типа)
                : -1;
            // Поле-значение «внешнего типа» невозможно: его размер неизвестен.
            if (поле->тип_данных == ТОКЕН_СТРУКТУРА && п->индекс_структуры >= 0
                && п->указатели == 0
                && а->структуры[п->индекс_структуры].внешний) {
                ошибка_семантики(а, &поле->токен,
                    "поле внешнего типа возможно только как указатель "
                    "(устройство типа скрыто в C)");
            }
        }
        а->число_структур++;
    }
}

// ─── публичный API ───────────────────────────────────────────────────────────

// Инъекция сигнатур из Konda-интерфейса библиотеки (безопасный путь 2): каждую
// экспортируемую функцию библиотеки добавляем в таблицу сигнатур как обычную
// известную функцию — вызовы к ней получают полную типо- и владение-проверку
// вместо непрозрачной ветки внешнего C. Локальные определения уже добавлены
// (собрать_сигнатуры) и имеют приоритет при поиске.
static void внедрить_интерфейс_сигнатуры(Анализатор *а,
                                         const ТаблицаИнтерфейса *интерфейсы)
{
    if (!интерфейсы) return;
    size_t m = интерфейс_число(интерфейсы);
    for (size_t i = 0; i < m; ++i) {
        const ИнтФункция *иф = интерфейс_получить(интерфейсы, i);
        if (!иф) break;
        if (а->число_функций >= МАКС_ФУНКЦИЙ) {
            переполнение_таблицы(а, nullptr,
                "функций (с учётом библиотечных из «.и»)", МАКС_ФУНКЦИЙ);
            break;
        }

        // Именованные типы из «.и» уже реконструированы и собраны в таблицы
        // структур/перечислений (собрать_сигнатуры ran над корнем с ними) —
        // имя → индекс. Не найденный тип даёт -1: вызовы с ним просто не
        // получат сверки структурного индекса (tипизатор вернёт неизвестный).
        Токен имя_возврата = { 0 };
        if (иф->имя_типа_возврата[0]) {
            имя_возврата.начало = иф->имя_типа_возврата;
            имя_возврата.длина = strlen(иф->имя_типа_возврата);
        }
        СигнатураФункции *с = &а->функции[а->число_функций++];
        snprintf(с->имя, sizeof(с->имя), "%s", иф->имя);
        с->тип_возврата = иф->тип_возврата;
        с->беззнаковый = иф->беззнаковый_возврата;
        с->указатели_возврата = иф->указатели_возврата;
        с->срез = иф->срез_возврата;
        с->возврат_заимствован = иф->возврат_заимствован;  // §37 п.6 (cross-library)
        с->индекс_структуры_возврата =
            иф->тип_возврата == ТОКЕН_СТРУКТУРА ? найти_индекс_структуры(а, &имя_возврата)
            : иф->тип_возврата == ТОКЕН_ПЕРЕЧИСЛЕНИЕ ? найти_индекс_перечисления(а, &имя_возврата)
            : -1;
        с->число_параметров = 0;
        for (size_t j = 0; j < иф->число_параметров && с->число_параметров < МАКС_ПАРАМЕТРОВ; ++j) {
            const ИнтПараметр *п = &иф->параметры[j];
            с->владеет_параметра[с->число_параметров] = п->владеет;
            int индекс = -1;
            if (п->имя_типа[0]) {
                Токен имя_типа = { 0 };
                имя_типа.начало = п->имя_типа;
                имя_типа.длина = strlen(п->имя_типа);
                индекс = п->тип == ТОКЕН_СТРУКТУРА
                             ? найти_индекс_структуры(а, &имя_типа)
                             : найти_индекс_перечисления(а, &имя_типа);
            }
            с->параметры[с->число_параметров] = (ИнфоПараметра){
                п->тип, п->беззнаковый, п->указатели, п->срез, /*буфер=*/0,
                индекс, п->по_ссылке
            };
            с->число_параметров++;
        }
    }
}

// Поля-«типфункции» структур: индекс псевдонима заполняется ОТДЕЛЬНЫМ проходом
// после собрать_типыфункций (структуры собираются раньше типфункций, т.к. те
// ссылаются на структуры в типах возврата — обратной перестановкой порядок не
// решить). Индекс нужен глобальным константам-слушателям: поле-колбэк сверяет
// сигнатуру присваиваемой функции со своим «типфункции»-псевдонимом.
static void дозаполнить_поля_типфункций(Анализатор *а, Узел *корень)
{
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *узел = узел_ребёнок(корень, i);
        if (узел->тип != УЗЕЛ_СТРУКТУРА || узел->токен.длина == 0) continue;
        int инд = найти_индекс_структуры(а, &узел->токен);
        if (инд < 0) continue;
        ОписаниеСтруктуры *оп = &а->структуры[инд];
        for (size_t j = 0; j < узел_число_детей(узел); ++j) {
            Узел *поле = узел_ребёнок(узел, j);
            if (!поле || поле->тип != УЗЕЛ_ПАРАМЕТР
                || поле->тип_данных != ТОКЕН_ФУНКУКАЗАТЕЛЬ) continue;
            for (size_t k = 0; k < оп->число_полей; ++k) {
                if (байты_равны(оп->поля[k].имя, strlen(оп->поля[k].имя),
                                поле->токен.начало, поле->токен.длина)) {
                    оп->поля[k].индекс_структуры =
                        найти_индекс_типфункции(а, &поле->имя_типа);
                    break;
                }
            }
        }
    }
}

// Глобальные константы верхнего уровня: «конст Тип ИМЯ = константное-выражение».
// Всё СТАТИЧЕСКОЕ: значение вычисляется на компиляции, в C уходит
// «static const …», рантайм-цены нет. Изменяемых глобалов по-прежнему НЕТ
// (инвариант №4 — «гонки невыразимы» держится на этом): любое верхнеуровневое
// объявление без «конст» — ошибка. Допустимые формы инициализатора:
//   * примитив — константное выражение (свёртка компилятором);
//   * «символ*» — строковый литерал (.rodata, иммутабелен);
//   * структура — литерал полей из констант/строковых литералов/имён функций
//     (последнее — для таблиц колбэков в стиле wl_listener; сигнатура функции
//     сверяется с «типфункции»-полем статически).
// Рекурсивно: значение годно как часть КОНСТАНТНОГО агрегата (конст-массив
// структур, вложенные массивы/структуры в полях)? Листья — строковый литерал,
// свёрнутая константа, ЛИБО бареидентификатор (enum-константа из #содержит-
// заголовка: транспилятор её не сворачивает, но передаёт в C, где она валидна) и
// унарный минус над таким. Агрегаты «{…}» обходятся рекурсивно. Вызовы/сложные
// выражения (нельзя в статическом инициализаторе C) — нет.
static int конст_агрегат_ок(Анализатор *а, Узел *зн)
{
    if (!зн) return 0;
    switch (зн->тип) {
        case УЗЕЛ_СТРОКА:
        case УЗЕЛ_ЧИСЛО:
        case УЗЕЛ_ИДЕНТИФИКАТОР:   // enum-константа заголовка (пропускаем в C)
            return 1;
        case УЗЕЛ_НУЛЬ:
            return 1;
        case УЗЕЛ_УНОП:
            return узел_число_детей(зн) == 1
                && конст_агрегат_ок(а, узел_ребёнок(зн, 0));
        case УЗЕЛ_ЛИТЕРАЛ_МАССИВА:
            for (size_t i = 0; i < узел_число_детей(зн); ++i)
                if (!конст_агрегат_ок(а, узел_ребёнок(зн, i))) return 0;
            return 1;
        case УЗЕЛ_ЛИТЕРАЛ_СТРУКТУРЫ:
            for (size_t i = 0; i < узел_число_детей(зн); ++i) {
                Узел *п = узел_ребёнок(зн, i);   // УЗЕЛ_ИНИЦ_ПОЛЯ
                if (узел_число_детей(п) == 0
                    || !конст_агрегат_ок(а, узел_ребёнок(п, 0))) return 0;
            }
            return 1;
        default: {
            long тмп;
            return вычислить_константу(а, зн, &тмп);   // прочее — только свёртка
        }
    }
}

static void собрать_глобальные_константы(Анализатор *а, Узел *корень)
{
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *узел = узел_ребёнок(корень, i);
        if (узел->тип != УЗЕЛ_ОБЪЯВЛЕНИЕ) continue;

        // «атом<T>» — ЕДИНСТВЕННЫЙ изменяемый глобал. Атомарный доступ (_Atomic в
        // C) → гонок ДАННЫХ нет по построению, инвариант №4 цел (memory-safe даже
        // с потоками). T — целочисленный примитив (lock-free атомик); инициализатор
        // — константа. Записывается как ИЗМЕНЯЕМЫЙ символ (присваивания разрешены).
        if (узел->атом) {
            if (узел->указатели > 0 || узел->массив || узел->срез) {
                ошибка_семантики(а, &узел->токен,
                    "«атом<T>»: T — целочисленный примитив (указатель/массив/срез "
                    "нельзя)");
                if (а->ошибки) собрать_ошибку(а);
                continue;
            }
            ИнфоТипа тэ = { узел->тип_данных, 0, узел->беззнаковый, 0, -1 };
            if (!тип_целочисленный(тэ) && узел->тип_данных != ТОКЕН_ЛОГИЧЕСКИЙ) {
                ошибка_семантики(а, &узел->токен,
                    "«атом<T>»: T — целочисленный тип (целоеN/байт/логический)");
                if (а->ошибки) собрать_ошибку(а);
                continue;
            }
            long ат_знач = 0;
            if (узел_число_детей(узел) > 0
                && !вычислить_константу(а, узел_ребёнок(узел, 0), &ат_знач)) {
                ошибка_семантики(а, &узел->токен,
                    "инициализатор «атом<T>» — константное выражение");
                if (а->ошибки) собрать_ошибку(а);
                continue;
            }
            if (а->число_глобальных >= МАКС_ГЛОБАЛЬНЫХ_КОНСТ) {
                переполнение_таблицы(а, &узел->токен,
                    "глобальных конст/атомиков", МАКС_ГЛОБАЛЬНЫХ_КОНСТ);
                return;
            }
            Символ *са = &а->глобальные[а->число_глобальных++];
            memset(са, 0, sizeof *са);
            size_t na = узел->токен.длина < МАКС_ИМЯ - 1 ? узел->токен.длина
                                                         : МАКС_ИМЯ - 1;
            memcpy(са->имя, узел->токен.начало, na);
            са->имя[na] = '\0';
            са->тип = узел->тип_данных;
            са->беззнаковый = узел->беззнаковый;
            са->индекс_структуры = -1;
            са->атом = 1;
            са->неизменяемый = 0;   // ИЗМЕНЯЕМЫЙ: присваивания атому разрешены
            са->инициализирована = 1;
            continue;
        }

        if (!узел->неизменяемый) {
            ошибка_семантики(а, &узел->токен,
                "глобальных переменных в Konda нет (иначе гонки данных стали бы "
                "выразимыми); на верхнем уровне допустима только константа "
                "«конст Тип ИМЯ = …» или атомик «атом<T> ИМЯ = …»");
            if (а->ошибки) собрать_ошибку(а);
            continue;
        }
        if (узел->выравнивание != 0
            && (узел->выравнивание <= 0
                || (узел->выравнивание & (узел->выравнивание - 1)) != 0)) {
            char вм[160];
            snprintf(вм, sizeof(вм),
                "«выровнять(%ld)»: выравнивание должно быть положительной "
                "степенью двойки (1, 2, 4, 8, 16, …)", узел->выравнивание);
            ошибка_семантики(а, &узел->токен, вм);
            if (а->ошибки) собрать_ошибку(а);
            continue;
        }
        if (узел->срез || узел->поток || узел->возможно) {
            ошибка_семантики(а, &узел->токен,
                "глобальная константа может быть примитивом, «символ*» со "
                "строковым литералом, структурой-литералом или массивом "
                "константных элементов (срез/поток/возможно — нельзя: они "
                "требуют владения или рантайма)");
            if (а->ошибки) собрать_ошибку(а);
            continue;
        }
        if (узел_число_детей(узел) == 0) {
            ошибка_семантики(а, &узел->токен,
                "глобальная константа обязана иметь инициализатор");
            if (а->ошибки) собрать_ошибку(а);
            continue;
        }
        if (а->число_глобальных >= МАКС_ГЛОБАЛЬНЫХ_КОНСТ)
            return (void)переполнение_таблицы(а, &узел->токен,
                "глобальных конст/атомиков", МАКС_ГЛОБАЛЬНЫХ_КОНСТ);
        Узел *иниц = узел_ребёнок(узел, 0);
        long значение = 0;
        int значение_известно = 0;
        int индекс_стр = -1;

        // Глобальный конст-МАССИВ: «конст Тип ИМЯ[N] = { … }». Иммутабельная
        // таблица (charset/строки/вершины/структуры) — «static const T ИМЯ[N]» в C,
        // нулевая рантайм-цена, инвариант №4 цел (значение не меняется). Элемент —
        // примитив, «символ*» (строковый литерал) ЛИБО СТРУКТУРА (вложенный литерал
        // полей, поля рекурсивно константны/строки/вложенные агрегаты).
        if (узел->массив) {
            // «имя[]» (выводимый размер) допустим ТОЛЬКО с «встроить(…)».
            if (узел->выводимый_размер && иниц->тип != УЗЕЛ_ВСТРОИТЬ) {
                ошибка_семантики(а, &узел->токен,
                    "массив с пустыми «[]» (выводимый размер) допустим только с "
                    "инициализатором «встроить(\"файл\")»; иначе укажите размер «[N]»");
                if (а->ошибки) собрать_ошибку(а);
                continue;
            }
            // «конст неподписанный целое8 ИМЯ[] = встроить("файл")» (C23 #embed):
            // байты файла в .rodata, размер выводит C. Длина транспилятору
            // неизвестна → индексация через рантайм-проверку по sizeof.
            if (иниц->тип == УЗЕЛ_ВСТРОИТЬ) {
                if (!(узел->выводимый_размер && узел->тип_данных == ТОКЕН_ЦЕЛОЕ8
                      && узел->беззнаковый && узел->указатели == 0)) {
                    ошибка_семантики(а, &узел->токен,
                        "«встроить(…)» требует объявления «неподписанный целое8 ИМЯ[] "
                        "= встроить(\"файл\")» (байтовый массив с выводимым размером)");
                    if (а->ошибки) собрать_ошибку(а);
                    continue;
                }
                Символ *св = &а->глобальные[а->число_глобальных++];
                memset(св, 0, sizeof *св);
                size_t nв = узел->токен.длина < МАКС_ИМЯ - 1 ? узел->токен.длина
                                                             : МАКС_ИМЯ - 1;
                memcpy(св->имя, узел->токен.начало, nв);
                св->имя[nв] = '\0';
                св->тип = ТОКЕН_ЦЕЛОЕ8;
                св->беззнаковый = 1;
                св->индекс_структуры = -1;
                св->массив = 1;
                св->неизменяемый = 1;
                св->инициализирована = 1;
                св->длина_известна = 0;   // размер выводит C → границы в рантайме
                св->безопасен_для_возврата = 1;
                continue;
            }
            // Массив СТРУКТУР: каждый элемент — литерал полей, рекурсивно
            // константный (проверяем конст_агрегат_ок; C-компилятор доопределит
            // типы). Индекс структуры кладём в символ (для доступа «т[i].поле»).
            if (узел->тип_данных == ТОКЕН_СТРУКТУРА) {
                int инд_сэ = найти_индекс_структуры(а, &узел->имя_типа);
                if (инд_сэ < 0) {
                    ошибка_семантики(а, &узел->токен,
                        "неизвестная структура-элемент конст-массива");
                    if (а->ошибки) собрать_ошибку(а);
                    continue;
                }
                if (иниц->тип != УЗЕЛ_ЛИТЕРАЛ_МАССИВА
                    || (long)узел_число_детей(иниц) > узел->размер_массива) {
                    ошибка_семантики(а, &узел->токен,
                        "конст-массив структур: литерал «{ {…}, … }» не длиннее размера");
                    if (а->ошибки) собрать_ошибку(а);
                    continue;
                }
                int сбой_с = 0;
                for (size_t j = 0; j < узел_число_детей(иниц); ++j) {
                    Узел *эл = узел_ребёнок(иниц, j);
                    if (эл->тип != УЗЕЛ_ЛИТЕРАЛ_СТРУКТУРЫ || !конст_агрегат_ок(а, эл)) {
                        ошибка_семантики(а, &эл->токен,
                            "элемент конст-массива структур — литерал полей "
                            "из констант/строк/вложенных агрегатов");
                        сбой_с = 1; break;
                    }
                }
                if (сбой_с) { if (а->ошибки) собрать_ошибку(а); continue; }
                Символ *сс = &а->глобальные[а->число_глобальных++];
                memset(сс, 0, sizeof *сс);
                size_t ns = узел->токен.длина < МАКС_ИМЯ - 1 ? узел->токен.длина
                                                             : МАКС_ИМЯ - 1;
                memcpy(сс->имя, узел->токен.начало, ns);
                сс->имя[ns] = '\0';
                сс->тип = ТОКЕН_СТРУКТУРА;
                сс->индекс_структуры = инд_сэ;
                сс->массив = 1;
                сс->неизменяемый = 1;
                сс->инициализирована = 1;
                сс->длина_известна = 1;
                сс->длина = узел->размер_массива;
                сс->безопасен_для_возврата = 1;
                continue;
            }
            if (иниц->тип != УЗЕЛ_ЛИТЕРАЛ_МАССИВА) {
                ошибка_семантики(а, &узел->токен,
                    "глобальный конст-массив инициализируется литералом "
                    "«{ значение, … }»");
                if (а->ошибки) собрать_ошибку(а);
                continue;
            }
            if ((long)узел_число_детей(иниц) > узел->размер_массива) {
                ошибка_семантики(а, &узел->токен,
                    "в литерале конст-массива больше значений, чем его размер");
                if (а->ошибки) собрать_ошибку(а);
                continue;
            }
            int эл_строка = (узел->тип_данных == ТОКЕН_ТИП_СИМВОЛ
                             && узел->указатели == 1);
            int сбой_м = 0;
            for (size_t j = 0; j < узел_число_детей(иниц); ++j) {
                Узел *эл = узел_ребёнок(иниц, j);
                long тмп;
                if (эл_строка) {
                    if (эл->тип != УЗЕЛ_СТРОКА) {
                        ошибка_семантики(а, &эл->токен,
                            "элемент конст-массива «символ*» — строковый литерал");
                        сбой_м = 1; break;
                    }
                } else if (узел->указатели > 0) {
                    ошибка_семантики(а, &узел->токен,
                        "глобальный конст-массив указателей — только «символ*» "
                        "со строковыми литералами");
                    сбой_м = 1; break;
                } else if (!вычислить_константу(а, эл, &тмп)) {
                    ошибка_семантики(а, &эл->токен,
                        "элемент конст-массива должен быть константным выражением");
                    сбой_м = 1; break;
                }
            }
            if (сбой_м) { if (а->ошибки) собрать_ошибку(а); continue; }
            Символ *см = &а->глобальные[а->число_глобальных++];
            memset(см, 0, sizeof *см);
            size_t nm = узел->токен.длина < МАКС_ИМЯ - 1 ? узел->токен.длина
                                                         : МАКС_ИМЯ - 1;
            memcpy(см->имя, узел->токен.начало, nm);
            см->имя[nm] = '\0';
            см->тип = узел->тип_данных;
            см->указатели = узел->указатели;
            см->беззнаковый = узел->беззнаковый;
            см->индекс_структуры = -1;
            см->массив = 1;
            см->неизменяемый = 1;
            см->инициализирована = 1;
            см->длина_известна = 1;
            см->длина = узел->размер_массива;
            см->безопасен_для_возврата = 1;   // статика переживёт возврат
            continue;
        }

        if (узел->тип_данных == ТОКЕН_СТРУКТУРА) {
            индекс_стр = найти_индекс_структуры(а, &узел->имя_типа);
            if (индекс_стр < 0 || иниц->тип != УЗЕЛ_ЛИТЕРАЛ_СТРУКТУРЫ
                || узел->указатели > 0) {
                ошибка_семантики(а, &узел->токен,
                    "глобальная константа-структура задаётся литералом полей "
                    "«{ поле = значение, … }» известной структуры (по значению)");
                if (а->ошибки) собрать_ошибку(а);
                continue;
            }
            ОписаниеСтруктуры *оп = &а->структуры[индекс_стр];
            int сбой = 0;
            for (size_t j = 0; j < узел_число_детей(иниц) && !сбой; ++j) {
                Узел *п = узел_ребёнок(иниц, j);
                ПолеСтруктуры *поле = nullptr;
                if (п->токен.длина == 0) {
                    // Позиционный элемент — поле по индексу.
                    if (j < оп->число_полей) поле = &оп->поля[j];
                } else {
                    for (size_t k = 0; k < оп->число_полей; ++k)
                        if (байты_равны(оп->поля[k].имя, strlen(оп->поля[k].имя),
                                        п->токен.начало, п->токен.длина))
                            поле = &оп->поля[k];
                }
                Узел *зн = узел_число_детей(п) > 0 ? узел_ребёнок(п, 0) : nullptr;
                if (!поле || !зн) {
                    ошибка_семантики(а, &п->токен,
                        "неизвестное поле в литерале глобальной константы");
                    сбой = 1;
                    break;
                }
                long тмп;
                if (поле->тип == ТОКЕН_ФУНКУКАЗАТЕЛЬ) {
                    // Поле-колбэк: значение — имя функции, сигнатура сверяется
                    // с «типфункции»-псевдонимом поля (статически).
                    СигнатураФункции *сф = зн->тип == УЗЕЛ_ИДЕНТИФИКАТОР
                        ? найти_сигнатуру_по_имени(а, зн->токен.начало,
                                                   зн->токен.длина)
                        : nullptr;
                    int тф = поле->индекс_структуры;
                    if (!сф || тф < 0
                        || !сигнатура_совпадает_с_типфункцией(сф,
                                &а->типыфункций[тф])) {
                        ошибка_семантики(а, &зн->токен,
                            "поле-колбэк глобальной константы: ожидалось имя "
                            "функции с сигнатурой «типфункции»-поля");
                        сбой = 1;
                    }
                } else if (зн->тип == УЗЕЛ_СТРОКА) {
                    if (!(поле->тип == ТОКЕН_ТИП_СИМВОЛ && поле->указатели == 1)) {
                        ошибка_семантики(а, &зн->токен,
                            "строковый литерал годен только полю «символ*»");
                        сбой = 1;
                    }
                } else if (!вычислить_константу(а, зн, &тмп)) {
                    ошибка_семантики(а, &зн->токен,
                        "поле глобальной константы должно быть константным "
                        "выражением, строковым литералом или именем функции");
                    сбой = 1;
                }
            }
            if (сбой) {
                if (а->ошибки) собрать_ошибку(а);
                continue;
            }
        } else if (узел->указатели > 0) {
            // Указатель: только «символ*» на строковый литерал (.rodata).
            if (!(узел->тип_данных == ТОКЕН_ТИП_СИМВОЛ && узел->указатели == 1
                  && иниц->тип == УЗЕЛ_СТРОКА)) {
                ошибка_семантики(а, &узел->токен,
                    "глобальная константа-указатель — только «символ*» со "
                    "строковым литералом");
                if (а->ошибки) собрать_ошибку(а);
                continue;
            }
        } else if (!вычислить_константу(а, иниц, &значение)) {
            ошибка_семантики(а, &узел->токен,
                "инициализатор глобальной константы должен быть константным "
                "выражением (вычислимым на компиляции)");
            if (а->ошибки) собрать_ошибку(а);
            continue;
        } else {
            значение_известно = 1;
        }

        Символ *с = &а->глобальные[а->число_глобальных++];
        memset(с, 0, sizeof *с);
        size_t n = узел->токен.длина < МАКС_ИМЯ - 1 ? узел->токен.длина
                                                    : МАКС_ИМЯ - 1;
        memcpy(с->имя, узел->токен.начало, n);
        с->имя[n] = '\0';
        с->тип = узел->тип_данных;
        с->указатели = узел->указатели;
        с->беззнаковый = узел->беззнаковый;
        с->индекс_структуры = индекс_стр;
        с->неизменяемый = 1;
        с->инициализирована = 1;
        с->из_литерала = узел->указатели > 0;   // строковый литерал → .rodata
        с->безопасен_для_возврата = 1;          // статика переживёт любой возврат
        с->значение_известно = значение_известно;
        с->значение = значение;
    }
}

// ─── типизированные слушатели ────────────────────────────────────────────────

static int найти_слушатель(const Анализатор *а, const Токен *имя)
{
    for (size_t i = 0; i < а->число_слушателей; ++i)
        if (байты_равны(а->слушатель_типы[i].имя,
                        strlen(а->слушатель_типы[i].имя),
                        имя->начало, имя->длина))
            return (int)i;
    return -1;
}

static int найти_экземпляр_слушателя(const Анализатор *а, const Токен *имя)
{
    for (size_t i = 0; i < а->число_экземпляров; ++i)
        if (байты_равны(а->слушатель_экземпляры[i].имя,
                        strlen(а->слушатель_экземпляры[i].имя),
                        имя->начало, имя->длина))
            return (int)i;
    return -1;
}

// Собирает типы слушателей: «внешний слушатель<T> Имя для C_тип { … }».
static void собрать_слушатели(Анализатор *а, Узел *корень)
{
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *узел = узел_ребёнок(корень, i);
        if (узел->тип != УЗЕЛ_СЛУШАТЕЛЬ_ТИП || узел->токен.длина == 0) continue;
        if (найти_слушатель(а, &узел->токен) >= 0) {
            ошибка_семантики(а, &узел->токен, "слушатель с таким именем уже объявлен");
            if (а->ошибки) собрать_ошибку(а);
            continue;
        }
        if (а->число_слушателей >= МАКС_СЛУШАТЕЛЕЙ)
            return (void)переполнение_таблицы(а, &узел->токен,
                "типов-слушателей", МАКС_СЛУШАТЕЛЕЙ);
        ОписаниеСлушателя *с = &а->слушатель_типы[а->число_слушателей++];
        size_t n = узел->токен.длина < МАКС_ИМЯ - 1 ? узел->токен.длина : МАКС_ИМЯ - 1;
        memcpy(с->имя, узел->токен.начало, n);
        с->имя[n] = '\0';
        с->userdata_тип = узел->тип_данных;
        с->userdata_указатели = 0;   // T по значению (v1)
        с->userdata_индекс = (узел->тип_данных == ТОКЕН_СТРУКТУРА)
            ? найти_индекс_структуры(а, &узел->имя_типа) : -1;
        if (узел->тип_данных == ТОКЕН_СТРУКТУРА && с->userdata_индекс < 0) {
            ошибка_семантики(а, &узел->имя_типа,
                "неизвестный userdata-тип в «слушатель<T>»");
            if (а->ошибки) собрать_ошибку(а);
        }
        с->c_имя[0] = '\0';
        if (узел->собственное_имя) {
            size_t m = strlen(узел->собственное_имя);
            if (m >= МАКС_ИМЯ) m = МАКС_ИМЯ - 1;
            memcpy(с->c_имя, узел->собственное_имя, m);
            с->c_имя[m] = '\0';
        }
        с->узел = узел;
    }
}

// Регистрирует экземпляр «Имя экз = { поле = функция… }» и проверяет, что
// функции существуют, а их первый параметр — «изменяемый/чтение T».
static void зарегистрировать_экземпляр(Анализатор *а, Узел *узел)
{
    int ит = найти_слушатель(а, &узел->имя_типа);
    if (ит < 0) {
        ошибка_семантики(а, &узел->имя_типа, "неизвестный тип слушателя");
        if (а->ошибки) собрать_ошибку(а);
        return;
    }
    if (найти_экземпляр_слушателя(а, &узел->токен) >= 0) return;  // уже
    if (а->число_экземпляров >= МАКС_СЛУШАТЕЛЕЙ)
        return (void)переполнение_таблицы(а, &узел->токен,
            "экземпляров слушателей", МАКС_СЛУШАТЕЛЕЙ);
    {
        ЭкземплярСлушателя *э = &а->слушатель_экземпляры[а->число_экземпляров++];
        size_t n = узел->токен.длина < МАКС_ИМЯ - 1 ? узел->токен.длина : МАКС_ИМЯ - 1;
        memcpy(э->имя, узел->токен.начало, n);
        э->имя[n] = '\0';
        э->индекс_типа = ит;
    }
    ОписаниеСлушателя *ст = &а->слушатель_типы[ит];
    // Каждое поле экземпляра — имя функции; сверяем, что первый параметр её —
    // «изменяемый T» (ключ тип-безопасности: тело колбэка получит T*, что и
    // передаст трампулин). Прочие параметры сверит C-компилятор при вызове.
    for (size_t i = 0; i < узел_число_детей(узел); ++i) {
        Узел *иниц = узел_ребёнок(узел, i);
        if (иниц->тип != УЗЕЛ_ИНИЦ_ПОЛЯ || узел_число_детей(иниц) == 0) continue;
        Узел *фн = узел_ребёнок(иниц, 0);
        const СигнатураФункции *сф = найти_сигнатуру_по_имени(а,
            фн->токен.начало, фн->токен.длина);
        if (!сф) {
            ошибка_семантики(а, &фн->токен,
                "колбэк экземпляра слушателя — имя объявленной функции");
            if (а->ошибки) собрать_ошибку(а);
            continue;
        }
        if (сф->число_параметров == 0
            || сф->параметры[0].тип != ст->userdata_тип
            || (ст->userdata_тип == ТОКЕН_СТРУКТУРА
                && сф->параметры[0].индекс_структуры != ст->userdata_индекс)
            || сф->параметры[0].по_ссылке == 0) {
            ошибка_семантики(а, &фн->токен,
                "первый параметр колбэка должен быть «изменяемый T»/«чтение T» "
                "(T — userdata-тип слушателя): каст void*→T прячет трампулин");
            if (а->ошибки) собрать_ошибку(а);
        }
    }
}

// Пред-проход: регистрирует ВСЕ экземпляры слушателей (верхний уровень и тела
// функций), чтобы «слушать» находило экземпляр независимо от порядка.
static void собрать_экземпляры_слушателей(Анализатор *а, Узел *узел)
{
    if (!узел) return;
    if (узел->тип == УЗЕЛ_СЛУШАТЕЛЬ_ЭКЗ) зарегистрировать_экземпляр(а, узел);
    for (size_t i = 0; i < узел_число_детей(узел); ++i)
        собрать_экземпляры_слушателей(а, узел_ребёнок(узел, i));
}

// ─── проход вывода тип-аргументов (гибрид, до мономорфизации) ─────────────────

// Заводит символ по узлу (объявление/параметр) — минимум, чтобы
// типизировать_выражение верно резолвил идентификаторы-аргументы обобщённых
// вызовов. Индекс структуры/перечисления проставляем отдельно (объявить_символ
// его не принимает).
static void вывод_объявить(Анализатор *а, Узел *узел)
{
    if (!узел || узел->токен.длина == 0) return;
    int инд = -1;
    if (узел->тип_данных == ТОКЕН_СТРУКТУРА)
        инд = найти_индекс_структуры(а, &узел->имя_типа);
    else if (узел->тип_данных == ТОКЕН_ПЕРЕЧИСЛЕНИЕ)
        инд = найти_индекс_перечисления(а, &узел->имя_типа);
    объявить_символ(а, узел->токен.начало, узел->токен.длина,
        узел->тип_данных, узел->указатели, узел->массив, узел->беззнаковый,
        узел->срез, 0, 0, &узел->токен, 0, 0);
    Символ *с = найти_символ(а, узел->токен.начало, узел->токен.длина);
    if (с) с->индекс_структуры = инд;
}

// Плоский пред-обход тела не-шаблонной функции: объявляет переменные по мере
// встречи и типизирует обобщённые вызовы (там срабатывает вывод тип-аргументов).
// Область НЕ выталкивается по блокам (over-approx: имя видно и после блока) — на
// точность вывода это влияет лишь консервативно, а корректность даёт проход 2.
static void вывод_обход(Анализатор *а, Узел *узел)
{
    if (!узел) return;
    if (узел->тип == УЗЕЛ_ОБЪЯВЛЕНИЕ) {
        вывод_объявить(а, узел);
        for (size_t i = 0; i < узел_число_детей(узел); ++i) {
            Узел *реб = узел_ребёнок(узел, i);
            if (реб && реб->тип == УЗЕЛ_ТИПОАРГУМЕНТ) continue;  // не инициализатор
            вывод_обход(а, реб);  // инициализатор может содержать обобщённый вызов
        }
        return;
    }
    if (узел->тип == УЗЕЛ_ВЫЗОВ) {
        типизировать_выражение(а, узел);  // выводит тип-аргументы (и вложенных вызовов)
        return;  // аргументы уже типизированы — повторно не спускаемся
    }
    for (size_t i = 0; i < узел_число_детей(узел); ++i)
        вывод_обход(а, узел_ребёнок(узел, i));
}

int вывести_типоаргументы(Узел *корень, const ТаблицаВнешних *внешние,
                          const ТаблицаИнтерфейса *интерфейсы)
{
    if (!корень) return 1;
    Диагностика мусор = {0};
    Анализатор а = { .диаг = &мусор, .внешние = внешние, .режим_вывода = 1 };
    собрать_перечисления(&а, корень);
    собрать_структуры(&а, корень);
    собрать_типыфункций(&а, корень);
    собрать_сигнатуры(&а, корень);
    внедрить_интерфейс_сигнатуры(&а, интерфейсы);
    собрать_аллокаторы(&а, корень);
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *ф = узел_ребёнок(корень, i);
        if (!ф || ф->тип != УЗЕЛ_ФУНКЦИЯ || ф->внешняя) continue;
        // Шаблоны пропускаем: их тела с тип-параметрами анализируются на проходе 2
        // (после мономорфизации); внутри шаблона вывод не делаем — явные «<>».
        int шаблон = узел_число_детей(ф) > 0 && узел_ребёнок(ф, 0)
                     && узел_ребёнок(ф, 0)->тип == УЗЕЛ_ТИПОПАРАМЕТР;
        if (шаблон) continue;
        а.число_символов = 0;
        а.глубина = 0;
        войти_в_область(&а);
        for (size_t j = 0; j < узел_число_детей(ф); ++j) {
            Узел *пар = узел_ребёнок(ф, j);
            if (пар && пар->тип == УЗЕЛ_ПАРАМЕТР) вывод_объявить(&а, пар);
        }
        size_t nc = узел_число_детей(ф);
        Узел *тело = nc ? узел_ребёнок(ф, nc - 1) : nullptr;
        if (тело && тело->тип == УЗЕЛ_БЛОК) вывод_обход(&а, тело);
        выйти_из_области(&а);
    }
    return 1;
}

// ─── Предупреждение о нехвостовой рекурсии (опционально, по флагу CLI) ────────

// Совпадают ли тексты двух токенов-имён.
static int два_токена_равны(const Токен *а, const Токен *б)
{
    return а && б && а->длина == б->длина && а->длина > 0
        && memcmp(а->начало, б->начало, а->длина) == 0;
}

// Рекурсивно считает вызовы функции с именем «имя» в поддереве. Если «только_хвост»
// — считает лишь те, что стоят прямым значением «вернуть» (хвостовая позиция).
static size_t считать_вызовы(const Узел *узел, const Токен *имя, int только_хвост)
{
    if (!узел) return 0;
    size_t всего = 0;
    if (только_хвост) {
        if (узел->тип == УЗЕЛ_ВОЗВРАТ && узел_число_детей(узел) > 0) {
            const Узел *знач = узел_ребёнок(узел, 0);
            if (знач && знач->тип == УЗЕЛ_ВЫЗОВ && два_токена_равны(&знач->токен, имя))
                всего++;
        }
    } else if (узел->тип == УЗЕЛ_ВЫЗОВ && два_токена_равны(&узел->токен, имя)) {
        всего++;
    }
    for (size_t i = 0; i < узел_число_детей(узел); ++i)
        всего += считать_вызовы(узел_ребёнок(узел, i), имя, только_хвост);
    return всего;
}

// Пригодна ли функция к КОНДА_ХВОСТ (те же гейты, что в кодогене): возврат —
// примитив/указатель (не структура/перечисление/срез), нет ref/out/чтение- и
// владеющих-срез-параметров. Только тогда хвостовая само-рекурсия реально
// оптимизируется в переход, и предупреждать не о чем.
static int функция_пригодна_к_хвосту(const Узел *ф)
{
    if (ф->срез || ф->тип_данных == ТОКЕН_СТРУКТУРА
        || ф->тип_данных == ТОКЕН_ПЕРЕЧИСЛЕНИЕ)
        return 0;
    for (size_t i = 0; i < узел_число_детей(ф); ++i) {
        const Узел *пар = узел_ребёнок(ф, i);
        if (!пар || пар->тип != УЗЕЛ_ПАРАМЕТР) continue;
        if (пар->по_ссылке) return 0;            // ref/out/чтение
        if (пар->владеет && пар->срез) return 0; // владеющий-срез параметр
    }
    return 1;
}

void предупредить_о_нехвостовой_рекурсии(Узел *корень, ДинМассив *предупреждения)
{
    if (!корень || !предупреждения) return;

    // Собираем определения функций верхнего уровня (с телом, не «внешняя»).
    size_t n = 0;
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *у = узел_ребёнок(корень, i);
        if (у->тип == УЗЕЛ_ФУНКЦИЯ && !у->внешняя && у->токен.длина > 0
            && !у->это_main)
            n++;
    }
    if (n == 0) return;

    Узел **функции = calloc(n, sizeof(*функции));
    if (!функции) return;
    size_t k = 0;
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        Узел *у = узел_ребёнок(корень, i);
        if (у->тип == УЗЕЛ_ФУНКЦИЯ && !у->внешняя && у->токен.длина > 0
            && !у->это_main)
            функции[k++] = у;
    }

    // Матрица достижимости по графу вызовов — только при разумном числе функций
    // (иначе n² памяти); при переполнении лимита взаимную рекурсию не ищем,
    // остаётся детект прямой (best-effort деградация, безопасность не страдает —
    // само переполнение всё равно перехватит защита стека).
    const size_t ЛИМИТ = 1024;
    unsigned char *дост = (n <= ЛИМИТ) ? calloc(n * n, 1) : nullptr;
    if (дост) {
        for (size_t i = 0; i < n; ++i)
            for (size_t j = 0; j < n; ++j)
                if (считать_вызовы(функции[i], &функции[j]->токен, 0) > 0)
                    дост[i * n + j] = 1;
        // Транзитивное замыкание (Уоршелл): дост[i][j] = i достигает j вызовами.
        for (size_t m = 0; m < n; ++m)
            for (size_t i = 0; i < n; ++i)
                if (дост[i * n + m])
                    for (size_t j = 0; j < n; ++j)
                        if (дост[m * n + j]) дост[i * n + j] = 1;
    }

    for (size_t i = 0; i < n; ++i) {
        Узел *ф = функции[i];
        const Токен *имя = &ф->токен;
        // Взаимная рекурсия: существует j ≠ i с i→j и j→i.
        int взаимная = 0;
        if (дост) {
            for (size_t j = 0; j < n; ++j)
                if (j != i && дост[i * n + j] && дост[j * n + i]) { взаимная = 1; break; }
        }
        size_t всего_само = считать_вызовы(ф, имя, 0);
        size_t хвост_само = считать_вызовы(ф, имя, 1);
        int прямая = всего_само > 0;

        Диагностика д = {0};
        д.строка = имя->строка;
        д.колонка = имя->позиция_в_строке;
        if (взаимная) {
            snprintf(д.сообщение, sizeof(д.сообщение),
                     "функция «%.*s» участвует во взаимной рекурсии — глубина не "
                     "ограничена, при большой рекурсии возможно переполнение стека "
                     "(перехватится защитой стека → чистая паника)",
                     (int)имя->длина, имя->начало);
            дин_массив_добавить(предупреждения, &д);
        } else if (прямая) {
            // Прямая само-рекурсия. Молчим, только если ВСЕ само-вызовы —
            // хвостовые и функция пригодна к КОНДА_ХВОСТ (тогда переполнения нет
            // по построению). Иначе предупреждаем.
            int безопасна = (всего_само == хвост_само)
                            && функция_пригодна_к_хвосту(ф);
            if (!безопасна) {
                snprintf(д.сообщение, sizeof(д.сообщение),
                         "функция «%.*s» рекурсивна и не является (полностью) "
                         "хвостовой — при большой глубине возможно переполнение "
                         "стека (перехватится защитой стека); для гарантии сделайте "
                         "рекурсивный вызов хвостовым: «вернуть %.*s(…)»",
                         (int)имя->длина, имя->начало,
                         (int)имя->длина, имя->начало);
                дин_массив_добавить(предупреждения, &д);
            }
        }
    }

    free(дост);
    free(функции);
}

int анализировать_полный_и(Узел *корень, Диагностика *диаг,
                           const ТаблицаВнешних *внешние,
                           const ТаблицаИнтерфейса *интерфейсы,
                           ДинМассив *предупреждения, ДинМассив *ошибки)
{
    Анализатор а = { .диаг = диаг, .внешние = внешние,
                     .предупреждения = предупреждения, .ошибки = ошибки };
    собрать_перечисления(&а, корень);
    собрать_структуры(&а, корень);
    собрать_типыфункций(&а, корень);
    собрать_сигнатуры(&а, корень);
    внедрить_интерфейс_сигнатуры(&а, интерфейсы);
    собрать_аллокаторы(&а, корень);
    дозаполнить_поля_типфункций(&а, корень);
    // Типизированные слушатели: типы, затем экземпляры (по всему дереву, до
    // анализа «слушать», который ищет экземпляр независимо от порядка).
    собрать_слушатели(&а, корень);
    собрать_экземпляры_слушателей(&а, корень);
    // Глобальные «конст» — после сигнатур (поля-колбэки сверяются с функциями).
    собрать_глобальные_константы(&а, корень);
    // После обеих точек заполнения таблицы: вывод чистоты должен видеть и
    // библиотечные сигнатуры (у них нет тела → нечистые).
    вывести_чистоту(&а, корень);
    вывести_владение_возврата(&а, корень);  // §37 п.6 — до анализа тел (call-site)
    for (size_t i = 0; i < узел_число_детей(корень); ++i) {
        // Не-батч режим: стоп на первой ошибке. Батч-режим: продолжаем, ошибки
        // накоплены в списке (диаг->ошибка сбрасывается на границах).
        if (диаг->ошибка && !ошибки) break;
        Узел *узел = узел_ребёнок(корень, i);
        if (узел->тип != УЗЕЛ_ФУНКЦИЯ) continue;
        // «внешняя» — прототип без тела: тела нет, но параметры проверяем
        // (вызовы проверяет общая типо-/ссылко-проверка по сигнатуре).
        if (узел->внешняя) {
            for (size_t j = 0; j < узел_число_детей(узел); ++j) {
                Узел *пар = узел_ребёнок(узел, j);
                if (!пар || пар->тип != УЗЕЛ_ПАРАМЕТР) continue;
                if (пар->тип_данных != ТОКЕН_СТРУКТУРА || пар->указатели > 0)
                    continue;
                int инд = найти_индекс_структуры(&а, &пар->имя_типа);
                if (инд >= 0 && а.структуры[инд].внешний) {
                    char msg[256];
                    snprintf(msg, sizeof(msg),
                             "«%.*s» — внешний тип: параметр возможен только "
                             "как указатель «%.*s*»",
                             (int)пар->имя_типа.длина, пар->имя_типа.начало,
                             (int)пар->имя_типа.длина, пар->имя_типа.начало);
                    ошибка_семантики(&а, &пар->токен, msg);
                    if (ошибки) собрать_ошибку(&а);
                }
            }
            continue;
        }

        анализ_функции(&а, узел);

        if (диаг->ошибка && ошибки) собрать_ошибку(&а);
        // Сброс «рабочего» состояния к базовой линии перед следующей функцией:
        // даже если ошибка внутри функции оставила стек областей несбаланси-
        // рованным, следующая функция начинает с чистого листа (глобальное —
        // структуры/перечисления/сигнатуры — не трогаем, оно собрано выше).
        if (ошибки) {
            а.число_символов = 0;
            а.глубина = 0;
            а.глубина_цикла = 0;
            а.число_безопасных = 0;
            а.число_связей = 0;
            а.глубина_ограничений = 0;
            а.число_фактов = 0;
            а.число_изменяемых = 0;
        }
    }
    // В батч-режиме успех определяется пустотой списка ошибок (диаг->ошибка мог
    // быть сброшен при сборе). В обычном — флагом диагностики.
    if (ошибки) return ошибки->длина == 0;
    return !диаг->ошибка;
}

int анализировать_полный(Узел *корень, Диагностика *диаг,
                         const ТаблицаВнешних *внешние,
                         ДинМассив *предупреждения, ДинМассив *ошибки)
{
    return анализировать_полный_и(корень, диаг, внешние, nullptr,
                                  предупреждения, ошибки);
}

int анализировать(Узел *корень, Диагностика *диаг)
{
    return анализировать_полный(корень, диаг, nullptr, nullptr, nullptr);
}

// Число собранных сигнатур функций Konda доступно только внутри Анализатора,
// который живёт лишь в анализировать_*. Для LSP-API сигнатуры собираются
// отдельно (см. libkonda_ide.c), поэтому здесь дополнительных геттеров нет.
